INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Gn', 7, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Noé: Entra tu e toda tua casa na arca porque a ti vi justo diante de mim nesta geração."}, {"numero": 2, "texto": "De todo animal limpo tomarás de sete em sete, macho e sua fêmea; mas dos animais que não são limpos, dois, macho e sua fêmea."}, {"numero": 3, "texto": "Também das aves dos céus de sete em sete, macho e fêmea; para guardar em vida a descendência sobre a face de toda a terra."}, {"numero": 4, "texto": "Porque passados ainda sete dias, eu farei chover sobre a terra quarenta dias e quarenta noites; e apagarei toda criatura que fiz de sobre a face da terra."}, {"numero": 5, "texto": "E fez Noé conforme tudo o que lhe mandou o SENHOR."}, {"numero": 6, "texto": "E sendo Noé de seiscentos anos, o dilúvio das águas foi sobre a terra."}, {"numero": 7, "texto": "E veio Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele à arca, por causa das águas do dilúvio."}, {"numero": 8, "texto": "Dos animais limpos, e dos animais que não eram limpos, e das aves, e de todo o que anda arrastando sobre a terra,"}, {"numero": 9, "texto": "De dois em dois entraram a Noé na arca: macho e fêmea, como mandou Deus a Noé."}, {"numero": 10, "texto": "E sucedeu que ao sétimo dia as águas do dilúvio foram sobre a terra."}, {"numero": 11, "texto": "No ano seiscentos da vida de Noé, no mês segundo, no dia dezessete do mês, naquele dia foram rompidas todas as fontes do grande abismo, e as comportas dos céus foram abertas;"}, {"numero": 12, "texto": "E houve chuva sobre a terra quarenta dias e quarenta noites."}, {"numero": 13, "texto": "Neste mesmo dia entrou Noé, e Sem, e Cam e Jafé, filhos de Noé, a mulher de Noé, e as três mulheres de seus filhos com ele na arca;"}, {"numero": 14, "texto": "Eles e todos os animais silvestres segundo suas espécies, e todos os animais mansos segundo suas espécies, e todo réptil que anda arrastando sobre a terra segundo sua espécie, e toda ave segundo sua espécie, todo pássaro, toda espécie de animal voador."}, {"numero": 15, "texto": "E vieram a Noé à arca, de dois em dois de toda carne em que havia espírito de vida."}, {"numero": 16, "texto": "E os que vieram, macho e fêmea de toda carne vieram, como lhe havia mandado Deus: e o SENHOR lhe fechou a porta"}, {"numero": 17, "texto": "E foi o dilúvio quarenta dias sobre a terra; e as águas cresceram, e levantaram a arca, e se elevou sobre a terra."}, {"numero": 18, "texto": "E prevaleceram as águas, e cresceram em grande maneira sobre a terra; e andava a arca sobre a face das águas."}, {"numero": 19, "texto": "E as águas prevaleceram muito em extremo sobre a terra; e todos os montes altos que havia debaixo de todos os céus, foram cobertos."}, {"numero": 20, "texto": "Quinze côvados em altura prevaleceram as águas; e foram cobertos os montes."}, {"numero": 21, "texto": "E morreu toda carne que se move sobre a terra, tanto de aves como de gados, e de animais, e de todo réptil que anda arrastando sobre a terra, e todo ser humano:"}, {"numero": 22, "texto": "Tudo o que tinha fôlego de espírito de vida em suas narinas, de tudo o que havia na terra, morreu."}, {"numero": 23, "texto": "Assim foi destruída toda criatura que vivia sobre a face da terra, desde o ser humano até o animal, e os répteis, e as aves do céu; e foram apagados da terra; e restou somente Noé, e os que com ele estavam na arca."}, {"numero": 24, "texto": "E prevaleceram as águas sobre a terra cento e cinquenta dias."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 7, 'en', '[{"numero": 1, "texto": "And the Lord said unto Noah, Come thou and all thy house into the ark; for thee have I seen righteous before me in this generation."}, {"numero": 2, "texto": "Of every clean beast thou shalt take to thee by sevens, the male and his female: and of beasts that are not clean by two, the male and his female."}, {"numero": 3, "texto": "Of fowls also of the air by sevens, the male and the female; to keep seed alive upon the face of all the earth."}, {"numero": 4, "texto": "For yet seven days, and I will cause it to rain upon the earth forty days and forty nights; and every living substance that I have made will I destroy from off the face of the earth."}, {"numero": 5, "texto": "And Noah did according unto all that the Lord commanded him."}, {"numero": 6, "texto": "And Noah was six hundred years old when the flood of waters was upon the earth."}, {"numero": 7, "texto": "And Noah went in, and his sons, and his wife, and his sons'' wives with him, into the ark, because of the waters of the flood."}, {"numero": 8, "texto": "Of clean beasts, and of beasts that are not clean, and of fowls, and of every thing that creepeth upon the earth,"}, {"numero": 9, "texto": "There went in two and two unto Noah into the ark, the male and the female, as God had commanded Noah."}, {"numero": 10, "texto": "And it came to pass after seven days, that the waters of the flood were upon the earth."}, {"numero": 11, "texto": "In the six hundredth year of Noah''s life, in the second month, the seventeenth day of the month, the same day were all the fountains of the great deep broken up, and the windows of heaven were opened."}, {"numero": 12, "texto": "And the rain was upon the earth forty days and forty nights."}, {"numero": 13, "texto": "In the selfsame day entered Noah, and Shem, and Ham, and Japheth, the sons of Noah, and Noah''s wife, and the three wives of his sons with them, into the ark;"}, {"numero": 14, "texto": "They, and every beast after his kind, and all the cattle after their kind, and every creeping thing that creepeth upon the earth after his kind, and every fowl after his kind, every bird of every sort."}, {"numero": 15, "texto": "And they went in unto Noah into the ark, two and two of all flesh, wherein is the breath of life."}, {"numero": 16, "texto": "And they that went in, went in male and female of all flesh, as God had commanded him: and the Lord shut him in."}, {"numero": 17, "texto": "And the flood was forty days upon the earth; and the waters increased, and bare up the ark, and it was lift up above the earth."}, {"numero": 18, "texto": "And the waters prevailed, and were increased greatly upon the earth; and the ark went upon the face of the waters."}, {"numero": 19, "texto": "And the waters prevailed exceedingly upon the earth; and all the high hills, that were under the whole heaven, were covered."}, {"numero": 20, "texto": "Fifteen cubits upward did the waters prevail; and the mountains were covered."}, {"numero": 21, "texto": "And all flesh died that moved upon the earth, both of fowl, and of cattle, and of beast, and of every creeping thing that creepeth upon the earth, and every man:"}, {"numero": 22, "texto": "All in whose nostrils was the breath of life, of all that was in the dry land, died."}, {"numero": 23, "texto": "And every living substance was destroyed which was upon the face of the ground, both man, and cattle, and the creeping things, and the fowl of the heaven; and they were destroyed from the earth: and Noah only remained alive, and they that were with him in the ark."}, {"numero": 24, "texto": "And the waters prevailed upon the earth an hundred and fifty days."}]'::jsonb, 'King James Version'),
  ('Gn', 7, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Noé: Entre dans l''''arche, toi et toute ta maison; car je t''''ai vu juste devant moi parmi cette génération."}, {"numero": 2, "texto": "Tu prendras auprès de toi sept couples de tous les animaux purs, le mâle et sa femelle; une paire des animaux qui ne sont pas purs, le mâle et sa femelle;"}, {"numero": 3, "texto": "sept couples aussi des oiseaux du ciel, mâle et femelle, afin de conserver leur race en vie sur la face de toute la terre."}, {"numero": 4, "texto": "Car, encore sept jours, et je ferai pleuvoir sur la terre quarante jours et quarante nuits, et j''''exterminerai de la face de la terre tous les êtres que j''''ai faits."}, {"numero": 5, "texto": "Noé exécuta tout ce que l''''Eternel lui avait ordonné."}, {"numero": 6, "texto": "Noé avait six cents ans, lorsque le déluge d''''eaux fut sur la terre."}, {"numero": 7, "texto": "Et Noé entra dans l''''arche avec ses fils, sa femme et les femmes de ses fils, pour échapper aux eaux du déluge."}, {"numero": 8, "texto": "D''''entre les animaux purs et les animaux qui ne sont pas purs, les oiseaux et tout ce qui se meut sur la terre,"}, {"numero": 9, "texto": "il entra dans l''''arche auprès de Noé, deux à deux, un mâle et une femelle, comme Dieu l''''avait ordonné à Noé."}, {"numero": 10, "texto": "Sept jours après, les eaux du déluge furent sur la terre."}, {"numero": 11, "texto": "L''''an six cent de la vie de Noé, le second mois, le dix-septième jour du mois, en ce jour-là toutes les sources du grand abîme jaillirent, et les écluses des cieux s''''ouvrirent."}, {"numero": 12, "texto": "La pluie tomba sur la terre quarante jours et quarante nuits."}, {"numero": 13, "texto": "Ce même jour entrèrent dans l''''arche Noé, Sem, Cham et Japhet, fils de Noé, la femme de Noé et les trois femmes de ses fils avec eux:"}, {"numero": 14, "texto": "eux, et tous les animaux selon leur espèce, tout le bétail selon son espèce, tous les reptiles qui rampent sur la terre selon leur espèce, tous les oiseaux selon leur espèce, tous les petits oiseaux, tout ce qui a des ailes."}, {"numero": 15, "texto": "Ils entrèrent dans l''''arche auprès de Noé, deux à deux, de toute chair ayant souffle de vie."}, {"numero": 16, "texto": "Il en entra, mâle et femelle, de toute chair, comme Dieu l''''avait ordonné à Noé. Puis l''''Eternel ferma la porte sur lui."}, {"numero": 17, "texto": "Le déluge fut quarante jours sur la terre. Les eaux crûrent et soulevèrent l''''arche, et elle s''''éleva au-dessus de la terre."}, {"numero": 18, "texto": "Les eaux grossirent et s''''accrurent beaucoup sur la terre, et l''''arche flotta sur la surface des eaux."}, {"numero": 19, "texto": "Les eaux grossirent de plus en plus, et toutes les hautes montagnes qui sont sous le ciel entier furent couvertes."}, {"numero": 20, "texto": "Les eaux s''''élevèrent de quinze coudées au-dessus des montagnes, qui furent couvertes."}, {"numero": 21, "texto": "Tout ce qui se mouvait sur la terre périt, tant les oiseaux que le bétail et les animaux, tout ce qui rampait sur la terre, et tous les hommes."}, {"numero": 22, "texto": "Tout ce qui avait respiration, souffle de vie dans ses narines, et qui était sur la terre sèche, mourut."}, {"numero": 23, "texto": "Tous les êtres qui étaient sur la face de la terre furent exterminés, depuis l''''homme jusqu''''au bétail, aux reptiles et aux oiseaux du ciel: ils furent exterminés de la terre. Il ne resta que Noé, et ce qui était avec lui dans l''''arche."}, {"numero": 24, "texto": "Les eaux furent grosses sur la terre pendant cent cinquante jours."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 7, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Noé: Entra tú y toda tu casa en el arca; porque á ti he visto justo delante de mí en esta generación."}, {"numero": 2, "texto": "De todo animal limpio te tomarás de siete en siete, macho y su hembra; mas de los animales que no son limpios, dos, macho y su hembra."}, {"numero": 3, "texto": "También de las aves de los cielos de siete en siete, macho y hembra; para guardar en vida la casta sobre la faz de toda la tierra."}, {"numero": 4, "texto": "Porque pasados aún siete días, yo haré llover sobre la tierra cuarenta días y cuarenta noches; y raeré toda sustancia que hice de sobre la faz de la tierra."}, {"numero": 5, "texto": "E hizo Noé conforme á todo lo que le mandó Jehová."}, {"numero": 6, "texto": "Y siendo Noé de seiscientos años, el diluvio de las aguas fué sobre la tierra."}, {"numero": 7, "texto": "Y vino Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él al arca, por las aguas del diluvio."}, {"numero": 8, "texto": "De los animales limpios, y de los animales que no eran limpios, y de las aves, y de todo lo que anda arrastrando sobre la tierra,"}, {"numero": 9, "texto": "De dos en dos entraron á Noé en el arca: macho y hembra, como mandó Dios á Noé."}, {"numero": 10, "texto": "Y sucedió que al séptimo día las aguas del diluvio fueron sobre la tierra."}, {"numero": 11, "texto": "El año seiscientos de la vida de Noé, en el mes segundo, á diecisiete días del mes, aquel día fueron rotas todas las fuentes del grande abismo, y las cataratas de los cielos fueron abiertas;"}, {"numero": 12, "texto": "Y hubo lluvia sobre la tierra cuarenta días y cuarenta noches."}, {"numero": 13, "texto": "En este mismo día entró Noé, y Sem y Châm y Japhet, hijos de Noé, la mujer de Noé, y las tres mujeres de sus hijos con él en el arca;"}, {"numero": 14, "texto": "Ellos, y todos los animales silvestres según sus especies, y todos los animales mansos según sus especies, y todo reptil que anda arrastrando sobre la tierra según su especie, y toda ave según su especie, todo pájaro, toda especie de volátil."}, {"numero": 15, "texto": "Y vinieron á Noé al arca, de dos en dos de toda carne en que había espíritu de vida."}, {"numero": 16, "texto": "Y los que vinieron, macho y hembra de toda carne vinieron, como le había mandado Dios: y Jehová le cerró la puerta."}, {"numero": 17, "texto": "Y fué el diluvio cuarenta días sobre la tierra; y las aguas crecieron, y alzaron el arca, y se elevó sobre la tierra."}, {"numero": 18, "texto": "Y prevalecieron las aguas, y crecieron en gran manera sobre la tierra; y andaba el arca sobre la faz de las aguas."}, {"numero": 19, "texto": "Y las aguas prevalecieron mucho en extremo sobre la tierra; y todos los montes altos que había debajo de todos los cielos, fueron cubiertos."}, {"numero": 20, "texto": "Quince codos en alto prevalecieron las aguas; y fueron cubiertos los montes."}, {"numero": 21, "texto": "Y murió toda carne que se mueve sobre la tierra, así de aves como de ganados, y de bestias, y de todo reptil que anda arrastrando sobre la tierra, y todo hombre:"}, {"numero": 22, "texto": "Todo lo que tenía aliento de espíritu de vida en sus narices, de todo lo que había en la tierra, murió."}, {"numero": 23, "texto": "Así fué destruída toda sustancia que vivía sobre la faz de la tierra, desde el hombre hasta la bestia, y los reptiles, y las aves del cielo; y fueron raídos de la tierra; y quedó solamente Noé, y lo que con él estaba en el arca."}, {"numero": 24, "texto": "Y prevalecieron las aguas sobre la tierra ciento y cincuenta días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 8, 'pt', '[{"numero": 1, "texto": "E lembrou-se Deus de Noé, e de todos os animais, selvagens e domésticos que estavam com ele na arca; e fez passar Deus um vento sobre a terra, e diminuíram as águas."}, {"numero": 2, "texto": "E se fecharam as fontes do abismo, e as comportas dos céus; e a chuva dos céus foi detida."}, {"numero": 3, "texto": "E voltaram-se as águas de sobre a terra, indo e voltando; e decresceram as águas ao fim de cento e cinquenta dias."}, {"numero": 4, "texto": "E repousou a arca no mês sétimo, a dezessete dias do mês, sobre os montes de Ararate."}, {"numero": 5, "texto": "E as águas foram decrescendo até o mês décimo: no décimo, ao primeiro dia do mês, se revelaram os cumes dos montes."}, {"numero": 6, "texto": "E sucedeu que, ao fim de quarenta dias, abriu Noé a janela da arca que havia feito,"}, {"numero": 7, "texto": "E enviou ao corvo, o qual saiu, e esteve indo e voltando até que as águas se secaram de sobre a terra."}, {"numero": 8, "texto": "Enviou também de si à pomba, para ver se as águas se haviam retirado de sobre a face da terra;"}, {"numero": 9, "texto": "E não achou a pomba onde sentar a planta de seu pé, e voltou-se a ele à arca, porque as águas estavam ainda sobre a face de toda a terra: então ele estendeu sua mão e recolhendo-a, a fez entrar consigo na arca."}, {"numero": 10, "texto": "E esperou ainda outros sete dias, e voltou a enviar a pomba fora da arca."}, {"numero": 11, "texto": "E a pomba voltou a ele à hora da tarde; e eis que trazia uma folha de oliveira tomada em seu bico; então Noé entendeu que as águas haviam se retirado de sobre a terra."}, {"numero": 12, "texto": "E esperou ainda outros sete dias, e enviou a pomba, a qual não voltou já mais a ele."}, {"numero": 13, "texto": "E sucedeu que no ano seiscentos e um de Noé, no mês primeiro, ao primeiro do mês, as águas se enxugaram de sobre a terra e tirou Noé a cobertura da arca, e olhou, e eis que a face da terra estava enxuta."}, {"numero": 14, "texto": "E no mês segundo, aos vinte e sete dias do mês, se secou a terra."}, {"numero": 15, "texto": "E falou Deus a Noé dizendo:"}, {"numero": 16, "texto": "Sai da arca tu, a tua mulher, os teus filhos, e as mulheres dos teus filhos contigo."}, {"numero": 17, "texto": "Todos os animais que estão contigo de toda carne, de aves e de animais e de todo réptil que anda arrastando sobre a terra, tirarás contigo; e vão pela terra, e frutifiquem, e multipliquem-se sobre a terra."}, {"numero": 18, "texto": "Então saiu Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele."}, {"numero": 19, "texto": "Todos os animais, e todo réptil e toda ave, tudo o que se move sobre a terra segundo suas espécies, saíram da arca."}, {"numero": 20, "texto": "E edificou Noé um altar ao SENHOR e tomou de todo animal limpo e de toda ave limpa, e ofereceu holocaustos sobre o altar."}, {"numero": 21, "texto": "E percebeu o SENHOR cheiro suave; e o SENHOR disse em seu coração: Não voltarei mais a amaldiçoar a terra por causa do ser humano; porque o intento do coração do ser humano é mau desde sua juventude: nem voltarei mais a destruir todo vivente, como fiz."}, {"numero": 22, "texto": "Enquanto a terra durar, a sementeira e a colheita, o frio e calor, verão e inverno, dia e noite, não cessarão."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 8, 'en', '[{"numero": 1, "texto": "And God remembered Noah, and every living thing, and all the cattle that was with him in the ark: and God made a wind to pass over the earth, and the waters assuaged;"}, {"numero": 2, "texto": "The fountains also of the deep and the windows of heaven were stopped, and the rain from heaven was restrained;"}, {"numero": 3, "texto": "And the waters returned from off the earth continually: and after the end of the hundred and fifty days the waters were abated."}, {"numero": 4, "texto": "And the ark rested in the seventh month, on the seventeenth day of the month, upon the mountains of Ararat."}, {"numero": 5, "texto": "And the waters decreased continually until the tenth month: in the tenth month, on the first day of the month, were the tops of the mountains seen."}, {"numero": 6, "texto": "And it came to pass at the end of forty days, that Noah opened the window of the ark which he had made:"}, {"numero": 7, "texto": "And he sent forth a raven, which went forth to and fro, until the waters were dried up from off the earth."}, {"numero": 8, "texto": "Also he sent forth a dove from him, to see if the waters were abated from off the face of the ground;"}, {"numero": 9, "texto": "But the dove found no rest for the sole of her foot, and she returned unto him into the ark, for the waters were on the face of the whole earth: then he put forth his hand, and took her, and pulled her in unto him into the ark."}, {"numero": 10, "texto": "And he stayed yet other seven days; and again he sent forth the dove out of the ark;"}, {"numero": 11, "texto": "And the dove came in to him in the evening; and, lo, in her mouth was an olive leaf pluckt off: so Noah knew that the waters were abated from off the earth."}, {"numero": 12, "texto": "And he stayed yet other seven days; and sent forth the dove; which returned not again unto him any more."}, {"numero": 13, "texto": "And it came to pass in the six hundredth and first year, in the first month, the first day of the month, the waters were dried up from off the earth: and Noah removed the covering of the ark, and looked, and, behold, the face of the ground was dry."}, {"numero": 14, "texto": "And in the second month, on the seven and twentieth day of the month, was the earth dried."}, {"numero": 15, "texto": "And God spake unto Noah, saying,"}, {"numero": 16, "texto": "Go forth of the ark, thou, and thy wife, and thy sons, and thy sons'' wives with thee."}, {"numero": 17, "texto": "Bring forth with thee every living thing that is with thee, of all flesh, both of fowl, and of cattle, and of every creeping thing that creepeth upon the earth; that they may breed abundantly in the earth, and be fruitful, and multiply upon the earth."}, {"numero": 18, "texto": "And Noah went forth, and his sons, and his wife, and his sons'' wives with him:"}, {"numero": 19, "texto": "Every beast, every creeping thing, and every fowl, and whatsoever creepeth upon the earth, after their kinds, went forth out of the ark."}, {"numero": 20, "texto": "And Noah builded an altar unto the Lord; and took of every clean beast, and of every clean fowl, and offered burnt offerings on the altar."}, {"numero": 21, "texto": "And the Lord smelled a sweet savour; and the Lord said in his heart, I will not again curse the ground any more for man''s sake; for the imagination of man''s heart is evil from his youth; neither will I again smite any more every thing living, as I have done."}, {"numero": 22, "texto": "While the earth remaineth, seedtime and harvest, and cold and heat, and summer and winter, and day and night shall not cease."}]'::jsonb, 'King James Version'),
  ('Gn', 8, 'fr', '[{"numero": 1, "texto": "Dieu se souvint de Noé, de tous les animaux et de tout le bétail qui étaient avec lui dans l''''arche; et Dieu fit passer un vent sur la terre, et les eaux s''''apaisèrent."}, {"numero": 2, "texto": "Les sources de l''''abîme et les écluses des cieux furent fermées, et la pluie ne tomba plus du ciel."}, {"numero": 3, "texto": "Les eaux se retirèrent de dessus la terre, s''''en allant et s''''éloignant, et les eaux diminuèrent au bout de cent cinquante jours."}, {"numero": 4, "texto": "Le septième mois, le dix-septième jour du mois, l''''arche s''''arrêta sur les montagnes d''''Ararat."}, {"numero": 5, "texto": "Les eaux allèrent en diminuant jusqu''''au dixième mois. Le dixième mois, le premier jour du mois, apparurent les sommets des montagnes."}, {"numero": 6, "texto": "Au bout de quarante jours, Noé ouvrit la fenêtre qu''''il avait faite à l''''arche."}, {"numero": 7, "texto": "Il lâcha le corbeau, qui sortit, partant et revenant, jusqu''''à ce que les eaux eussent séché sur la terre."}, {"numero": 8, "texto": "Il lâcha aussi la colombe, pour voir si les eaux avaient diminué à la surface de la terre."}, {"numero": 9, "texto": "Mais la colombe ne trouva aucun lieu pour poser la plante de son pied, et elle revint à lui dans l''''arche, car il y avait des eaux à la surface de toute la terre. Il avança la main, la prit, et la fit rentrer auprès de lui dans l''''arche."}, {"numero": 10, "texto": "Il attendit encore sept autres jours, et il lâcha de nouveau la colombe hors de l''''arche."}, {"numero": 11, "texto": "La colombe revint à lui sur le soir; et voici, une feuille d''''olivier arrachée était dans son bec. Noé connut ainsi que les eaux avaient diminué sur la terre."}, {"numero": 12, "texto": "Il attendit encore sept autres jours; et il lâcha la colombe. Mais elle ne revint plus à lui."}, {"numero": 13, "texto": "L''''an six cent un, le premier mois, le premier jour du mois, les eaux avaient séché sur la terre. Noé ôta la couverture de l''''arche: il regarda, et voici, la surface de la terre avait séché."}, {"numero": 14, "texto": "Le second mois, le vingt-septième jour du mois, la terre fut sèche."}, {"numero": 15, "texto": "Alors Dieu parla à Noé, en disant:"}, {"numero": 16, "texto": "Sors de l''''arche, toi et ta femme, tes fils et les femmes de tes fils avec toi."}, {"numero": 17, "texto": "Fais sortir avec toi tous les animaux de toute chair qui sont avec toi, tant les oiseaux que le bétail et tous les reptiles qui rampent sur la terre: qu''''ils se répandent sur la terre, qu''''ils soient féconds et multiplient sur la terre."}, {"numero": 18, "texto": "Et Noé sortit, avec ses fils, sa femme, et les femmes de ses fils."}, {"numero": 19, "texto": "Tous les animaux, tous les reptiles, tous les oiseaux, tout ce qui se meut sur la terre, selon leurs espèces, sortirent de l''''arche."}, {"numero": 20, "texto": "Noé bâtit un autel à l''''Eternel; il prit de toutes les bêtes pures et de tous les oiseaux purs, et il offrit des holocaustes sur l''''autel."}, {"numero": 21, "texto": "L''''Eternel sentit une odeur agréable, et l''''Eternel dit en son coeur: Je ne maudirai plus la terre, à cause de l''''homme, parce que les pensées du coeur de l''''homme sont mauvaises dès sa jeunesse; et je ne frapperai plus tout ce qui est vivant, comme je l''''ai fait."}, {"numero": 22, "texto": "Tant que la terre subsistera, les semailles et la moisson, le froid et la chaleur, l''''été et l''''hiver, le jour et la nuit ne cesseront point."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 8, 'es', '[{"numero": 1, "texto": "Y ACORDÓSE Dios de Noé, y de todos los animales, y de todas las bestias que estaban con él en el arca; é hizo pasar Dios un viento sobre la tierra, y disminuyeron las aguas."}, {"numero": 2, "texto": "Y se cerraron las fuentes del abismo, y las cataratas de los cielos; y la lluvia de los cielos fué detenida."}, {"numero": 3, "texto": "Y tornáronse las aguas de sobre la tierra, yendo y volviendo: y decrecieron las aguas al cabo de ciento y cincuenta días."}, {"numero": 4, "texto": "Y reposó el arca en el mes séptimo, á diecisiete días del mes, sobre los montes de Armenia."}, {"numero": 5, "texto": "Y las aguas fueron decreciendo hasta el mes décimo: en el décimo, al primero del mes, se descubrieron las cimas de los montes."}, {"numero": 6, "texto": "Y sucedió que, al cabo de cuarenta días, abrió Noé la ventana del arca que había hecho,"}, {"numero": 7, "texto": "Y envió al cuervo, el cual salió, y estuvo yendo y tornando hasta que las aguas se secaron de sobre la tierra."}, {"numero": 8, "texto": "Envió también de sí á la paloma, para ver si las aguas se habían retirado de sobre la faz de la tierra;"}, {"numero": 9, "texto": "Y no halló la paloma donde sentar la planta de su pie, y volvióse á él al arca, porque las aguas estaban aún sobre la faz de toda la tierra: entonces él extendió su mano, y cogiéndola, hízola entrar consigo en el arca."}, {"numero": 10, "texto": "Y esperó aún otros siete días, y volvió á enviar la paloma fuera del arca."}, {"numero": 11, "texto": "Y la paloma volvió á él á la hora de la tarde; y he aquí que traía una hoja de oliva tomada en su pico: y entendió Noé que las aguas se habían retirado de sobre la tierra."}, {"numero": 12, "texto": "Y esperó aún otros siete días, y envió la paloma, la cual no volvió ya más á él."}, {"numero": 13, "texto": "Y sucedió que en el año seiscientos y uno de Noé, en el mes primero, al primero del mes, las aguas se enjugaron de sobre la tierra; y quitó Noé la cubierta del arca, y miró, y he aquí que la faz de la tierra estaba enjuta."}, {"numero": 14, "texto": "Y en el mes segundo, á los veintisiete días del mes, se secó la tierra."}, {"numero": 15, "texto": "Y habló Dios á Noé diciendo:"}, {"numero": 16, "texto": "Sal del arca tú, y tu mujer, y tus hijos, y las mujeres de tus hijos contigo."}, {"numero": 17, "texto": "Todos los animales que están contigo de toda carne, de aves y de bestias y de todo reptil que anda arrastrando sobre la tierra, sacarás contigo; y vayan por la tierra, y fructifiquen, y multiplíquense sobre la tierra."}, {"numero": 18, "texto": "Entonces salió Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él."}, {"numero": 19, "texto": "Todos los animales, y todo reptil y toda ave, todo lo que se mueve sobre la tierra según sus especies, salieron del arca."}, {"numero": 20, "texto": "Y edificó Noé un altar á Jehová, y tomó de todo animal limpio y de toda ave limpia, y ofreció holocausto en el altar."}, {"numero": 21, "texto": "Y percibió Jehová olor de suavidad; y dijo Jehová en su corazón: No tornaré más á maldecir la tierra por causa del hombre; porque el intento del corazón del hombre es malo desde su juventud: ni volveré más á destruir todo viviente, como he hecho."}, {"numero": 22, "texto": "Todavía serán todos los tiempos de la tierra; la sementera y la siega, y el frío y calor, verano é invierno, y día y noche, no cesarán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 9, 'pt', '[{"numero": 1, "texto": "E Deus abençoou Noé e seus filhos, e disse-lhes: Frutificai, e multiplicai, e enchei a terra:"}, {"numero": 2, "texto": "E vosso temor e vosso pavor será sobre todo animal da terra, e sobre toda ave dos céus, em tudo o que se mover na terra, e em todos os peixes do mar: em vossa mão são entregues."}, {"numero": 3, "texto": "Tudo o que se move e vive vos será para mantimento: assim como os legumes e ervas, vos dei disso tudo."}, {"numero": 4, "texto": "Porém a carne com sua vida, que é seu sangue, não comereis."}, {"numero": 5, "texto": "Porque certamente exigirei o sangue de vossas vidas; da mão de todo animal o exigirei, e da mão do ser humano; da mão do homem seu irmão exigirei a vida do ser humano."}, {"numero": 6, "texto": "O que derramar sangue humano, pelo ser humano seu sangue será derramado; porque à imagem de Deus o ser humano foi feito."}, {"numero": 7, "texto": "Mas vós frutificai, e multiplicai-vos; procriai abundantemente na terra, e multiplicai-vos nela."}, {"numero": 8, "texto": "E falou Deus a Noé e a seus filhos com ele, dizendo:"}, {"numero": 9, "texto": "Eis que eu mesmo estabeleço meu pacto convosco, e com vossa descendência depois de vós;"}, {"numero": 10, "texto": "E com toda alma vivente que está convosco, de aves, de animais, e de toda fera da terra que está convosco; desde todos os que saíram da arca até todo animal da terra."}, {"numero": 11, "texto": "Estabelecerei meu pacto convosco, e não será mais exterminada toda carne com águas de dilúvio; nem haverá mais dilúvio para destruir a terra."}, {"numero": 12, "texto": "E disse Deus: Este será o sinal do pacto que estabeleço entre mim e vós e toda alma vivente que está convosco, por tempos perpétuos:"}, {"numero": 13, "texto": "Meu arco porei nas nuvens, o qual será por sinal de aliança entre mim e a terra."}, {"numero": 14, "texto": "E será que quando fizer vir nuvens sobre a terra, se deixará ver então meu arco nas nuvens."}, {"numero": 15, "texto": "E me lembrarei do meu pacto, que há entre mim e vós e toda alma vivente de toda carne; e não serão mais as águas por dilúvio para destruir toda carne."}, {"numero": 16, "texto": "E estará o arco nas nuvens, e o verei para me lembrar do pacto perpétuo entre Deus e toda alma vivente, com toda carne que há sobre a terra."}, {"numero": 17, "texto": "Disse, pois, Deus a Noé: Este será o sinal do pacto que estabeleci entre mim e toda carne que está sobre a terra."}, {"numero": 18, "texto": "E os filhos de Noé que saíram da arca foram Sem, Cam e Jafé: e Cam é o pai de Canaã."}, {"numero": 19, "texto": "Estes três são os filhos de Noé; e deles foi cheia toda a terra."}, {"numero": 20, "texto": "E começou Noé a lavrar a terra, e plantou uma vinha;"}, {"numero": 21, "texto": "E bebeu do vinho, e se embriagou, e estava descoberto dentro de sua tenda."}, {"numero": 22, "texto": "E Cam, pai de Canaã, viu a nudez de seu pai, e disse-o aos seus dois irmãos do lado de fora."}, {"numero": 23, "texto": "Então Sem e Jafé tomaram a roupa, e a puseram sobre seus próprios ombros, e andando para trás, cobriram a nudez de seu pai tendo seus rostos virados, e assim não viram a nudez de seu pai."}, {"numero": 24, "texto": "E despertou Noé de seu vinho, e soube o que havia feito com ele seu filho o mais jovem;"}, {"numero": 25, "texto": "E disse: Maldito seja Canaã; Servo de servos será a seus irmãos."}, {"numero": 26, "texto": "Disse mais: Bendito o SENHOR o Deus de Sem, E seja-lhe Canaã servo."}, {"numero": 27, "texto": "Engrandeça Deus a Jafé, E habite nas tendas de Sem, E seja-lhe Canaã servo."}, {"numero": 28, "texto": "E viveu Noé depois do dilúvio trezentos e cinquenta anos."}, {"numero": 29, "texto": "E foram todos os dias de Noé novecentos e cinquenta anos; e morreu."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 9, 'en', '[{"numero": 1, "texto": "And God blessed Noah and his sons, and said unto them, Be fruitful, and multiply, and replenish the earth."}, {"numero": 2, "texto": "And the fear of you and the dread of you shall be upon every beast of the earth, and upon every fowl of the air, upon all that moveth upon the earth, and upon all the fishes of the sea; into your hand are they delivered."}, {"numero": 3, "texto": "Every moving thing that liveth shall be meat for you; even as the green herb have I given you all things."}, {"numero": 4, "texto": "But flesh with the life thereof, which is the blood thereof, shall ye not eat."}, {"numero": 5, "texto": "And surely your blood of your lives will I require; at the hand of every beast will I require it, and at the hand of man; at the hand of every man''s brother will I require the life of man."}, {"numero": 6, "texto": "Whoso sheddeth man''s blood, by man shall his blood be shed: for in the image of God made he man."}, {"numero": 7, "texto": "And you, be ye fruitful, and multiply; bring forth abundantly in the earth, and multiply therein."}, {"numero": 8, "texto": "And God spake unto Noah, and to his sons with him, saying,"}, {"numero": 9, "texto": "And I, behold, I establish my covenant with you, and with your seed after you;"}, {"numero": 10, "texto": "And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you; from all that go out of the ark, to every beast of the earth."}, {"numero": 11, "texto": "And I will establish my covenant with you, neither shall all flesh be cut off any more by the waters of a flood; neither shall there any more be a flood to destroy the earth."}, {"numero": 12, "texto": "And God said, This is the token of the covenant which I make between me and you and every living creature that is with you, for perpetual generations:"}, {"numero": 13, "texto": "I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth."}, {"numero": 14, "texto": "And it shall come to pass, when I bring a cloud over the earth, that the bow shall be seen in the cloud:"}, {"numero": 15, "texto": "And I will remember my covenant, which is between me and you and every living creature of all flesh; and the waters shall no more become a flood to destroy all flesh."}, {"numero": 16, "texto": "And the bow shall be in the cloud; and I will look upon it, that I may remember the everlasting covenant between God and every living creature of all flesh that is upon the earth."}, {"numero": 17, "texto": "And God said unto Noah, This is the token of the covenant, which I have established between me and all flesh that is upon the earth."}, {"numero": 18, "texto": "And the sons of Noah, that went forth of the ark, were Shem, and Ham, and Japheth: and Ham is the father of Canaan."}, {"numero": 19, "texto": "These are the three sons of Noah: and of them was the whole earth overspread."}, {"numero": 20, "texto": "And Noah began to be an husbandman, and he planted a vineyard:"}, {"numero": 21, "texto": "And he drank of the wine, and was drunken; and he was uncovered within his tent."}, {"numero": 22, "texto": "And Ham, the father of Canaan, saw the nakedness of his father, and told his two brethren without."}, {"numero": 23, "texto": "And Shem and Japheth took a garment, and laid it upon both their shoulders, and went backward, and covered the nakedness of their father; and their faces were backward, and they saw not their father''s nakedness."}, {"numero": 24, "texto": "And Noah awoke from his wine, and knew what his younger son had done unto him."}, {"numero": 25, "texto": "And he said, Cursed be Canaan; a servant of servants shall he be unto his brethren."}, {"numero": 26, "texto": "And he said, Blessed be the Lord God of Shem; and Canaan shall be his servant."}, {"numero": 27, "texto": "God shall enlarge Japheth, and he shall dwell in the tents of Shem; and Canaan shall be his servant."}, {"numero": 28, "texto": "And Noah lived after the flood three hundred and fifty years."}, {"numero": 29, "texto": "And all the days of Noah were nine hundred and fifty years: and he died."}]'::jsonb, 'King James Version'),
  ('Gn', 9, 'fr', '[{"numero": 1, "texto": "Dieu bénit Noé et ses fils, et leur dit: Soyez féconds, multipliez, et remplissez la terre."}, {"numero": 2, "texto": "Vous serez un sujet de crainte et d''''effroi pour tout animal de la terre, pour tout oiseau du ciel, pour tout ce qui se meut sur la terre, et pour tous les poissons de la mer: ils sont livrés entre vos mains."}, {"numero": 3, "texto": "Tout ce qui se meut et qui a vie vous servira de nourriture: je vous donne tout cela comme l''''herbe verte."}, {"numero": 4, "texto": "Seulement, vous ne mangerez point de chair avec son âme, avec son sang."}, {"numero": 5, "texto": "Sachez-le aussi, je redemanderai le sang de vos âmes, je le redemanderai à tout animal; et je redemanderai l''''âme de l''''homme à l''''homme, à l''''homme qui est son frère."}, {"numero": 6, "texto": "Si quelqu''''un verse le sang de l''''homme, par l''''homme son sang sera versé; car Dieu a fait l''''homme à son image."}, {"numero": 7, "texto": "Et vous, soyez féconds et multipliez, répandez-vous sur la terre et multipliez sur elle."}, {"numero": 8, "texto": "Dieu parla encore à Noé et à ses fils avec lui, en disant:"}, {"numero": 9, "texto": "Voici, j''''établis mon alliance avec vous et avec votre postérité après vous;"}, {"numero": 10, "texto": "avec tous les êtres vivants qui sont avec vous, tant les oiseaux que le bétail et tous les animaux de la terre, soit avec tous ceux qui sont sortis de l''''arche, soit avec tous les animaux de la terre."}, {"numero": 11, "texto": "J''''établis mon alliance avec vous: aucune chair ne sera plus exterminée par les eaux du déluge, et il n''''y aura plus de déluge pour détruire la terre."}, {"numero": 12, "texto": "Et Dieu dit: C''''est ici le signe de l''''alliance que j''''établis entre moi et vous, et tous les êtres vivants qui sont avec vous, pour les générations à toujours:"}, {"numero": 13, "texto": "j''''ai placé mon arc dans la nue, et il servira de signe d''''alliance entre moi et la terre."}, {"numero": 14, "texto": "Quand j''''aurai rassemblé des nuages au-dessus de la terre, l''''arc paraîtra dans la nue;"}, {"numero": 15, "texto": "et je me souviendrai de mon alliance entre moi et vous, et tous les êtres vivants, de toute chair, et les eaux ne deviendront plus un déluge pour détruire toute chair."}, {"numero": 16, "texto": "L''''arc sera dans la nue; et je le regarderai, pour me souvenir de l''''alliance perpétuelle entre Dieu et tous les êtres vivants, de toute chair qui est sur la terre."}, {"numero": 17, "texto": "Et Dieu dit à Noé: Tel est le signe de l''''alliance que j''''établis entre moi et toute chair qui est sur la terre."}, {"numero": 18, "texto": "Les fils de Noé, qui sortirent de l''''arche, étaient Sem, Cham et Japhet. Cham fut le père de Canaan."}, {"numero": 19, "texto": "Ce sont là les trois fils de Noé, et c''''est leur postérité qui peupla toute la terre."}, {"numero": 20, "texto": "Noé commença à cultiver la terre, et planta de la vigne."}, {"numero": 21, "texto": "Il but du vin, s''''enivra, et se découvrit au milieu de sa tente."}, {"numero": 22, "texto": "Cham, père de Canaan, vit la nudité de son père, et il le rapporta dehors à ses deux frères."}, {"numero": 23, "texto": "Alors Sem et Japhet prirent le manteau, le mirent sur leurs épaules, marchèrent à reculons, et couvrirent la nudité de leur père; comme leur visage était détourné, ils ne virent point la nudité de leur père."}, {"numero": 24, "texto": "Lorsque Noé se réveilla de son vin, il apprit ce que lui avait fait son fils cadet."}, {"numero": 25, "texto": "Et il dit: Maudit soit Canaan! qu''''il soit l''''esclave des esclaves de ses frères!"}, {"numero": 26, "texto": "Il dit encore: Béni soit l''''Eternel, Dieu de Sem, et que Canaan soit leur esclave!"}, {"numero": 27, "texto": "Que Dieu étende les possessions de Japhet, qu''''il habite dans les tentes de Sem, et que Canaan soit leur esclave!"}, {"numero": 28, "texto": "Noé vécut, après le déluge, trois cent cinquante ans."}, {"numero": 29, "texto": "Tous les jours de Noé furent de neuf cent cinquante ans; puis il mourut."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 9, 'es', '[{"numero": 1, "texto": "Y BENDIJO Dios á Noé y á sus hijos, y díjoles: Fructificad, y multiplicad, y henchid la tierra:"}, {"numero": 2, "texto": "Y vuestro temor y vuestro pavor será sobre todo animal de la tierra, y sobre toda ave de los cielos, en todo lo que se moverá en la tierra, y en todos los peces del mar: en vuestra mano son entregados."}, {"numero": 3, "texto": "Todo lo que se mueve y vive, os será para mantenimiento: así como las legumbres y hierbas, os lo he dado todo."}, {"numero": 4, "texto": "Empero carne con su vida, que es su sangre, no comeréis."}, {"numero": 5, "texto": "Porque ciertamente demandaré la sangre de vuestras vidas; de mano de todo animal la demandaré, y de mano del hombre; de mano del varón su hermano demandaré la vida del hombre."}, {"numero": 6, "texto": "El que derramare sangre del hombre, por el hombre su sangre será derramada; porque á imagen de Dios es hecho el hombre."}, {"numero": 7, "texto": "Mas vosotros fructificad, y multiplicaos; procread abundantemente en la tierra, y multiplicaos en ella."}, {"numero": 8, "texto": "Y habló Dios á Noé y á sus hijos con él, diciendo:"}, {"numero": 9, "texto": "Yo, he aquí que yo establezco mi pacto con vosotros, y con vuestra simiente después de vosotros;"}, {"numero": 10, "texto": "Y con toda alma viviente que está con vosotros, de aves, de animales, y de toda bestia de la tierra que está con vosotros; desde todos los que salieron del arca hasta todo animal de la tierra."}, {"numero": 11, "texto": "Estableceré mi pacto con vosotros, y no fenecerá ya más toda carne con aguas de diluvio; ni habrá más diluvio para destruir la tierra."}, {"numero": 12, "texto": "Y dijo Dios: Esta será la señal del pacto que yo establezco entre mí y vosotros y toda alma viviente que está con vosotros, por siglos perpetuos:"}, {"numero": 13, "texto": "Mi arco pondré en las nubes, el cual será por señal de convenio entre mí y la tierra."}, {"numero": 14, "texto": "Y será que cuando haré venir nubes sobre la tierra, se dejará ver entonces mi arco en las nubes."}, {"numero": 15, "texto": "Y acordarme he del pacto mío, que hay entre mí y vosotros y toda alma viviente de toda carne; y no serán más las aguas por diluvio para destruir toda carne."}, {"numero": 16, "texto": "Y estará el arco en las nubes, y verlo he para acordarme del pacto perpetuo entre Dios y toda alma viviente, con toda carne que hay sobre la tierra."}, {"numero": 17, "texto": "Dijo, pues, Dios á Noé: Esta será la señal del pacto que he establecido entre mí y toda carne que está sobre la tierra."}, {"numero": 18, "texto": "Y los hijos de Noé que salieron del arca fueron Sem, Châm y Japhet: y Châm es el padre de Canaán."}, {"numero": 19, "texto": "Estos tres son los hijos de Noé; y de ellos fué llena toda la tierra."}, {"numero": 20, "texto": "Y comenzó Noé á labrar la tierra, y plantó una viña:"}, {"numero": 21, "texto": "Y bebió del vino, y se embriagó, y estaba descubierto en medio de su tienda."}, {"numero": 22, "texto": "Y Châm, padre de Canaán, vió la desnudez de su padre, y díjolo á sus dos hermanos á la parte de afuera."}, {"numero": 23, "texto": "Entonces Sem y Japhet tomaron la ropa, y la pusieron sobre sus propios hombros, y andando hacia atrás, cubrieron la desnudez de su padre, teniendo vueltos sus rostros, y así no vieron la desnudez de su padre."}, {"numero": 24, "texto": "Y despertó Noé de su vino, y supo lo que había hecho con él su hijo el más joven;"}, {"numero": 25, "texto": "Y dijo: Maldito sea Canaán; siervo de siervos será á sus hermanos."}, {"numero": 26, "texto": "Dijo más: Bendito Jehová el Dios de Sem, y séale Canaán siervo."}, {"numero": 27, "texto": "Engrandezca Dios á Japhet, y habite en las tiendas de Sem, y séale Canaán siervo."}, {"numero": 28, "texto": "Y vivió Noé después del diluvio trescientos y cincuenta años."}, {"numero": 29, "texto": "Y fueron todos los días de Noé novecientos y cincuenta años; y murió."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 11, 'pt', '[{"numero": 1, "texto": "Era, então, toda a terra de uma língua e umas mesmas palavras."}, {"numero": 2, "texto": "E aconteceu que, quando se partiram do oriente, acharam um vale na terra de Sinear; e ali passaram a habitar."}, {"numero": 3, "texto": "E disseram uns aos outros: Vinde, façamos tijolos e o cozamos com fogo. E foi-lhes os tijolos em lugar de pedra, e o betume em lugar de argamassa."}, {"numero": 4, "texto": "E disseram: Vamos, edifiquemo-nos uma cidade e uma torre, cuja ponta chegue ao céu; e façamo-nos um nome, para que não sejamos espalhados sobre a face de toda a terra."}, {"numero": 5, "texto": "E desceu o SENHOR para ver a cidade e a torre que edificavam os filhos dos homens."}, {"numero": 6, "texto": "E disse o SENHOR: Eis que o povo é um, e todos estes têm uma língua; e começaram a agir, e nada lhes restringirá agora do que pensaram fazer."}, {"numero": 7, "texto": "Agora, pois, desçamos, e confundamos ali suas línguas, para que ninguém entenda a fala de seu companheiro."}, {"numero": 8, "texto": "Assim os espalhou o SENHOR desde ali sobre a face de toda a terra, e deixaram de edificar a cidade."}, {"numero": 9, "texto": "Por isto foi chamado o nome dela Babel, porque ali confundiu o SENHOR a língua de toda a terra, e desde ali os espalhou sobre a face de toda a terra."}, {"numero": 10, "texto": "Estas são as gerações de Sem: Sem, de idade de cem anos, gerou a Arfaxade, dois anos depois do dilúvio."}, {"numero": 11, "texto": "E viveu Sem, depois que gerou a Arfaxade quinhentos anos, e gerou filhos e filhas."}, {"numero": 12, "texto": "E Arfaxade viveu trinta e cinco anos, e gerou a Salá."}, {"numero": 13, "texto": "E viveu Arfaxade, depois que gerou a Salá, quatrocentos e três anos, e gerou filhos e filhas."}, {"numero": 14, "texto": "E viveu Salá trinta anos, e gerou a Héber."}, {"numero": 15, "texto": "E viveu Salá, depois que gerou a Héber, quatrocentos e três anos, e gerou filhos e filhas."}, {"numero": 16, "texto": "E viveu Héber trinta e quatro anos, e gerou a Pelegue."}, {"numero": 17, "texto": "E viveu Héber, depois que gerou a Pelegue, quatrocentos e trinta anos, e gerou filhos e filhas."}, {"numero": 18, "texto": "E viveu Pelegue, trinta anos, e gerou a Reú."}, {"numero": 19, "texto": "E viveu Pelegue, depois que gerou a Reú, duzentos e nove anos, e gerou filhos e filhas."}, {"numero": 20, "texto": "E Reú viveu trinta e dois anos, e gerou a Serugue."}, {"numero": 21, "texto": "E viveu Reú, depois que gerou a Serugue, duzentos e sete anos, e gerou filhos e filhas."}, {"numero": 22, "texto": "E viveu Serugue trinta anos, e gerou a Naor."}, {"numero": 23, "texto": "E viveu Serugue, depois que gerou a Naor, duzentos anos, e gerou filhos e filhas."}, {"numero": 24, "texto": "E viveu Naor vinte e nove anos, e gerou a Terá."}, {"numero": 25, "texto": "E viveu Naor, depois que gerou a Terá, cento e dezenove anos, e gerou filhos e filhas."}, {"numero": 26, "texto": "E viveu Terá setenta anos, e gerou a Abrão, e a Naor, e a Harã."}, {"numero": 27, "texto": "Estas são as gerações de Terá: Terá gerou a Abrão, e a Naor, e a Harã; e Harã gerou a Ló."}, {"numero": 28, "texto": "E morreu Harã antes que seu pai Terá na terra de seu nascimento, em Ur dos caldeus."}, {"numero": 29, "texto": "E tomaram Abrão e Naor para si mulheres: o nome da mulher de Abrão foi Sarai, e o nome da mulher de Naor, Milca, filha de Harã, pai de Milca e de Iscá."}, {"numero": 30, "texto": "Mas Sarai era estéril, e não tinha filho."}, {"numero": 31, "texto": "E tomou Terá a Abrão seu filho, e a Ló filho de Harã, filho de seu filho, e a Sarai sua nora, mulher de Abrão seu filho: e saiu com eles de Ur dos caldeus, para ir à terra de Canaã: e vieram até Harã, e assentaram ali."}, {"numero": 32, "texto": "E foram os dias de Terá duzentos e cinco anos; e morreu Terá em Harã."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 11, 'en', '[{"numero": 1, "texto": "And the whole earth was of one language, and of one speech."}, {"numero": 2, "texto": "And it came to pass, as they journeyed from the east, that they found a plain in the land of Shinar; and they dwelt there."}, {"numero": 3, "texto": "And they said one to another, Go to, let us make brick, and burn them thoroughly. And they had brick for stone, and slime had they for morter."}, {"numero": 4, "texto": "And they said, Go to, let us build us a city and a tower, whose top may reach unto heaven; and let us make us a name, lest we be scattered abroad upon the face of the whole earth."}, {"numero": 5, "texto": "And the Lord came down to see the city and the tower, which the children of men builded."}, {"numero": 6, "texto": "And the Lord said, Behold, the people is one, and they have all one language; and this they begin to do: and now nothing will be restrained from them, which they have imagined to do."}, {"numero": 7, "texto": "Go to, let us go down, and there confound their language, that they may not understand one another''s speech."}, {"numero": 8, "texto": "So the Lord scattered them abroad from thence upon the face of all the earth: and they left off to build the city."}, {"numero": 9, "texto": "Therefore is the name of it called Babel; because the Lord did there confound the language of all the earth: and from thence did the Lord scatter them abroad upon the face of all the earth."}, {"numero": 10, "texto": "These are the generations of Shem: Shem was an hundred years old, and begat Arphaxad two years after the flood:"}, {"numero": 11, "texto": "And Shem lived after he begat Arphaxad five hundred years, and begat sons and daughters."}, {"numero": 12, "texto": "And Arphaxad lived five and thirty years, and begat Salah:"}, {"numero": 13, "texto": "And Arphaxad lived after he begat Salah four hundred and three years, and begat sons and daughters."}, {"numero": 14, "texto": "And Salah lived thirty years, and begat Eber:"}, {"numero": 15, "texto": "And Salah lived after he begat Eber four hundred and three years, and begat sons and daughters."}, {"numero": 16, "texto": "And Eber lived four and thirty years, and begat Peleg:"}, {"numero": 17, "texto": "And Eber lived after he begat Peleg four hundred and thirty years, and begat sons and daughters."}, {"numero": 18, "texto": "And Peleg lived thirty years, and begat Reu:"}, {"numero": 19, "texto": "And Peleg lived after he begat Reu two hundred and nine years, and begat sons and daughters."}, {"numero": 20, "texto": "And Reu lived two and thirty years, and begat Serug:"}, {"numero": 21, "texto": "And Reu lived after he begat Serug two hundred and seven years, and begat sons and daughters."}, {"numero": 22, "texto": "And Serug lived thirty years, and begat Nahor:"}, {"numero": 23, "texto": "And Serug lived after he begat Nahor two hundred years, and begat sons and daughters."}, {"numero": 24, "texto": "And Nahor lived nine and twenty years, and begat Terah:"}, {"numero": 25, "texto": "And Nahor lived after he begat Terah an hundred and nineteen years, and begat sons and daughters."}, {"numero": 26, "texto": "And Terah lived seventy years, and begat Abram, Nahor, and Haran."}, {"numero": 27, "texto": "Now these are the generations of Terah: Terah begat Abram, Nahor, and Haran; and Haran begat Lot."}, {"numero": 28, "texto": "And Haran died before his father Terah in the land of his nativity, in Ur of the Chaldees."}, {"numero": 29, "texto": "And Abram and Nahor took them wives: the name of Abram''s wife was Sarai; and the name of Nahor''s wife, Milcah, the daughter of Haran, the father of Milcah, and the father of Iscah."}, {"numero": 30, "texto": "But Sarai was barren; she had no child."}, {"numero": 31, "texto": "And Terah took Abram his son, and Lot the son of Haran his son''s son, and Sarai his daughter in law, his son Abram''s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there."}, {"numero": 32, "texto": "And the days of Terah were two hundred and five years: and Terah died in Haran."}]'::jsonb, 'King James Version'),
  ('Gn', 11, 'fr', '[{"numero": 1, "texto": "Toute la terre avait une seule langue et les mêmes mots."}, {"numero": 2, "texto": "Comme ils étaient partis de l''''orient, ils trouvèrent une plaine au pays de Schinear, et ils y habitèrent."}, {"numero": 3, "texto": "Ils se dirent l''''un à l''''autre: Allons! faisons des briques, et cuisons-les au feu. Et la brique leur servit de pierre, et le bitume leur servit de ciment."}, {"numero": 4, "texto": "Ils dirent encore: Allons! bâtissons-nous une ville et une tour dont le sommet touche au ciel, et faisons-nous un nom, afin que nous ne soyons pas dispersés sur la face de toute la terre."}, {"numero": 5, "texto": "L''''Eternel descendit pour voir la ville et la tour que bâtissaient les fils des hommes."}, {"numero": 6, "texto": "Et l''''Eternel dit: Voici, ils forment un seul peuple et ont tous une même langue, et c''''est là ce qu''''ils ont entrepris; maintenant rien ne les empêcherait de faire tout ce qu''''ils auraient projeté."}, {"numero": 7, "texto": "Allons! descendons, et là confondons leur langage, afin qu''''ils n''''entendent plus la langue, les uns des autres."}, {"numero": 8, "texto": "Et l''''Eternel les dispersa loin de là sur la face de toute la terre; et ils cessèrent de bâtir la ville."}, {"numero": 9, "texto": "C''''est pourquoi on l''''appela du nom de Babel, car c''''est là que l''''Eternel confondit le langage de toute la terre, et c''''est de là que l''''Eternel les dispersa sur la face de toute la terre."}, {"numero": 10, "texto": "Voici la postérité de Sem. Sem, âgé de cent ans, engendra Arpacschad, deux ans après le déluge."}, {"numero": 11, "texto": "Sem vécut, après la naissance d''''Arpacschad, cinq cents ans; et il engendra des fils et des filles."}, {"numero": 12, "texto": "Arpacschad, âgé de trente-cinq ans, engendra Schélach."}, {"numero": 13, "texto": "Arpacschad vécut, après la naissance de Schélach, quatre cent trois ans; et il engendra des fils et des filles."}, {"numero": 14, "texto": "Schélach, âgé de trente ans, engendra Héber."}, {"numero": 15, "texto": "Schélach vécut, après la naissance d''''Héber, quatre cent trois ans; et il engendra des fils et des filles."}, {"numero": 16, "texto": "Héber, âgé de trente-quatre ans, engendra Péleg."}, {"numero": 17, "texto": "Héber vécut, après la naissance de Péleg, quatre cent trente ans; et il engendra des fils et des filles."}, {"numero": 18, "texto": "Péleg, âgé de trente ans, engendra Rehu."}, {"numero": 19, "texto": "Péleg vécut, après la naissance de Rehu, deux cent neuf ans; et il engendra des fils et des filles."}, {"numero": 20, "texto": "Rehu, âgé de trente-deux ans, engendra Serug."}, {"numero": 21, "texto": "Rehu vécut, après la naissance de Serug, deux cent sept ans; et il engendra des fils et des filles."}, {"numero": 22, "texto": "Serug, âgé de trente ans, engendra Nachor."}, {"numero": 23, "texto": "Serug vécut, après la naissance de Nachor, deux cents ans; et il engendra des fils et des filles."}, {"numero": 24, "texto": "Nachor, âgé de vingt-neuf ans, engendra Térach."}, {"numero": 25, "texto": "Nachor vécut, après la naissance de Térach, cent dix-neuf ans; et il engendra des fils et des filles."}, {"numero": 26, "texto": "Térach, âgé de soixante-dix ans, engendra Abram, Nachor et Haran."}, {"numero": 27, "texto": "Voici la postérité de Térach. Térach engendra Abram, Nachor et Haran. -Haran engendra Lot."}, {"numero": 28, "texto": "Et Haran mourut en présence de Térach, son père, au pays de sa naissance, à Ur en Chaldée. -"}, {"numero": 29, "texto": "Abram et Nachor prirent des femmes: le nom de la femme d''''Abram était Saraï, et le nom de la femme de Nachor était Milca, fille d''''Haran, père de Milca et père de Jisca."}, {"numero": 30, "texto": "Saraï était stérile: elle n''''avait point d''''enfants."}, {"numero": 31, "texto": "Térach prit Abram, son fils, et Lot, fils d''''Haran, fils de son fils, et Saraï, sa belle-fille, femme d''''Abram, son fils. Ils sortirent ensemble d''''Ur en Chaldée, pour aller au pays de Canaan. Ils vinrent jusqu''''à Charan, et ils y habitèrent."}, {"numero": 32, "texto": "Les jours de Térach furent de deux cent cinq ans; et Térach mourut à Charan."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 11, 'es', '[{"numero": 1, "texto": "ERA entonces toda la tierra de una lengua y unas mismas palabras."}, {"numero": 2, "texto": "Y aconteció que, como se partieron de oriente, hallaron una vega en la tierra de Shinar, y asentaron allí."}, {"numero": 3, "texto": "Y dijeron los unos á los otros: Vaya, hagamos ladrillo y cozámoslo con fuego. Y fuéles el ladrillo en lugar de piedra, y el betún en lugar de mezcla."}, {"numero": 4, "texto": "Y dijeron: Vamos, edifiquémonos una ciudad y una torre, cuya cúspide llegue al cielo; y hagámonos un nombre, por si fuéremos esparcidos sobre la faz de toda la tierra."}, {"numero": 5, "texto": "Y descendió Jehová para ver la ciudad y la torre que edificaban los hijos de los hombres."}, {"numero": 6, "texto": "Y dijo Jehová: He aquí el pueblo es uno, y todos éstos tienen un lenguaje: y han comenzado á obrar, y nada les retraerá ahora de lo que han pensando hacer."}, {"numero": 7, "texto": "Ahora pues, descendamos, y confundamos allí sus lenguas, para que ninguno entienda el habla de su compañero."}, {"numero": 8, "texto": "Así los esparció Jehová desde allí sobre la faz de toda la tierra, y dejaron de edificar la ciudad."}, {"numero": 9, "texto": "Por esto fué llamado el nombre de ella Babel, porque allí confundió Jehová el lenguaje de toda la tierra, y desde allí los esparció sobre la faz de toda la tierra."}, {"numero": 10, "texto": "Estas son las generaciones de Sem: Sem, de edad de cien años, engendró á Arphaxad, dos años después del diluvio."}, {"numero": 11, "texto": "Y vivió Sem, después que engendró á Arphaxad, quinientos años, y engendró hijos é hijas."}, {"numero": 12, "texto": "Y Arphaxad vivió treinta y cinco años, y engendró á Sala."}, {"numero": 13, "texto": "Y vivió Arphaxad, después que engendró á Sala, cuatrocientos y tres años, y engendró hijos é hijas."}, {"numero": 14, "texto": "Y vivió Sala treinta años, y engendró á Heber."}, {"numero": 15, "texto": "Y vivió Sala, después que engendró á Heber, cuatrocientos y tres años, y engendró hijos é hijas."}, {"numero": 16, "texto": "Y vivió Heber treinta y cuatro años, y engendró á Peleg."}, {"numero": 17, "texto": "Y vivió Heber, después que engendró á Peleg, cuatrocientos y treinta años, y engendró hijos é hijas."}, {"numero": 18, "texto": "Y vivió Peleg treinta años, y engendró á Reu."}, {"numero": 19, "texto": "Y vivió Peleg, después que engendró á Reu, doscientos y nueve años, y engendró hijos é hijas."}, {"numero": 20, "texto": "Y Reu vivió treinta y dos años, y engendró á Serug."}, {"numero": 21, "texto": "Y vivió Reu, después que engendró á Serug, doscientos y siete años, y engendró hijos é hijas."}, {"numero": 22, "texto": "Y vivió Serug treinta años, y engendró á Nachôr."}, {"numero": 23, "texto": "Y vivió Serug, después que engendró á Nachôr, doscientos años, y engendró hijos é hijas."}, {"numero": 24, "texto": "Y vivió Nachôr veintinueve años, y engendró á Thare."}, {"numero": 25, "texto": "Y vivió Nachôr, después que engendró á Thare, ciento diecinueve años, y engendró hijos é hijas."}, {"numero": 26, "texto": "Y vivió Thare setenta años, y engendró á Abram, y á Nachôr, y á Harán."}, {"numero": 27, "texto": "Estas son las generaciones de Thare: Thare engendró á Abram, y á Nachôr, y á Harán; y Harán engendró á Lot."}, {"numero": 28, "texto": "Y murió Harán antes que su padre Thare en la tierra de su naturaleza, en Ur de los Caldeos."}, {"numero": 29, "texto": "Y tomaron Abram y Nachôr para sí mujeres: el nombre de la mujer de Abram fué Sarai, y el nombre de la mujer de Nachôr, Milca, hija de Harán, padre de Milca y de Isca."}, {"numero": 30, "texto": "Mas Sarai fué estéril, y no tenía hijo."}, {"numero": 31, "texto": "Y tomó Thare á Abram su hijo, y á Lot hijo de Harán, hijo de su hijo, y á Sarai su nuera, mujer de Abram su hijo: y salió con ellos de Ur de los Caldeos, para ir á la tierra de Canaán: y vinieron hasta Harán, y asentaron allí."}, {"numero": 32, "texto": "Y fueron los días de Thare doscientos y cinco años; y murió Thare en Harán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 12, 'pt', '[{"numero": 1, "texto": "O SENHOR disse a Abrão: “Sai da tua terra, e da tua parentela, e da casa de teu pai, para terra que eu te mostrarei."}, {"numero": 2, "texto": "E farei de ti uma grande nação, e te abençoarei, e engrandecerei o teu nome, e tu serás uma bênção."}, {"numero": 3, "texto": "E abençoarei os que te abençoarem, e amaldiçoarei os que te amaldiçoarem; e em ti todas as famílias da terra serão benditas.”"}, {"numero": 4, "texto": "Assim se foi Abrão, como o SENHOR lhe dissera; e Ló foi com ele. Abrão tinha setenta e cinco anos de idade quando saiu de Harã."}, {"numero": 5, "texto": "E Abrão tomou a Sarai, sua mulher, e a Ló, filho de seu irmão, e todos os seus pertences que haviam ganhado, e as pessoas que eles haviam adquirido em Harã, e saíram para ir à terra de Canaã; e à terra de Canaã chegaram."}, {"numero": 6, "texto": "E passou Abrão por aquela terra até o lugar de Siquém, até o carvalho de Moré; e os cananeus estavam então na terra."}, {"numero": 7, "texto": "E o SENHOR apareceu a Abrão, e lhe disse: À tua descendência darei esta terra. E ele edificou ali um altar ao SENHOR, que lhe havia aparecido."}, {"numero": 8, "texto": "E passou-se dali a um monte ao oriente de Betel, e estendeu sua tenda, tendo a Betel ao ocidente e Ai ao oriente: e edificou ali altar ao SENHOR e invocou o nome do SENHOR."}, {"numero": 9, "texto": "E moveu Abrão dali, caminhando e indo até o Sul."}, {"numero": 10, "texto": "E houve fome na terra, e desceu Abrão ao Egito para peregrinar ali; porque era grande a fome na terra."}, {"numero": 11, "texto": "E aconteceu que quando estava para entrar no Egito, disse a Sarai sua mulher: Eis que, agora conheço que és mulher bela à vista;"}, {"numero": 12, "texto": "E será que quando te houverem visto os egípcios, dirão: Sua mulher é: e matarão a mim, e a ti te preservarão a vida."}, {"numero": 13, "texto": "Agora, pois, dize que és minha irmã, para que eu vá bem por tua causa, e viva minha alma por causa de ti."}, {"numero": 14, "texto": "E aconteceu que, quando entrou Abrão no Egito, os egípcios viram a mulher que era bela em grande maneira."}, {"numero": 15, "texto": "Viram-na também os príncipes de Faraó, e a elogiaram; e foi levada a mulher a casa de Faraó:"}, {"numero": 16, "texto": "E fez bem a Abrão por causa dela; e teve ovelhas, e vacas, e asnos, e servos, e criadas, e asnas e camelos."}, {"numero": 17, "texto": "Mas o SENHOR feriu a Faraó e à sua casa com grandes pragas, por causa de Sarai mulher de Abrão."}, {"numero": 18, "texto": "Então Faraó chamou a Abrão e lhe disse: Que é isto que fizeste comigo? Por que não me declaraste que era tua mulher?"}, {"numero": 19, "texto": "Por que disseste: “É minha irmã”, pondo-me em risco de tomá-la para mim por mulher? Agora, pois, eis aqui tua mulher, toma-a e vai-te."}, {"numero": 20, "texto": "Então Faraó deu ordem a seus homens acerca de Abrão; e lhe acompanharam, e à sua mulher com tudo o que tinha."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 12, 'en', '[{"numero": 1, "texto": "Now the Lord had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father''s house, unto a land that I will shew thee:"}, {"numero": 2, "texto": "And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing:"}, {"numero": 3, "texto": "And I will bless them that bless thee, and curse him that curseth thee: and in thee shall all families of the earth be blessed."}, {"numero": 4, "texto": "So Abram departed, as the Lord had spoken unto him; and Lot went with him: and Abram was seventy and five years old when he departed out of Haran."}, {"numero": 5, "texto": "And Abram took Sarai his wife, and Lot his brother''s son, and all their substance that they had gathered, and the souls that they had gotten in Haran; and they went forth to go into the land of Canaan; and into the land of Canaan they came."}, {"numero": 6, "texto": "And Abram passed through the land unto the place of Sichem, unto the plain of Moreh. And the Canaanite was then in the land."}, {"numero": 7, "texto": "And the Lord appeared unto Abram, and said, Unto thy seed will I give this land: and there builded he an altar unto the Lord, who appeared unto him."}, {"numero": 8, "texto": "And he removed from thence unto a mountain on the east of Bethel, and pitched his tent, having Bethel on the west, and Hai on the east: and there he builded an altar unto the Lord, and called upon the name of the Lord."}, {"numero": 9, "texto": "And Abram journeyed, going on still toward the south."}, {"numero": 10, "texto": "And there was a famine in the land: and Abram went down into Egypt to sojourn there; for the famine was grievous in the land."}, {"numero": 11, "texto": "And it came to pass, when he was come near to enter into Egypt, that he said unto Sarai his wife, Behold now, I know that thou art a fair woman to look upon:"}, {"numero": 12, "texto": "Therefore it shall come to pass, when the Egyptians shall see thee, that they shall say, This is his wife: and they will kill me, but they will save thee alive."}, {"numero": 13, "texto": "Say, I pray thee, thou art my sister: that it may be well with me for thy sake; and my soul shall live because of thee."}, {"numero": 14, "texto": "And it came to pass, that, when Abram was come into Egypt, the Egyptians beheld the woman that she was very fair."}, {"numero": 15, "texto": "The princes also of Pharaoh saw her, and commended her before Pharaoh: and the woman was taken into Pharaoh''s house."}, {"numero": 16, "texto": "And he entreated Abram well for her sake: and he had sheep, and oxen, and he asses, and menservants, and maidservants, and she asses, and camels."}, {"numero": 17, "texto": "And the Lord plagued Pharaoh and his house with great plagues because of Sarai Abram''s wife."}, {"numero": 18, "texto": "And Pharaoh called Abram and said, What is this that thou hast done unto me? why didst thou not tell me that she was thy wife?"}, {"numero": 19, "texto": "Why saidst thou, She is my sister? so I might have taken her to me to wife: now therefore behold thy wife, take her, and go thy way."}, {"numero": 20, "texto": "And Pharaoh commanded his men concerning him: and they sent him away, and his wife, and all that he had."}]'::jsonb, 'King James Version'),
  ('Gn', 12, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Abram: Va-t-en de ton pays, de ta patrie, et de la maison de ton père, dans le pays que je te montrerai."}, {"numero": 2, "texto": "Je ferai de toi une grande nation, et je te bénirai; je rendrai ton nom grand, et tu seras une source de bénédiction."}, {"numero": 3, "texto": "Je bénirai ceux qui te béniront, et je maudirai ceux qui te maudiront; et toutes les familles de la terre seront bénies en toi."}, {"numero": 4, "texto": "Abram partit, comme l''''Eternel le lui avait dit, et Lot partit avec lui. Abram était âgé de soixante-quinze ans, lorsqu''''il sortit de Charan."}, {"numero": 5, "texto": "Abram prit Saraï, sa femme, et Lot, fils de son frère, avec tous les biens qu''''ils possédaient et les serviteurs qu''''ils avaient acquis à Charan. Ils partirent pour aller dans le pays de Canaan, et ils arrivèrent au pays de Canaan."}, {"numero": 6, "texto": "Abram parcourut le pays jusqu''''au lieu nommé Sichem, jusqu''''aux chênes de Moré. Les Cananéens étaient alors dans le pays."}, {"numero": 7, "texto": "L''''Eternel apparut à Abram, et dit: Je donnerai ce pays à ta postérité. Et Abram bâtit là un autel à l''''Eternel, qui lui était apparu."}, {"numero": 8, "texto": "Il se transporta de là vers la montagne, à l''''orient de Béthel, et il dressa ses tentes, ayant Béthel à l''''occident et Aï à l''''orient. Il bâtit encore là un autel à l''''Eternel, et il invoqua le nom de l''''Eternel."}, {"numero": 9, "texto": "Abram continua ses marches, en s''''avançant vers le midi."}, {"numero": 10, "texto": "Il y eut une famine dans le pays; et Abram descendit en Egypte pour y séjourner, car la famine était grande dans le pays."}, {"numero": 11, "texto": "Comme il était près d''''entrer en Egypte, il dit à Saraï, sa femme: Voici, je sais que tu es une femme belle de figure."}, {"numero": 12, "texto": "Quand les Egyptiens te verront, ils diront: C''''est sa femme! Et ils me tueront, et te laisseront la vie."}, {"numero": 13, "texto": "Dis, je te prie, que tu es ma soeur, afin que je sois bien traité à cause de toi, et que mon âme vive grâce à toi."}, {"numero": 14, "texto": "Lorsque Abram fut arrivé en Egypte, les Egyptiens virent que la femme était fort belle."}, {"numero": 15, "texto": "Les grands de Pharaon la virent aussi et la vantèrent à Pharaon; et la femme fut emmenée dans la maison de Pharaon."}, {"numero": 16, "texto": "Il traita bien Abram à cause d''''elle; et Abram reçut des brebis, des boeufs, des ânes, des serviteurs et des servantes, des ânesses, et des chameaux."}, {"numero": 17, "texto": "Mais l''''Eternel frappa de grandes plaies Pharaon et sa maison, au sujet de Saraï, femme d''''Abram."}, {"numero": 18, "texto": "Alors Pharaon appela Abram, et dit: Qu''''est-ce que tu m''''as fait? Pourquoi ne m''''as-tu pas déclaré que c''''est ta femme?"}, {"numero": 19, "texto": "Pourquoi as-tu dit: C''''est ma soeur? Aussi l''''ai-je prise pour ma femme. Maintenant, voici ta femme, prends-la, et va-t-en!"}, {"numero": 20, "texto": "Et Pharaon donna ordre à ses gens de le renvoyer, lui et sa femme, avec tout ce qui lui appartenait."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 12, 'es', '[{"numero": 1, "texto": "EMPERO Jehová había dicho á Abram: Vete de tu tierra y de tu parentela, y de la casa de tu padre, á la tierra que te mostraré;"}, {"numero": 2, "texto": "Y haré de ti una nación grande, y bendecirte he, y engrandeceré tu nombre, y serás bendición:"}, {"numero": 3, "texto": "Y bendeciré á los que te bendijeren, y á los que te maldijeren maldeciré: y serán benditas en ti todas las familias de la tierra."}, {"numero": 4, "texto": "Y fuése Abram, como Jehová le dijo; y fué con él Lot: y era Abram de edad de setenta y cinco años cuando salió de Harán."}, {"numero": 5, "texto": "Y tomó Abram á Sarai su mujer, y á Lot hijo de su hermano, y toda su hacienda que habían ganado, y las almas que habían adquirido en Harán, y salieron para ir á tierra de Canaán; y á tierra de Canaán llegaron."}, {"numero": 6, "texto": "Y pasó Abram por aquella tierra hasta el lugar de Sichêm, hasta el valle de Moreh: y el Cananeo estaba entonces en la tierra."}, {"numero": 7, "texto": "Y apareció Jehová á Abram, y le dijo: A tu simiente daré esta tierra. Y edificó allí un altar á Jehová, que le había aparecido."}, {"numero": 8, "texto": "Y pasóse de allí á un monte al oriente de Bethel, y tendió su tienda, teniendo á Bethel al occidente y Hai al oriente: y edificó allí altar á Jehová, é invocó el nombre de Jehová."}, {"numero": 9, "texto": "Y movió Abram de allí, caminando y yendo hacia el Mediodía."}, {"numero": 10, "texto": "Y hubo hambre en la tierra, y descendió Abram á Egipto para peregrinar allá; porque era grande el hambre en la tierra."}, {"numero": 11, "texto": "Y aconteció que cuando estaba para entrar en Egipto, dijo á Sarai su mujer: He aquí, ahora conozco que eres mujer hermosa de vista;"}, {"numero": 12, "texto": "Y será que cuando te habrán visto los Egipcios, dirán: Su mujer es: y me matarán á mí, y á ti te reservarán la vida."}, {"numero": 13, "texto": "Ahora pues, di que eres mi hermana, para que yo haya bien por causa tuya, y viva mi alma por amor de ti."}, {"numero": 14, "texto": "Y aconteció que, como entró Abram en Egipto, los Egipcios vieron la mujer que era hermosa en gran manera."}, {"numero": 15, "texto": "Viéronla también los príncipes de Faraón, y se la alabaron; y fué llevada la mujer á casa de Faraón:"}, {"numero": 16, "texto": "E hizo bien á Abram por causa de ella; y tuvo ovejas, y vacas, y asnos, y siervos, y criadas, y asnas y camellos."}, {"numero": 17, "texto": "Mas Jehová hirió á Faraón y á su casa con grandes plagas, por causa de Sarai mujer de Abram."}, {"numero": 18, "texto": "Entonces Faraón llamó á Abram, y le dijo: ¿Qué es esto que has hecho conmigo? ¿Por qué no me declaraste que era tu mujer?"}, {"numero": 19, "texto": "¿Por qué dijiste: Es mi hermana? poniéndome en ocasión de tomarla para mí por mujer? Ahora pues, he aquí tu mujer, tómala y vete."}, {"numero": 20, "texto": "Entonces Faraón dió orden á sus gentes acerca de Abram; y le acompañaron, y á su mujer con todo lo que tenía."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 14, 'pt', '[{"numero": 1, "texto": "E aconteceu nos dias de Anrafel, rei de Sinear, Arioque, rei de Elasar, Quedorlaomer, rei de Elão, e Tidal, rei de nações,"}, {"numero": 2, "texto": "Que estes fizeram guerra contra Bera, rei de Sodoma, e contra Birsa, rei de Gomorra, e contra Sinabe, rei de Admá, e contra Semeber, rei de Zeboim, e contra o rei de Belá, a qual é Zoar."}, {"numero": 3, "texto": "Todos estes se juntaram no vale de Sidim, que é o mar salgado."}, {"numero": 4, "texto": "Doze anos haviam servido a Quedorlaomer, e ao décimo terceiro ano se rebelaram."}, {"numero": 5, "texto": "E no ano décimo quarto veio Quedorlaomer, e os reis que estavam de sua parte, e derrotaram aos refains em Asterote-Carnaim, aos zuzins em Hã, e aos emins em Savé-Quiriataim."}, {"numero": 6, "texto": "E aos horeus no monte de Seir, até a El-Parã, que está junto ao deserto."}, {"numero": 7, "texto": "E voltaram e vieram a En-Mispate, que é Cades, e devastaram todas as terras dos amalequitas, e também aos amorreus, que habitavam em Hazazom-Tamar."}, {"numero": 8, "texto": "E saiu o rei de Sodoma, e o rei de Gomorra, e o rei de Admá, e o rei de Zeboim, e o rei de Belá, que é Zoar, e ordenaram contra eles batalha no vale de Sidim;"}, {"numero": 9, "texto": "A saber, contra Quedorlaomer, rei de Elão, e Tidal, rei de nações, e Anrafel, rei de Sinear, e Arioque, rei de Elasar; quatro reis contra cinco."}, {"numero": 10, "texto": "E o vale de Sidim estava cheio de poços de betume: e fugiram o rei de Sodoma e o de Gomorra, e caíram ali; e os demais fugiram ao monte."}, {"numero": 11, "texto": "E tomaram toda a riqueza de Sodoma e de Gomorra, e todos os seus mantimentos, e se foram."}, {"numero": 12, "texto": "Tomaram também Ló, filho do irmão de Abrão, que morava em Sodoma, e sua riqueza, e se foram."}, {"numero": 13, "texto": "E veio um dos que escaparam, e denunciou-o a Abrão o hebreu, que habitava no vale de Manre, amorreu, irmão de Escol e irmão de Aner, os quais tinham feito pacto com Abrão."}, {"numero": 14, "texto": "E ouviu Abrão que seu irmão estava prisioneiro, e armou seus criados, os criados de sua casa, trezentos e dezoito, e seguiu-os até Dã."}, {"numero": 15, "texto": "E derramou-se sobre eles de noite ele e seus servos, e feriu-os, e foi os seguindo até Hobá, que está à esquerda de Damasco."}, {"numero": 16, "texto": "E recuperou todos os bens, e também a Ló seu irmão e sua riqueza, e também as mulheres e gente."}, {"numero": 17, "texto": "E saiu o rei de Sodoma a recebê-lo, quando voltava da derrota de Quedorlaomer e dos reis que com ele estavam, ao vale de Savé, que é o vale do Rei."}, {"numero": 18, "texto": "Então Melquisedeque, rei de Salém, tirou pão e vinho; o qual era sacerdote do Deus altíssimo;"}, {"numero": 19, "texto": "E abençoou-lhe, e disse: Bendito seja Abrão do Deus altíssimo, possuidor dos céus e da terra;"}, {"numero": 20, "texto": "E bendito seja o Deus altíssimo, que entregou teus inimigos em tua mão."}, {"numero": 21, "texto": "Então o rei de Sodoma disse a Abrão: Dá-me as pessoas, e toma para ti a riqueza."}, {"numero": 22, "texto": "E respondeu Abrão ao rei de Sodoma: Levantei minha mão ao SENHOR Deus altíssimo, possuidor dos céus e da terra,"}, {"numero": 23, "texto": "Que desde um fio até a correia de um calçado, nada tomarei de tudo o que é teu, para que não digas: Eu enriqueci a Abrão:"}, {"numero": 24, "texto": "Tirando somente o que os rapazes comeram, e a porção dos homens que foram comigo, Aner, Escol, e Manre; eles tomem a sua parte."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 14, 'en', '[{"numero": 1, "texto": "And it came to pass in the days of Amraphel king of Shinar, Arioch king of Ellasar, Chedorlaomer king of Elam, and Tidal king of nations;"}, {"numero": 2, "texto": "That these made war with Bera king of Sodom, and with Birsha king of Gomorrah, Shinab king of Admah, and Shemeber king of Zeboiim, and the king of Bela, which is Zoar."}, {"numero": 3, "texto": "All these were joined together in the vale of Siddim, which is the salt sea."}, {"numero": 4, "texto": "Twelve years they served Chedorlaomer, and in the thirteenth year they rebelled."}, {"numero": 5, "texto": "And in the fourteenth year came Chedorlaomer, and the kings that were with him, and smote the Rephaims in Ashteroth Karnaim, and the Zuzims in Ham, and the Emins in Shaveh Kiriathaim,"}, {"numero": 6, "texto": "And the Horites in their mount Seir, unto Elparan, which is by the wilderness."}, {"numero": 7, "texto": "And they returned, and came to Enmishpat, which is Kadesh, and smote all the country of the Amalekites, and also the Amorites, that dwelt in Hazezontamar."}, {"numero": 8, "texto": "And there went out the king of Sodom, and the king of Gomorrah, and the king of Admah, and the king of Zeboiim, and the king of Bela (the same is Zoar;) and they joined battle with them in the vale of Siddim;"}, {"numero": 9, "texto": "With Chedorlaomer the king of Elam, and with Tidal king of nations, and Amraphel king of Shinar, and Arioch king of Ellasar; four kings with five."}, {"numero": 10, "texto": "And the vale of Siddim was full of slimepits; and the kings of Sodom and Gomorrah fled, and fell there; and they that remained fled to the mountain."}, {"numero": 11, "texto": "And they took all the goods of Sodom and Gomorrah, and all their victuals, and went their way."}, {"numero": 12, "texto": "And they took Lot, Abram''s brother''s son, who dwelt in Sodom, and his goods, and departed."}, {"numero": 13, "texto": "And there came one that had escaped, and told Abram the Hebrew; for he dwelt in the plain of Mamre the Amorite, brother of Eshcol, and brother of Aner: and these were confederate with Abram."}, {"numero": 14, "texto": "And when Abram heard that his brother was taken captive, he armed his trained servants, born in his own house, three hundred and eighteen, and pursued them unto Dan."}, {"numero": 15, "texto": "And he divided himself against them, he and his servants, by night, and smote them, and pursued them unto Hobah, which is on the left hand of Damascus."}, {"numero": 16, "texto": "And he brought back all the goods, and also brought again his brother Lot, and his goods, and the women also, and the people."}, {"numero": 17, "texto": "And the king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer, and of the kings that were with him, at the valley of Shaveh, which is the king''s dale."}, {"numero": 18, "texto": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}, {"numero": 19, "texto": "And he blessed him, and said, Blessed be Abram of the most high God, possessor of heaven and earth:"}, {"numero": 20, "texto": "And blessed be the most high God, which hath delivered thine enemies into thy hand. And he gave him tithes of all."}, {"numero": 21, "texto": "And the king of Sodom said unto Abram, Give me the persons, and take the goods to thyself."}, {"numero": 22, "texto": "And Abram said to the king of Sodom, I have lift up mine hand unto the Lord, the most high God, the possessor of heaven and earth,"}, {"numero": 23, "texto": "That I will not take from a thread even to a shoelatchet, and that I will not take any thing that is thine, lest thou shouldest say, I have made Abram rich:"}, {"numero": 24, "texto": "Save only that which the young men have eaten, and the portion of the men which went with me, Aner, Eshcol, and Mamre; let them take their portion."}]'::jsonb, 'King James Version'),
  ('Gn', 14, 'fr', '[{"numero": 1, "texto": "Dans le temps d''''Amraphel, roi de Schinear, d''''Arjoc, roi d''''Ellasar, de Kedorlaomer, roi d''''Elam, et de Tideal, roi de Gojim,"}, {"numero": 2, "texto": "il arriva qu''''ils firent la guerre à Béra, roi de Sodome, à Birscha, roi de Gomorrhe, à Schineab, roi d''''Adma, à Schémeéber, roi de Tseboïm, et au roi de Béla, qui est Tsoar."}, {"numero": 3, "texto": "Ces derniers s''''assemblèrent tous dans la vallée de Siddim, qui est la mer Salée."}, {"numero": 4, "texto": "Pendant douze ans, ils avaient été soumis à Kedorlaomer; et la treizième année, ils s''''étaient révoltés."}, {"numero": 5, "texto": "Mais, la quatorzième année, Kedorlaomer et les rois qui étaient avec lui se mirent en marche, et ils battirent les Rephaïm à Aschteroth-Karnaïm, les Zuzim à Ham, les Emim à Schavé-Kirjathaïm,"}, {"numero": 6, "texto": "et les Horiens dans leur montagne de Séir, jusqu''''au chêne de Paran, qui est près du désert."}, {"numero": 7, "texto": "Puis ils s''''en retournèrent, vinrent à En-Mischpath, qui est Kadès, et battirent les Amalécites sur tout leur territoire, ainsi que les Amoréens établis à Hatsatson-Thamar."}, {"numero": 8, "texto": "Alors s''''avancèrent le roi de Sodome, le roi de Gomorrhe, le roi d''''Adma, le roi de Tseboïm, et le roi de Béla, qui est Tsoar; et ils se rangèrent en bataille contre eux, dans la vallée de Siddim,"}, {"numero": 9, "texto": "contre Kedorlaomer, roi d''''Elam, Tideal, roi de Gojim, Amraphel, roi de Schinear, et Arjoc, roi d''''Ellasar: quatre rois contre cinq."}, {"numero": 10, "texto": "La vallée de Siddim était couverte de puits de bitume; le roi de Sodome et celui de Gomorrhe prirent la fuite, et y tombèrent; le reste s''''enfuit vers la montagne."}, {"numero": 11, "texto": "Les vainqueurs enlevèrent toutes les richesses de Sodome et de Gomorrhe, et toutes leurs provisions; et ils s''''en allèrent."}, {"numero": 12, "texto": "Ils enlevèrent aussi, avec ses biens, Lot, fils du frère d''''Abram, qui demeurait à Sodome; et ils s''''en allèrent."}, {"numero": 13, "texto": "Un fuyard vint l''''annoncer à Abram, l''''Hébreu; celui-ci habitait parmi les chênes de Mamré, l''''Amoréen, frère d''''Eschcol et frère d''''Aner, qui avaient fait alliance avec Abram."}, {"numero": 14, "texto": "Dès qu''''Abram eut appris que son frère avait été fait prisonnier, il arma trois cent dix-huit de ses plus braves serviteurs, nés dans sa maison, et il poursuivit les rois jusqu''''à Dan."}, {"numero": 15, "texto": "Il divisa sa troupe, pour les attaquer de nuit, lui et ses serviteurs; il les battit, et les poursuivit jusqu''''à Choba, qui est à la gauche de Damas."}, {"numero": 16, "texto": "Il ramena toutes les richesses; il ramena aussi Lot, son frère, avec ses biens, ainsi que les femmes et le peuple."}, {"numero": 17, "texto": "Après qu''''Abram fut revenu vainqueur de Kedorlaomer et des rois qui étaient avec lui, le roi de Sodome sortit à sa rencontre dans la vallée de Schavé, qui est la vallée du roi."}, {"numero": 18, "texto": "Melchisédek, roi de Salem, fit apporter du pain et du vin: il était sacrificateur du Dieu Très-Haut."}, {"numero": 19, "texto": "Il bénit Abram, et dit: Béni soit Abram par le Dieu Très-Haut, maître du ciel et de la terre!"}, {"numero": 20, "texto": "Béni soit le Dieu Très-Haut, qui a livré tes ennemis entre tes mains! Et Abram lui donna la dîme de tout."}, {"numero": 21, "texto": "Le roi de Sodome dit à Abram: Donne-moi les personnes, et prends pour toi les richesses."}, {"numero": 22, "texto": "Abram répondit au roi de Sodome: Je lève la main vers l''''Eternel, le Dieu Très-Haut, maître du ciel et de la terre:"}, {"numero": 23, "texto": "je ne prendrai rien de tout ce qui est à toi, pas même un fil, ni un cordon de soulier, afin que tu ne dises pas: J''''ai enrichi Abram. Rien pour moi!"}, {"numero": 24, "texto": "Seulement, ce qu''''ont mangé les jeunes gens, et la part des hommes qui ont marché avec moi, Aner, Eschcol et Mamré: eux, ils prendront leur part."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 14, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ en los días de Amraphel, rey de Shinar, Arioch, rey de Elazar, Chêdorlaomer, rey de Elá, y Tidal, rey de naciones,"}, {"numero": 2, "texto": "Que éstos hicieron guerra contra Bera, rey de Sodoma, y contra Birsha, rey de Gomorra, y contra Shinab, rey de Adma, y contra Shemeber, rey de Zeboim, y contra el rey de Bela, la cual es Zoar."}, {"numero": 3, "texto": "Todos estos se juntaron en el valle de Siddim, que es el mar salado."}, {"numero": 4, "texto": "Doce años habían servido á Chêdorlaomer, y al décimotercio año se rebelaron."}, {"numero": 5, "texto": "Y en el año décimocuarto vino Chêdorlaomer, y los reyes que estaban de su parte, y derrotaron á los Raphaitas en Ashteroth-carnaim, á los Zuzitas en Ham, y á los Emitas en Shave-Kiriataim."}, {"numero": 6, "texto": "Y á los Horeos en el monte de Seir, hasta la llanura de Parán, que está junto al desierto."}, {"numero": 7, "texto": "Y volvieron, y vinieron á Emmisphat, que es Cades, y devastaron todas las haciendas de los Amalecitas, y también al Amorrheo, que habitaba en Hazezón-tamar."}, {"numero": 8, "texto": "Y salió el rey de Sodoma, y el rey de Gomorra, y el rey de Adma, y el rey de Zeboim, y el rey de Bela, que es Zoar, y ordenaron contra ellos batalla en el valle de Siddim;"}, {"numero": 9, "texto": "Es á saber, contra Chêdorlaomer, rey de Elam, y Tidal, rey de naciones, y Amraphel, rey de Shinar, y Arioch, rey de Elasar; cuatro reyes contra cinco."}, {"numero": 10, "texto": "Y el valle de Siddim estaba lleno de pozos de betún: y huyeron el rey de Sodoma y el de Gomorra, y cayeron allí; y los demás huyeron al monte."}, {"numero": 11, "texto": "Y tomaron toda la riqueza de Sodoma y de Gomorra, y todas sus vituallas, y se fueron."}, {"numero": 12, "texto": "Tomaron también á Lot, hijo del hermano de Abram, que moraba en Sodoma, y su hacienda, y se fueron."}, {"numero": 13, "texto": "Y vino uno de los que escaparon, y denunciólo á Abram el Hebreo, que habitaba en el valle de Mamre Amorrheo, hermano de Eschôl y hermano de Aner, los cuales estaban confederados con Abram."}, {"numero": 14, "texto": "Y oyó Abram que su hermano estaba prisionero, y armó sus criados, los criados de su casa, trescientos dieciocho, y siguiólos hasta Dan."}, {"numero": 15, "texto": "Y derramóse sobre ellos de noche él y sus siervos, é hiriólos, y fuélos siguiendo hasta Hobah, que está á la izquierda de Damasco."}, {"numero": 16, "texto": "Y recobró todos los bienes, y también á Lot su hermano y su hacienda, y también las mujeres y gente."}, {"numero": 17, "texto": "Y salió el rey de Sodoma á recibirlo, cuando volvía de la derrota de Chêdorlaomer y de los reyes que con él estaban, al valle de Shave, que es el valle del Rey."}, {"numero": 18, "texto": "Entonces Melchîsedec, rey de Salem, sacó pan y vino; el cual era sacerdote del Dios alto;"}, {"numero": 19, "texto": "Y bendíjole, y dijo: Bendito sea Abram del Dios alto, poseedor de los cielos y de la tierra;"}, {"numero": 20, "texto": "Y bendito sea el Dios alto, que entregó tus enemigos en tu mano. Y dióle Abram los diezmos de todo."}, {"numero": 21, "texto": "Entonces el rey de Sodoma dijo á Abram: Dame las personas, y toma para ti la hacienda."}, {"numero": 22, "texto": "Y respondió Abram al rey de Sodoma: He alzado mi mano á Jehová Dios alto, poseedor de los cielos y de la tierra,"}, {"numero": 23, "texto": "Que desde un hilo hasta la correa de un calzado, nada tomaré de todo lo que es tuyo, porque no digas: Yo enriquecí á Abram:"}, {"numero": 24, "texto": "Sacando solamente lo que comieron los mancebos, y la porción de los varones que fueron conmigo, Aner, Eschôl, y Mamre; los cuales tomarán su parte."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 15, 'pt', '[{"numero": 1, "texto": "Depois destas coisas a palavra do SENHOR veio a Abrão em visão, dizendo: Não temas, Abrão; eu sou o teu escudo; a tua recompensa será muito grande."}, {"numero": 2, "texto": "Abrão respondeu: Senhor DEUS, que me darás, sendo que não tenho filho, e o herdeiro da minha casa é Eliézer de Damasco?"}, {"numero": 3, "texto": "Disse mais Abrão: Eis que não me deste descendência, e eis que meu herdeiro é um nascido em minha casa."}, {"numero": 4, "texto": "E logo a palavra do SENHOR veio a ele dizendo: Não esse não herdará de ti, mas sim o que sairá de tuas entranhas será o que de ti herdará."}, {"numero": 5, "texto": "E tirou-lhe fora, e disse: Olha agora aos céus, e conta as estrelas, se as podes contar. E lhe disse: Assim será tua descendência."}, {"numero": 6, "texto": "E creu ao SENHOR, e contou-lhe por justiça."}, {"numero": 7, "texto": "E disse-lhe: Eu sou o SENHOR, que te tirei de Ur dos caldeus, para dar-te a herdar esta terra."}, {"numero": 8, "texto": "E ele respondeu: Senhor DEUS, com que saberei que a vou herdar?"}, {"numero": 9, "texto": "E lhe disse: Separa-me uma bezerra de três anos, e uma cabra de três anos, e um carneiro de três anos, uma rolinha também, e um pombinho."}, {"numero": 10, "texto": "E tomou ele todas estas coisas, e partiu-as pela metade, e pôs cada metade uma em frente de outra; mas não partiu as aves."}, {"numero": 11, "texto": "E desciam aves sobre os corpos mortos, e enxotava-as Abrão."}, {"numero": 12, "texto": "Mas ao pôr do sol veio o sono a Abrão, e eis que o pavor de uma grande escuridão caiu sobre ele."}, {"numero": 13, "texto": "Então disse a Abrão: Tem certeza que a tua descendência será peregrina em terra que não é sua, e serão escravizados e afligidos por quatrocentos anos."}, {"numero": 14, "texto": "Mas também a nação a quem servirão, eu julgarei; e depois disto sairão com grande riqueza."}, {"numero": 15, "texto": "Tu, porém, virás aos teus pais em paz, e serás sepultado em boa velhice."}, {"numero": 16, "texto": "E na quarta geração voltarão para cá; porque ainda não está completa a maldade dos amorreus até aqui."}, {"numero": 17, "texto": "E sucedeu que, depois de posto o sol, e já estando escuro, apareceu um fogo fumegando, e uma tocha de fogo que passou por entre os animais divididos."}, {"numero": 18, "texto": "Naquele dia fez o SENHOR um pacto com Abrão dizendo: À tua descendência darei esta terra desde o rio do Egito até o rio grande, o rio Eufrates;"}, {"numero": 19, "texto": "Os queneus, e os quenezeus, e os cadmoneus,"}, {"numero": 20, "texto": "E os heteus, e os perizeus, e os refains,"}, {"numero": 21, "texto": "E os amorreus, e os cananeus, e os girgaseus, e os jebuseus."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 15, 'en', '[{"numero": 1, "texto": "After these things the word of the Lord came unto Abram in a vision, saying, Fear not, Abram: I am thy shield, and thy exceeding great reward."}, {"numero": 2, "texto": "And Abram said, Lord God, what wilt thou give me, seeing I go childless, and the steward of my house is this Eliezer of Damascus?"}, {"numero": 3, "texto": "And Abram said, Behold, to me thou hast given no seed: and, lo, one born in my house is mine heir."}, {"numero": 4, "texto": "And, behold, the word of the Lord came unto him, saying, This shall not be thine heir; but he that shall come forth out of thine own bowels shall be thine heir."}, {"numero": 5, "texto": "And he brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be."}, {"numero": 6, "texto": "And he believed in the Lord; and he counted it to him for righteousness."}, {"numero": 7, "texto": "And he said unto him, I am the Lord that brought thee out of Ur of the Chaldees, to give thee this land to inherit it."}, {"numero": 8, "texto": "And he said, Lord God, whereby shall I know that I shall inherit it?"}, {"numero": 9, "texto": "And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon."}, {"numero": 10, "texto": "And he took unto him all these, and divided them in the midst, and laid each piece one against another: but the birds divided he not."}, {"numero": 11, "texto": "And when the fowls came down upon the carcases, Abram drove them away."}, {"numero": 12, "texto": "And when the sun was going down, a deep sleep fell upon Abram; and, lo, an horror of great darkness fell upon him."}, {"numero": 13, "texto": "And he said unto Abram, Know of a surety that thy seed shall be a stranger in a land that is not theirs, and shall serve them; and they shall afflict them four hundred years;"}, {"numero": 14, "texto": "And also that nation, whom they shall serve, will I judge: and afterward shall they come out with great substance."}, {"numero": 15, "texto": "And thou shalt go to thy fathers in peace; thou shalt be buried in a good old age."}, {"numero": 16, "texto": "But in the fourth generation they shall come hither again: for the iniquity of the Amorites is not yet full."}, {"numero": 17, "texto": "And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces."}, {"numero": 18, "texto": "In the same day the Lord made a covenant with Abram, saying, Unto thy seed have I given this land, from the river of Egypt unto the great river, the river Euphrates:"}, {"numero": 19, "texto": "The Kenites, and the Kenizzites, and the Kadmonites,"}, {"numero": 20, "texto": "And the Hittites, and the Perizzites, and the Rephaims,"}, {"numero": 21, "texto": "And the Amorites, and the Canaanites, and the Girgashites, and the Jebusites."}]'::jsonb, 'King James Version'),
  ('Gn', 15, 'fr', '[{"numero": 1, "texto": "Après ces événements, la parole de l''''Eternel fut adressée à Abram dans une vision, et il dit: Abram, ne crains point; je suis ton bouclier, et ta récompense sera très grande."}, {"numero": 2, "texto": "Abram répondit: Seigneur Eternel, que me donneras-tu? Je m''''en vais sans enfants; et l''''héritier de ma maison, c''''est Eliézer de Damas."}, {"numero": 3, "texto": "Et Abram dit: Voici, tu ne m''''as pas donné de postérité, et celui qui est né dans ma maison sera mon héritier."}, {"numero": 4, "texto": "Alors la parole de l''''Eternel lui fut adressée ainsi: Ce n''''est pas lui qui sera ton héritier, mais c''''est celui qui sortira de tes entrailles qui sera ton héritier."}, {"numero": 5, "texto": "Et après l''''avoir conduit dehors, il dit: Regarde vers le ciel, et compte les étoiles, si tu peux les compter. Et il lui dit: Telle sera ta postérité."}, {"numero": 6, "texto": "Abram eut confiance en l''''Eternel, qui le lui imputa à justice."}, {"numero": 7, "texto": "L''''Eternel lui dit encore: Je suis l''''Eternel, qui t''''ai fait sortir d''''Ur en Chaldée, pour te donner en possession ce pays."}, {"numero": 8, "texto": "Abram répondit: Seigneur Eternel, à quoi connaîtrai-je que je le posséderai?"}, {"numero": 9, "texto": "Et l''''Eternel lui dit: Prends une génisse de trois ans, une chèvre de trois ans, un bélier de trois ans, une tourterelle et une jeune colombe."}, {"numero": 10, "texto": "Abram prit tous ces animaux, les coupa par le milieu, et mit chaque morceau l''''un vis-à-vis de l''''autre; mais il ne partagea point les oiseaux."}, {"numero": 11, "texto": "Les oiseaux de proie s''''abattirent sur les cadavres; et Abram les chassa."}, {"numero": 12, "texto": "Au coucher du soleil, un profond sommeil tomba sur Abram; et voici, une frayeur et une grande obscurité vinrent l''''assaillir."}, {"numero": 13, "texto": "Et l''''Eternel dit à Abram: Sache que tes descendants seront étrangers dans un pays qui ne sera point à eux; ils y seront asservis, et on les opprimera pendant quatre cents ans."}, {"numero": 14, "texto": "Mais je jugerai la nation à laquelle ils seront asservis, et ils sortiront ensuite avec de grandes richesses."}, {"numero": 15, "texto": "Toi, tu iras en paix vers tes pères, tu seras enterré après une heureuse vieillesse."}, {"numero": 16, "texto": "A la quatrième génération, ils reviendront ici; car l''''iniquité des Amoréens n''''est pas encore à son comble."}, {"numero": 17, "texto": "Quand le soleil fut couché, il y eut une obscurité profonde; et voici, ce fut une fournaise fumante, et des flammes passèrent entre les animaux partagés."}, {"numero": 18, "texto": "En ce jour-là, l''''Eternel fit alliance avec Abram, et dit: Je donne ce pays à ta postérité, depuis le fleuve d''''Egypte jusqu''''au grand fleuve, au fleuve d''''Euphrate,"}, {"numero": 19, "texto": "le pays des Kéniens, des Keniziens, des Kadmoniens,"}, {"numero": 20, "texto": "des Héthiens, des Phéréziens, des Rephaïm,"}, {"numero": 21, "texto": "des Amoréens, des Cananéens, des Guirgasiens et des Jébusiens."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 15, 'es', '[{"numero": 1, "texto": "DESPUÉS de estas cosas fué la palabra de Jehová á Abram en visión, diciendo: No temas, Abram; yo soy tu escudo, y tu galardón sobremanera grande."}, {"numero": 2, "texto": "Y respondió Abram: Señor Jehová ¿qué me has de dar, siendo así que ando sin hijo, y el mayordomo de mi casa es ese Damasceno Eliezer?"}, {"numero": 3, "texto": "Dijo más Abram: Mira que no me has dado prole, y he aquí que es mi heredero uno nacido en mi casa."}, {"numero": 4, "texto": "Y luego la palabra de Jehová fué á él diciendo: No te heredará éste, sino el que saldrá de tus entrañas será el que te herede."}, {"numero": 5, "texto": "Y sacóle fuera, y dijo: Mira ahora á los cielos, y cuenta las estrellas, si las puedes contar. Y le dijo: Así será tu simiente."}, {"numero": 6, "texto": "Y creyó á Jehová, y contóselo por justicia."}, {"numero": 7, "texto": "Y díjole: Yo soy Jehová, que te saqué de Ur de los Caldeos, para darte á heredar esta tierra."}, {"numero": 8, "texto": "Y él respondió: Señor Jehová, ¿en qué conoceré que la tengo de heredar?"}, {"numero": 9, "texto": "Y le dijo: Apártame una becerra de tres años, y una cabra de tres años, y un carnero de tres años, una tórtola también, y un palomino."}, {"numero": 10, "texto": "Y tomó él todas estas cosas, y partiólas por la mitad, y puso cada mitad una enfrente de otra; mas no partió las aves."}, {"numero": 11, "texto": "Y descendían aves sobre los cuerpos muertos, y ojeábalas Abram."}, {"numero": 12, "texto": "Mas á la caída del sol sobrecogió el sueño á Abram, y he aquí que el pavor de una grande obscuridad cayó sobre él."}, {"numero": 13, "texto": "Entonces dijo á Abram: Ten por cierto que tu simiente será peregrina en tierra no suya, y servirá á los de allí, y serán por ellos afligidos cuatrocientos años."}, {"numero": 14, "texto": "Mas también á la gente á quien servirán, juzgaré yo; y después de esto saldrán con grande riqueza."}, {"numero": 15, "texto": "Y tú vendrás á tus padres en paz, y serás sepultado en buena vejez."}, {"numero": 16, "texto": "Y en la cuarta generación volverán acá: porque aun no está cumplida la maldad del Amorrheo hasta aquí."}, {"numero": 17, "texto": "Y sucedió que puesto el sol, y ya obscurecido, dejóse ver un horno humeando, y una antorcha de fuego que pasó por entre los animales divididos."}, {"numero": 18, "texto": "En aquel día hizo Jehová un pacto con Abram diciendo: A tu simiente daré esta tierra desde el río de Egipto hasta el río grande, el río Eufrates;"}, {"numero": 19, "texto": "Los Cineos, y los Ceneceos, y los Cedmoneos,"}, {"numero": 20, "texto": "Y los Hetheos, y los Pherezeos, y los Raphaitas,"}, {"numero": 21, "texto": "Y los Amorrheos, y los Cananeos, y los Gergeseos, y los Jebuseos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 17, 'pt', '[{"numero": 1, "texto": "Quando Abrão tinha a idade de noventa e nove anos, o SENHOR lhe apareceu, e disse-lhe: Eu sou o Deus Todo-Poderoso; anda diante de mim, e sê íntegro."}, {"numero": 2, "texto": "E constituirei meu pacto entre mim e ti, e te multiplicarei em grandíssima maneira."}, {"numero": 3, "texto": "Então Abrão prostrou-se com o rosto ao chão, e Deus falou com ele, dizendo:"}, {"numero": 4, "texto": "Quanto a mim, este é o meu pacto contigo: Serás pai de multidão de nações:"}, {"numero": 5, "texto": "E não se chamará mais teu nome Abrão, mas sim que será teu nome Abraão, porque te pus por pai de multidão de nações."}, {"numero": 6, "texto": "E te multiplicarei muito em grande maneira, e te porei em nações, e reis sairão de ti."}, {"numero": 7, "texto": "E estabelecerei meu pacto entre mim e ti, e tua descendência depois de ti em suas gerações, por aliança perpétua, para ser para ti por Deus, e à tua descendência depois de ti."}, {"numero": 8, "texto": "E darei a ti, e à tua descendência depois de ti, a terra de tuas peregrinações, toda a terra de Canaã em herança perpétua; e serei o Deus deles."}, {"numero": 9, "texto": "Disse de novo Deus a Abraão: Tu, porém, guardarás meu pacto, tu e tua descendência depois de ti por suas gerações."}, {"numero": 10, "texto": "Este será meu pacto, que guardareis entre mim e vós e tua descendência depois de ti: Será circuncidado todo macho dentre vós."}, {"numero": 11, "texto": "Circuncidareis, pois, a carne de vosso prepúcio, e será por sinal do pacto entre mim e vós."}, {"numero": 12, "texto": "E de idade de oito dias será circuncidado todo macho entre vós por vossas gerações: o nascido em casa, e o comprado a dinheiro de qualquer estrangeiro, que não for de tua descendência."}, {"numero": 13, "texto": "Deve ser circuncidado o nascido em tua casa, e o comprado por teu dinheiro: e estará meu pacto em vossa carne para aliança perpétua."}, {"numero": 14, "texto": "E o macho incircunciso que não houver circuncidado a carne de seu prepúcio, aquela pessoa será exterminada de seu povo; violou meu pacto."}, {"numero": 15, "texto": "Disse também Deus a Abraão: A Sarai tua mulher não a chamarás Sarai, mas Sara será seu nome."}, {"numero": 16, "texto": "E a abençoarei, e também te darei dela filho; sim, a abençoarei, e virá a ser mãe de nações; dela surgirão reis de povos."}, {"numero": 17, "texto": "Então Abraão postrou-se com o rosto ao chão, riu, e disse em seu coração: A um homem de cem anos nasceráfilho? E Sara, já de noventa anos, há de dar à luz?"}, {"numero": 18, "texto": "E disse Abraão a Deus: Que Ismael viva diante de ti!"}, {"numero": 19, "texto": "E respondeu Deus: Certamente Sara tua mulher te dará à luz um filho, e chamarás seu nome Isaque; e confirmarei meu pacto com ele por aliança perpétua para sua descendência depois dele."}, {"numero": 20, "texto": "E quanto a Ismael, também te ouvi; eis que o abençoarei, e lhe farei frutificar e multiplicar em grandíssima maneira; doze príncipes gerará, e dele farei grande nação."}, {"numero": 21, "texto": "Mas meu pacto estabelecerei com Isaque, ao qual Sara te dará à luz por este tempo no ano seguinte."}, {"numero": 22, "texto": "E acabou de falar com ele, e Deus subiu da presença de Abraão."}, {"numero": 23, "texto": "Então tomou Abraão a Ismael seu filho, e a todos os servos nascidos em sua casa, e a todos os comprados por seu dinheiro, a todo homem entre os domésticos da casa de Abraão, e circuncidou a carne do prepúcio deles naquele mesmo dia, como Deus lhe havia dito."}, {"numero": 24, "texto": "Era Abraão de idade de noventa e nove anos quando circuncidou a carne de seu prepúcio."}, {"numero": 25, "texto": "E Ismael seu filho era de treze anos quando foi circuncidada a carne de seu prepúcio."}, {"numero": 26, "texto": "No mesmo dia foi circuncidado Abraão e Ismael seu filho."}, {"numero": 27, "texto": "E todos os homens de sua casa, o servo nascido em casa, e o comprado por dinheiro do estrangeiro, foram circuncidados com ele."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 17, 'en', '[{"numero": 1, "texto": "And when Abram was ninety years old and nine, the Lord appeared to Abram, and said unto him, I am the Almighty God; walk before me, and be thou perfect."}, {"numero": 2, "texto": "And I will make my covenant between me and thee, and will multiply thee exceedingly."}, {"numero": 3, "texto": "And Abram fell on his face: and God talked with him, saying,"}, {"numero": 4, "texto": "As for me, behold, my covenant is with thee, and thou shalt be a father of many nations."}, {"numero": 5, "texto": "Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee."}, {"numero": 6, "texto": "And I will make thee exceeding fruitful, and I will make nations of thee, and kings shall come out of thee."}, {"numero": 7, "texto": "And I will establish my covenant between me and thee and thy seed after thee in their generations for an everlasting covenant, to be a God unto thee, and to thy seed after thee."}, {"numero": 8, "texto": "And I will give unto thee, and to thy seed after thee, the land wherein thou art a stranger, all the land of Canaan, for an everlasting possession; and I will be their God."}, {"numero": 9, "texto": "And God said unto Abraham, Thou shalt keep my covenant therefore, thou, and thy seed after thee in their generations."}, {"numero": 10, "texto": "This is my covenant, which ye shall keep, between me and you and thy seed after thee; Every man child among you shall be circumcised."}, {"numero": 11, "texto": "And ye shall circumcise the flesh of your foreskin; and it shall be a token of the covenant betwixt me and you."}, {"numero": 12, "texto": "And he that is eight days old shall be circumcised among you, every man child in your generations, he that is born in the house, or bought with money of any stranger, which is not of thy seed."}, {"numero": 13, "texto": "He that is born in thy house, and he that is bought with thy money, must needs be circumcised: and my covenant shall be in your flesh for an everlasting covenant."}, {"numero": 14, "texto": "And the uncircumcised man child whose flesh of his foreskin is not circumcised, that soul shall be cut off from his people; he hath broken my covenant."}, {"numero": 15, "texto": "And God said unto Abraham, As for Sarai thy wife, thou shalt not call her name Sarai, but Sarah shall her name be."}, {"numero": 16, "texto": "And I will bless her, and give thee a son also of her: yea, I will bless her, and she shall be a mother of nations; kings of people shall be of her."}, {"numero": 17, "texto": "Then Abraham fell upon his face, and laughed, and said in his heart, Shall a child be born unto him that is an hundred years old? and shall Sarah, that is ninety years old, bear?"}, {"numero": 18, "texto": "And Abraham said unto God, O that Ishmael might live before thee!"}, {"numero": 19, "texto": "And God said, Sarah thy wife shall bear thee a son indeed; and thou shalt call his name Isaac: and I will establish my covenant with him for an everlasting covenant, and with his seed after him."}, {"numero": 20, "texto": "And as for Ishmael, I have heard thee: Behold, I have blessed him, and will make him fruitful, and will multiply him exceedingly; twelve princes shall he beget, and I will make him a great nation."}, {"numero": 21, "texto": "But my covenant will I establish with Isaac, which Sarah shall bear unto thee at this set time in the next year."}, {"numero": 22, "texto": "And he left off talking with him, and God went up from Abraham."}, {"numero": 23, "texto": "And Abraham took Ishmael his son, and all that were born in his house, and all that were bought with his money, every male among the men of Abraham''s house; and circumcised the flesh of their foreskin in the selfsame day, as God had said unto him."}, {"numero": 24, "texto": "And Abraham was ninety years old and nine, when he was circumcised in the flesh of his foreskin."}, {"numero": 25, "texto": "And Ishmael his son was thirteen years old, when he was circumcised in the flesh of his foreskin."}, {"numero": 26, "texto": "In the selfsame day was Abraham circumcised, and Ishmael his son."}, {"numero": 27, "texto": "And all the men of his house, born in the house, and bought with money of the stranger, were circumcised with him."}]'::jsonb, 'King James Version'),
  ('Gn', 17, 'fr', '[{"numero": 1, "texto": "Lorsque Abram fut âgé de quatre-vingt-dix-neuf ans, l''''Eternel apparut à Abram, et lui dit: Je suis le Dieu tout-puissant. Marche devant ma face, et sois intègre."}, {"numero": 2, "texto": "J''''établirai mon alliance entre moi et toi, et je te multiplierai à l''''infini."}, {"numero": 3, "texto": "Abram tomba sur sa face; et Dieu lui parla, en disant:"}, {"numero": 4, "texto": "Voici mon alliance, que je fais avec toi. Tu deviendras père d''''une multitude de nations."}, {"numero": 5, "texto": "On ne t''''appellera plus Abram; mais ton nom sera Abraham, car je te rends père d''''une multitude de nations."}, {"numero": 6, "texto": "Je te rendrai fécond à l''''infini, je ferai de toi des nations; et des rois sortiront de toi."}, {"numero": 7, "texto": "J''''établirai mon alliance entre moi et toi, et tes descendants après toi, selon leurs générations: ce sera une alliance perpétuelle, en vertu de laquelle je serai ton Dieu et celui de ta postérité après toi."}, {"numero": 8, "texto": "Je te donnerai, et à tes descendants après toi, le pays que tu habites comme étranger, tout le pays de Canaan, en possession perpétuelle, et je serai leur Dieu."}, {"numero": 9, "texto": "Dieu dit à Abraham: Toi, tu garderas mon alliance, toi et tes descendants après toi, selon leurs générations."}, {"numero": 10, "texto": "C''''est ici mon alliance, que vous garderez entre moi et vous, et ta postérité après toi: tout mâle parmi vous sera circoncis."}, {"numero": 11, "texto": "Vous vous circoncirez; et ce sera un signe d''''alliance entre moi et vous."}, {"numero": 12, "texto": "A l''''âge de huit jours, tout mâle parmi vous sera circoncis, selon vos générations, qu''''il soit né dans la maison, ou qu''''il soit acquis à prix d''''argent de tout fils d''''étranger, sans appartenir à ta race."}, {"numero": 13, "texto": "On devra circoncire celui qui est né dans la maison et celui qui est acquis à prix d''''argent; et mon alliance sera dans votre chair une alliance perpétuelle."}, {"numero": 14, "texto": "Un mâle incirconcis, qui n''''aura pas été circoncis dans sa chair, sera exterminé du milieu de son peuple: il aura violé mon alliance."}, {"numero": 15, "texto": "Dieu dit à Abraham: Tu ne donneras plus à Saraï, ta femme, le nom de Saraï; mais son nom sera Sara."}, {"numero": 16, "texto": "Je la bénirai, et je te donnerai d''''elle un fils; je la bénirai, et elle deviendra des nations; des rois de peuples sortiront d''''elle."}, {"numero": 17, "texto": "Abraham tomba sur sa face; il rit, et dit en son coeur: Naîtrait-il un fils à un homme de cent ans? et Sara, âgée de quatre-vingt-dix ans, enfanterait-elle?"}, {"numero": 18, "texto": "Et Abraham dit à Dieu: Oh! qu''''Ismaël vive devant ta face!"}, {"numero": 19, "texto": "Dieu dit: Certainement Sara, ta femme, t''''enfantera un fils; et tu l''''appelleras du nom d''''Isaac. J''''établirai mon alliance avec lui comme une alliance perpétuelle pour sa postérité après lui."}, {"numero": 20, "texto": "A l''''égard d''''Ismaël, je t''''ai exaucé. Voici, je le bénirai, je le rendrai fécond, et je le multiplierai à l''''infini; il engendrera douze princes, et je ferai de lui une grande nation."}, {"numero": 21, "texto": "J''''établirai mon alliance avec Isaac, que Sara t''''enfantera à cette époque-ci de l''''année prochaine."}, {"numero": 22, "texto": "Lorsqu''''il eut achevé de lui parler, Dieu s''''éleva au-dessus d''''Abraham."}, {"numero": 23, "texto": "Abraham prit Ismaël, son fils, tous ceux qui étaient nés dans sa maison et tous ceux qu''''il avait acquis à prix d''''argent, tous les mâles parmi les gens de la maison d''''Abraham; et il les circoncit ce même jour, selon l''''ordre que Dieu lui avait donné."}, {"numero": 24, "texto": "Abraham était âgé de quatre-vingt-dix-neuf ans, lorsqu''''il fut circoncis."}, {"numero": 25, "texto": "Ismaël, son fils, était âgé de treize ans lorsqu''''il fut circoncis."}, {"numero": 26, "texto": "Ce même jour, Abraham fut circoncis, ainsi qu''''Ismaël, son fils."}, {"numero": 27, "texto": "Et tous les gens de sa maison, nés dans sa maison, ou acquis à prix d''''argent des étrangers, furent circoncis avec lui."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 17, 'es', '[{"numero": 1, "texto": "Y SIENDO Abram de edad de noventa y nueve años, aparecióle Jehová, y le dijo: Yo soy el Dios Todopoderoso; anda delante de mí, y sé perfecto."}, {"numero": 2, "texto": "Y pondré mi pacto entre mí y ti, y multiplicarte he mucho en gran manera."}, {"numero": 3, "texto": "Entonces Abram cayó sobre su rostro, y Dios habló con él diciendo:"}, {"numero": 4, "texto": "Yo, he aquí mi pacto contigo: Serás padre de muchedumbre de gentes:"}, {"numero": 5, "texto": "Y no se llamará más tu nombre Abram, sino que será tu nombre Abraham, porque te he puesto por padre de muchedumbre de gentes."}, {"numero": 6, "texto": "Y multiplicarte he mucho en gran manera, y te pondré en gentes, y reyes saldrán de ti."}, {"numero": 7, "texto": "Y estableceré mi pacto entre mí y ti, y tu simiente después de ti en sus generaciones, por alianza perpetua, para serte á ti por Dios, y á tu simiente después de ti."}, {"numero": 8, "texto": "Y te daré á ti, y á tu simiente después de ti, la tierra de tus peregrinaciones, toda la tierra de Canaán en heredad perpetua; y seré el Dios de ellos."}, {"numero": 9, "texto": "Dijo de nuevo Dios á Abraham: Tú empero guardarás mi pacto, tú y tu simiente después de ti por sus generaciones."}, {"numero": 10, "texto": "Este será mi pacto, que guardaréis entre mí y vosotros y tu simiente después de ti: Será circuncidado todo varón de entre vosotros."}, {"numero": 11, "texto": "Circuncidaréis, pues, la carne de vuestro prepucio, y será por señal del pacto entre mí y vosotros."}, {"numero": 12, "texto": "Y de edad de ocho días será circuncidado todo varón entre vosotros por vuestras generaciones: el nacido en casa, y el comprado á dinero de cualquier extranjero, que no fuere de tu simiente."}, {"numero": 13, "texto": "Debe ser circuncidado el nacido en tu casa, y el comprado por tu dinero: y estará mi pacto en vuestra carne para alianza perpetua."}, {"numero": 14, "texto": "Y el varón incircunciso que no hubiere circuncidado la carne de su prepucio, aquella persona será borrada de su pueblo; ha violado mi pacto."}, {"numero": 15, "texto": "Dijo también Dios á Abraham: A Sarai tu mujer no la llamarás Sarai, mas Sara será su nombre."}, {"numero": 16, "texto": "Y bendecirla he, y también te daré de ella hijo; sí, la bendeciré, y vendrá á ser madre de naciones; reyes de pueblos serán de ella."}, {"numero": 17, "texto": "Entonces Abraham cayó sobre su rostro, y rióse, y dijo en su corazón: ¿A hombre de cien años ha de nacer hijo? ¿y Sara, ya de noventa años, ha de parir?"}, {"numero": 18, "texto": "Y dijo Abraham á Dios: Ojalá Ismael viva delante de ti."}, {"numero": 19, "texto": "Y respondió Dios: Ciertamente Sara tu mujer te parirá un hijo, y llamarás su nombre Isaac; y confirmaré mi pacto con él por alianza perpetua para su simiente después de él."}, {"numero": 20, "texto": "Y en cuanto á Ismael, también te he oído: he aquí que le bendeciré, y le haré fructificar y multiplicar mucho en gran manera: doce príncipes engendrará, y ponerlo he por gran gente."}, {"numero": 21, "texto": "Mas yo estableceré mi pacto con Isaac, al cual te parirá Sara por este tiempo el año siguiente."}, {"numero": 22, "texto": "Y acabó de hablar con él, y subió Dios de con Abraham."}, {"numero": 23, "texto": "Entonces tomó Abraham á Ismael su hijo, y á todos los siervos nacidos en su casa, y á todos los comprados por su dinero, á todo varón entre los domésticos de la casa de Abraham, y circuncidó la carne del prepucio de ellos en aquel mismo día, como Dios le había dicho."}, {"numero": 24, "texto": "Era Abraham de edad de noventa y nueve años cuando circuncidó la carne de su prepucio."}, {"numero": 25, "texto": "E Ismael su hijo era de trece años, cuando fué circuncidada la carne de su prepucio."}, {"numero": 26, "texto": "En el mismo día fué circuncidado Abraham é Ismael su hijo."}, {"numero": 27, "texto": "Y todos los varones de su casa, el siervo nacido en casa, y el comprado por dinero del extranjero, fueron circuncidados con él."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 18, 'pt', '[{"numero": 1, "texto": "E apareceu-lhe o SENHOR nos carvalhos de Manre, estando ele sentado à porta de sua tenda no calor do dia."}, {"numero": 2, "texto": "E levantou seus olhos e olhou, e eis que três homens que estavam junto a ele: e quando os viu, saiu correndo da porta de sua tenda a recebê-los, e inclinou-se até a terra,"}, {"numero": 3, "texto": "E disse: Senhor, se agora achei favor aos teus olhos, rogo-te que não passes de teu servo."}, {"numero": 4, "texto": "Que se traga agora um pouco de água, e lavai vossos pés; e recostai-vos debaixo de uma árvore,"}, {"numero": 5, "texto": "E trarei um bocado de pão, e confortai vosso coração; depois passareis; pois por isso passastes perto de vosso servo."}, {"numero": 6, "texto": "Então Abraão foi depressa à tenda a Sara, e lhe disse: Toma logo três medidas de boa farinha, amassa e faz pães cozidos."}, {"numero": 7, "texto": "E correu Abraão às vacas, e tomou um bezerro tenro e bom, e deu-o ao jovem, e deu-se este pressa a prepará-lo."}, {"numero": 8, "texto": "Tomou também manteiga e leite, e o bezerro que havia preparado, e o pôs diante deles; e ele estava junto a eles debaixo da árvore; e comeram."}, {"numero": 9, "texto": "E lhe disseram: Onde está Sara tua mulher? E ele respondeu: Aqui na tenda."}, {"numero": 10, "texto": "Então disse: De certo voltarei a ti segundo o tempo da vida, e eis que Sara, tua mulher, terá um filho."}, {"numero": 11, "texto": "Abraão e Sara eram idosos, avançados em dias; a Sara já havia cessado o costume das mulheres."}, {"numero": 12, "texto": "Riu, pois, Sara consigo mesma, dizendo: Depois que envelheci terei prazer, sendo também meu senhor já velho?"}, {"numero": 13, "texto": "Então o SENHOR disse a Abraão: Por que Sara riu dizendo: Será verdade que darei à luz, sendo já velha?"}, {"numero": 14, "texto": "Há para Deus alguma coisa difícil? Ao tempo assinalado voltarei a ti, segundo o tempo da vida, e Sara terá um filho."}, {"numero": 15, "texto": "Então Sara negou dizendo: Não ri; pois teve medo. Mas ele disse: Não é assim, mas riste."}, {"numero": 16, "texto": "E os homens se levantaram dali, e olharam até Sodoma: e Abraão ia com eles acompanhando-os."}, {"numero": 17, "texto": "E o SENHOR disse: Encobrirei eu a Abraão o que vou a fazer,"}, {"numero": 18, "texto": "Havendo de ser Abraão em uma nação grande e forte, e havendo de ser benditas nele todas as nações da terra?"}, {"numero": 19, "texto": "Porque eu o conheci, sei que mandará a seus filhos e a sua casa depois de si, que guardem o caminho do SENHOR, fazendo justiça e juízo, para que faça vir o SENHOR sobre Abraão o que falou acerca dele."}, {"numero": 20, "texto": "Então o SENHOR lhe disse: Porquanto o clamor de Sodoma e Gomorra se aumenta mais e mais, e o pecado deles se agravou em extremo,"}, {"numero": 21, "texto": "Descerei agora, e verei se consumaram sua obra segundo o clamor que veio até mim; e se não, eu o saberei."}, {"numero": 22, "texto": "E apartaram-se dali os homens, e foram até Sodoma: mas Abraão estava ainda diante do SENHOR."}, {"numero": 23, "texto": "E aproximou-se Abraão e disse: Destruirás também ao justo com o ímpio?"}, {"numero": 24, "texto": "Talvez haja cinquenta justos dentro da cidade: destruirás também e não perdoarás ao lugar por cinquenta justos que estejam dentro dela?"}, {"numero": 25, "texto": "Longe de ti o fazer tal, que faças morrer ao justo com o ímpio e que seja o justo tratado como o ímpio; nunca faças tal. O juiz de toda a terra, não há de fazer o que é justo?"}, {"numero": 26, "texto": "Então respondeu o SENHOR: Se achar em Sodoma cinquenta justos dentro da cidade, perdoarei a todo este lugar por causa deles."}, {"numero": 27, "texto": "E Abraão replicou e disse: Eis que agora que comecei a falar a meu Senhor, ainda que sou pó e cinza:"}, {"numero": 28, "texto": "Talvez faltem de cinquenta justos cinco; destruirás por aqueles cinco toda a cidade? E disse: Não a destruirei, se achar ali quarenta e cinco."}, {"numero": 29, "texto": "E voltou a falar-lhe, e disse: Talvez se acharão ali quarenta. E respondeu: Não o farei por causa dos quarenta."}, {"numero": 30, "texto": "E disse: Não se ire agora meu Senhor, se falar: talvez se achem ali trinta. E respondeu: Não o farei se achar ali trinta."}, {"numero": 31, "texto": "E disse: Eis que agora que me empreendi em falar a meu Senhor: talvez se achem ali vinte. Não a destruirei, respondeu, por causa dos vinte."}, {"numero": 32, "texto": "E voltou a dizer: Não se ire agora meu Senhor, se falar somente uma vez: talvez se achem ali dez. Não a destruirei, respondeu, por causa dos dez."}, {"numero": 33, "texto": "E foi-se o SENHOR, logo que acabou de falar a Abraão: e Abraão se voltou a seu lugar."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 18, 'en', '[{"numero": 1, "texto": "And the Lord appeared unto him in the plains of Mamre: and he sat in the tent door in the heat of the day;"}, {"numero": 2, "texto": "And he lift up his eyes and looked, and, lo, three men stood by him: and when he saw them, he ran to meet them from the tent door, and bowed himself toward the ground,"}, {"numero": 3, "texto": "And said, My Lord, if now I have found favour in thy sight, pass not away, I pray thee, from thy servant:"}, {"numero": 4, "texto": "Let a little water, I pray you, be fetched, and wash your feet, and rest yourselves under the tree:"}, {"numero": 5, "texto": "And I will fetch a morsel of bread, and comfort ye your hearts; after that ye shall pass on: for therefore are ye come to your servant. And they said, So do, as thou hast said."}, {"numero": 6, "texto": "And Abraham hastened into the tent unto Sarah, and said, Make ready quickly three measures of fine meal, knead it, and make cakes upon the hearth."}, {"numero": 7, "texto": "And Abraham ran unto the herd, and fetcht a calf tender and good, and gave it unto a young man; and he hasted to dress it."}, {"numero": 8, "texto": "And he took butter, and milk, and the calf which he had dressed, and set it before them; and he stood by them under the tree, and they did eat."}, {"numero": 9, "texto": "And they said unto him, Where is Sarah thy wife? And he said, Behold, in the tent."}, {"numero": 10, "texto": "And he said, I will certainly return unto thee according to the time of life; and, lo, Sarah thy wife shall have a son. And Sarah heard it in the tent door, which was behind him."}, {"numero": 11, "texto": "Now Abraham and Sarah were old and well stricken in age; and it ceased to be with Sarah after the manner of women."}, {"numero": 12, "texto": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}, {"numero": 13, "texto": "And the Lord said unto Abraham, Wherefore did Sarah laugh, saying, Shall I of a surety bear a child, which am old?"}, {"numero": 14, "texto": "Is any thing too hard for the Lord? At the time appointed I will return unto thee, according to the time of life, and Sarah shall have a son."}, {"numero": 15, "texto": "Then Sarah denied, saying, I laughed not; for she was afraid. And he said, Nay; but thou didst laugh."}, {"numero": 16, "texto": "And the men rose up from thence, and looked toward Sodom: and Abraham went with them to bring them on the way."}, {"numero": 17, "texto": "And the Lord said, Shall I hide from Abraham that thing which I do;"}, {"numero": 18, "texto": "Seeing that Abraham shall surely become a great and mighty nation, and all the nations of the earth shall be blessed in him?"}, {"numero": 19, "texto": "For I know him, that he will command his children and his household after him, and they shall keep the way of the Lord, to do justice and judgment; that the Lord may bring upon Abraham that which he hath spoken of him."}, {"numero": 20, "texto": "And the Lord said, Because the cry of Sodom and Gomorrah is great, and because their sin is very grievous;"}, {"numero": 21, "texto": "I will go down now, and see whether they have done altogether according to the cry of it, which is come unto me; and if not, I will know."}, {"numero": 22, "texto": "And the men turned their faces from thence, and went toward Sodom: but Abraham stood yet before the Lord."}, {"numero": 23, "texto": "And Abraham drew near, and said, Wilt thou also destroy the righteous with the wicked?"}, {"numero": 24, "texto": "Peradventure there be fifty righteous within the city: wilt thou also destroy and not spare the place for the fifty righteous that are therein?"}, {"numero": 25, "texto": "That be far from thee to do after this manner, to slay the righteous with the wicked: and that the righteous should be as the wicked, that be far from thee: Shall not the Judge of all the earth do right?"}, {"numero": 26, "texto": "And the Lord said, If I find in Sodom fifty righteous within the city, then I will spare all the place for their sakes."}, {"numero": 27, "texto": "And Abraham answered and said, Behold now, I have taken upon me to speak unto the Lord, which am but dust and ashes:"}, {"numero": 28, "texto": "Peradventure there shall lack five of the fifty righteous: wilt thou destroy all the city for lack of five? And he said, If I find there forty and five, I will not destroy it."}, {"numero": 29, "texto": "And he spake unto him yet again, and said, Peradventure there shall be forty found there. And he said, I will not do it for forty''s sake."}, {"numero": 30, "texto": "And he said unto him, Oh let not the Lord be angry, and I will speak: Peradventure there shall thirty be found there. And he said, I will not do it, if I find thirty there."}, {"numero": 31, "texto": "And he said, Behold now, I have taken upon me to speak unto the Lord: Peradventure there shall be twenty found there. And he said, I will not destroy it for twenty''s sake."}, {"numero": 32, "texto": "And he said, Oh let not the Lord be angry, and I will speak yet but this once: Peradventure ten shall be found there. And he said, I will not destroy it for ten''s sake."}, {"numero": 33, "texto": "And the Lord went his way, as soon as he had left communing with Abraham: and Abraham returned unto his place."}]'::jsonb, 'King James Version'),
  ('Gn', 18, 'fr', '[{"numero": 1, "texto": "L''''Eternel lui apparut parmi les chênes de Mamré, comme il était assis à l''''entrée de sa tente, pendant la chaleur du jour."}, {"numero": 2, "texto": "Il leva les yeux, et regarda: et voici, trois hommes étaient debout près de lui. Quand il les vit, il courut au-devant d''''eux, depuis l''''entrée de sa tente, et se prosterna en terre."}, {"numero": 3, "texto": "Et il dit: Seigneur, si j''''ai trouvé grâce à tes yeux, ne passe point, je te prie, loin de ton serviteur."}, {"numero": 4, "texto": "Permettez qu''''on apporte un peu d''''eau, pour vous laver les pieds; et reposez-vous sous cet arbre."}, {"numero": 5, "texto": "J''''irai prendre un morceau de pain, pour fortifier votre coeur; après quoi, vous continuerez votre route; car c''''est pour cela que vous passez près de votre serviteur. Ils répondirent: Fais comme tu l''''as dit."}, {"numero": 6, "texto": "Abraham alla promptement dans sa tente vers Sara, et il dit: Vite, trois mesures de fleur de farine, pétris, et fais des gâteaux."}, {"numero": 7, "texto": "Et Abraham courut à son troupeau, prit un veau tendre et bon, et le donna à un serviteur, qui se hâta de l''''apprêter."}, {"numero": 8, "texto": "Il prit encore de la crème et du lait, avec le veau qu''''on avait apprêté, et il les mit devant eux. Il se tint lui-même à leurs côtés, sous l''''arbre. Et ils mangèrent."}, {"numero": 9, "texto": "Alors ils lui dirent: Où est Sara, ta femme? Il répondit: Elle est là, dans la tente."}, {"numero": 10, "texto": "L''''un d''''entre eux dit: Je reviendrai vers toi à cette même époque; et voici, Sara, ta femme, aura un fils. Sara écoutait à l''''entrée de la tente, qui était derrière lui."}, {"numero": 11, "texto": "Abraham et Sara étaient vieux, avancés en âge: et Sara ne pouvait plus espérer avoir des enfants."}, {"numero": 12, "texto": "Elle rit en elle-même, en disant: Maintenant que je suis vieille, aurais-je encore des désirs? Mon seigneur aussi est vieux."}, {"numero": 13, "texto": "L''''Eternel dit à Abraham: Pourquoi donc Sara a-t-elle ri, en disant: Est-ce que vraiment j''''aurais un enfant, moi qui suis vieille?"}, {"numero": 14, "texto": "Y a-t-il rien qui soit étonnant de la part de l''''Eternel? Au temps fixé je reviendrai vers toi, à cette même époque; et Sara aura un fils."}, {"numero": 15, "texto": "Sara mentit, en disant: Je n''''ai pas ri. Car elle eut peur. Mais il dit: Au contraire, tu as ri."}, {"numero": 16, "texto": "Ces hommes se levèrent pour partir, et ils regardèrent du côté de Sodome. Abraham alla avec eux, pour les accompagner."}, {"numero": 17, "texto": "Alors l''''Eternel dit: Cacherai-je à Abraham ce que je vais faire?..."}, {"numero": 18, "texto": "Abraham deviendra certainement une nation grande et puissante, et en lui seront bénies toutes les nations de la terre."}, {"numero": 19, "texto": "Car je l''''ai choisi, afin qu''''il ordonne à ses fils et à sa maison après lui de garder la voie de l''''Eternel, en pratiquant la droiture et la justice, et qu''''ainsi l''''Eternel accomplisse en faveur d''''Abraham les promesses qu''''il lui a faites..."}, {"numero": 20, "texto": "Et l''''Eternel dit: Le cri contre Sodome et Gomorrhe s''''est accru, et leur péché est énorme."}, {"numero": 21, "texto": "C''''est pourquoi je vais descendre, et je verrai s''''ils ont agi entièrement selon le bruit venu jusqu''''à moi; et si cela n''''est pas, je le saurai."}, {"numero": 22, "texto": "Les hommes s''''éloignèrent, et allèrent vers Sodome. Mais Abraham se tint encore en présence de l''''Eternel."}, {"numero": 23, "texto": "Abraham s''''approcha, et dit: Feras-tu aussi périr le juste avec le méchant?"}, {"numero": 24, "texto": "Peut-être y a-t-il cinquante justes au milieu de la ville: les feras-tu périr aussi, et ne pardonneras-tu pas à la ville à cause des cinquante justes qui sont au milieu d''''elle?"}, {"numero": 25, "texto": "Faire mourir le juste avec le méchant, en sorte qu''''il en soit du juste comme du méchant, loin de toi cette manière d''''agir! loin de toi! Celui qui juge toute la terre n''''exercera-t-il pas la justice?"}, {"numero": 26, "texto": "Et l''''Eternel dit: Si je trouve dans Sodome cinquante justes au milieu de la ville, je pardonnerai à toute la ville, à cause d''''eux."}, {"numero": 27, "texto": "Abraham reprit, et dit: Voici, j''''ai osé parler au Seigneur, moi qui ne suis que poudre et cendre."}, {"numero": 28, "texto": "Peut-être des cinquante justes en manquera-t-il cinq: pour cinq, détruiras-tu toute la ville? Et l''''Eternel dit: Je ne la détruirai point, si j''''y trouve quarante-cinq justes."}, {"numero": 29, "texto": "Abraham continua de lui parler, et dit: Peut-être s''''y trouvera-t-il quarante justes. Et l''''Eternel dit: Je ne ferai rien, à cause de ces quarante."}, {"numero": 30, "texto": "Abraham dit: Que le Seigneur ne s''''irrite point, et je parlerai. Peut-être s''''y trouvera-t-il trente justes. Et l''''Eternel dit: Je ne ferai rien, si j''''y trouve trente justes."}, {"numero": 31, "texto": "Abraham dit: Voici, j''''ai osé parler au Seigneur. Peut-être s''''y trouvera-t-il vingt justes. Et l''''Eternel dit: Je ne la détruirai point, à cause de ces vingt."}, {"numero": 32, "texto": "Abraham dit: Que le Seigneur ne s''''irrite point, et je ne parlerai plus que cette fois. Peut-être s''''y trouvera-t-il dix justes. Et l''''Eternel dit: Je ne la détruirai point, à cause de ces dix justes."}, {"numero": 33, "texto": "L''''Eternel s''''en alla lorsqu''''il eut achevé de parler à Abraham. Et Abraham retourna dans sa demeure."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 18, 'es', '[{"numero": 1, "texto": "Y APARECIÓLE Jehová en el valle de Mamre, estando él sentado á la puerta de su tienda en el calor del día."}, {"numero": 2, "texto": "Y alzó sus ojos y miró, y he aquí tres varones que estaban junto á él: y cuando los vió, salió corriendo de la puerta de su tienda á recibirlos, é inclinóse hacia la tierra,"}, {"numero": 3, "texto": "Y dijo: Señor, si ahora he hallado gracia en tus ojos, ruégote que no pases de tu siervo."}, {"numero": 4, "texto": "Que se traiga ahora un poco de agua, y lavad vuestros pies; y recostaos debajo de un árbol,"}, {"numero": 5, "texto": "Y traeré un bocado de pan, y sustentad vuestro corazón; después pasaréis: porque por eso habéis pasado cerca de vuestro siervo. Y ellos dijeron: Haz así como has dicho."}, {"numero": 6, "texto": "Entonces Abraham fué de priesa á la tienda á Sara, y le dijo: Toma presto tres medidas de flor de harina, amasa y haz panes cocidos debajo del rescoldo."}, {"numero": 7, "texto": "Y corrió Abraham á las vacas, y tomó un becerro tierno y bueno, y diólo al mozo, y dióse éste priesa á aderezarlo."}, {"numero": 8, "texto": "Tomó también manteca y leche, y el becerro que había aderezado, y púsolo delante de ellos; y él estaba junto á ellos debajo del árbol; y comieron."}, {"numero": 9, "texto": "Y le dijeron: ¿Dónde está Sara tu mujer? Y él respondió: Aquí en la tienda."}, {"numero": 10, "texto": "Entonces dijo: De cierto volveré á ti según el tiempo de la vida, y he aquí, tendrá un hijo Sara tu mujer. Y Sara escuchaba á la puerta de la tienda, que estaba detrás de él."}, {"numero": 11, "texto": "Y Abraham y Sara eran viejos, entrados en días: á Sara había cesado ya la costumbre de las mujeres."}, {"numero": 12, "texto": "Rióse, pues, Sara entre sí, diciendo: ¿Después que he envejecido tendré deleite, siendo también mi señor ya viejo?"}, {"numero": 13, "texto": "Entonces Jehová dijo á Abraham: ¿Por qué se ha reído Sara diciendo: Será cierto que he de parir siendo ya vieja?"}, {"numero": 14, "texto": "¿Hay para Dios alguna cosa difícil? Al tiempo señalado volveré á ti, según el tiempo de la vida, y Sara tendrá un hijo."}, {"numero": 15, "texto": "Entonces Sara negó diciendo: No me reí; porque tuvo miedo. Y él dijo: No es así, sino que te has reído."}, {"numero": 16, "texto": "Y los varones se levantaron de allí, y miraron hacia Sodoma: y Abraham iba con ellos acompañándolos."}, {"numero": 17, "texto": "Y Jehová dijo: ¿Encubriré yo á Abraham lo que voy á hacer,"}, {"numero": 18, "texto": "Habiendo de ser Abraham en una nación grande y fuerte, y habiendo de ser benditas en él todas las gentes de la tierra?"}, {"numero": 19, "texto": "Porque yo lo he conocido, sé que mandará á sus hijos y á su casa después de sí, que guarden el camino de Jehová, haciendo justicia y juicio, para que haga venir Jehová sobre Abraham lo que ha hablado acerca de él."}, {"numero": 20, "texto": "Entonces Jehová le dijo: Por cuanto el clamor de Sodoma y Gomorra se aumenta más y más, y el pecado de ellos se ha agravado en extremo,"}, {"numero": 21, "texto": "Descenderé ahora, y veré si han consumado su obra según el clamor que ha venido hasta mí; y si no, saberlo he."}, {"numero": 22, "texto": "Y apartáronse de allí los varones, y fueron hacia Sodoma: mas Abraham estaba aún delante de Jehová."}, {"numero": 23, "texto": "Y acercóse Abraham y dijo: ¿Destruirás también al justo con el impío?"}, {"numero": 24, "texto": "Quizá hay cincuenta justos dentro de la ciudad: ¿destruirás también y no perdonarás al lugar por cincuenta justos que estén dentro de él?"}, {"numero": 25, "texto": "Lejos de ti el hacer tal, que hagas morir al justo con el impío, y que sea el justo tratado como el impío; nunca tal hagas. El juez de toda la tierra, ¿no ha de hacer lo que es justo?"}, {"numero": 26, "texto": "Entonces respondió Jehová: Si hallare en Sodoma cincuenta justos dentro de la ciudad, perdonaré á todo este lugar por amor de ellos."}, {"numero": 27, "texto": "Y Abraham replicó y dijo: He aquí ahora que he comenzado á hablar á mi Señor, aunque soy polvo y ceniza:"}, {"numero": 28, "texto": "Quizá faltarán de cincuenta justos cinco: ¿destruirás por aquellos cinco toda la ciudad? Y dijo: No la destruiré, si hallare allí cuarenta y cinco."}, {"numero": 29, "texto": "Y volvió á hablarle, y dijo: Quizá se hallarán allí cuarenta. Y respondió: No lo haré por amor de los cuarenta."}, {"numero": 30, "texto": "Y dijo: No se enoje ahora mi Señor, si hablare: quizá se hallarán allí treinta. Y respondió: No lo haré si hallare allí treinta."}, {"numero": 31, "texto": "Y dijo: He aquí ahora que he emprendido el hablar á mi Señor: quizá se hallarán allí veinte. No la destruiré, respondió, por amor de los veinte."}, {"numero": 32, "texto": "Y volvió á decir: No se enoje ahora mi Señor, si hablare solamente una vez: quizá se hallarán allí diez. No la destruiré, respondió, por amor de los diez."}, {"numero": 33, "texto": "Y fuése Jehová, luego que acabó de hablar á Abraham: y Abraham se volvió á su lugar."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 19, 'pt', '[{"numero": 1, "texto": "Chegaram, pois, os dois anjos a Sodoma ao cair da tarde; e Ló estava sentado à porta de Sodoma. E vendo-os Ló, levantou-se a recebê-los, e inclinou-se até o chão;"}, {"numero": 2, "texto": "E disse: Agora, pois, meus senhores, vos rogo que venhais à casa de vosso servo e vos hospedeis, e lavareis vossos pés: e pela manhã vos levantareis, e seguireis vosso caminho. E eles responderam: Não, que na praça nos ficaremos esta noite."}, {"numero": 3, "texto": "Mas ele insistiu com eles muito, e se vieram com ele, e entraram em sua casa; e fez-lhes banquete, e cozeu pães sem levedura e comeram."}, {"numero": 4, "texto": "E antes que se deitassem, cercaram a casa os homens da cidade, os homens de Sodoma, todo o povo junto, desde o mais jovem até o mais velho;"}, {"numero": 5, "texto": "E chamaram a Ló, e lhe disseram: Onde estão os homens que vieram a ti esta noite? tira-os a nós, para que os conheçamos."}, {"numero": 6, "texto": "Então Ló saiu a eles à porta, e fechou as portas atrás de si,"}, {"numero": 7, "texto": "E disse: Eu vos rogo, meus irmãos, que não façais tal maldade."}, {"numero": 8, "texto": "Eis aqui agora eu tenho duas filhas que não conheceram homem; eu as tirarei fora para vós, e fazei delas como bem vos parecer: somente a estes homens não façais nada, pois que vieram à sombra de meu telhado."}, {"numero": 9, "texto": "E eles responderam: Sai daí: e acrescentaram: Veio este aqui para habitar como um estrangeiro, e haverá de levantar-se como juiz? Agora te faremos mais mal que a eles. E faziam grande violência ao homem, a Ló, e se aproximaram para romper as portas."}, {"numero": 10, "texto": "Então os homens estenderam a mão, e meteram a Ló em casa com eles, e fecharam as portas."}, {"numero": 11, "texto": "E aos homens que estavam à porta da casa desde o menor até o maior, feriram com cegueira; mas eles se cansavam tentando achar a porta."}, {"numero": 12, "texto": "E disseram os homens a Ló: Tens aqui alguém mais? Genros, e teus filhos e tuas filhas, e tudo o que tens na cidade, tira-o deste lugar:"}, {"numero": 13, "texto": "Porque vamos destruir este lugar, porquanto o clamor deles subiu demais diante do SENHOR; portanto o SENHOR nos enviou para destruí-lo."}, {"numero": 14, "texto": "Então saiu Ló, e falou a seus genros, os que haviam de se casar com suas filhas, e lhes disse: Levantai-vos, saí deste lugar; porque o SENHOR vai destruir esta cidade. Mas pareceu a seus genros como que se ridicularizava."}, {"numero": 15, "texto": "E ao raiar a alva, os anjos davam pressa a Ló, dizendo: Levanta-te, toma tua mulher, e teus dois filhas que se acham aqui, para que não pereças no castigo da cidade."}, {"numero": 16, "texto": "E demorando-se ele, os homens pegaram por sua mão, e pela mão de sua mulher, e pelas mãos de suas duas filhas segundo a misericórdia do SENHOR para com ele; e o tiraram, e o puseram fora da cidade."}, {"numero": 17, "texto": "E foi que quando os tirou fora, disse: Escapa por tua vida; não olhes atrás de ti, nem pares toda esta planície; escapa ao monte, não seja que pereças."}, {"numero": 18, "texto": "E Ló lhes disse: Não, eu vos rogo, senhores meus;"}, {"numero": 19, "texto": "Eis que agora achou teu servo favor em teus olhos, e engrandeceste tua misericórdia que fizeste comigo dando-me a vida; mas eu não poderei escapar ao monte, não seja caso que me alcance o mal e morra."}, {"numero": 20, "texto": "Eis que agora esta cidade está próxima para fugir ali, a qual é pequena; escaparei agora ali, (não é ela pequena?) e viverá minha alma."}, {"numero": 21, "texto": "E lhe respondeu: Eis que recebi também tua súplica sobre isto, e não destruirei a cidade de que falaste."}, {"numero": 22, "texto": "Apressa-te, escapa-te ali; porque nada poderei fazer até que ali tenhas chegado. Por isto foi chamado o nome da cidade, Zoar."}, {"numero": 23, "texto": "O sol saía sobre a terra, quando Ló chegou a Zoar."}, {"numero": 24, "texto": "Então choveu o SENHOR sobre Sodoma e sobre Gomorra enxofre e fogo da parte do SENHOR desde os céus;"}, {"numero": 25, "texto": "E destruiu as cidades, e toda aquela planície, com todos os moradores daquelas cidades, e o fruto da terra."}, {"numero": 26, "texto": "Então a mulher de Ló olhou atrás, às costas dele, e se tornou estátua de sai."}, {"numero": 27, "texto": "E subiu Abraão pela manhã ao lugar onde havia estado diante do SENHOR:"}, {"numero": 28, "texto": "E olhou até Sodoma e Gomorra, e até toda a terra daquela planície olhou; e eis que a fumaça subia da terra como a fumaça de um forno."}, {"numero": 29, "texto": "Assim foi que, quando destruiu Deus as cidades da planície, lembrou-se Deus de Abraão, e enviou fora a Ló do meio da destruição, ao assolar as cidades onde Ló estava."}, {"numero": 30, "texto": "Porém Ló subiu de Zoar, e assentou no monte, e suas duas filhas com ele; porque teve medo de ficar em Zoar, e se abrigou em uma caverna ele e suas duas filhas."}, {"numero": 31, "texto": "Então a maior disse à menor: Nosso pai é velho, e não resta homem na terra que entre a nós conforme o costume de toda a terra:"}, {"numero": 32, "texto": "Vem, demos a beber vinho a nosso pai, e durmamos com ele, e conservaremos de nosso pai geração."}, {"numero": 33, "texto": "E deram a beber vinho a seu pai aquela noite: e entrou a maior, e dormiu com seu pai; mas ele não sentiu quando se deitou com ela nem quando se levantou."}, {"numero": 34, "texto": "O dia seguinte disse a maior à menor: Eis que eu dormi a noite passada com meu pai; demos a ele de beber vinho também esta noite, e entra e dorme com ele, para que conservemos de nosso pai geração."}, {"numero": 35, "texto": "E deram a beber vinho a seu pai também aquela noite: e levantou-se a menor, e dormiu com ele; mas não conseguiu perceber quando se deitou com ela, nem quando se levantou."}, {"numero": 36, "texto": "E conceberam as duas filhas de Ló, de seu pai."}, {"numero": 37, "texto": "E deu à luz a maior um filho, e chamou seu nome Moabe, o qual é pai dos moabitas até hoje."}, {"numero": 38, "texto": "A menor também deu à luz um filho, e chamou seu nome Ben-Ami, o qual é pai dos amonitas até hoje."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 19, 'en', '[{"numero": 1, "texto": "And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground;"}, {"numero": 2, "texto": "And he said, Behold now, my lords, turn in, I pray you, into your servant''s house, and tarry all night, and wash your feet, and ye shall rise up early, and go on your ways. And they said, Nay; but we will abide in the street all night."}, {"numero": 3, "texto": "And he pressed upon them greatly; and they turned in unto him, and entered into his house; and he made them a feast, and did bake unleavened bread, and they did eat."}, {"numero": 4, "texto": "But before they lay down, the men of the city, even the men of Sodom, compassed the house round, both old and young, all the people from every quarter:"}, {"numero": 5, "texto": "And they called unto Lot, and said unto him, Where are the men which came in to thee this night? bring them out unto us, that we may know them."}, {"numero": 6, "texto": "And Lot went out at the door unto them, and shut the door after him,"}, {"numero": 7, "texto": "And said, I pray you, brethren, do not so wickedly."}, {"numero": 8, "texto": "Behold now, I have two daughters which have not known man; let me, I pray you, bring them out unto you, and do ye to them as is good in your eyes: only unto these men do nothing; for therefore came they under the shadow of my roof."}, {"numero": 9, "texto": "And they said, Stand back. And they said again, This one fellow came in to sojourn, and he will needs be a judge: now will we deal worse with thee, than with them. And they pressed sore upon the man, even Lot, and came near to break the door."}, {"numero": 10, "texto": "But the men put forth their hand, and pulled Lot into the house to them, and shut to the door."}, {"numero": 11, "texto": "And they smote the men that were at the door of the house with blindness, both small and great: so that they wearied themselves to find the door."}, {"numero": 12, "texto": "And the men said unto Lot, Hast thou here any besides? son in law, and thy sons, and thy daughters, and whatsoever thou hast in the city, bring them out of this place:"}, {"numero": 13, "texto": "For we will destroy this place, because the cry of them is waxen great before the face of the Lord; and the Lord hath sent us to destroy it."}, {"numero": 14, "texto": "And Lot went out, and spake unto his sons in law, which married his daughters, and said, Up, get you out of this place; for the Lord will destroy this city. But he seemed as one that mocked unto his sons in law."}, {"numero": 15, "texto": "And when the morning arose, then the angels hastened Lot, saying, Arise, take thy wife, and thy two daughters, which are here; lest thou be consumed in the iniquity of the city."}, {"numero": 16, "texto": "And while he lingered, the men laid hold upon his hand, and upon the hand of his wife, and upon the hand of his two daughters; the Lord being merciful unto him: and they brought him forth, and set him without the city."}, {"numero": 17, "texto": "And it came to pass, when they had brought them forth abroad, that he said, Escape for thy life; look not behind thee, neither stay thou in all the plain; escape to the mountain, lest thou be consumed."}, {"numero": 18, "texto": "And Lot said unto them, Oh, not so, my Lord:"}, {"numero": 19, "texto": "Behold now, thy servant hath found grace in thy sight, and thou hast magnified thy mercy, which thou hast shewed unto me in saving my life; and I cannot escape to the mountain, lest some evil take me, and I die:"}, {"numero": 20, "texto": "Behold now, this city is near to flee unto, and it is a little one: Oh, let me escape thither, (is it not a little one?) and my soul shall live."}, {"numero": 21, "texto": "And he said unto him, See, I have accepted thee concerning this thing also, that I will not overthrow this city, for the which thou hast spoken."}, {"numero": 22, "texto": "Haste thee, escape thither; for I cannot do anything till thou be come thither. Therefore the name of the city was called Zoar."}, {"numero": 23, "texto": "The sun was risen upon the earth when Lot entered into Zoar."}, {"numero": 24, "texto": "Then the Lord rained upon Sodom and upon Gomorrah brimstone and fire from the Lord out of heaven;"}, {"numero": 25, "texto": "And he overthrew those cities, and all the plain, and all the inhabitants of the cities, and that which grew upon the ground."}, {"numero": 26, "texto": "But his wife looked back from behind him, and she became a pillar of salt."}, {"numero": 27, "texto": "And Abraham gat up early in the morning to the place where he stood before the Lord:"}, {"numero": 28, "texto": "And he looked toward Sodom and Gomorrah, and toward all the land of the plain, and beheld, and, lo, the smoke of the country went up as the smoke of a furnace."}, {"numero": 29, "texto": "And it came to pass, when God destroyed the cities of the plain, that God remembered Abraham, and sent Lot out of the midst of the overthrow, when he overthrew the cities in the which Lot dwelt."}, {"numero": 30, "texto": "And Lot went up out of Zoar, and dwelt in the mountain, and his two daughters with him; for he feared to dwell in Zoar: and he dwelt in a cave, he and his two daughters."}, {"numero": 31, "texto": "And the firstborn said unto the younger, Our father is old, and there is not a man in the earth to come in unto us after the manner of all the earth:"}, {"numero": 32, "texto": "Come, let us make our father drink wine, and we will lie with him, that we may preserve seed of our father."}, {"numero": 33, "texto": "And they made their father drink wine that night: and the firstborn went in, and lay with her father; and he perceived not when she lay down, nor when she arose."}, {"numero": 34, "texto": "And it came to pass on the morrow, that the firstborn said unto the younger, Behold, I lay yesternight with my father: let us make him drink wine this night also; and go thou in, and lie with him, that we may preserve seed of our father."}, {"numero": 35, "texto": "And they made their father drink wine that night also: and the younger arose, and lay with him; and he perceived not when she lay down, nor when she arose."}, {"numero": 36, "texto": "Thus were both the daughters of Lot with child by their father."}, {"numero": 37, "texto": "And the first born bare a son, and called his name Moab: the same is the father of the Moabites unto this day."}, {"numero": 38, "texto": "And the younger, she also bare a son, and called his name Benammi: the same is the father of the children of Ammon unto this day."}]'::jsonb, 'King James Version'),
  ('Gn', 19, 'fr', '[{"numero": 1, "texto": "Les deux anges arrivèrent à Sodome sur le soir; et Lot était assis à la porte de Sodome. Quand Lot les vit, il se leva pour aller au-devant d''''eux, et se prosterna la face contre terre."}, {"numero": 2, "texto": "Puis il dit: Voici, mes seigneurs, entrez, je vous prie, dans la maison de votre serviteur, et passez-y la nuit; lavez-vous les pieds; vous vous lèverez de bon matin, et vous poursuivrez votre route. Non, répondirent-ils, nous passerons la nuit dans la rue."}, {"numero": 3, "texto": "Mais Lot les pressa tellement qu''''ils vinrent chez lui et entrèrent dans sa maison. Il leur donna un festin, et fit cuire des pains sans levain. Et ils mangèrent."}, {"numero": 4, "texto": "Ils n''''étaient pas encore couchés que les gens de la ville, les gens de Sodome, entourèrent la maison, depuis les enfants jusqu''''aux vieillards; toute la population était accourue."}, {"numero": 5, "texto": "Ils appelèrent Lot, et lui dirent: Où sont les hommes qui sont entrés chez toi cette nuit? Fais-les sortir vers nous, pour que nous les connaissions."}, {"numero": 6, "texto": "Lot sortit vers eux à l''''entrée de la maison, et ferma la porte derrière lui."}, {"numero": 7, "texto": "Et il dit: Mes frères, je vous prie, ne faites pas le mal!"}, {"numero": 8, "texto": "Voici, j''''ai deux filles qui n''''ont point connu d''''homme; je vous les amènerai dehors, et vous leur ferez ce qu''''il vous plaira. Seulement, ne faites rien à ces hommes puisqu''''ils sont venus à l''''ombre de mon toit."}, {"numero": 9, "texto": "Ils dirent: Retire-toi! Ils dirent encore: Celui-ci est venu comme étranger, et il veut faire le juge! Eh bien, nous te ferons pis qu''''à eux. Et, pressant Lot avec violence, ils s''''avancèrent pour briser la porte."}, {"numero": 10, "texto": "Les hommes étendirent la main, firent rentrer Lot vers eux dans la maison, et fermèrent la porte."}, {"numero": 11, "texto": "Et ils frappèrent d''''aveuglement les gens qui étaient à l''''entrée de la maison, depuis le plus petit jusqu''''au plus grand, de sorte qu''''ils se donnèrent une peine inutile pour trouver la porte."}, {"numero": 12, "texto": "Les hommes dirent à Lot: Qui as-tu encore ici? Gendres, fils et filles, et tout ce qui t''''appartient dans la ville, fais-les sortir de ce lieu."}, {"numero": 13, "texto": "Car nous allons détruire ce lieu, parce que le cri contre ses habitants est grand devant l''''Eternel. L''''Eternel nous a envoyés pour le détruire."}, {"numero": 14, "texto": "Lot sortit, et parla à ses gendres qui avaient pris ses filles: Levez-vous, dit-il, sortez de ce lieu; car l''''Eternel va détruire la ville. Mais, aux yeux de ses gendres, il parut plaisanter."}, {"numero": 15, "texto": "Dès l''''aube du jour, les anges insistèrent auprès de Lot, en disant: Lève-toi, prends ta femme et tes deux filles qui se trouvent ici, de peur que tu ne périsses dans la ruine de la ville."}, {"numero": 16, "texto": "Et comme il tardait, les hommes le saisirent par la main, lui, sa femme et ses deux filles, car l''''Eternel voulait l''''épargner; ils l''''emmenèrent, et le laissèrent hors de la ville."}, {"numero": 17, "texto": "Après les avoir fait sortir, l''''un d''''eux dit: Sauve-toi, pour ta vie; ne regarde pas derrière toi, et ne t''''arrête pas dans toute la plaine; sauve-toi vers la montagne, de peur que tu ne périsses."}, {"numero": 18, "texto": "Lot leur dit: Oh! non, Seigneur!"}, {"numero": 19, "texto": "Voici, j''''ai trouvé grâce à tes yeux, et tu as montré la grandeur de ta miséricorde à mon égard, en me conservant la vie; mais je ne puis me sauver à la montagne, avant que le désastre m''''atteigne, et je périrai."}, {"numero": 20, "texto": "Voici, cette ville est assez proche pour que je m''''y réfugie, et elle est petite. Oh! que je puisse m''''y sauver,... n''''est-elle pas petite?... et que mon âme vive!"}, {"numero": 21, "texto": "Et il lui dit: Voici, je t''''accorde encore cette grâce, et je ne détruirai pas la ville dont tu parles."}, {"numero": 22, "texto": "Hâte-toi de t''''y réfugier, car je ne puis rien faire jusqu''''à ce que tu y sois arrivé. C''''est pour cela que l''''on a donné à cette ville le nom de Tsoar."}, {"numero": 23, "texto": "Le soleil se levait sur la terre, lorsque Lot entra dans Tsoar."}, {"numero": 24, "texto": "Alors l''''Eternel fit pleuvoir du ciel sur Sodome et sur Gomorrhe du soufre et du feu, de par l''''Eternel."}, {"numero": 25, "texto": "Il détruisit ces villes, toute la plaine et tous les habitants des villes, et les plantes de la terre."}, {"numero": 26, "texto": "La femme de Lot regarda en arrière, et elle devint une statue de sel."}, {"numero": 27, "texto": "Abraham se leva de bon matin, pour aller au lieu où il s''''était tenu en présence de l''''Eternel."}, {"numero": 28, "texto": "Il porta ses regards du côté de Sodome et de Gomorrhe, et sur tout le territoire de la plaine; et voici, il vit s''''élever de la terre une fumée, comme la fumée d''''une fournaise."}, {"numero": 29, "texto": "Lorsque Dieu détruisit les villes de la plaine, il se souvint d''''Abraham; et il fit échapper Lot du milieu du désastre, par lequel il bouleversa les villes où Lot avait établi sa demeure."}, {"numero": 30, "texto": "Lot quitta Tsoar pour la hauteur, et se fixa sur la montagne, avec ses deux filles, car il craignait de rester à Tsoar. Il habita dans une caverne, lui et ses deux filles."}, {"numero": 31, "texto": "L''''aînée dit à la plus jeune: Notre père est vieux; et il n''''y a point d''''homme dans la contrée, pour venir vers nous, selon l''''usage de tous les pays."}, {"numero": 32, "texto": "Viens, faisons boire du vin à notre père, et couchons avec lui, afin que nous conservions la race de notre père."}, {"numero": 33, "texto": "Elles firent donc boire du vin à leur père cette nuit-là; et l''''aînée alla coucher avec son père: il ne s''''aperçut ni quand elle se coucha, ni quand elle se leva."}, {"numero": 34, "texto": "Le lendemain, l''''aînée dit à la plus jeune: Voici, j''''ai couché la nuit dernière avec mon père; faisons-lui boire du vin encore cette nuit, et va coucher avec lui, afin que nous conservions la race de notre père."}, {"numero": 35, "texto": "Elles firent boire du vin à leur père encore cette nuit-là; et la cadette alla coucher avec lui: il ne s''''aperçut ni quand elle se coucha, ni quand elle se leva."}, {"numero": 36, "texto": "Les deux filles de Lot devinrent enceintes de leur père."}, {"numero": 37, "texto": "L''''aînée enfanta un fils, qu''''elle appela du nom de Moab: c''''est le père des Moabites, jusqu''''à ce jour."}, {"numero": 38, "texto": "La plus jeune enfanta aussi un fils, qu''''elle appela du nom de Ben-Ammi: c''''est le père des Ammonites, jusqu''''à ce jour."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 19, 'es', '[{"numero": 1, "texto": "LLEGARON, pues, los dos ángeles á Sodoma á la caída de la tarde: y Lot estaba sentado á la puerta de Sodoma. Y viéndolos Lot, levantóse á recibirlos, é inclinóse hacia el suelo;"}, {"numero": 2, "texto": "Y dijo: Ahora, pues, mis señores, os ruego que vengáis á casa de vuestro siervo y os hospedéis, y lavaréis vuestros pies: y por la mañana os levantaréis, y seguiréis vuestro camino. Y ellos respondieron: No, que en la plaza nos quedaremos esta noche."}, {"numero": 3, "texto": "Mas él porfió con ellos mucho, y se vinieron con él, y entraron en su casa; é hízoles banquete, y coció panes sin levadura, y comieron."}, {"numero": 4, "texto": "Y antes que se acostasen, cercaron la casa los hombres de la ciudad, los varones de Sodoma, todo el pueblo junto, desde el más joven hasta el más viejo;"}, {"numero": 5, "texto": "Y llamaron á Lot, y le dijeron: ¿Dónde están los varones que vinieron á ti esta noche? sácanoslos, para que los conozcamos."}, {"numero": 6, "texto": "Entonces Lot salió á ellos á la puerta, y cerró las puertas tras sí,"}, {"numero": 7, "texto": "Y dijo: Os ruego, hermanos míos, que no hagáis tal maldad."}, {"numero": 8, "texto": "He aquí ahora yo tengo dos hijas que no han conocido varón; os las sacaré afuera, y haced de ellas como bien os pareciere: solamente á estos varones no hagáis nada, pues que vinieron á la sombra de mi tejado."}, {"numero": 9, "texto": "Y ellos respondieron: Quita allá: y añadieron: Vino éste aquí para habitar como un extraño, ¿y habrá de erigirse en juez? Ahora te haremos más mal que á ellos. Y hacían gran violencia al varón, á Lot, y se acercaron para romper las puertas."}, {"numero": 10, "texto": "Entonces los varones alargaron la mano, y metieron á Lot en casa con ellos, y cerraron las puertas."}, {"numero": 11, "texto": "Y á los hombres que estaban á la puerta de la casa desde el menor hasta el mayor, hirieron con ceguera; mas ellos se fatigaban por hallar la puerta."}, {"numero": 12, "texto": "Y dijeron los varones á Lot: ¿Tienes aquí alguno más? Yernos, y tus hijos y tus hijas, y todo lo que tienes en la ciudad, sácalo de este lugar:"}, {"numero": 13, "texto": "Porque vamos á destruir este lugar, por cuanto el clamor de ellos ha subido de punto delante de Jehová; por tanto Jehová nos ha enviado para destruirlo."}, {"numero": 14, "texto": "Entonces salió Lot, y habló á sus yernos, los que habían de tomar sus hijas, y les dijo: Levantaos, salid de este lugar; porque Jehová va á destruir esta ciudad. Mas pareció á sus yernos como que se burlaba."}, {"numero": 15, "texto": "Y al rayar el alba, los ángeles daban prisa á Lot, diciendo: Levántate, toma tu mujer, y tus dos hijas que se hallan aquí, porque no perezcas en el castigo de la ciudad."}, {"numero": 16, "texto": "Y deteniéndose él, los varones asieron de su mano, y de la mano de su mujer, y de las manos de sus dos hijas, según la misericordia de Jehová para con él; y le sacaron, y le pusieron fuera de la ciudad."}, {"numero": 17, "texto": "Y fué que cuando los hubo sacado fuera, dijo: Escapa por tu vida; no mires tras ti, ni pares en toda esta llanura; escapa al monte, no sea que perezcas."}, {"numero": 18, "texto": "Y Lot les dijo: No, yo os ruego, señores míos;"}, {"numero": 19, "texto": "He aquí ahora ha hallado tu siervo gracia en tus ojos, y has engrandecido tu misericordia que has hecho conmigo dándome la vida; mas yo no podré escapar al monte, no sea caso que me alcance el mal, y muera."}, {"numero": 20, "texto": "He aquí ahora esta ciudad está cerca para huir allá, la cual es pequeña; escaparé ahora allá, (¿no es ella pequeña?) y vivirá mi alma."}, {"numero": 21, "texto": "Y le respondió: He aquí he recibido también tu súplica sobre esto, y no destruiré la ciudad de que has hablado."}, {"numero": 22, "texto": "Date priesa, escápate allá; porque nada podré hacer hasta que allí hayas llegado. Por esto fué llamado el nombre de la ciudad, Zoar."}, {"numero": 23, "texto": "El sol salía sobre la tierra, cuando Lot llegó á Zoar."}, {"numero": 24, "texto": "Entonces llovió Jehová sobre Sodoma y sobre Gomorra azufre y fuego de parte de Jehová desde los cielos;"}, {"numero": 25, "texto": "Y destruyó las ciudades, y toda aquella llanura, con todos los moradores de aquellas ciudades, y el fruto de la tierra."}, {"numero": 26, "texto": "Entonces la mujer de Lot miró atrás, á espaldas de él, y se volvió estatua de sal."}, {"numero": 27, "texto": "Y subió Abraham por la mañana al lugar donde había estado delante de Jehová:"}, {"numero": 28, "texto": "Y miró hacia Sodoma y Gomorra, y hacia toda la tierra de aquella llanura miró; y he aquí que el humo subía de la tierra como el humo de un horno."}, {"numero": 29, "texto": "Así fué que, cuando destruyó Dios las ciudades de la llanura, acordóse Dios de Abraham, y envió fuera á Lot de en medio de la destrucción, al asolar las ciudades donde Lot estaba."}, {"numero": 30, "texto": "Empero Lot subió de Zoar, y asentó en el monte, y sus dos hijas con él; porque tuvo miedo de quedar en Zoar, y se alojó en una cueva él y sus dos hijas."}, {"numero": 31, "texto": "Entonces la mayor dijo á la menor: Nuestro padre es viejo, y no queda varón en la tierra que entre á nosotras conforme á la costumbre de toda la tierra:"}, {"numero": 32, "texto": "Ven, demos á beber vino á nuestro padre, y durmamos con él, y conservaremos de nuestro padre generación."}, {"numero": 33, "texto": "Y dieron á beber vino á su padre aquella noche: y entró la mayor, y durmió con su padre; mas él no sintió cuándo se acostó ella, ni cuándo se levantó."}, {"numero": 34, "texto": "El día siguiente dijo la mayor á la menor: He aquí yo dormí la noche pasada con mi padre; démosle á beber vino también esta noche, y entra y duerme con él, para que conservemos de nuestro padre generación."}, {"numero": 35, "texto": "Y dieron á beber vino á su padre también aquella noche: y levantóse la menor, y durmió con él; pero no echó de ver cuándo se acostó ella, ni cuándo se levantó."}, {"numero": 36, "texto": "Y concibieron las dos hijas de Lot, de su padre."}, {"numero": 37, "texto": "Y parió la mayor un hijo, y llamó su nombre Moab, el cual es padre de los Moabitas hasta hoy."}, {"numero": 38, "texto": "La menor también parió un hijo, y llamó su nombre Ben-ammí, el cual es padre de los Ammonitas hasta hoy."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 21, 'pt', '[{"numero": 1, "texto": "E o SENHOR visitou Sara, como disse, e o SENHOR fez com Sara como havia falado."}, {"numero": 2, "texto": "E concebeu e deu à luz Sara a Abraão um filho em sua velhice, no tempo que Deus lhe havia dito."}, {"numero": 3, "texto": "E chamou Abraão o nome de seu filho que lhe nasceu, que lhe deu à luz Sara, Isaque."}, {"numero": 4, "texto": "E circuncidou Abraão a seu filho Isaque de oito dias, como Deus lhe havia mandado."}, {"numero": 5, "texto": "E era Abraão de cem anos, quando lhe nasceu Isaque seu filho."}, {"numero": 6, "texto": "Então disse Sara: Deus me fez rir, e qualquer um que o ouvir, se rirá comigo."}, {"numero": 7, "texto": "E acrescentou: Quem diria a Abraão que Sara havia de dar de mamar a filhos? pois que lhe dei um filho em sua velhice."}, {"numero": 8, "texto": "E cresceu o menino, e foi desmamado; e fez Abraão grande banquete no dia que foi desmamado Isaque."}, {"numero": 9, "texto": "E viu Sara ao filho de Agar a egípcia, o qual havia esta dado a Abraão, que o ridicularizava."}, {"numero": 10, "texto": "Portanto disse a Abraão: Expulsa a esta serva e a seu filho; que o filho desta serva não herdará com meu filho, com Isaque."}, {"numero": 11, "texto": "Este dito pareceu grave em grande maneira a Abraão por causa de seu filho."}, {"numero": 12, "texto": "Então disse Deus a Abraão: Não te pareça grave por causa do jovem e de tua serva; em tudo o que te disser Sara, ouve sua voz, porque em Isaque será chamada tua descendência."}, {"numero": 13, "texto": "E também do filho da serva farei nação, porque é descendência tua."}, {"numero": 14, "texto": "Então Abraão se levantou manhã muito cedo, e tomou pão, e um odre de água, e deu-o a Agar, pondo-o sobre seu ombro, e entregou-lhe o jovem, e despediu-a. E ela partiu, e andava errante pelo deserto de Berseba."}, {"numero": 15, "texto": "E faltou a água do odre, e deitou ao jovem debaixo de uma árvore;"}, {"numero": 16, "texto": "E foi-se e sentou-se em frente, afastando-se como um tiro de arco; porque dizia: Não verei quando o jovem morrer: e sentou-se em frente, e levantou sua voz e chorou."}, {"numero": 17, "texto": "E ouviu Deus a voz do jovem; e o anjo de Deus chamou a Agar desde o céu, e lhe disse: Que tens, Agar? Não temas; porque Deus ouviu a voz do jovem onde está."}, {"numero": 18, "texto": "Levanta-te, ergue ao jovem, e pegue-o por tua mão, porque farei dele uma grande nação."}, {"numero": 19, "texto": "Então abriu Deus os olhos dela, e ela viu uma fonte de água; e foi, e encheu o odre de água, e deu de beber ao jovem."}, {"numero": 20, "texto": "E foi Deus com o jovem; e cresceu, e habitou no deserto, e foi atirador de arco."}, {"numero": 21, "texto": "E habitou no deserto de Parã; e sua mãe lhe tomou mulher da terra do Egito."}, {"numero": 22, "texto": "E aconteceu naquele mesmo tempo que falou Abimeleque, e Ficol, príncipe de seu exército, a Abraão dizendo: Deus é contigo em tudo quanto fazes."}, {"numero": 23, "texto": "Agora, pois, jura-me aqui por Deus, que não tratarás com falsidade a mim, nem a meu filho, nem a meu neto; mas sim que conforme a bondade que eu fiz contigo, farás tu comigo e com a terra onde peregrinaste."}, {"numero": 24, "texto": "E respondeu Abraão: Eu jurarei."}, {"numero": 25, "texto": "E Abraão reclamou com Abimeleque por causa de um poço de água, que os servos de Abimeleque lhe haviam tirado."}, {"numero": 26, "texto": "E respondeu Abimeleque: Não sei quem tenha feito isto, nem tampouco tu me fizeste saber, nem eu o ouvi até hoje."}, {"numero": 27, "texto": "E tomou Abraão ovelhas e vacas, e deu a Abimeleque; e fizeram ambos aliança."}, {"numero": 28, "texto": "E pôs Abraão sete cordeiras do rebanho à parte."}, {"numero": 29, "texto": "E disse Abimeleque a Abraão: Que significam essas sete cordeiras que puseste à parte?"}, {"numero": 30, "texto": "E ele respondeu: Que estas sete cordeiras tomarás de minha mão, para que me sejam em testemunho de que eu cavei este poço."}, {"numero": 31, "texto": "Por isto chamou a aquele lugar Berseba; porque ali ambos juraram."}, {"numero": 32, "texto": "Assim fizeram aliança em Berseba: e levantaram-se Abimeleque e Ficol, príncipe de seu exército, e se voltaram à terra dos filisteus."}, {"numero": 33, "texto": "E plantou Abraão um bosque em Berseba, e invocou ali o nome do SENHOR Deus eterno."}, {"numero": 34, "texto": "E morou Abraão na terra dos filisteus por muitos dias."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 21, 'en', '[{"numero": 1, "texto": "And the Lord visited Sarah as he had said, and the Lord did unto Sarah as he had spoken."}, {"numero": 2, "texto": "For Sarah conceived, and bare Abraham a son in his old age, at the set time of which God had spoken to him."}, {"numero": 3, "texto": "And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac."}, {"numero": 4, "texto": "And Abraham circumcised his son Isaac being eight days old, as God had commanded him."}, {"numero": 5, "texto": "And Abraham was an hundred years old, when his son Isaac was born unto him."}, {"numero": 6, "texto": "And Sarah said, God hath made me to laugh, so that all that hear will laugh with me."}, {"numero": 7, "texto": "And she said, Who would have said unto Abraham, that Sarah should have given children suck? for I have born him a son in his old age."}, {"numero": 8, "texto": "And the child grew, and was weaned: and Abraham made a great feast the same day that Isaac was weaned."}, {"numero": 9, "texto": "And Sarah saw the son of Hagar the Egyptian, which she had born unto Abraham, mocking."}, {"numero": 10, "texto": "Wherefore she said unto Abraham, Cast out this bondwoman and her son: for the son of this bondwoman shall not be heir with my son, even with Isaac."}, {"numero": 11, "texto": "And the thing was very grievous in Abraham''s sight because of his son."}, {"numero": 12, "texto": "And God said unto Abraham, Let it not be grievous in thy sight because of the lad, and because of thy bondwoman; in all that Sarah hath said unto thee, hearken unto her voice; for in Isaac shall thy seed be called."}, {"numero": 13, "texto": "And also of the son of the bondwoman will I make a nation, because he is thy seed."}, {"numero": 14, "texto": "And Abraham rose up early in the morning, and took bread, and a bottle of water, and gave it unto Hagar, putting it on her shoulder, and the child, and sent her away: and she departed, and wandered in the wilderness of Beersheba."}, {"numero": 15, "texto": "And the water was spent in the bottle, and she cast the child under one of the shrubs."}, {"numero": 16, "texto": "And she went, and sat her down over against him a good way off, as it were a bow shot: for she said, Let me not see the death of the child. And she sat over against him, and lift up her voice, and wept."}, {"numero": 17, "texto": "And God heard the voice of the lad; and the angel of God called to Hagar out of heaven, and said unto her, What aileth thee, Hagar? fear not; for God hath heard the voice of the lad where he is."}, {"numero": 18, "texto": "Arise, lift up the lad, and hold him in thine hand; for I will make him a great nation."}, {"numero": 19, "texto": "And God opened her eyes, and she saw a well of water; and she went, and filled the bottle with water, and gave the lad drink."}, {"numero": 20, "texto": "And God was with the lad; and he grew, and dwelt in the wilderness, and became an archer."}, {"numero": 21, "texto": "And he dwelt in the wilderness of Paran: and his mother took him a wife out of the land of Egypt."}, {"numero": 22, "texto": "And it came to pass at that time, that Abimelech and Phichol the chief captain of his host spake unto Abraham, saying, God is with thee in all that thou doest:"}, {"numero": 23, "texto": "Now therefore swear unto me here by God that thou wilt not deal falsely with me, nor with my son, nor with my son''s son: but according to the kindness that I have done unto thee, thou shalt do unto me, and to the land wherein thou hast sojourned."}, {"numero": 24, "texto": "And Abraham said, I will swear."}, {"numero": 25, "texto": "And Abraham reproved Abimelech because of a well of water, which Abimelech''s servants had violently taken away."}, {"numero": 26, "texto": "And Abimelech said, I wot not who hath done this thing; neither didst thou tell me, neither yet heard I of it, but to day."}, {"numero": 27, "texto": "And Abraham took sheep and oxen, and gave them unto Abimelech; and both of them made a covenant."}, {"numero": 28, "texto": "And Abraham set seven ewe lambs of the flock by themselves."}, {"numero": 29, "texto": "And Abimelech said unto Abraham, What mean these seven ewe lambs which thou hast set by themselves?"}, {"numero": 30, "texto": "And he said, For these seven ewe lambs shalt thou take of my hand, that they may be a witness unto me, that I have digged this well."}, {"numero": 31, "texto": "Wherefore he called that place Beersheba; because there they sware both of them."}, {"numero": 32, "texto": "Thus they made a covenant at Beersheba: then Abimelech rose up, and Phichol the chief captain of his host, and they returned into the land of the Philistines."}, {"numero": 33, "texto": "And Abraham planted a grove in Beersheba, and called there on the name of the Lord, the everlasting God."}, {"numero": 34, "texto": "And Abraham sojourned in the Philistines'' land many days."}]'::jsonb, 'King James Version'),
  ('Gn', 21, 'fr', '[{"numero": 1, "texto": "L''''Eternel se souvint de ce qu''''il avait dit à Sara, et l''''Eternel accomplit pour Sara ce qu''''il avait promis."}, {"numero": 2, "texto": "Sara devint enceinte, et elle enfanta un fils à Abraham dans sa vieillesse, au temps fixé dont Dieu lui avait parlé."}, {"numero": 3, "texto": "Abraham donna le nom d''''Isaac au fils qui lui était né, que Sara lui avait enfanté."}, {"numero": 4, "texto": "Abraham circoncit son fils Isaac, âgé de huit jours, comme Dieu le lui avait ordonné."}, {"numero": 5, "texto": "Abraham était âgé de cent ans, à la naissance d''''Isaac, son fils."}, {"numero": 6, "texto": "Et Sara dit: Dieu m''''a fait un sujet de rire; quiconque l''''apprendra rira de moi."}, {"numero": 7, "texto": "Elle ajouta: Qui aurait dit à Abraham: Sara allaitera des enfants? Cependant je lui ai enfanté un fils dans sa vieillesse."}, {"numero": 8, "texto": "L''''enfant grandit, et fut sevré; et Abraham fit un grand festin le jour où Isaac fut sevré."}, {"numero": 9, "texto": "Sara vit rire le fils qu''''Agar, l''''Egyptienne, avait enfanté à Abraham;"}, {"numero": 10, "texto": "et elle dit à Abraham: Chasse cette servante et son fils, car le fils de cette servante n''''héritera pas avec mon fils, avec Isaac."}, {"numero": 11, "texto": "Cette parole déplut fort aux yeux d''''Abraham, à cause de son fils."}, {"numero": 12, "texto": "Mais Dieu dit à Abraham: Que cela ne déplaise pas à tes yeux, à cause de l''''enfant et de ta servante. Accorde à Sara tout ce qu''''elle te demandera; car c''''est d''''Isaac que sortira une postérité qui te sera propre."}, {"numero": 13, "texto": "Je ferai aussi une nation du fils de ta servante; car il est ta postérité."}, {"numero": 14, "texto": "Abraham se leva de bon matin; il prit du pain et une outre d''''eau, qu''''il donna à Agar et plaça sur son épaule; il lui remit aussi l''''enfant, et la renvoya. Elle s''''en alla, et s''''égara dans le désert de Beer-Schéba."}, {"numero": 15, "texto": "Quand l''''eau de l''''outre fut épuisée, elle laissa l''''enfant sous un des arbrisseaux,"}, {"numero": 16, "texto": "et alla s''''asseoir vis-à-vis, à une portée d''''arc; car elle disait: Que je ne voie pas mourir mon enfant! Elle s''''assit donc vis-à-vis de lui, éleva la voix et pleura."}, {"numero": 17, "texto": "Dieu entendit la voix de l''''enfant; et l''''ange de Dieu appela du ciel Agar, et lui dit: Qu''''as-tu, Agar? Ne crains point, car Dieu a entendu la voix de l''''enfant dans le lieu où il est."}, {"numero": 18, "texto": "Lève-toi, prends l''''enfant, saisis-le de ta main; car je ferai de lui une grande nation."}, {"numero": 19, "texto": "Et Dieu lui ouvrit les yeux, et elle vit un puits d''''eau; elle alla remplir d''''eau l''''outre, et donna à boire à l''''enfant."}, {"numero": 20, "texto": "Dieu fut avec l''''enfant, qui grandit, habita dans le désert, et devint tireur d''''arc."}, {"numero": 21, "texto": "Il habita dans le désert de Paran, et sa mère lui prit une femme du pays d''''Egypte."}, {"numero": 22, "texto": "En ce temps-là, Abimélec, accompagné de Picol, chef de son armée, parla ainsi à Abraham: Dieu est avec toi dans tout ce que tu fais."}, {"numero": 23, "texto": "Jure-moi maintenant ici, par le nom de Dieu, que tu ne tromperas ni moi, ni mes enfants, ni mes petits-enfants, et que tu auras pour moi et le pays où tu séjournes la même bienveillance que j''''ai eue pour toi."}, {"numero": 24, "texto": "Abraham dit: Je le jurerai."}, {"numero": 25, "texto": "Mais Abraham fit des reproches à Abimélec, au sujet d''''un puits d''''eau, dont s''''étaient emparés de force les serviteurs d''''Abimélec."}, {"numero": 26, "texto": "Abimélec répondit: J''''ignore qui a fait cette chose-là; tu ne m''''en as point informé, et moi, je ne l''''apprends qu''''aujourd''''hui."}, {"numero": 27, "texto": "Et Abraham prit des brebis et des boeufs, qu''''il donna à Abimélec; et ils firent tous deux alliance."}, {"numero": 28, "texto": "Abraham mit à part sept jeunes brebis."}, {"numero": 29, "texto": "Et Abimélec dit à Abraham: Qu''''est-ce que ces sept jeunes brebis, que tu as mises à part?"}, {"numero": 30, "texto": "Il répondit: Tu accepteras de ma main ces sept brebis, afin que cela me serve de témoignage que j''''ai creusé ce puits."}, {"numero": 31, "texto": "C''''est pourquoi on appelle ce lieu Beer-Schéba; car c''''est là qu''''ils jurèrent l''''un et l''''autre."}, {"numero": 32, "texto": "Ils firent donc alliance à Beer-Schéba. Après quoi, Abimélec se leva, avec Picol, chef de son armée; et ils retournèrent au pays des Philistins."}, {"numero": 33, "texto": "Abraham planta des tamariscs à Beer-Schéba; et là il invoqua le nom de l''''Eternel, Dieu de l''''éternité."}, {"numero": 34, "texto": "Abraham séjourna longtemps dans le pays des Philistins."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 21, 'es', '[{"numero": 1, "texto": "Y VISITÓ Jehová á Sara, como había dicho, é hizo Jehová con Sara como había hablado."}, {"numero": 2, "texto": "Y concibió y parió Sara á Abraham un hijo en su vejez, en el tiempo que Dios le había dicho."}, {"numero": 3, "texto": "Y llamó Abraham el nombre de su hijo que le nació, que le parió Sara, Isaac."}, {"numero": 4, "texto": "Y circuncidó Abraham á su hijo Isaac de ocho días, como Dios le había mandado."}, {"numero": 5, "texto": "Y era Abraham de cien años, cuando le nació Isaac su hijo."}, {"numero": 6, "texto": "Entonces dijo Sara: Dios me ha hecho reir, y cualquiera que lo oyere, se reirá conmigo."}, {"numero": 7, "texto": "Y añadió: ¿Quién dijera á Abraham que Sara había de dar de mamar á hijos? pues que le he parido un hijo á su vejez."}, {"numero": 8, "texto": "Y creció el niño, y fué destetado; é hizo Abraham gran banquete el día que fué destetado Isaac."}, {"numero": 9, "texto": "Y vió Sara al hijo de Agar la Egipcia, el cual había ésta parido á Abraham, que se burlaba."}, {"numero": 10, "texto": "Por tanto dijo á Abraham: Echa á esta sierva y á su hijo; que el hijo de esta sierva no ha de heredar con mi hijo, con Isaac."}, {"numero": 11, "texto": "Este dicho pareció grave en gran manera á Abraham á causa de su hijo."}, {"numero": 12, "texto": "Entonces dijo Dios á Abraham: No te parezca grave á causa del muchacho y de tu sierva; en todo lo que te dijere Sara, oye su voz, porque en Isaac te será llamada descendencia."}, {"numero": 13, "texto": "Y también al hijo de la sierva pondré en gente, porque es tu simiente."}, {"numero": 14, "texto": "Entonces Abraham se levantó muy de mañana, y tomó pan, y un odre de agua, y diólo á Agar, poniéndolo sobre su hombro, y entrególe el muchacho, y despidióla. Y ella partió, y andaba errante por el desierto de Beer-seba."}, {"numero": 15, "texto": "Y faltó el agua del odre, y echó al muchacho debajo de un árbol;"}, {"numero": 16, "texto": "Y fuése y sentóse enfrente, alejándose como un tiro de arco; porque decía: No veré cuando el muchacho morirá: y sentóse enfrente, y alzó su voz y lloró."}, {"numero": 17, "texto": "Y oyó Dios la voz del muchacho; y el ángel de Dios llamó á Agar desde el cielo, y le dijo: ¿Qué tienes, Agar? No temas; porque Dios ha oído la voz del muchacho en donde está."}, {"numero": 18, "texto": "Levántate, alza al muchacho, y ásele de tu mano, porque en gran gente lo tengo de poner."}, {"numero": 19, "texto": "Entonces abrió Dios sus ojos, y vió una fuente de agua; y fué, y llenó el odre de agua, y dió de beber al muchacho."}, {"numero": 20, "texto": "Y fué Dios con el muchacho; y creció, y habitó en el desierto, y fué tirador de arco."}, {"numero": 21, "texto": "Y habitó en el desierto de Parán; y su madre le tomó mujer de la tierra de Egipto."}, {"numero": 22, "texto": "Y aconteció en aquel mismo tiempo que habló Abimelech, y Phicol , príncipe de su ejército, á Abraham diciendo: Dios es contigo en todo cuanto haces:"}, {"numero": 23, "texto": "Ahora pues, júrame aquí por Dios, que no faltarás á mí, ni á mi hijo, ni á mi nieto; sino que conforme á la bondad que yo hice contigo, harás tú conmigo, y con la tierra donde has peregrinado."}, {"numero": 24, "texto": "Y respondió Abraham: Yo juraré."}, {"numero": 25, "texto": "Y Abraham reconvino á Abimelech á causa de un pozo de agua, que los siervos de Abimelech le habían quitado."}, {"numero": 26, "texto": "Y respondió Abimelech: No sé quién haya hecho esto, ni tampoco tú me lo hiciste saber, ni yo lo he oído hasta hoy."}, {"numero": 27, "texto": "Y tomó Abraham ovejas y vacas, y dió á Abimelech; é hicieron ambos alianza."}, {"numero": 28, "texto": "Y puso Abraham siete corderas del rebaño aparte."}, {"numero": 29, "texto": "Y dijo Abimelech á Abraham: ¿Qué significan esas siete corderas que has puesto aparte?"}, {"numero": 30, "texto": "Y él respondió: Que estas siete corderas tomarás de mi mano, para que me sean en testimonio de que yo cavé este pozo."}, {"numero": 31, "texto": "Por esto llamó á aquel lugar Beer-seba; porque allí juraron ambos."}, {"numero": 32, "texto": "Así hicieron alianza en Beer-seba: y levantóse Abimelech, y Phicol, príncipe de su ejército, y se volvieron á tierra de los Filisteos."}, {"numero": 33, "texto": "Y plantó Abraham un bosque en Beer-seba, é invocó allí el nombre de Jehová Dios eterno."}, {"numero": 34, "texto": "Y moró Abraham en tierra de los Filisteos muchos días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 22, 'pt', '[{"numero": 1, "texto": "E aconteceu, depois dessas coisas, que Deus provou Abraão, e disse-lhe: Abraão. E ele respondeu: Eis-me aqui."}, {"numero": 2, "texto": "E disse: Toma agora teu filho, teu único, Isaque, a quem amas, e vai à terra de Moriá, e oferece-o ali em holocausto sobre um dos montes que eu te direi."}, {"numero": 3, "texto": "E Abraão se levantou manhã muito cedo, e preparou seu asno, e tomou consigo dois servos seus, e a Isaque seu filho: e cortou lenha para o holocausto, e levantou-se, e foi ao lugar que Deus lhe disse."}, {"numero": 4, "texto": "Ao terceiro dia levantou Abraão seus olhos, e viu o lugar de longe."}, {"numero": 5, "texto": "Então disse Abraão a seus servos: Esperai aqui com o asno, e eu e o jovem iremos até ali, e adoraremos, e voltaremos a vós."}, {"numero": 6, "texto": "E tomou Abraão a lenha do holocausto, e a pôs sobre Isaque seu filho: e ele tomou em sua mão o fogo e a espada; e foram ambos juntos."}, {"numero": 7, "texto": "Então falou Isaque a Abraão seu pai, e disse: Meu pai. e ele respondeu: Eis-me aqui, meu filho. E ele disse: Eis aqui o fogo e a lenha; mas onde está o cordeiro para o holocausto?"}, {"numero": 8, "texto": "E respondeu Abraão: Deus se proverá de cordeiro para o holocausto, filho meu. E iam juntos."}, {"numero": 9, "texto": "E quando chegaram ao lugar que Deus lhe havia dito, edificou ali Abraão um altar, e compôs a lenha, e amarrou a Isaque seu filho, e pôs-lhe no altar sobre a lenha."}, {"numero": 10, "texto": "E estendeu Abraão sua mão, e tomou a espada, para degolar a seu filho."}, {"numero": 11, "texto": "Então o anjo do SENHOR lhe gritou do céu, e disse: Abraão, Abraão. E ele respondeu: Eis-me aqui."}, {"numero": 12, "texto": "E disse: Não estendas tua mão sobre o jovem, nem lhe faças nada; que já conheço que temes a Deus, pois que não me recusaste o teu filho, o teu único;"}, {"numero": 13, "texto": "Então levantou Abraão seus olhos, e olhou, e eis um carneiro a suas costas preso em um arbusto por seus chifres: e foi Abraão, e tomou o carneiro, e ofereceu-lhe em holocausto em lugar de seu filho."}, {"numero": 14, "texto": "E chamou Abraão o nome daquele lugar, O SENHOR proverá. Portanto se diz hoje: No monte do SENHOR se proverá."}, {"numero": 15, "texto": "E chamou o anjo do SENHOR a Abraão segunda vez desde o céu,"}, {"numero": 16, "texto": "E disse: Por mim mesmo jurei, diz o SENHOR, que porquanto fizeste isto, e não me recusaste teu filho, teu único;"}, {"numero": 17, "texto": "certamente te abençoarei, e multiplicarei tua descendência como as estrelas do céu, e como a areia que está na beira do mar; e tua descendência possuirá as portas de seus inimigos:"}, {"numero": 18, "texto": "Em tua descendência serão abençoadas todas as nações da terra, porquanto obedeceste à minha voz."}, {"numero": 19, "texto": "E voltou Abraão a seus servos, e levantaram-se e se foram juntos a Berseba; e habitou Abraão em Berseba."}, {"numero": 20, "texto": "E aconteceu depois destas coisas, que foi dada notícia a Abraão, dizendo: Eis que também Milca havia dado à luz filhos a teu irmão Naor:"}, {"numero": 21, "texto": "A Uz, seu primogênito, e a Buz, seu irmão, e a Quemuel, pai de Arã."}, {"numero": 22, "texto": "E a Quésede, e a Hazo, e a Pildas, e a Jidlafe, e a Betuel."}, {"numero": 23, "texto": "E Betuel gerou Rebeca. Milca deu à luz estes oito de Naor, irmão de Abraão."}, {"numero": 24, "texto": "E sua concubina, que se chamava Reumá, deu à luz também a Tebá, e a Gaã, e a Taás, e a Maaca."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 22, 'en', '[{"numero": 1, "texto": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am."}, {"numero": 2, "texto": "And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}, {"numero": 3, "texto": "And Abraham rose up early in the morning, and saddled his ass, and took two of his young men with him, and Isaac his son, and clave the wood for the burnt offering, and rose up, and went unto the place of which God had told him."}, {"numero": 4, "texto": "Then on the third day Abraham lifted up his eyes, and saw the place afar off."}, {"numero": 5, "texto": "And Abraham said unto his young men, Abide ye here with the ass; and I and the lad will go yonder and worship, and come again to you."}, {"numero": 6, "texto": "And Abraham took the wood of the burnt offering, and laid it upon Isaac his son; and he took the fire in his hand, and a knife; and they went both of them together."}, {"numero": 7, "texto": "And Isaac spake unto Abraham his father, and said, My father: and he said, Here am I, my son. And he said, Behold the fire and the wood: but where is the lamb for a burnt offering?"}, {"numero": 8, "texto": "And Abraham said, My son, God will provide himself a lamb for a burnt offering: so they went both of them together."}, {"numero": 9, "texto": "And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood."}, {"numero": 10, "texto": "And Abraham stretched forth his hand, and took the knife to slay his son."}, {"numero": 11, "texto": "And the angel of the Lord called unto him out of heaven, and said, Abraham, Abraham: and he said, Here am I."}, {"numero": 12, "texto": "And he said, Lay not thine hand upon the lad, neither do thou any thing unto him: for now I know that thou fearest God, seeing thou hast not withheld thy son, thine only son from me."}, {"numero": 13, "texto": "And Abraham lifted up his eyes, and looked, and behold behind him a ram caught in a thicket by his horns: and Abraham went and took the ram, and offered him up for a burnt offering in the stead of his son."}, {"numero": 14, "texto": "And Abraham called the name of that place Jehovahjireh: as it is said to this day, In the mount of the Lord it shall be seen."}, {"numero": 15, "texto": "And the angel of the Lord called unto Abraham out of heaven the second time,"}, {"numero": 16, "texto": "And said, By myself have I sworn, saith the Lord, for because thou hast done this thing, and hast not withheld thy son, thine only son:"}, {"numero": 17, "texto": "That in blessing I will bless thee, and in multiplying I will multiply thy seed as the stars of the heaven, and as the sand which is upon the sea shore; and thy seed shall possess the gate of his enemies;"}, {"numero": 18, "texto": "And in thy seed shall all the nations of the earth be blessed; because thou hast obeyed my voice."}, {"numero": 19, "texto": "So Abraham returned unto his young men, and they rose up and went together to Beersheba; and Abraham dwelt at Beersheba."}, {"numero": 20, "texto": "And it came to pass after these things, that it was told Abraham, saying, Behold, Milcah, she hath also born children unto thy brother Nahor;"}, {"numero": 21, "texto": "Huz his firstborn, and Buz his brother, and Kemuel the father of Aram,"}, {"numero": 22, "texto": "And Chesed, and Hazo, and Pildash, and Jidlaph, and Bethuel."}, {"numero": 23, "texto": "And Bethuel begat Rebekah: these eight Milcah did bear to Nahor, Abraham''s brother."}, {"numero": 24, "texto": "And his concubine, whose name was Reumah, she bare also Tebah, and Gaham, and Thahash, and Maachah."}]'::jsonb, 'King James Version'),
  ('Gn', 22, 'fr', '[{"numero": 1, "texto": "Après ces choses, Dieu mit Abraham à l''''épreuve, et lui dit: Abraham! Et il répondit: Me voici!"}, {"numero": 2, "texto": "Dieu dit: Prends ton fils, ton unique, celui que tu aimes, Isaac; va-t''''en au pays de Morija, et là offre-le en holocauste sur l''''une des montagnes que je te dirai."}, {"numero": 3, "texto": "Abraham se leva de bon matin, sella son âne, et prit avec lui deux serviteurs et son fils Isaac. Il fendit du bois pour l''''holocauste, et partit pour aller au lieu que Dieu lui avait dit."}, {"numero": 4, "texto": "Le troisième jour, Abraham, levant les yeux, vit le lieu de loin."}, {"numero": 5, "texto": "Et Abraham dit à ses serviteurs: Restez ici avec l''''âne; moi et le jeune homme, nous irons jusque-là pour adorer, et nous reviendrons auprès de vous."}, {"numero": 6, "texto": "Abraham prit le bois pour l''''holocauste, le chargea sur son fils Isaac, et porta dans sa main le feu et le couteau. Et ils marchèrent tous deux ensemble."}, {"numero": 7, "texto": "Alors Isaac, parlant à Abraham, son père, dit: Mon père! Et il répondit: Me voici, mon fils! Isaac reprit: Voici le feu et le bois; mais où est l''''agneau pour l''''holocauste?"}, {"numero": 8, "texto": "Abraham répondit: Mon fils, Dieu se pourvoira lui-même de l''''agneau pour l''''holocauste. Et ils marchèrent tous deux ensemble."}, {"numero": 9, "texto": "Lorsqu''''ils furent arrivés au lieu que Dieu lui avait dit, Abraham y éleva un autel, et rangea le bois. Il lia son fils Isaac, et le mit sur l''''autel, par-dessus le bois."}, {"numero": 10, "texto": "Puis Abraham étendit la main, et prit le couteau, pour égorger son fils."}, {"numero": 11, "texto": "Alors l''''ange de l''''Eternel l''''appela des cieux, et dit: Abraham! Abraham! Et il répondit: Me voici!"}, {"numero": 12, "texto": "L''''ange dit: N''''avance pas ta main sur l''''enfant, et ne lui fais rien; car je sais maintenant que tu crains Dieu, et que tu ne m''''as pas refusé ton fils, ton unique."}, {"numero": 13, "texto": "Abraham leva les yeux, et vit derrière lui un bélier retenu dans un buisson par les cornes; et Abraham alla prendre le bélier, et l''''offrit en holocauste à la place de son fils."}, {"numero": 14, "texto": "Abraham donna à ce lieu le nom de Jehova-Jiré. C''''est pourquoi l''''on dit aujourd''''hui: A la montagne de l''''Eternel il sera pourvu."}, {"numero": 15, "texto": "L''''ange de l''''Eternel appela une seconde fois Abraham des cieux,"}, {"numero": 16, "texto": "et dit: Je le jure par moi-même, parole de l''''Eternel! parce que tu as fait cela, et que tu n''''as pas refusé ton fils, ton unique,"}, {"numero": 17, "texto": "je te bénirai et je multiplierai ta postérité, comme les étoiles du ciel et comme le sable qui est sur le bord de la mer; et ta postérité possédera la porte de ses ennemis."}, {"numero": 18, "texto": "Toutes les nations de la terre seront bénies en ta postérité, parce que tu as obéi à ma voix."}, {"numero": 19, "texto": "Abraham étant retourné vers ses serviteurs, ils se levèrent et s''''en allèrent ensemble à Beer-Schéba; car Abraham demeurait à Beer-Schéba."}, {"numero": 20, "texto": "Après ces choses, on fit à Abraham un rapport, en disant: Voici, Milca a aussi enfanté des fils à Nachor, ton frère:"}, {"numero": 21, "texto": "Uts, son premier-né, Buz, son frère, Kemuel, père d''''Aram,"}, {"numero": 22, "texto": "Késed, Hazo, Pildasch, Jidlaph et Bethuel."}, {"numero": 23, "texto": "Bethuel a engendré Rebecca. Ce sont là les huit fils que Milca a enfantés à Nachor, frère d''''Abraham."}, {"numero": 24, "texto": "Sa concubine, nommée Réuma, a aussi enfanté Thébach, Gaham, Tahasch et Maaca."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 22, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después de estas cosas, que tentó Dios á Abraham, y le dijo: Abraham. Y él respondió: Heme aquí."}, {"numero": 2, "texto": "Y dijo: Toma ahora tu hijo, tu único, Isaac, á quien amas, y vete á tierra de Moriah, y ofrécelo allí en holocausto sobre uno de los montes que yo te diré."}, {"numero": 3, "texto": "Y Abraham se levantó muy de mañana, y enalbardó su asno, y tomó consigo dos mozos suyos, y á Isaac su hijo: y cortó leña para el holocausto, y levantóse, y fué al lugar que Dios le dijo."}, {"numero": 4, "texto": "Al tercer día alzó Abraham sus ojos, y vió el lugar de lejos."}, {"numero": 5, "texto": "Entonces dijo Abraham á sus mozos: Esperaos aquí con el asno, y yo y el muchacho iremos hasta allí, y adoraremos, y volveremos á vosotros."}, {"numero": 6, "texto": "Y tomó Abraham la leña del holocausto, y púsola sobre Isaac su hijo: y él tomó en su mano el fuego y el cuchillo; y fueron ambos juntos."}, {"numero": 7, "texto": "Entonces habló Isaac á Abraham su padre, y dijo: Padre mío. Y él respondió: Heme aquí, mi hijo. Y él dijo: He aquí el fuego y la leña; mas ¿dónde está el cordero para el holocausto?"}, {"numero": 8, "texto": "Y respondió Abraham: Dios se proveerá de cordero para el holocausto, hijo mío. E iban juntos."}, {"numero": 9, "texto": "Y como llegaron al lugar que Dios le había dicho, edificó allí Abraham un altar, y compuso la leña, y ató á Isaac su hijo, y púsole en el altar sobre la leña."}, {"numero": 10, "texto": "Y extendió Abraham su mano, y tomó el cuchillo, para degollar á su hijo."}, {"numero": 11, "texto": "Entonces el ángel de Jehová le dió voces del cielo, y dijo: Abraham, Abraham. Y él respondió: Heme aquí."}, {"numero": 12, "texto": "Y dijo: No extiendas tu mano sobre el muchacho, ni le hagas nada; que ya conozco que temes á Dios, pues que no me rehusaste tu hijo, tu único."}, {"numero": 13, "texto": "Entonces alzó Abraham sus ojos, y miró, y he aquí un carnero á sus espaldas trabado en un zarzal por sus cuernos: y fué Abraham, y tomó el carnero, y ofrecióle en holocausto en lugar de su hijo."}, {"numero": 14, "texto": "Y llamó Abraham el nombre de aquel lugar, Jehová proveerá. Por tanto se dice hoy: En el monte de Jehová será provisto."}, {"numero": 15, "texto": "Y llamó el ángel de Jehová á Abraham segunda vez desde el cielo,"}, {"numero": 16, "texto": "Y dijo: Por mí mismo he jurado, dice Jehová, que por cuanto has hecho esto, y no me has rehusado tu hijo, tu único;"}, {"numero": 17, "texto": "Bendiciendo te bendeciré, y multiplicando multiplicaré tu simiente como las estrellas del cielo, y como la arena que está á la orilla del mar; y tu simiente poseerá las puertas de sus enemigos:"}, {"numero": 18, "texto": "En tu simiente serán benditas todas las gentes de la tierra, por cuanto obedeciste á mi voz."}, {"numero": 19, "texto": "Y tornóse Abraham á sus mozos, y levantáronse y se fueron juntos á Beer-seba; y habitó Abraham en Beer-seba."}, {"numero": 20, "texto": "Y aconteció después de estas cosas, que fué dada nueva á Abraham, diciendo: He aquí que también Milca ha parido hijos á Nachôr tu hermano:"}, {"numero": 21, "texto": "A Huz su primogénito, y á Buz su hermano, y á Kemuel padre de Aram,"}, {"numero": 22, "texto": "Y á Chêsed, y á Hazo, y á Pildas, y á Jidlaph, y á Bethuel."}, {"numero": 23, "texto": "Y Bethuel engendró á Rebeca. Estos ocho parió Milca á Nachôr, hermano de Abraham."}, {"numero": 24, "texto": "Y su concubina, que se llamaba Reúma, parió también á Teba, y á Gaham, y á Taas, y á Maachâ."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 23, 'pt', '[{"numero": 1, "texto": "E foi a vida de Sara cento e vinte e sete anos; estes foram os anos da vida de Sara."}, {"numero": 2, "texto": "E morreu Sara em Quiriate-Arba, que é Hebrom, na terra de Canaã; e Abraão veio para ficar de luto por Sara e para chorar por ela."}, {"numero": 3, "texto": "E levantou-se Abraão de diante de sua morta, e falou aos filhos de Hete, dizendo:"}, {"numero": 4, "texto": "Peregrino e estrangeiro sou entre vós; dá-me propriedade de sepultura convosco, e sepultarei minha falecida de diante de mim."}, {"numero": 5, "texto": "E responderam os filhos de Hete a Abraão, e disseram-lhe:"}, {"numero": 6, "texto": "Ouve-nos, senhor meu, és um príncipe de Deus entre nós; no melhor de nossas sepulturas sepulta a tua falecida; nenhum de nós te impedirá sua sepultura, para que enterres tua falecida."}, {"numero": 7, "texto": "E Abraão se levantou, e inclinou-se ao povo daquela terra, aos filhos de Hete;"}, {"numero": 8, "texto": "E falou com eles, dizendo: Se queres que eu sepulte minha falecida de diante de mim, ouvi-me, e intercedei por mim com Efrom, filho de Zoar,"}, {"numero": 9, "texto": "Para que me dê a caverna de Macpela, que tem na extremidade de sua propriedade: que por seu justo preço a dê a mim, para possessão de sepultura em meio de vós."}, {"numero": 10, "texto": "Este Efrom achava-se entre os filhos de Hete: e respondeu Efrom Heteu a Abraão, aos ouvidos dos filhos de Hete, de todos os que entravam pela porta de sua cidade, dizendo:"}, {"numero": 11, "texto": "Não, senhor meu, ouve-me: eu te dou a propriedade, e te dou também a caverna que está nela; diante dos filhos de meu povo a dou a ti; sepulta tua falecida."}, {"numero": 12, "texto": "E Abraão se inclinou diante do povo da terra."}, {"numero": 13, "texto": "E respondeu a Efrom aos ouvidos do povo da terra, dizendo: Antes, se for do teu agrado, rogo-te que me ouças; eu darei o preço da propriedade, toma-o de mim, e sepultarei nela minha falecida."}, {"numero": 14, "texto": "E respondeu Efrom a Abraão, dizendo-lhe:"}, {"numero": 15, "texto": "Senhor meu, escuta-me: a terra vale quatrocentos siclos de prata: que é isto entre mim e ti? Enterra, pois, tua falecida."}, {"numero": 16, "texto": "Então Abraão concordou com Efrom, e pesou Abraão a Efrom o dinheiro que disse, ouvindo-o os filhos de Hete, quatrocentos siclos de prata, de acordo com o padrão dos mercadores."}, {"numero": 17, "texto": "E ficou a propriedade de Efrom que estava em Macpela em frente de Manre, a propriedade e a caverna que estava nela, e todas as árvores que havia na herança, e em todo o seu termo ao derredor,"}, {"numero": 18, "texto": "Para Abraão em possessão, à vista dos filhos de Hete, e de todos os que entravam pela porta da cidade."}, {"numero": 19, "texto": "E depois disto sepultou Abraão a Sara, sua mulher, na caverna da propriedade de Macpela em frente de Manre, que é Hebrom na terra de Canaã."}, {"numero": 20, "texto": "E ficou a propriedade e a caverna que nela havia, para Abraão, em possessão de sepultura adquirida dos filhos de Hete."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 23, 'en', '[{"numero": 1, "texto": "And Sarah was an hundred and seven and twenty years old: these were the years of the life of Sarah."}, {"numero": 2, "texto": "And Sarah died in Kirjatharba; the same is Hebron in the land of Canaan: and Abraham came to mourn for Sarah, and to weep for her."}, {"numero": 3, "texto": "And Abraham stood up from before his dead, and spake unto the sons of Heth, saying,"}, {"numero": 4, "texto": "I am a stranger and a sojourner with you: give me a possession of a buryingplace with you, that I may bury my dead out of my sight."}, {"numero": 5, "texto": "And the children of Heth answered Abraham, saying unto him,"}, {"numero": 6, "texto": "Hear us, my lord: thou art a mighty prince among us: in the choice of our sepulchres bury thy dead; none of us shall withhold from thee his sepulchre, but that thou mayest bury thy dead."}, {"numero": 7, "texto": "And Abraham stood up, and bowed himself to the people of the land, even to the children of Heth."}, {"numero": 8, "texto": "And he communed with them, saying, If it be your mind that I should bury my dead out of my sight; hear me, and intreat for me to Ephron the son of Zohar,"}, {"numero": 9, "texto": "That he may give me the cave of Machpelah, which he hath, which is in the end of his field; for as much money as it is worth he shall give it me for a possession of a buryingplace amongst you."}, {"numero": 10, "texto": "And Ephron dwelt among the children of Heth: and Ephron the Hittite answered Abraham in the audience of the children of Heth, even of all that went in at the gate of his city, saying,"}, {"numero": 11, "texto": "Nay, my lord, hear me: the field give I thee, and the cave that is therein, I give it thee; in the presence of the sons of my people give I it thee: bury thy dead."}, {"numero": 12, "texto": "And Abraham bowed down himself before the people of the land."}, {"numero": 13, "texto": "And he spake unto Ephron in the audience of the people of the land, saying, But if thou wilt give it, I pray thee, hear me: I will give thee money for the field; take it of me, and I will bury my dead there."}, {"numero": 14, "texto": "And Ephron answered Abraham, saying unto him,"}, {"numero": 15, "texto": "My lord, hearken unto me: the land is worth four hundred shekels of silver; what is that betwixt me and thee? bury therefore thy dead."}, {"numero": 16, "texto": "And Abraham hearkened unto Ephron; and Abraham weighed to Ephron the silver, which he had named in the audience of the sons of Heth, four hundred shekels of silver, current money with the merchant."}, {"numero": 17, "texto": "And the field of Ephron which was in Machpelah, which was before Mamre, the field, and the cave which was therein, and all the trees that were in the field, that were in all the borders round about, were made sure"}, {"numero": 18, "texto": "Unto Abraham for a possession in the presence of the children of Heth, before all that went in at the gate of his city."}, {"numero": 19, "texto": "And after this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre: the same is Hebron in the land of Canaan."}, {"numero": 20, "texto": "And the field, and the cave that is therein, were made sure unto Abraham for a possession of a buryingplace by the sons of Heth."}]'::jsonb, 'King James Version'),
  ('Gn', 23, 'fr', '[{"numero": 1, "texto": "La vie de Sara fut de cent vingt-sept ans: telles sont les années de la vie de Sara."}, {"numero": 2, "texto": "Sara mourut à Kirjath-Arba, qui est Hébron, dans le pays de Canaan; et Abraham vint pour mener deuil sur Sara et pour la pleurer."}, {"numero": 3, "texto": "Abraham se leva de devant son mort, et parla ainsi aux fils de Heth:"}, {"numero": 4, "texto": "Je suis étranger et habitant parmi vous; donnez-moi la possession d''''un sépulcre chez vous, pour enterrer mon mort et l''''ôter de devant moi."}, {"numero": 5, "texto": "Les fils de Heth répondirent à Abraham, en lui disant:"}, {"numero": 6, "texto": "Ecoute-nous, mon seigneur! Tu es un prince de Dieu au milieu de nous; enterre ton mort dans celui de nos sépulcres que tu choisiras; aucun de nous ne te refusera son sépulcre pour enterrer ton mort."}, {"numero": 7, "texto": "Abraham se leva, et se prosterna devant le peuple du pays, devant les fils de Heth."}, {"numero": 8, "texto": "Et il leur parla ainsi: Si vous permettez que j''''enterre mon mort et que je l''''ôte de devant mes yeux, écoutez-moi, et priez pour moi Ephron, fils de Tsochar,"}, {"numero": 9, "texto": "de me céder la caverne de Macpéla, qui lui appartient, à l''''extrémité de son champ, de me la céder contre sa valeur en argent, afin qu''''elle me serve de possession sépulcrale au milieu de vous."}, {"numero": 10, "texto": "Ephron était assis parmi les fils de Heth. Et Ephron, le Héthien, répondit à Abraham, en présence des fils de Heth et de tous ceux qui entraient par la porte de sa ville:"}, {"numero": 11, "texto": "Non, mon seigneur, écoute-moi! Je te donne le champ, et je te donne la caverne qui y est. Je te les donne, aux yeux des fils de mon peuple: enterre ton mort."}, {"numero": 12, "texto": "Abraham se prosterna devant le peuple du pays."}, {"numero": 13, "texto": "Et il parla ainsi à Ephron, en présence du peuple du pays: Ecoute-moi, je te prie! Je donne le prix du champ: accepte-le de moi; et j''''y enterrerai mon mort."}, {"numero": 14, "texto": "Et Ephron répondit à Abraham, en lui disant:"}, {"numero": 15, "texto": "Mon seigneur, écoute-moi! Une terre de quatre cents sicles d''''argent, qu''''est-ce que cela entre moi et toi? Enterre ton mort."}, {"numero": 16, "texto": "Abraham comprit Ephron; et Abraham pesa à Ephron l''''argent qu''''il avait dit, en présence des fils de Heth, quatre cents sicles d''''argent ayant cours chez le marchand."}, {"numero": 17, "texto": "Le champ d''''Ephron à Macpéla, vis-à-vis de Mamré, le champ et la caverne qui y est, et tous les arbres qui sont dans le champ et dans toutes ses limites alentour,"}, {"numero": 18, "texto": "devinrent ainsi la propriété d''''Abraham, aux yeux des fils de Heth et de tous ceux qui entraient par la porte de sa ville."}, {"numero": 19, "texto": "Après cela, Abraham enterra Sara, sa femme, dans la caverne du champ de Macpéla, vis-à-vis de Mamré, qui est Hébron, dans le pays de Canaan."}, {"numero": 20, "texto": "Le champ et la caverne qui y est demeurèrent à Abraham comme possession sépulcrale, acquise des fils de Heth."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 23, 'es', '[{"numero": 1, "texto": "Y FUÉ la vida de Sara ciento veintisiete años: tantos fueron los años de la vida de Sara."}, {"numero": 2, "texto": "Y murió Sara en Kiriath-arba, que es Hebrón, en la tierra de Canaán: y vino Abraham á hacer el duelo á Sara, y á llorarla."}, {"numero": 3, "texto": "Y levantóse Abraham de delante de su muerto, y habló á los hijos de Heth, diciendo:"}, {"numero": 4, "texto": "Peregrino y advenedizo soy entre vosotros; dadme heredad de sepultura con vosotros, y sepultaré mi muerto de delante de mí."}, {"numero": 5, "texto": "Y respondieron los hijos de Heth á Abraham, y dijéronle:"}, {"numero": 6, "texto": "Oyenos, señor mío, eres un príncipe de Dios entre nosotros; en lo mejor de nuestras sepulturas sepulta á tu muerto; ninguno de nosotros te impedirá su sepultura, para que entierres tu muerto."}, {"numero": 7, "texto": "Y Abraham se levantó, é inclinóse al pueblo de aquella tierra, á los hijos de Heth;"}, {"numero": 8, "texto": "Y habló con ellos, diciendo: Si tenéis voluntad que yo sepulte mi muerto de delante de mí, oidme, é interceded por mí con Ephrón, hijo de Zohar,"}, {"numero": 9, "texto": "Para que me dé la cueva de Macpela, que tiene al cabo de su heredad: que por su justo precio me la dé, para posesión de sepultura en medio de vosotros."}, {"numero": 10, "texto": "Este Ephrón hallábase entre los hijos de Heth: y respondió Ephrón Hetheo á Abraham, en oídos de los hijos de Heth, de todos los que entraban por la puerta de su ciudad, diciendo:"}, {"numero": 11, "texto": "No, señor mío, óyeme: te doy la heredad, y te doy también la cueva que está en ella; delante de los hijos de mi pueblo te la doy; sepulta tu muerto."}, {"numero": 12, "texto": "Y Abraham se inclinó delante del pueblo de la tierra."}, {"numero": 13, "texto": "Y respondió á Ephrón en oídos del pueblo de la tierra, diciendo: Antes, si te place, ruégote que me oigas; yo daré el precio de la heredad, tómalo de mí, y sepultaré en ella mi muerto."}, {"numero": 14, "texto": "Y respondió Ephrón á Abraham, diciéndole:"}, {"numero": 15, "texto": "Señor mío, escúchame: la tierra vale cuatrocientos siclos de plata: ¿qué es esto entre mí y ti? entierra pues tu muerto."}, {"numero": 16, "texto": "Entonces Abraham se convino con Ephrón, y pesó Abraham á Ephrón el dinero que dijo, oyéndolo los hijos de Heth, cuatrocientos siclos de plata, de buena ley entre mercaderes."}, {"numero": 17, "texto": "Y quedó la heredad de Ephrón que estaba en Macpela enfrente de Mamre, la heredad y la cueva que estaba en ella, y todos los árboles que había en la heredad, y en todo su término al derredor,"}, {"numero": 18, "texto": "Por de Abraham en posesión, á vista de los hijos de Heth, y de todos los que entraban por la puerta de la ciudad."}, {"numero": 19, "texto": "Y después de esto sepultó Abraham á Sara su mujer en la cueva de la heredad de Macpela enfrente de Mamre, que es Hebrón en la tierra de Canaán."}, {"numero": 20, "texto": "Y quedó la heredad y la cueva que en ella había, por de Abraham, en posesión de sepultura adquirida de los hijos de Heth."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 24, 'pt', '[{"numero": 1, "texto": "E Abraão era velho, e cheio de dias; e o SENHOR havia abençoado a Abraão em tudo."}, {"numero": 2, "texto": "E disse Abraão a um criado seu, o mais velho de sua casa, que era o que governava em tudo o que tinha: Põe agora tua mão debaixo de minha coxa,"}, {"numero": 3, "texto": "E te juramentarei pelo SENHOR, Deus dos céus e Deus da terra, que não tomarás mulher para meu filho das filhas dos cananeus, entre os quais eu habito;"}, {"numero": 4, "texto": "Em vez disso irás à minha terra e à minha parentela, e tomarás mulher para meu filho Isaque."}, {"numero": 5, "texto": "E o criado lhe respondeu: Talvez a mulher não queira vir atrás de mim a esta terra; farei voltar, pois, teu filho à terra de onde saíste?"}, {"numero": 6, "texto": "E Abraão lhe disse: Guarda-te que não faças voltar a meu filho ali."}, {"numero": 7, "texto": "O SENHOR, Deus dos céus, que me tomou da casa de meu pai e da terra de minha parentela, e me falou e me jurou, dizendo: À tua descendência darei esta terra; ele enviará seu anjo diante de ti, e tu tomarás dali mulher para meu filho."}, {"numero": 8, "texto": "E se a mulher não quiser vir atrás de ti, serás livre deste meu juramento; somente que não faças voltar ali a meu filho."}, {"numero": 9, "texto": "Então o criado pôs sua mão debaixo da coxa de Abraão seu senhor, e jurou-lhe sobre este negócio."}, {"numero": 10, "texto": "E o criado tomou dez camelos dos camelos de seu senhor, e foi-se, pois tinha à sua disposição todos os bens de seu senhor: e posto em caminho, chegou à Mesopotâmia, à cidade de Naor."}, {"numero": 11, "texto": "E fez ajoelhar os camelos fora da cidade, junto a um poço de água, à hora da tarde, à hora em que saem as moças por água."}, {"numero": 12, "texto": "E disse: SENHOR, Deus de meu senhor Abraão, dá-me, te rogo, o ter hoje bom encontro, e faze misericórdia com meu senhor Abraão."}, {"numero": 13, "texto": "Eis que eu estou junto à fonte de água, e as filhas dos homens desta cidade saem por água:"}, {"numero": 14, "texto": "Seja, pois, que a moça a quem eu disser: Baixa teu cântaro, te rogo, para que eu beba; e ela responder: Bebe, e também darei de beber a teus camelos: que seja esta a que tu destinaste para teu servo Isaque; e nisto conhecerei que haverás feito misericórdia com meu senhor."}, {"numero": 15, "texto": "E aconteceu que antes que ele acabasse de falar, eis que Rebeca, que havia nascido a Betuel, filho de Milca, mulher de Naor irmão de Abraão, a qual saía com seu cântaro sobre seu ombro."}, {"numero": 16, "texto": "E a moça era de muito belo aspecto, virgem, à que homem não havia conhecido; a qual desceu à fonte, e encheu seu cântaro, e se voltava."}, {"numero": 17, "texto": "Então o criado correu até ela, e disse: Rogo-te que me dês a beber um pouco de água de teu cântaro."}, {"numero": 18, "texto": "E ela respondeu: Bebe, meu senhor; e apressou-se a baixar seu cântaro sobre sua mão, e lhe deu a beber."}, {"numero": 19, "texto": "E quando acabou de dar-lhe de beber, disse: Também para teus camelos tirarei água, até que acabem de beber."}, {"numero": 20, "texto": "E apressou-se, e esvaziou seu cântaro no bebedouro, e correu outra vez ao poço para tirar água, e tirou para todos os seus camelos."}, {"numero": 21, "texto": "E o homem estava maravilhado dela, permanecendo calado, para saber se o SENHOR havia prosperado ou não sua viagem."}, {"numero": 22, "texto": "E foi que quando os camelos acabaram de beber, presenteou-lhe o homem um pendente de ouro que pesava meio siclo, e dois braceletes que pesavam dez;"}, {"numero": 23, "texto": "E disse: De quem és filha? Rogo-te me digas, há lugar em casa de teu pai onde possamos passar a noite?"}, {"numero": 24, "texto": "E ela respondeu: Sou filha de Betuel, filho de Milca, o qual deu à luz ela a Naor."}, {"numero": 25, "texto": "E acrescentou: Também há em nossa casa palha e muita forragem, e lugar para passar a noite."}, {"numero": 26, "texto": "O homem então se inclinou, e adorou ao SENHOR."}, {"numero": 27, "texto": "E disse: Bendito seja o SENHOR, Deus de meu senhor Abraão, que não afastou sua misericórdia e sua verdade de meu senhor, guiando-me o SENHOR no caminho à casa dos irmãos de meu senhor."}, {"numero": 28, "texto": "E a moça correu, e fez saber na casa de sua mãe estas coisas."}, {"numero": 29, "texto": "E Rebeca tinha um irmão que se chamava Labão, o qual correu fora ao homem, à fonte;"}, {"numero": 30, "texto": "E foi que quando viu o pendente e os braceletes nas mãos de sua irmã, que dizia, Assim me falou aquele homem; veio a ele: e eis que estava junto aos camelos à fonte."}, {"numero": 31, "texto": "E disse-lhe: Vem, bendito do SENHOR; por que estás fora? eu limpei a casa, e o lugar para os camelos."}, {"numero": 32, "texto": "Então o homem veio à casa, e Labão desatou os camelos; e deu-lhes palha e forragem, e água para lavar os pés dele, e os pés dos homens que com ele vinham."}, {"numero": 33, "texto": "E puseram diante dele comida; mas ele disse: Não comerei até que tenha dito minha mensagem. E ele lhe disse: Fala."}, {"numero": 34, "texto": "Então disse: Eu sou criado de Abraão;"}, {"numero": 35, "texto": "E o SENHOR abençoou muito a meu senhor, e ele se engrandeceu: e lhe deu ovelhas e vacas, prata e ouro, servos e servas, camelos e asnos."}, {"numero": 36, "texto": "E Sara, mulher de meu senhor, deu à luz em sua velhice um filho a meu senhor, quem lhe deu tudo quanto tem."}, {"numero": 37, "texto": "E meu senhor me fez jurar, dizendo: Não tomarás mulher para meu filho das filhas dos cananeus, em cuja terra habito;"}, {"numero": 38, "texto": "Em vez disso irás à casa de meu pai, e à minha parentela, e tomarás mulher para meu filho."}, {"numero": 39, "texto": "E eu disse: Talvez a mulher não queira me seguir."}, {"numero": 40, "texto": "Então ele me respondeu: O SENHOR, em cuja presença tenho andado, enviará seu anjo contigo, e fará teu caminho ser bem-sucedido; e tomarás mulher para meu filho de minha linhagem e da casa de meu pai;"}, {"numero": 41, "texto": "Então serás livre de meu juramento, quando houveres chegado à minha linhagem; e se não a derem a ti, serás livre de meu juramento."}, {"numero": 42, "texto": "Cheguei, pois, hoje à fonte, e disse: SENHOR, Deus de meu senhor Abraão, se tu fazes bem-sucedido agora meu caminho pelo qual ando;"}, {"numero": 43, "texto": "Eis que eu estou junto à fonte de água; seja, pois, que a virgem que sair por água, à qual disser: Dá-me de beber, te rogo, um pouco de água de teu cântaro;"}, {"numero": 44, "texto": "E ela me responder, Bebe tu, e também para teus camelos tirarei água: esta seja a mulher que destinou o SENHOR para o filho de meu senhor."}, {"numero": 45, "texto": "E antes que acabasse de falar em meu coração, eis que Rebeca saía com seu cântaro sobre seu ombro; e desceu à fonte, e tirou água; e lhe disse: Rogo-te que me dês de beber."}, {"numero": 46, "texto": "E prontamente baixou seu cântaro de cima de si, e disse: Bebe, e também a teus camelos darei a beber. E bebi, e deu também de beber a meus camelos."}, {"numero": 47, "texto": "Então lhe perguntei, e disse: De quem és filha? E ela respondeu: Filha de Betuel, filho de Naor, que Milca lhe deu. Então pus nela um pendente sobre seu nariz, e braceletes sobre suas mãos;"}, {"numero": 48, "texto": "E inclinei-me, e adorei ao SENHOR, e bendisse ao SENHOR, Deus de meu senhor Abraão, que me havia guiado pelo caminho de verdade para tomar a filha do irmão de meu senhor para seu filho."}, {"numero": 49, "texto": "Agora, pois, se vós fazeis misericórdia e verdade com meu senhor, declarai-o a mim; e se não, declarai-o a mim; e irei embora à direita ou à esquerda."}, {"numero": 50, "texto": "Então Labão e Betuel responderam e disseram: Do SENHOR saiu isto; não podemos falar-te mal nem bem."}, {"numero": 51, "texto": "Eis aí Rebeca diante de ti; toma-a e vai-te, e seja mulher do filho de teu senhor, como o disse o SENHOR."}, {"numero": 52, "texto": "E foi, que quando o criado de Abraão ouviu suas palavras, inclinou-se à terra ao SENHOR."}, {"numero": 53, "texto": "E o criado tirou objetos de prata, objetos de ouro e roupas, e deu a Rebeca: também deu coisas preciosas a seu irmão e a sua mãe."}, {"numero": 54, "texto": "E comeram e beberam ele e os homens que vinham com ele, e dormiram; e levantando-se de manhã, disse: Autorizai-me voltar a meu senhor."}, {"numero": 55, "texto": "Então respondeu seu irmão e sua mãe: Espere a moça conosco ao menos dez dias, e depois irá."}, {"numero": 56, "texto": "E ele lhes disse: Não me detenhais, pois que o SENHOR fez prosperar meu caminho; despede-me para que me vá a meu senhor."}, {"numero": 57, "texto": "Eles responderam então: Chamemos a moça e perguntemos a ela."}, {"numero": 58, "texto": "E chamaram a Rebeca, e disseram-lhe: Irás tu com este homem? E ela respondeu: Sim, irei."}, {"numero": 59, "texto": "Então deixaram ir a Rebeca sua irmã, e à sua criada, e ao criado de Abraão e a seus homens."}, {"numero": 60, "texto": "E abençoaram a Rebeca, e disseram-lhe: És nossa irmã; sejas em milhares de milhares, e tua geração possua a porta de seus inimigos."}, {"numero": 61, "texto": "Levantou-se então Rebeca e suas moças, e subiram sobre os camelos, e seguiram ao homem; e o criado tomou a Rebeca, e foi embora."}, {"numero": 62, "texto": "E vinha Isaque do poço do Vivente que me vê; porque ele habitava na terra do Sul;"}, {"numero": 63, "texto": "E havia saído Isaque a orar ao campo, à hora da tarde; e levantando seus olhos, olhou, e eis os camelos que vinham."}, {"numero": 64, "texto": "Rebeca também levantou seus olhos, e viu a Isaque, e desceu do camelo;"}, {"numero": 65, "texto": "Porque havia perguntado ao criado: Quem é este homem que vem pelo campo até nós? E o servo havia respondido: Este é meu senhor. Ela então tomou o véu, e cobriu-se."}, {"numero": 66, "texto": "Então o criado contou a Isaque tudo o que havia feito."}, {"numero": 67, "texto": "E trouxe-a Isaque à tenda de sua mãe Sara, e tomou a Rebeca por mulher; e amou-a: e consolou-se Isaque depois da morte de sua mãe."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 24, 'en', '[{"numero": 1, "texto": "And Abraham was old, and well stricken in age: and the Lord had blessed Abraham in all things."}, {"numero": 2, "texto": "And Abraham said unto his eldest servant of his house, that ruled over all that he had, Put, I pray thee, thy hand under my thigh:"}, {"numero": 3, "texto": "And I will make thee swear by the Lord, the God of heaven, and the God of the earth, that thou shalt not take a wife unto my son of the daughters of the Canaanites, among whom I dwell:"}, {"numero": 4, "texto": "But thou shalt go unto my country, and to my kindred, and take a wife unto my son Isaac."}, {"numero": 5, "texto": "And the servant said unto him, Peradventure the woman will not be willing to follow me unto this land: must I needs bring thy son again unto the land from whence thou camest?"}, {"numero": 6, "texto": "And Abraham said unto him, Beware thou that thou bring not my son thither again."}, {"numero": 7, "texto": "The Lord God of heaven, which took me from my father''s house, and from the land of my kindred, and which spake unto me, and that sware unto me, saying, Unto thy seed will I give this land; he shall send his angel before thee, and thou shalt take a wife unto my son from thence."}, {"numero": 8, "texto": "And if the woman will not be willing to follow thee, then thou shalt be clear from this my oath: only bring not my son thither again."}, {"numero": 9, "texto": "And the servant put his hand under the thigh of Abraham his master, and sware to him concerning that matter."}, {"numero": 10, "texto": "And the servant took ten camels of the camels of his master, and departed; for all the goods of his master were in his hand: and he arose, and went to Mesopotamia, unto the city of Nahor."}, {"numero": 11, "texto": "And he made his camels to kneel down without the city by a well of water at the time of the evening, even the time that women go out to draw water."}, {"numero": 12, "texto": "And he said O Lord God of my master Abraham, I pray thee, send me good speed this day, and shew kindness unto my master Abraham."}, {"numero": 13, "texto": "Behold, I stand here by the well of water; and the daughters of the men of the city come out to draw water:"}, {"numero": 14, "texto": "And let it come to pass, that the damsel to whom I shall say, Let down thy pitcher, I pray thee, that I may drink; and she shall say, Drink, and I will give thy camels drink also: let the same be she that thou hast appointed for thy servant Isaac; and thereby shall I know that thou hast shewed kindness unto my master."}, {"numero": 15, "texto": "And it came to pass, before he had done speaking, that, behold, Rebekah came out, who was born to Bethuel, son of Milcah, the wife of Nahor, Abraham''s brother, with her pitcher upon her shoulder."}, {"numero": 16, "texto": "And the damsel was very fair to look upon, a virgin, neither had any man known her: and she went down to the well, and filled her pitcher, and came up."}, {"numero": 17, "texto": "And the servant ran to meet her, and said, Let me, I pray thee, drink a little water of thy pitcher."}, {"numero": 18, "texto": "And she said, Drink, my lord: and she hasted, and let down her pitcher upon her hand, and gave him drink."}, {"numero": 19, "texto": "And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking."}, {"numero": 20, "texto": "And she hasted, and emptied her pitcher into the trough, and ran again unto the well to draw water, and drew for all his camels."}, {"numero": 21, "texto": "And the man wondering at her held his peace, to wit whether the Lord had made his journey prosperous or not."}, {"numero": 22, "texto": "And it came to pass, as the camels had done drinking, that the man took a golden earring of half a shekel weight, and two bracelets for her hands of ten shekels weight of gold;"}, {"numero": 23, "texto": "And said, Whose daughter art thou? tell me, I pray thee: is there room in thy father''s house for us to lodge in?"}, {"numero": 24, "texto": "And she said unto him, I am the daughter of Bethuel the son of Milcah, which she bare unto Nahor."}, {"numero": 25, "texto": "She said moreover unto him, We have both straw and provender enough, and room to lodge in."}, {"numero": 26, "texto": "And the man bowed down his head, and worshipped the Lord."}, {"numero": 27, "texto": "And he said, Blessed be the Lord God of my master Abraham, who hath not left destitute my master of his mercy and his truth: I being in the way, the Lord led me to the house of my master''s brethren."}, {"numero": 28, "texto": "And the damsel ran, and told them of her mother''s house these things."}, {"numero": 29, "texto": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}, {"numero": 30, "texto": "And it came to pass, when he saw the earring and bracelets upon his sister''s hands, and when he heard the words of Rebekah his sister, saying, Thus spake the man unto me; that he came unto the man; and, behold, he stood by the camels at the well."}, {"numero": 31, "texto": "And he said, Come in, thou blessed of the Lord; wherefore standest thou without? for I have prepared the house, and room for the camels."}, {"numero": 32, "texto": "And the man came into the house: and he ungirded his camels, and gave straw and provender for the camels, and water to wash his feet, and the men''s feet that were with him."}, {"numero": 33, "texto": "And there was set meat before him to eat: but he said, I will not eat, until I have told mine errand. And he said, Speak on."}, {"numero": 34, "texto": "And he said, I am Abraham''s servant."}, {"numero": 35, "texto": "And the Lord hath blessed my master greatly; and he is become great: and he hath given him flocks, and herds, and silver, and gold, and menservants, and maidservants, and camels, and asses."}, {"numero": 36, "texto": "And Sarah my master''s wife bare a son to my master when she was old: and unto him hath he given all that he hath."}, {"numero": 37, "texto": "And my master made me swear, saying, Thou shalt not take a wife to my son of the daughters of the Canaanites, in whose land I dwell:"}, {"numero": 38, "texto": "But thou shalt go unto my father''s house, and to my kindred, and take a wife unto my son."}, {"numero": 39, "texto": "And I said unto my master, Peradventure the woman will not follow me."}, {"numero": 40, "texto": "And he said unto me, The Lord, before whom I walk, will send his angel with thee, and prosper thy way; and thou shalt take a wife for my son of my kindred, and of my father''s house:"}, {"numero": 41, "texto": "Then shalt thou be clear from this my oath, when thou comest to my kindred; and if they give not thee one, thou shalt be clear from my oath."}, {"numero": 42, "texto": "And I came this day unto the well, and said, O Lord God of my master Abraham, if now thou do prosper my way which I go:"}, {"numero": 43, "texto": "Behold, I stand by the well of water; and it shall come to pass, that when the virgin cometh forth to draw water, and I say to her, Give me, I pray thee, a little water of thy pitcher to drink;"}, {"numero": 44, "texto": "And she say to me, Both drink thou, and I will also draw for thy camels: let the same be the woman whom the Lord hath appointed out for my master''s son."}, {"numero": 45, "texto": "And before I had done speaking in mine heart, behold, Rebekah came forth with her pitcher on her shoulder; and she went down unto the well, and drew water: and I said unto her, Let me drink, I pray thee."}, {"numero": 46, "texto": "And she made haste, and let down her pitcher from her shoulder, and said, Drink, and I will give thy camels drink also: so I drank, and she made the camels drink also."}, {"numero": 47, "texto": "And I asked her, and said, Whose daughter art thou? And she said, the daughter of Bethuel, Nahor''s son, whom Milcah bare unto him: and I put the earring upon her face, and the bracelets upon her hands."}, {"numero": 48, "texto": "And I bowed down my head, and worshipped the Lord, and blessed the Lord God of my master Abraham, which had led me in the right way to take my master''s brother''s daughter unto his son."}, {"numero": 49, "texto": "And now if ye will deal kindly and truly with my master, tell me: and if not, tell me; that I may turn to the right hand, or to the left."}, {"numero": 50, "texto": "Then Laban and Bethuel answered and said, The thing proceedeth from the Lord: we cannot speak unto thee bad or good."}, {"numero": 51, "texto": "Behold, Rebekah is before thee, take her, and go, and let her be thy master''s son''s wife, as the Lord hath spoken."}, {"numero": 52, "texto": "And it came to pass, that, when Abraham''s servant heard their words, he worshipped the Lord, bowing himself to the earth."}, {"numero": 53, "texto": "And the servant brought forth jewels of silver, and jewels of gold, and raiment, and gave them to Rebekah: he gave also to her brother and to her mother precious things."}, {"numero": 54, "texto": "And they did eat and drink, he and the men that were with him, and tarried all night; and they rose up in the morning, and he said, Send me away unto my master."}, {"numero": 55, "texto": "And her brother and her mother said, Let the damsel abide with us a few days, at the least ten; after that she shall go."}, {"numero": 56, "texto": "And he said unto them, Hinder me not, seeing the Lord hath prospered my way; send me away that I may go to my master."}, {"numero": 57, "texto": "And they said, We will call the damsel, and enquire at her mouth."}, {"numero": 58, "texto": "And they called Rebekah, and said unto her, Wilt thou go with this man? And she said, I will go."}, {"numero": 59, "texto": "And they sent away Rebekah their sister, and her nurse, and Abraham''s servant, and his men."}, {"numero": 60, "texto": "And they blessed Rebekah, and said unto her, Thou art our sister, be thou the mother of thousands of millions, and let thy seed possess the gate of those which hate them."}, {"numero": 61, "texto": "And Rebekah arose, and her damsels, and they rode upon the camels, and followed the man: and the servant took Rebekah, and went his way."}, {"numero": 62, "texto": "And Isaac came from the way of the well Lahairoi; for he dwelt in the south country."}, {"numero": 63, "texto": "And Isaac went out to meditate in the field at the eventide: and he lifted up his eyes, and saw, and, behold, the camels were coming."}, {"numero": 64, "texto": "And Rebekah lifted up her eyes, and when she saw Isaac, she lighted off the camel."}, {"numero": 65, "texto": "For she had said unto the servant, What man is this that walketh in the field to meet us? And the servant had said, It is my master: therefore she took a vail, and covered herself."}, {"numero": 66, "texto": "And the servant told Isaac all things that he had done."}, {"numero": 67, "texto": "And Isaac brought her into his mother Sarah''s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother''s death."}]'::jsonb, 'King James Version'),
  ('Gn', 24, 'fr', '[{"numero": 1, "texto": "Abraham était vieux, avancé en âge; et l''''Eternel avait béni Abraham en toute chose."}, {"numero": 2, "texto": "Abraham dit à son serviteur, le plus ancien de sa maison, l''''intendant de tous ses biens: Mets, je te prie, ta main sous ma cuisse;"}, {"numero": 3, "texto": "et je te ferai jurer par l''''Eternel, le Dieu du ciel et le Dieu de la terre, de ne pas prendre pour mon fils une femme parmi les filles des Cananéens au milieu desquels j''''habite,"}, {"numero": 4, "texto": "mais d''''aller dans mon pays et dans ma patrie prendre une femme pour mon fils Isaac."}, {"numero": 5, "texto": "Le serviteur lui répondit: Peut-être la femme ne voudra-t-elle pas me suivre dans ce pays-ci; devrai-je mener ton fils dans le pays d''''où tu es sorti?"}, {"numero": 6, "texto": "Abraham lui dit: Garde-toi d''''y mener mon fils!"}, {"numero": 7, "texto": "L''''Eternel, le Dieu du ciel, qui m''''a fait sortir de la maison de mon père et de ma patrie, qui m''''a parlé et qui m''''a juré, en disant: Je donnerai ce pays à ta postérité, lui-même enverra son ange devant toi; et c''''est de là que tu prendras une femme pour mon fils."}, {"numero": 8, "texto": "Si la femme ne veut pas te suivre, tu seras dégagé de ce serment que je te fais faire. Seulement, tu n''''y mèneras pas mon fils."}, {"numero": 9, "texto": "Le serviteur mit sa main sous la cuisse d''''Abraham, son seigneur, et lui jura d''''observer ces choses."}, {"numero": 10, "texto": "Le serviteur prit dix chameaux parmi les chameaux de son seigneur, et il partit, ayant à sa disposition tous les biens de son seigneur. Il se leva, et alla en Mésopotamie, à la ville de Nachor."}, {"numero": 11, "texto": "Il fit reposer les chameaux sur leurs genoux hors de la ville, près d''''un puits, au temps du soir, au temps où sortent celles qui vont puiser de l''''eau."}, {"numero": 12, "texto": "Et il dit: Eternel, Dieu de mon seigneur Abraham, fais-moi, je te prie, rencontrer aujourd''''hui ce que je désire, et use de bonté envers mon seigneur Abraham!"}, {"numero": 13, "texto": "Voici, je me tiens près de la source d''''eau, et les filles des gens de la ville vont sortir pour puiser de l''''eau."}, {"numero": 14, "texto": "Que la jeune fille à laquelle je dirai: Penche ta cruche, je te prie, pour que je boive, et qui répondra: Bois, et je donnerai aussi à boire à tes chameaux, soit celle que tu as destinée à ton serviteur Isaac! Et par là je connaîtrai que tu uses de bonté envers mon seigneur."}, {"numero": 15, "texto": "Il n''''avait pas encore fini de parler que sortit, sa cruche sur l''''épaule, Rebecca, née de Bethuel, fils de Milca, femme de Nachor, frère d''''Abraham."}, {"numero": 16, "texto": "C''''était une jeune fille très belle de figure; elle était vierge, et aucun homme ne l''''avait connue. Elle descendit à la source, remplit sa cruche, et remonta."}, {"numero": 17, "texto": "Le serviteur courut au-devant d''''elle, et dit: Laisse-moi boire, je te prie, un peu d''''eau de ta cruche."}, {"numero": 18, "texto": "Elle répondit: Bois, mon seigneur. Et elle s''''empressa d''''abaisser sa cruche sur sa main, et de lui donner à boire."}, {"numero": 19, "texto": "Quand elle eut achevé de lui donner à boire, elle dit: Je puiserai aussi pour tes chameaux, jusqu''''à ce qu''''ils aient assez bu."}, {"numero": 20, "texto": "Et elle s''''empressa de vider sa cruche dans l''''abreuvoir, et courut encore au puits pour puiser; et elle puisa pour tous les chameaux."}, {"numero": 21, "texto": "L''''homme la regardait avec étonnement et sans rien dire, pour voir si l''''Eternel faisait réussir son voyage, ou non."}, {"numero": 22, "texto": "Quand les chameaux eurent fini de boire, l''''homme prit un anneau d''''or, du poids d''''un demi-sicle, et deux bracelets, du poids de dix sicles d''''or."}, {"numero": 23, "texto": "Et il dit: De qui es-tu fille? dis-le moi, je te prie. Y a-t-il dans la maison de ton père de la place pour passer la nuit?"}, {"numero": 24, "texto": "Elle répondit: Je suis fille de Bethuel, fils de Milca et de Nachor."}, {"numero": 25, "texto": "Elle lui dit encore: Il y a chez nous de la paille et du fourrage en abondance, et aussi de la place pour passer la nuit."}, {"numero": 26, "texto": "Alors l''''homme s''''inclina et se prosterna devant l''''Eternel,"}, {"numero": 27, "texto": "en disant: Béni soit l''''Eternel, le Dieu de mon seigneur Abraham, qui n''''a pas renoncé à sa miséricorde et à sa fidélité envers mon seigneur! Moi-même, l''''Eternel m''''a conduit à la maison des frères de mon seigneur."}, {"numero": 28, "texto": "La jeune fille courut raconter ces choses à la maison de sa mère."}, {"numero": 29, "texto": "Rebecca avait un frère, nommé Laban. Et Laban courut dehors vers l''''homme, près de la source."}, {"numero": 30, "texto": "Il avait vu l''''anneau et les bracelets aux mains de sa soeur, et il avait entendu les paroles de Rebecca, sa soeur, disant: Ainsi m''''a parlé l''''homme. Il vint donc à cet homme qui se tenait auprès des chameaux, vers la source,"}, {"numero": 31, "texto": "et il dit: Viens, béni de l''''Eternel! Pourquoi resterais-tu dehors? J''''ai préparé la maison, et une place pour les chameaux."}, {"numero": 32, "texto": "L''''homme arriva à la maison. Laban fit décharger les chameaux, et il donna de la paille et du fourrage aux chameaux, et de l''''eau pour laver les pieds de l''''homme et les pieds des gens qui étaient avec lui."}, {"numero": 33, "texto": "Puis, il lui servit à manger. Mais il dit: Je ne mangerai point, avant d''''avoir dit ce que j''''ai à dire. Parle! dit Laban."}, {"numero": 34, "texto": "Alors il dit: Je suis serviteur d''''Abraham."}, {"numero": 35, "texto": "L''''Eternel a comblé de bénédictions mon seigneur, qui est devenu puissant. Il lui a donné des brebis et des boeufs, de l''''argent et de l''''or, des serviteurs et des servantes, des chameaux et des ânes."}, {"numero": 36, "texto": "Sara, la femme de mon seigneur, a enfanté dans sa vieillesse un fils à mon seigneur; et il lui a donné tout ce qu''''il possède."}, {"numero": 37, "texto": "Mon seigneur m''''a fait jurer, en disant: Tu ne prendras pas pour mon fils une femme parmi les filles des Cananéens, dans le pays desquels j''''habite;"}, {"numero": 38, "texto": "mais tu iras dans la maison de mon père et de ma famille prendre une femme pour mon fils."}, {"numero": 39, "texto": "J''''ai dit à mon seigneur: Peut-être la femme ne voudra-t-elle pas me suivre."}, {"numero": 40, "texto": "Et il m''''a répondu: L''''Eternel, devant qui j''''ai marché, enverra son ange avec toi, et fera réussir ton voyage; et tu prendras pour mon fils une femme de la famille et de la maison de mon père."}, {"numero": 41, "texto": "Tu seras dégagé du serment que tu me fais, quand tu auras été vers ma famille; si on ne te l''''accorde pas, tu seras dégagé du serment que tu me fais."}, {"numero": 42, "texto": "Je suis arrivé aujourd''''hui à la source, et j''''ai dit: Eternel, Dieu de mon seigneur Abraham, si tu daignes faire réussir le voyage que j''''accomplis,"}, {"numero": 43, "texto": "voici, je me tiens près de la source d''''eau, et que la jeune fille qui sortira pour puiser, à qui je dirai: Laisse-moi boire, je te prie, un peu d''''eau de ta cruche,"}, {"numero": 44, "texto": "et qui me répondra: Bois toi-même, et je puiserai aussi pour tes chameaux, que cette jeune fille soit la femme que l''''Eternel a destinée au fils de mon seigneur!"}, {"numero": 45, "texto": "Avant que j''''eusse fini de parler en mon coeur, voici, Rebecca est sortie, sa cruche sur l''''épaule; elle est descendue à la source, et a puisé. Je lui ai dit: Donne-moi à boire, je te prie."}, {"numero": 46, "texto": "Elle s''''est empressée d''''abaisser sa cruche de dessus son épaule, et elle a dit: Bois, et je donnerai aussi à boire à tes chameaux. J''''ai bu, et elle a aussi donné à boire à mes chameaux."}, {"numero": 47, "texto": "Je l''''ai interrogée, et j''''ai dit: De qui es-tu fille? Elle a répondu: Je suis fille de Bethuel, fils de Nachor et de Milca. J''''ai mis l''''anneau à son nez, et les bracelets à ses mains."}, {"numero": 48, "texto": "Puis je me suis incliné et prosterné devant l''''Eternel, et j''''ai béni l''''Eternel, le Dieu de mon seigneur Abraham, qui m''''a conduit fidèlement, afin que je prisse la fille du frère de mon seigneur pour son fils."}, {"numero": 49, "texto": "Maintenant, si vous voulez user de bienveillance et de fidélité envers mon seigneur, déclarez-le-moi; sinon, déclarez-le-moi, et je me tournerai à droite ou à gauche."}, {"numero": 50, "texto": "Laban et Bethuel répondirent, et dirent: C''''est de l''''Eternel que la chose vient; nous ne pouvons te parler ni en mal ni en bien."}, {"numero": 51, "texto": "Voici Rebecca devant toi; prends et va, et qu''''elle soit la femme du fils de ton seigneur, comme l''''Eternel l''''a dit."}, {"numero": 52, "texto": "Lorsque le serviteur d''''Abraham eut entendu leurs paroles, il se prosterna en terre devant l''''Eternel."}, {"numero": 53, "texto": "Et le serviteur sortit des objets d''''argent, des objets d''''or, et des vêtements, qu''''il donna à Rebecca; il fit aussi de riches présents à son frère et à sa mère."}, {"numero": 54, "texto": "Après quoi, ils mangèrent et burent, lui et les gens qui étaient avec lui, et ils passèrent la nuit. Le matin, quand ils furent levés, le serviteur dit: Laissez-moi retourner vers mon seigneur."}, {"numero": 55, "texto": "Le frère et la mère dirent: Que la jeune fille reste avec nous quelque temps encore, une dizaine de jours; ensuite, tu partiras."}, {"numero": 56, "texto": "Il leur répondit: Ne me retardez pas, puisque l''''Eternel a fait réussir mon voyage; laissez-moi partir, et que j''''aille vers mon seigneur."}, {"numero": 57, "texto": "Alors ils répondirent: Appelons la jeune fille et consultons-la."}, {"numero": 58, "texto": "Ils appelèrent donc Rebecca, et lui dirent: Veux-tu aller avec cet homme? Elle répondit: J''''irai."}, {"numero": 59, "texto": "Et ils laissèrent partir Rebecca, leur soeur, et sa nourrice, avec le serviteur d''''Abraham et ses gens."}, {"numero": 60, "texto": "Ils bénirent Rebecca, et lui dirent: O notre soeur, puisses-tu devenir des milliers de myriades, et que ta postérité possède la porte de ses ennemis!"}, {"numero": 61, "texto": "Rebecca se leva, avec ses servantes; elles montèrent sur les chameaux, et suivirent l''''homme. Et le serviteur emmena Rebecca, et partit."}, {"numero": 62, "texto": "Cependant Isaac était revenu du puits de Lachaï-roï, et il habitait dans le pays du midi."}, {"numero": 63, "texto": "Un soir qu''''Isaac était sorti pour méditer dans les champs, il leva les yeux, et regarda; et voici, des chameaux arrivaient."}, {"numero": 64, "texto": "Rebecca leva aussi les yeux, vit Isaac, et descendit de son chameau."}, {"numero": 65, "texto": "Elle dit au serviteur: Qui est cet homme, qui vient dans les champs à notre rencontre? Et le serviteur répondit: C''''est mon seigneur. Alors elle prit son voile, et se couvrit."}, {"numero": 66, "texto": "Le serviteur raconta à Isaac toutes les choses qu''''il avait faites."}, {"numero": 67, "texto": "Isaac conduisit Rebecca dans la tente de Sara, sa mère; il prit Rebecca, qui devint sa femme, et il l''''aima. Ainsi fut consolé Isaac, après avoir perdu sa mère."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 24, 'es', '[{"numero": 1, "texto": "Y ABRAHAM era viejo, y bien entrado en días; y Jehová había bendecido á Abraham en todo."}, {"numero": 2, "texto": "Y dijo Abraham á un criado suyo, el más viejo de su casa, que era el que gobernaba en todo lo que tenía: Pon ahora tu mano debajo de mi muslo,"}, {"numero": 3, "texto": "Y te juramentaré por Jehová, Dios de los cielos y Dios de la tierra, que no has de tomar mujer para mi hijo de las hijas de los Cananeos, entre los cuales yo habito;"}, {"numero": 4, "texto": "Sino que irás á mi tierra y á mi parentela, y tomarás mujer para mi hijo Isaac."}, {"numero": 5, "texto": "Y el criado le respondió: Quizá la mujer no querrá venir en pos de mí á esta tierra: ¿volveré, pues, tu hijo á la tierra de donde saliste?"}, {"numero": 6, "texto": "Y Abraham le dijo: Guárdate que no vuelvas á mi hijo allá."}, {"numero": 7, "texto": "Jehová, Dios de los cielos, que me tomó de la casa de mi padre y de la tierra de mi parentela, y me habló y me juró, diciendo: A tu simiente daré esta tierra; él enviará su ángel delante de ti, y tú tomarás de allá mujer para mi hijo."}, {"numero": 8, "texto": "Y si la mujer no quisiere venir en pos de ti, serás libre de este mi juramento; solamente que no vuelvas allá á mi hijo."}, {"numero": 9, "texto": "Entonces el criado puso su mano debajo del muslo de Abraham su señor, y juróle sobre este negocio."}, {"numero": 10, "texto": "Y el criado tomó diez camellos de los camellos de su señor, y fuése, pues tenía á su disposición todos los bienes de su señor: y puesto en camino, llegó á Mesopotamia, á la ciudad de Nachôr."}, {"numero": 11, "texto": "E hizo arrodillar los camellos fuera de la ciudad, junto á un pozo de agua, á la hora de la tarde, á la hora en que salen las mozas por agua."}, {"numero": 12, "texto": "Y dijo: Jehová, Dios de mi señor Abraham, dame, te ruego, el tener hoy buen encuentro, y haz misericordia con mi señor Abraham."}, {"numero": 13, "texto": "He aquí yo estoy junto á la fuente de agua, y las hijas de los varones de esta ciudad salen por agua:"}, {"numero": 14, "texto": "Sea, pues, que la moza á quien yo dijere: Baja tu cántaro, te ruego, para que yo beba; y ella respondiere: Bebe, y también daré de beber á tus camellos: que sea ésta la que tú has destinado para tu siervo Isaac; y en esto conoceré que habrás hecho misericordia con mi señor."}, {"numero": 15, "texto": "Y aconteció que antes que él acabase de hablar, he aquí Rebeca, que había nacido á Bethuel, hijo de Milca, mujer de Nachôr hermano de Abraham, la cual salía con su cántaro sobre su hombro."}, {"numero": 16, "texto": "Y la moza era de muy hermoso aspecto, virgen, á la que varón no había conocido; la cual descendió á la fuente, y llenó su cántaro, y se volvía."}, {"numero": 17, "texto": "Entonces el criado corrió hacia ella, y dijo: Ruégote que me des á beber un poco de agua de tu cántaro."}, {"numero": 18, "texto": "Y ella respondió: Bebe, señor mío: y dióse prisa á bajar su cántaro sobre su mano, y le dió á beber."}, {"numero": 19, "texto": "Y cuando acabó de darle á beber, dijo: También para tus camellos sacaré agua, hasta que acaben de beber."}, {"numero": 20, "texto": "Y dióse prisa, y vació su cántaro en la pila, y corrió otra vez al pozo para sacar agua, y sacó para todos sus camellos."}, {"numero": 21, "texto": "Y el hombre estaba maravillado de ella, callando, para saber si Jehová había prosperado ó no su viaje."}, {"numero": 22, "texto": "Y fué que como los camellos acabaron de beber, presentóle el hombre un pendiente de oro que pesaba medio siclo, y dos brazaletes que pesaban diez:"}, {"numero": 23, "texto": "Y dijo: ¿De quién eres hija? Ruégote me digas, ¿hay lugar en casa de tu padre donde posemos?"}, {"numero": 24, "texto": "Y ella respondió: Soy hija de Bethuel, hijo de Milca, el cual parió ella á Nachôr."}, {"numero": 25, "texto": "Y añadió: También hay en nuestra casa paja y mucho forraje, y lugar para posar."}, {"numero": 26, "texto": "El hombre entonces se inclinó, y adoró á Jehová."}, {"numero": 27, "texto": "Y dijo: Bendito sea Jehová, Dios de mi amo Abraham, que no apartó su misericordia y su verdad de mi amo, guiándome Jehová en el camino á casa de los hermanos de mi amo."}, {"numero": 28, "texto": "Y la moza corrió, é hizo saber en casa de su madre estas cosas."}, {"numero": 29, "texto": "Y Rebeca tenía un hermano que se llamaba Labán, el cual corrió afuera al hombre, á la fuente;"}, {"numero": 30, "texto": "Y fué que como vió el pendiente y los brazaletes en las manos de su hermana, que decía, Así me habló aquel hombre; vino á él: y he aquí que estaba junto á los camellos á la fuente."}, {"numero": 31, "texto": "Y díjole: Ven, bendito de Jehová; ¿por qué estás fuera? yo he limpiado la casa, y el lugar para los camellos."}, {"numero": 32, "texto": "Entonces el hombre vino á casa, y Labán desató los camellos; y dióles paja y forraje, y agua para lavar los piés de él, y los piés de los hombres que con él venían."}, {"numero": 33, "texto": "Y pusiéronle delante qué comer; mas él dijo: No comeré hasta que haya dicho mi mensaje. Y él le dijo: Habla."}, {"numero": 34, "texto": "Entonces dijo: Yo soy criado de Abraham;"}, {"numero": 35, "texto": "Y Jehová ha bendecido mucho á mi amo, y él se ha engrandecido: y le ha dado ovejas y vacas, plata y oro, siervos y siervas, camellos y asnos."}, {"numero": 36, "texto": "Y Sara, mujer de mi amo, parió en su vejez un hijo á mi señor, quien le ha dado todo cuanto tiene."}, {"numero": 37, "texto": "Y mi amo me hizo jurar, diciendo: No tomarás mujer para mi hijo de las hijas de los Cananeos, en cuya tierra habito;"}, {"numero": 38, "texto": "Sino que irás á la casa de mi padre, y á mi parentela, y tomarás mujer para mi hijo."}, {"numero": 39, "texto": "Y yo dije: Quizás la mujer no querrá seguirme."}, {"numero": 40, "texto": "Entonces él me respondió: Jehová, en cuya presencia he andado, enviará su ángel contigo, y prosperará tu camino; y tomarás mujer para mi hijo de mi linaje y de la casa de mi padre:"}, {"numero": 41, "texto": "Entonces serás libre de mi juramento, cuando hubieres llegado á mi linaje; y si no te la dieren, serás libre de mi juramento."}, {"numero": 42, "texto": "Llegué, pues, hoy á la fuente, y dije: Jehová, Dios de mi señor Abraham, si tú prosperas ahora mi camino por el cual ando;"}, {"numero": 43, "texto": "He aquí yo estoy junto á la fuente de agua; sea, pues, que la doncella que saliere por agua, á la cual dijere: Dame á beber, te ruego, un poco de agua de tu cántaro;"}, {"numero": 44, "texto": "Y ella me respondiere, Bebe tú, y también para tus camellos sacaré agua: ésta sea la mujer que destinó Jehová para el hijo de mi señor."}, {"numero": 45, "texto": "Y antes que acabase de hablar en mi corazón, he aquí Rebeca, que salía con su cántaro sobre su hombro; y descendió á la fuente, y sacó agua; y le dije: Ruégote que me des á beber."}, {"numero": 46, "texto": "Y prestamente bajó su cántaro de encima de sí, y dijo: Bebe, y también á tus camellos daré á beber. Y bebí, y dió también de beber á mis camellos."}, {"numero": 47, "texto": "Entonces preguntéle, y dije: ¿De quién eres hija? Y ella respondió: Hija de Bethuel, hijo de Nachôr, que le parió Milca. Entonces púsele un pendiente sobre su nariz, y brazaletes sobre sus manos:"}, {"numero": 48, "texto": "E inclinéme, y adoré á Jehová, y bendije á Jehová, Dios de mi señor Abraham, que me había guiado por camino de verdad para tomar la hija del hermano de mi señor para su hijo."}, {"numero": 49, "texto": "Ahora pues, si vosotros hacéis misericordia y verdad con mi señor, declarádmelo; y si no, declarádmelo; y echaré á la diestra ó á la siniestra."}, {"numero": 50, "texto": "Entonces Labán y Bethuel respondieron y dijeron: De Jehová ha salido esto; no podemos hablarte malo ni bueno."}, {"numero": 51, "texto": "He ahí Rebeca delante de ti; tómala y vete, y sea mujer del hijo de tu señor, como lo ha dicho Jehová."}, {"numero": 52, "texto": "Y fué, que como el criado de Abraham oyó sus palabras, inclinóse á tierra á Jehová."}, {"numero": 53, "texto": "Y sacó el criado vasos de plata, y vasos de oro y vestidos, y dió á Rebeca: también dió cosas preciosas á su hermano y á su madre."}, {"numero": 54, "texto": "Y comieron y bebieron él y los varones que venían con él, y durmieron; y levantándose de mañana, dijo: Enviadme á mi señor."}, {"numero": 55, "texto": "Entonces respondió su hermano y su madre: Espere la moza con nosotros á lo menos diez días, y después irá."}, {"numero": 56, "texto": "Y él les dijo: No me detengáis, pues que Jehová ha prosperado mi camino; despachadme para que me vaya á mi señor."}, {"numero": 57, "texto": "Ellos respondieron entonces: Llamemos la moza y preguntémosle."}, {"numero": 58, "texto": "Y llamaron á Rebeca, y dijéronle: ¿Irás tú con este varón? Y ella respondió: Sí, iré."}, {"numero": 59, "texto": "Entonces dejaron ir á Rebeca su hermana, y á su nodriza, y al criado de Abraham y á sus hombres."}, {"numero": 60, "texto": "Y bendijeron á Rebeca, y dijéronle: Nuestra hermana eres; seas en millares de millares, y tu generación posea la puerta de sus enemigos."}, {"numero": 61, "texto": "Levantóse entonces Rebeca y sus mozas, y subieron sobre los camellos, y siguieron al hombre; y el criado tomó á Rebeca, y fuése."}, {"numero": 62, "texto": "Y venía Isaac del pozo del Viviente que me ve; porque él habitaba en la tierra del Mediodía;"}, {"numero": 63, "texto": "Y había salido Isaac á orar al campo, á la hora de la tarde; y alzando sus ojos miró, y he aquí los camellos que venían."}, {"numero": 64, "texto": "Rebeca también alzó sus ojos, y vió á Isaac, y descendió del camello;"}, {"numero": 65, "texto": "Porque había preguntado al criado: ¿Quién es este varón que viene por el campo hacia nosotros? Y el siervo había respondido: Este es mi señor. Ella entonces tomó el velo, y cubrióse."}, {"numero": 66, "texto": "Entonces el criado contó á Isaac todo lo que había hecho."}, {"numero": 67, "texto": "E introdújola Isaac á la tienda de su madre Sara, y tomó á Rebeca por mujer; y amóla: y consolóse Isaac después de la muerte de su madre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 27, 'pt', '[{"numero": 1, "texto": "E aconteceu que quando havia Isaque envelhecido, e seus olhos se ofuscaram ficando sem vista, chamou a Esaú, seu filho o maior, e disse-lhe: Meu filho. E ele respondeu: Eis-me aqui."}, {"numero": 2, "texto": "E ele disse: Eis que já sou velho, não sei o dia de minha morte:"}, {"numero": 3, "texto": "Toma, pois, agora tuas armas, tua aljava e teu arco, e sai ao campo, e pega-me caça;"}, {"numero": 4, "texto": "E faze-me um guisado, como eu gosto, e traze-o a mim, e comerei: para que te abençoe minha alma antes que morra."}, {"numero": 5, "texto": "E Rebeca estava ouvindo, quando falava Isaque a Esaú seu filho: e foi-se Esaú ao campo para pegar a caça que havia de trazer."}, {"numero": 6, "texto": "Então Rebeca falou a Jacó seu filho, dizendo: Eis que eu ouvi a teu pai que falava com Esaú teu irmão, dizendo:"}, {"numero": 7, "texto": "Traze-me caça, e faze-me um guisado, para que coma, e te abençoe diante do SENHOR antes que eu morra."}, {"numero": 8, "texto": "Agora, pois, filho meu, obedece à minha voz no que te mando;"}, {"numero": 9, "texto": "Vai agora ao gado, e traze-me dali dois bons cabritos das cabras, e farei deles iguarias para teu pai, como ele gosta;"}, {"numero": 10, "texto": "E tu as levarás a teu pai, e comerá, para que te abençoe antes de sua morte."}, {"numero": 11, "texto": "E Jacó disse a Rebeca sua mãe: Eis que Esaú meu irmão é homem peludo, e eu liso:"}, {"numero": 12, "texto": "Talvez meu pai me apalpe, e me terá por enganador, e trarei sobre mim maldição e não bênção."}, {"numero": 13, "texto": "E sua mãe respondeu: Filho meu, sobre mim tua maldição: somente obedece à minha voz, e vai e traze-os a mim."}, {"numero": 14, "texto": "Então ele foi, e tomou, e trouxe-os à sua mãe: e sua mãe fez guisados, como seu pai gostava."}, {"numero": 15, "texto": "E tomou Rebeca as roupas de Esaú seu filho maior, as melhores, que ela tinha em casa, e vestiu a Jacó seu filho menor:"}, {"numero": 16, "texto": "E fez-lhe vestir sobre suas mãos e sobre o pescoço onde não tinha pelo, as peles dos cabritos das cabras;"}, {"numero": 17, "texto": "E entregou os guisados e o pão que havia preparado, em mão de Jacó seu filho."}, {"numero": 18, "texto": "E ele foi a seu pai, e disse: Meu pai: e ele respondeu: Eis-me aqui, quem és, filho meu?"}, {"numero": 19, "texto": "E Jacó disse a seu pai: Eu sou Esaú teu primogênito; fiz como me disseste: levanta-te agora, e senta, e come de minha caça, para que me abençoe tua alma."}, {"numero": 20, "texto": "Então Isaque disse a seu filho: Como é que a achaste tão depressa, filho meu? E ele respondeu: Porque o SENHOR teu Deus fez que se encontrasse diante de mim."}, {"numero": 21, "texto": "E Isaque disse a Jacó: Aproxima-te agora, e te apalparei, filho meu, para [que eu saiba] se és meu filho Esaú ou não."}, {"numero": 22, "texto": "E chegou-se Jacó a seu pai Isaque; e ele lhe apalpou, e disse: A voz é a voz de Jacó, mas as mãos, as mãos de Esaú."}, {"numero": 23, "texto": "E não lhe reconheceu, porque suas mãos eram peludas como as mãos de Esaú: e lhe abençoou."}, {"numero": 24, "texto": "E disse: És tu meu filho Esaú? E ele respondeu: Eu sou."}, {"numero": 25, "texto": "E disse: Aproxima-a a mim, e comerei da caça de meu filho, para que te abençoe minha alma; e ele a aproximou, e comeu: trouxe-lhe também vinho, e bebeu."}, {"numero": 26, "texto": "E disse-lhe Isaque seu pai: Aproxima-te agora, e beija-me, filho meu."}, {"numero": 27, "texto": "E ele se chegou, e lhe beijou; e cheirou Isaque o cheiro de suas roupas, e lhe abençoou, e disse: Eis que o cheiro de meu filho é como o cheiro do campo que o SENHOR abençoou;"}, {"numero": 28, "texto": "Deus, pois, te dê do orvalho do céu, e das gorduras da terra, e abundância de trigo e de mosto."}, {"numero": 29, "texto": "Sirvam-te povos, E nações se inclinem a ti: Sê senhor de teus irmãos, e inclinem-se a ti os filhos de tua mãe; malditos os que te amaldiçoarem, e benditos os que te abençoarem."}, {"numero": 30, "texto": "E aconteceu, logo que havia Isaque de abençoar a Jacó, e apenas havia saído Jacó de diante de Isaque seu pai, que Esaú seu irmão veio de sua caça."}, {"numero": 31, "texto": "E também ele fez guisado, e trouxe a seu pai, e disse-lhe: Levante-se meu pai, e coma da caça de seu filho, para que me abençoe tua alma."}, {"numero": 32, "texto": "Então Isaque seu pai lhe disse: Quem és tu? E ele disse: Eu sou teu filho, teu primogênito, Esaú."}, {"numero": 33, "texto": "E Estremeceu-se Isaque com grande estremecimento, e disse: Quem é o que veio aqui, que agarrou caça, e me trouxe, e comi de tudo antes que viesses? Eu o abençoei, e será bendito."}, {"numero": 34, "texto": "Quando Esaú ouviu as palavras de seu pai clamou com uma muito grande e muito amarga exclamação, e lhe disse: Abençoa também a mim, meu pai."}, {"numero": 35, "texto": "E ele disse: Veio teu irmão com engano, e tomou tua bênção."}, {"numero": 36, "texto": "E ele respondeu: Bem chamaram seu nome Jacó, que já me enganou duas vezes; tirou minha primogenitura, e eis que agora tomou minha bênção. E disse: Não guardaste bênção para mim?"}, {"numero": 37, "texto": "Isaque respondeu e disse a Esaú: Eis que eu o pus por senhor teu, e lhe dei por servos a todos os seus irmãos: de trigo e de vinho lhe provi: que, pois, farei a ti agora, filho meu?"}, {"numero": 38, "texto": "E Esaú respondeu a seu pai: Não tens mais que uma só bênção, meu pai? Abençoa também a mim, meu pai. E levantou Esaú sua voz, e chorou."}, {"numero": 39, "texto": "Então Isaque seu pai falou e disse-lhe: Eis que será tua habitação sem gorduras da terra, E sem orvalho dos céus de acima;"}, {"numero": 40, "texto": "E por tua espada viverás, e a teu irmão servirás: E sucederá quando te dominares, Que descarregarás seu jugo de teu pescoço."}, {"numero": 41, "texto": "E odiou Esaú a Jacó pela bênção com que lhe havia abençoado, e disse em seu coração: Chegarão os dias do luto de meu pai, e eu matarei a Jacó meu irmão."}, {"numero": 42, "texto": "E foram ditas a Rebeca as palavras de Esaú seu filho mais velho: e ela enviou e chamou a Jacó seu filho mais novo, e disse-lhe: Eis que, Esaú teu irmão se consola acerca de ti com a ideia de matar-te."}, {"numero": 43, "texto": "Agora, pois, filho meu, obedece à minha voz; levanta-te, e foge-te a Labão meu irmão, a Harã."}, {"numero": 44, "texto": "E mora com ele alguns dias, até que a ira de teu irmão se diminua;"}, {"numero": 45, "texto": "Até que se aplaque a ira de teu irmão contra ti, e se esqueça do que lhe fizeste: eu enviarei então, e te trarei dali: por que serei privada de vós ambos em um dia?"}, {"numero": 46, "texto": "E disse Rebeca a Isaque: Desgosto tenho de minha vida, por causa das filhas de Hete. Se Jacó toma mulher das filhas de Hete, como estas, das filhas desta terra, para que quero a vida?"}]'::jsonb, 'Almeida Livre'),
  ('Gn', 27, 'en', '[{"numero": 1, "texto": "And it came to pass, that when Isaac was old, and his eyes were dim, so that he could not see, he called Esau his eldest son, and said unto him, My son: and he said unto him, Behold, here am I."}, {"numero": 2, "texto": "And he said, Behold now, I am old, I know not the day of my death:"}, {"numero": 3, "texto": "Now therefore take, I pray thee, thy weapons, thy quiver and thy bow, and go out to the field, and take me some venison;"}, {"numero": 4, "texto": "And make me savoury meat, such as I love, and bring it to me, that I may eat; that my soul may bless thee before I die."}, {"numero": 5, "texto": "And Rebekah heard when Isaac spake to Esau his son. And Esau went to the field to hunt for venison, and to bring it."}, {"numero": 6, "texto": "And Rebekah spake unto Jacob her son, saying, Behold, I heard thy father speak unto Esau thy brother, saying,"}, {"numero": 7, "texto": "Bring me venison, and make me savoury meat, that I may eat, and bless thee before the Lord before my death."}, {"numero": 8, "texto": "Now therefore, my son, obey my voice according to that which I command thee."}, {"numero": 9, "texto": "Go now to the flock, and fetch me from thence two good kids of the goats; and I will make them savoury meat for thy father, such as he loveth:"}, {"numero": 10, "texto": "And thou shalt bring it to thy father, that he may eat, and that he may bless thee before his death."}, {"numero": 11, "texto": "And Jacob said to Rebekah his mother, Behold, Esau my brother is a hairy man, and I am a smooth man:"}, {"numero": 12, "texto": "My father peradventure will feel me, and I shall seem to him as a deceiver; and I shall bring a curse upon me, and not a blessing."}, {"numero": 13, "texto": "And his mother said unto him, Upon me be thy curse, my son: only obey my voice, and go fetch me them."}, {"numero": 14, "texto": "And he went, and fetched, and brought them to his mother: and his mother made savoury meat, such as his father loved."}, {"numero": 15, "texto": "And Rebekah took goodly raiment of her eldest son Esau, which were with her in the house, and put them upon Jacob her younger son:"}, {"numero": 16, "texto": "And she put the skins of the kids of the goats upon his hands, and upon the smooth of his neck:"}, {"numero": 17, "texto": "And she gave the savoury meat and the bread, which she had prepared, into the hand of her son Jacob."}, {"numero": 18, "texto": "And he came unto his father, and said, My father: and he said, Here am I; who art thou, my son?"}, {"numero": 19, "texto": "And Jacob said unto his father, I am Esau thy first born; I have done according as thou badest me: arise, I pray thee, sit and eat of my venison, that thy soul may bless me."}, {"numero": 20, "texto": "And Isaac said unto his son, How is it that thou hast found it so quickly, my son? And he said, Because the Lord thy God brought it to me."}, {"numero": 21, "texto": "And Isaac said unto Jacob, Come near, I pray thee, that I may feel thee, my son, whether thou be my very son Esau or not."}, {"numero": 22, "texto": "And Jacob went near unto Isaac his father; and he felt him, and said, The voice is Jacob''s voice, but the hands are the hands of Esau."}, {"numero": 23, "texto": "And he discerned him not, because his hands were hairy, as his brother Esau''s hands: so he blessed him."}, {"numero": 24, "texto": "And he said, Art thou my very son Esau? And he said, I am."}, {"numero": 25, "texto": "And he said, Bring it near to me, and I will eat of my son''s venison, that my soul may bless thee. And he brought it near to him, and he did eat: and he brought him wine and he drank."}, {"numero": 26, "texto": "And his father Isaac said unto him, Come near now, and kiss me, my son."}, {"numero": 27, "texto": "And he came near, and kissed him: and he smelled the smell of his raiment, and blessed him, and said, See, the smell of my son is as the smell of a field which the Lord hath blessed:"}, {"numero": 28, "texto": "Therefore God give thee of the dew of heaven, and the fatness of the earth, and plenty of corn and wine:"}, {"numero": 29, "texto": "Let people serve thee, and nations bow down to thee: be lord over thy brethren, and let thy mother''s sons bow down to thee: cursed be every one that curseth thee, and blessed be he that blesseth thee."}, {"numero": 30, "texto": "And it came to pass, as soon as Isaac had made an end of blessing Jacob, and Jacob was yet scarce gone out from the presence of Isaac his father, that Esau his brother came in from his hunting."}, {"numero": 31, "texto": "And he also had made savoury meat, and brought it unto his father, and said unto his father, Let my father arise, and eat of his son''s venison, that thy soul may bless me."}, {"numero": 32, "texto": "And Isaac his father said unto him, Who art thou? And he said, I am thy son, thy firstborn Esau."}, {"numero": 33, "texto": "And Isaac trembled very exceedingly, and said, Who? where is he that hath taken venison, and brought it me, and I have eaten of all before thou camest, and have blessed him? yea, and he shall be blessed."}, {"numero": 34, "texto": "And when Esau heard the words of his father, he cried with a great and exceeding bitter cry, and said unto his father, Bless me, even me also, O my father."}, {"numero": 35, "texto": "And he said, Thy brother came with subtilty, and hath taken away thy blessing."}, {"numero": 36, "texto": "And he said, Is not he rightly named Jacob? for he hath supplanted me these two times: he took away my birthright; and, behold, now he hath taken away my blessing. And he said, Hast thou not reserved a blessing for me?"}, {"numero": 37, "texto": "And Isaac answered and said unto Esau, Behold, I have made him thy lord, and all his brethren have I given to him for servants; and with corn and wine have I sustained him: and what shall I do now unto thee, my son?"}, {"numero": 38, "texto": "And Esau said unto his father, Hast thou but one blessing, my father? bless me, even me also, O my father. And Esau lifted up his voice, and wept."}, {"numero": 39, "texto": "And Isaac his father answered and said unto him, Behold, thy dwelling shall be the fatness of the earth, and of the dew of heaven from above;"}, {"numero": 40, "texto": "And by thy sword shalt thou live, and shalt serve thy brother; and it shall come to pass when thou shalt have the dominion, that thou shalt break his yoke from off thy neck."}, {"numero": 41, "texto": "And Esau hated Jacob because of the blessing wherewith his father blessed him: and Esau said in his heart, The days of mourning for my father are at hand; then will I slay my brother Jacob."}, {"numero": 42, "texto": "And these words of Esau her elder son were told to Rebekah: and she sent and called Jacob her younger son, and said unto him, Behold, thy brother Esau, as touching thee, doth comfort himself, purposing to kill thee."}, {"numero": 43, "texto": "Now therefore, my son, obey my voice; arise, flee thou to Laban my brother to Haran;"}, {"numero": 44, "texto": "And tarry with him a few days, until thy brother''s fury turn away;"}, {"numero": 45, "texto": "Until thy brother''s anger turn away from thee, and he forget that which thou hast done to him: then I will send, and fetch thee from thence: why should I be deprived also of you both in one day?"}, {"numero": 46, "texto": "And Rebekah said to Isaac, I am weary of my life because of the daughters of Heth: if Jacob take a wife of the daughters of Heth, such as these which are of the daughters of the land, what good shall my life do me?"}]'::jsonb, 'King James Version'),
  ('Gn', 27, 'fr', '[{"numero": 1, "texto": "Isaac devenait vieux, et ses yeux s''''étaient affaiblis au point qu''''il ne voyait plus. Alors il appela Esaü, son fils aîné, et lui dit: Mon fils! Et il lui répondit: Me voici!"}, {"numero": 2, "texto": "Isaac dit: Voici donc, je suis vieux, je ne connais pas le jour de ma mort."}, {"numero": 3, "texto": "Maintenant donc, je te prie, prends tes armes, ton carquois et ton arc, va dans les champs, et chasse-moi du gibier."}, {"numero": 4, "texto": "Fais-moi un mets comme j''''aime, et apporte-le-moi à manger, afin que mon âme te bénisse avant que je meure."}, {"numero": 5, "texto": "Rebecca écouta ce qu''''Isaac disait à Esaü, son fils. Et Esaü s''''en alla dans les champs, pour chasser du gibier et pour le rapporter."}, {"numero": 6, "texto": "Puis Rebecca dit à Jacob, son fils: Voici, j''''ai entendu ton père qui parlait ainsi à Esaü, ton frère:"}, {"numero": 7, "texto": "Apporte-moi du gibier et fais-moi un mets que je mangerai; et je te bénirai devant l''''Eternel avant ma mort."}, {"numero": 8, "texto": "Maintenant, mon fils, écoute ma voix à l''''égard de ce que je te commande."}, {"numero": 9, "texto": "Va me prendre au troupeau deux bons chevreaux; j''''en ferai pour ton père un mets comme il aime;"}, {"numero": 10, "texto": "et tu le porteras à manger à ton père, afin qu''''il te bénisse avant sa mort."}, {"numero": 11, "texto": "Jacob répondit à sa mère: Voici, Esaü, mon frère, est velu, et je n''''ai point de poil."}, {"numero": 12, "texto": "Peut-être mon père me touchera-t-il, et je passerai à ses yeux pour un menteur, et je ferai venir sur moi la malédiction, et non la bénédiction."}, {"numero": 13, "texto": "Sa mère lui dit: Que cette malédiction, mon fils, retombe sur moi! Ecoute seulement ma voix, et va me les prendre."}, {"numero": 14, "texto": "Jacob alla les prendre, et les apporta à sa mère, qui fit un mets comme son père aimait."}, {"numero": 15, "texto": "Ensuite, Rebecca prit les vêtements d''''Esaü, son fils aîné, les plus beaux qui se trouvaient à la maison, et elle les fit mettre à Jacob, son fils cadet."}, {"numero": 16, "texto": "Elle couvrit ses mains de la peau des chevreaux, et son cou qui était sans poil."}, {"numero": 17, "texto": "Et elle plaça dans la main de Jacob, son fils, le mets et le pain qu''''elle avait préparés."}, {"numero": 18, "texto": "Il vint vers son père, et dit: Mon père! Et Isaac dit: Me voici! qui es-tu, mon fils?"}, {"numero": 19, "texto": "Jacob répondit à son père: Je suis Esaü, ton fils aîné; j''''ai fait ce que tu m''''as dit. Lève-toi, je te prie, assieds-toi, et mange de mon gibier, afin que ton âme me bénisse."}, {"numero": 20, "texto": "Isaac dit à son fils: Eh quoi! tu en as déjà trouvé, mon fils! Et Jacob répondit: C''''est que l''''Eternel, ton Dieu, l''''a fait venir devant moi."}, {"numero": 21, "texto": "Isaac dit à Jacob: Approche donc, et que je te touche, mon fils, pour savoir si tu es mon fils Esaü, ou non."}, {"numero": 22, "texto": "Jacob s''''approcha d''''Isaac, son père, qui le toucha, et dit: La voix est la voix de Jacob, mais les mains sont les mains d''''Esaü."}, {"numero": 23, "texto": "Il ne le reconnut pas, parce que ses mains étaient velues, comme les mains d''''Esaü, son frère; et il le bénit."}, {"numero": 24, "texto": "Il dit: C''''est toi qui es mon fils Esaü? Et Jacob répondit: C''''est moi."}, {"numero": 25, "texto": "Isaac dit: Sers-moi, et que je mange du gibier de mon fils, afin que mon âme te bénisse. Jacob le servit, et il mangea; il lui apporta aussi du vin, et il but."}, {"numero": 26, "texto": "Alors Isaac, son père, lui dit: Approche donc, et baise-moi, mon fils."}, {"numero": 27, "texto": "Jacob s''''approcha, et le baisa. Isaac sentit l''''odeur de ses vêtements; puis il le bénit, et dit: Voici, l''''odeur de mon fils est comme l''''odeur d''''un champ que l''''Eternel a béni."}, {"numero": 28, "texto": "Que Dieu te donne de la rosée du ciel Et de la graisse de la terre, Du blé et du vin en abondance!"}, {"numero": 29, "texto": "Que des peuples te soient soumis, Et que des nations se prosternent devant toi! Sois le maître de tes frères, Et que les fils de ta mère se prosternent devant toi! Maudit soit quiconque te maudira, Et béni soit quiconque te bénira."}, {"numero": 30, "texto": "Isaac avait fini de bénir Jacob, et Jacob avait à peine quitté son père Isaac, qu''''Esaü, son frère, revint de la chasse."}, {"numero": 31, "texto": "Il fit aussi un mets, qu''''il porta à son père; et il dit à son père: Que mon père se lève et mange du gibier de son fils, afin que ton âme me bénisse!"}, {"numero": 32, "texto": "Isaac, son père, lui dit: Qui es-tu? Et il répondit: Je suis ton fils aîné, Esaü."}, {"numero": 33, "texto": "Isaac fut saisi d''''une grande, d''''une violente émotion, et il dit: Qui est donc celui qui a chassé du gibier, et me l''''a apporté? J''''ai mangé de tout avant que tu vinsses, et je l''''ai béni. Aussi sera-t-il béni."}, {"numero": 34, "texto": "Lorsque Esaü entendit les paroles de son père, il poussa de forts cris, pleins d''''amertume, et il dit à son père: Bénis-moi aussi, mon père!"}, {"numero": 35, "texto": "Isaac dit: Ton frère est venu avec ruse, et il a enlevé ta bénédiction."}, {"numero": 36, "texto": "Esaü dit: Est-ce parce qu''''on l''''a appelé du nom de Jacob qu''''il m''''a supplanté deux fois? Il a enlevé mon droit d''''aînesse, et voici maintenant qu''''il vient d''''enlever ma bénédiction. Et il dit: N''''as-tu point réservé de bénédiction pour moi?"}, {"numero": 37, "texto": "Isaac répondit, et dit à Esaü: Voici, je l''''ai établi ton maître, et je lui ai donné tous ses frères pour serviteurs, je l''''ai pourvu de blé et de vin: que puis-je donc faire pour toi, mon fils?"}, {"numero": 38, "texto": "Esaü dit à son père: N''''as-tu que cette seule bénédiction, mon père? Bénis-moi aussi, mon père! Et Esaü éleva la voix, et pleura."}, {"numero": 39, "texto": "Isaac, son père, répondit, et lui dit: Voici! Ta demeure sera privée de la graisse de la terre Et de la rosée du ciel, d''''en haut."}, {"numero": 40, "texto": "Tu vivras de ton épée, Et tu seras asservi à ton frère; Mais en errant librement çà et là, Tu briseras son joug de dessus ton cou."}, {"numero": 41, "texto": "Esaü conçut de la haine contre Jacob, à cause de la bénédiction dont son père l''''avait béni; et Esaü disait en son coeur: Les jours du deuil de mon père vont approcher, et je tuerai Jacob, mon frère."}, {"numero": 42, "texto": "On rapporta à Rebecca les paroles d''''Esaü, son fils aîné. Elle fit alors appeler Jacob, son fils cadet, et elle lui dit: Voici, Esaü, ton frère, veut tirer vengeance de toi, en te tuant."}, {"numero": 43, "texto": "Maintenant, mon fils, écoute ma voix! Lève-toi, fuis chez Laban, mon frère, à Charan;"}, {"numero": 44, "texto": "et reste auprès de lui quelque temps, jusqu''''à ce que la fureur de ton frère s''''apaise,"}, {"numero": 45, "texto": "jusqu''''à ce que la colère de ton frère se détourne de toi, et qu''''il oublie ce que tu lui as fait. Alors je te ferai revenir. Pourquoi serais-je privée de vous deux en un même jour?"}, {"numero": 46, "texto": "Rebecca dit à Isaac: Je suis dégoûtée de la vie, à cause des filles de Heth. Si Jacob prend une femme, comme celles-ci, parmi les filles de Heth, parmi les filles du pays, à quoi me sert la vie?"}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 27, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que cuando hubo Isaac envejecido, y sus ojos se ofuscaron quedando sin vista, llamó á Esaú, su hijo el mayor, y díjole: Mi hijo. Y él respondió: Heme aquí."}, {"numero": 2, "texto": "Y él dijo: He aquí ya soy viejo, no sé el día de mi muerte:"}, {"numero": 3, "texto": "Toma, pues, ahora tus armas, tu aljaba y tu arco, y sal al campo, y cógeme caza;"}, {"numero": 4, "texto": "Y hazme un guisado, como yo gusto, y tráemelo, y comeré; para que te bendiga mi alma antes que muera."}, {"numero": 5, "texto": "Y Rebeca estaba oyendo, cuando hablaba Isaac á Esaú su hijo: y fuése Esaú al campo para coger la caza que había de traer."}, {"numero": 6, "texto": "Entonces Rebeca habló á Jacob su hijo, diciendo: He aquí yo he oído á tu padre que hablaba con Esaú tu hermano, diciendo:"}, {"numero": 7, "texto": "Tráeme caza, y hazme un guisado, para que coma, y te bendiga delante de Jehová antes que yo muera."}, {"numero": 8, "texto": "Ahora pues, hijo mío, obedece á mi voz en lo que te mando;"}, {"numero": 9, "texto": "Ve ahora al ganado, y tráeme de allí dos buenos cabritos de las cabras, y haré de ellos viandas para tu padre, como él gusta;"}, {"numero": 10, "texto": "Y tú las llevarás á tu padre, y comerá, para que te bendiga antes de su muerte."}, {"numero": 11, "texto": "Y Jacob dijo á Rebeca su madre: He aquí, Esaú mi hermano es hombre velloso, y yo lampiño:"}, {"numero": 12, "texto": "Quizá me tentará mi padre, y me tendrá por burlador, y traeré sobre mí maldición y no bendición."}, {"numero": 13, "texto": "Y su madre respondió: Hijo mío, sobre mí tu maldición: solamente obedece á mi voz, y ve y tráemelos."}, {"numero": 14, "texto": "Entonces él fué, y tomó, y trájolos á su madre: y su madre hizo guisados, como su padre gustaba."}, {"numero": 15, "texto": "Y tomó Rebeca los vestidos de Esaú su hijo mayor, los preciosos, que ella tenía en casa, y vistió á Jacob su hijo menor:"}, {"numero": 16, "texto": "E hízole vestir sobre sus manos, y sobre la cerviz donde no tenía vello, las pieles de los cabritos de las cabras;"}, {"numero": 17, "texto": "Y entregó los guisados y el pan que había aderezado, en mano de Jacob su hijo."}, {"numero": 18, "texto": "Y él fué á su padre, y dijo: Padre mío: y él respondió: Heme aquí, ¿quién eres, hijo mío?"}, {"numero": 19, "texto": "Y Jacob dijo á su padre: Yo soy Esaú tu primogénito; he hecho como me dijiste: levántate ahora, y siéntate, y come de mi caza, para que me bendiga tu alma."}, {"numero": 20, "texto": "Entonces Isaac dijo á su hijo: ¿Cómo es que la hallaste tan presto, hijo mío? Y él respondió: Porque Jehová tu Dios hizo que se encontrase delante de mí."}, {"numero": 21, "texto": "E Isaac dijo á Jacob: Acércate ahora, y te palparé, hijo mío, por si eres mi hijo Esaú, ó no."}, {"numero": 22, "texto": "Y llegóse Jacob á su padre Isaac; y él le palpó, y dijo: La voz es la voz de Jacob, mas las manos, las manos de Esaú."}, {"numero": 23, "texto": "Y no le conoció, porque sus manos eran vellosas como las manos de Esaú: y le bendijo."}, {"numero": 24, "texto": "Y dijo: ¿Eres tú mi hijo Esaú? Y él respondió: Yo soy."}, {"numero": 25, "texto": "Y dijo: Acércamela, y comeré de la caza de mi hijo, para que te bendiga mi alma; y él se la acercó, y comió: trájole también vino, y bebió."}, {"numero": 26, "texto": "Y díjole Isaac su padre: Acércate ahora, y bésame, hijo mío."}, {"numero": 27, "texto": "Y él se llegó, y le besó; y olió Isaac el olor de sus vestidos, y le bendijo, y dijo: Mira, el olor de mi hijo como el olor del campo que Jehová ha bendecido:"}, {"numero": 28, "texto": "Dios, pues, te dé del rocío del cielo, y de las grosuras de la tierra, y abundancia de trigo y de mosto."}, {"numero": 29, "texto": "Sírvante pueblos, y naciones se inclinen á ti: sé señor de tus hermanos, e inclínense á ti los hijos de tu madre: malditos los que te maldijeren, y benditos los que te bendijeren."}, {"numero": 30, "texto": "Y aconteció, luego que hubo Isaac acabado de bendecir á Jacob, y apenas había salido Jacob de delante de Isaac su padre, que Esaú su hermano vino de su caza."}, {"numero": 31, "texto": "E hizo él también guisados, y trajo á su padre, y díjole: Levántese mi padre, y coma de la caza de su hijo, para que me bendiga tu alma."}, {"numero": 32, "texto": "Entonces Isaac su padre le dijo: ¿Quién eres tú? Y él dijo: Yo soy tu hijo, tu primogénito, Esaú."}, {"numero": 33, "texto": "Y estremecióse Isaac con grande estremecimiento, y dijo: ¿Quién es el que vino aquí, que cogió caza, y me trajo, y comí de todo antes que vinieses? Yo le bendije, y será bendito."}, {"numero": 34, "texto": "Como Esaú oyó las palabras de su padre, clamó con una muy grande y muy amarga exclamación, y le dijo: Bendíceme también á mí, padre mío."}, {"numero": 35, "texto": "Y él dijo: Vino tu hermano con engaño, y tomó tu bendición."}, {"numero": 36, "texto": "Y él respondió: Bien llamaron su nombre Jacob, que ya me ha engañado dos veces; alzóse con mi primogenitura, y he aquí ahora ha tomado mi bendición. Y dijo: ¿No has guardado bendición para mí?"}, {"numero": 37, "texto": "Isaac respondió y dijo á Esaú: He aquí yo le he puesto por señor tuyo, y le he dado por siervos á todos sus hermanos: de trigo y de vino le he provisto: ¿qué, pues, te haré á ti ahora, hijo mío?"}, {"numero": 38, "texto": "Y Esaú respondió á su padre: ¿No tienes más que una sola bendición, padre mío? bendíceme también á mí, padre mío. Y alzó Esaú su voz, y lloró."}, {"numero": 39, "texto": "Entonces Isaac su padre habló y díjole: He aquí será tu habitación en grosuras de la tierra, y del rocío de los cielos de arriba;"}, {"numero": 40, "texto": "Y por tu espada vivirás, y á tu hermano servirás: y sucederá cuando te enseñorees, que descargarás su yugo de tu cerviz."}, {"numero": 41, "texto": "Y aborreció Esaú á Jacob por la bendición con que le había bendecido, y dijo en su corazón: Llegarán los días del luto de mi padre, y yo mataré á Jacob mi hermano."}, {"numero": 42, "texto": "Y fueron dichas á Rebeca las palabras de Esaú su hijo mayor: y ella envió y llamó á Jacob su hijo menor, y díjole: He aquí, Esaú tu hermano se consuela acerca de ti con la idea de matarte."}, {"numero": 43, "texto": "Ahora pues, hijo mío, obedece á mi voz; levántate, y húyete á Labán mi hermano, á Harán;"}, {"numero": 44, "texto": "Y mora con él algunos días, hasta que el enojo de tu hermano se mitigue;"}, {"numero": 45, "texto": "Hasta que se aplaque la ira de tu hermano contra ti, y se olvide de lo que le has hecho: yo enviaré entonces, y te traeré de allá: ¿por qué seré privada de vosotros ambos en un día?"}, {"numero": 46, "texto": "Y dijo Rebeca á Isaac: Fastidio tengo de mi vida, á causa de las hijas de Heth. Si Jacob toma mujer de las hijas de Heth, como éstas, de las hijas de esta tierra, ¿para qué quiero la vida?"}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 28, 'pt', '[{"numero": 1, "texto": "Então Isaque chamou a Jacó, e o abençoou, e mandou-lhe dizendo: Não tomes mulher das filhas de Canaã."}, {"numero": 2, "texto": "Levanta-te, vai a Padã-Arã, à casa de Betuel, pai de tua mãe, e toma ali mulher das filhas de Labão, irmão de tua mãe."}, {"numero": 3, "texto": "E o Deus Todo-Poderoso te abençoe e te faça frutificar, e te multiplique, até vir a ser congregação de povos;"}, {"numero": 4, "texto": "E te dê a bênção de Abraão, e à tua descendência contigo, para que herdes a terra de tuas peregrinações, que Deus deu a Abraão."}, {"numero": 5, "texto": "Assim enviou Isaque a Jacó, o qual foi a Padã-Arã, a Labão, filho de Betuel arameu, irmão de Rebeca, mãe de Jacó e de Esaú."}, {"numero": 6, "texto": "E viu Esaú como Isaque havia abençoado a Jacó, e lhe havia enviado a Padã-Arã, para tomar para si mulher dali; e que quando lhe abençoou, lhe havia mandado, dizendo: Não tomarás mulher das filhas de Canaã;"}, {"numero": 7, "texto": "E que Jacó havia obedecido a seu pai e a sua mãe, e se havia ido a Padã-Arã."}, {"numero": 8, "texto": "Esaú viu que as filhas de Canaã pareciam mal ao seu pai Isaque."}, {"numero": 9, "texto": "Então Esaú foi a Ismael, e tomou para si por mulher, além de suas outras mulheres, a Maalate, filha de Ismael, filho de Abraão, irmã de Nebaiote."}, {"numero": 10, "texto": "E Jacó saiu de Berseba, e foi a Harã;"}, {"numero": 11, "texto": "ele chegou a um lugar, e ali dormiu, porque o sol já se havia posto. E tomou uma das pedras daquele lugar e a pôs por sua cabeceira, e deitou-se naquele lugar."}, {"numero": 12, "texto": "E sonhou, e eis uma escada que estava posta na terra, e seu topo tocava no céu; e eis que anjos de Deus subiam e desciam por ela."}, {"numero": 13, "texto": "E eis que o SENHOR estava no alto dela, e disse: “Eu sou o SENHOR, o Deus de teu pai Abraão, e o Deus de Isaque; a terra em que estás deitado, eu a darei a ti e à tua descendência."}, {"numero": 14, "texto": "E a tua descendência será como o pó da terra, e te estenderás ao ocidente, ao oriente, ao norte, e ao sul; e todas as famílias da terra serão abençoadas em ti e na tua descendência."}, {"numero": 15, "texto": "E eis que eu estou contigo, e te guardarei por onde quer que fores, e te farei voltar a esta terra; porque não te deixarei, até que eu tenha feito o que te disse.”"}, {"numero": 16, "texto": "Jacó despertou-se de seu sonho, e disse: “Certamente o SENHOR está neste lugar, e eu não sabia.”"}, {"numero": 17, "texto": "E teve medo, e disse: “Quão temível é este lugar! Não é outra coisa, senão casa de Deus e porta do céu.”"}, {"numero": 18, "texto": "Jacó levantou-se de manhã cedo, tomou a pedra que havia colocado de cabeceira, e a pôs por coluna, e derramou azeite sobre ela."}, {"numero": 19, "texto": "E chamou o nome daquele lugar Betel, porém antes o nome da cidade era Luz."}, {"numero": 20, "texto": "E Jacó fez um voto, dizendo: “Se Deus for comigo, e me guardar nesta viagem que vou, e me der pão para comer e roupa para vestir,"}, {"numero": 21, "texto": "e se eu voltar em paz à casa de meu pai, o SENHOR será meu Deus,"}, {"numero": 22, "texto": "e esta pedra que pus por coluna será casa de Deus; e de tudo o que me deres, darei a ti o dízimo."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 28, 'en', '[{"numero": 1, "texto": "And Isaac called Jacob, and blessed him, and charged him, and said unto him, Thou shalt not take a wife of the daughters of Canaan."}, {"numero": 2, "texto": "Arise, go to Padanaram, to the house of Bethuel thy mother''s father; and take thee a wife from thence of the daughers of Laban thy mother''s brother."}, {"numero": 3, "texto": "And God Almighty bless thee, and make thee fruitful, and multiply thee, that thou mayest be a multitude of people;"}, {"numero": 4, "texto": "And give thee the blessing of Abraham, to thee, and to thy seed with thee; that thou mayest inherit the land wherein thou art a stranger, which God gave unto Abraham."}, {"numero": 5, "texto": "And Isaac sent away Jacob: and he went to Padanaram unto Laban, son of Bethuel the Syrian, the brother of Rebekah, Jacob''s and Esau''s mother."}, {"numero": 6, "texto": "When Esau saw that Isaac had blessed Jacob, and sent him away to Padanaram, to take him a wife from thence; and that as he blessed him he gave him a charge, saying, Thou shalt not take a wife of the daughers of Canaan;"}, {"numero": 7, "texto": "And that Jacob obeyed his father and his mother, and was gone to Padanaram;"}, {"numero": 8, "texto": "And Esau seeing that the daughters of Canaan pleased not Isaac his father;"}, {"numero": 9, "texto": "Then went Esau unto Ishmael, and took unto the wives which he had Mahalath the daughter of Ishmael Abraham''s son, the sister of Nebajoth, to be his wife."}, {"numero": 10, "texto": "And Jacob went out from Beersheba, and went toward Haran."}, {"numero": 11, "texto": "And he lighted upon a certain place, and tarried there all night, because the sun was set; and he took of the stones of that place, and put them for his pillows, and lay down in that place to sleep."}, {"numero": 12, "texto": "And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it."}, {"numero": 13, "texto": "And, behold, the Lord stood above it, and said, I am the Lord God of Abraham thy father, and the God of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed;"}, {"numero": 14, "texto": "And thy seed shall be as the dust of the earth, and thou shalt spread abroad to the west, and to the east, and to the north, and to the south: and in thee and in thy seed shall all the families of the earth be blessed."}, {"numero": 15, "texto": "And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of."}, {"numero": 16, "texto": "And Jacob awaked out of his sleep, and he said, Surely the Lord is in this place; and I knew it not."}, {"numero": 17, "texto": "And he was afraid, and said, How dreadful is this place! this is none other but the house of God, and this is the gate of heaven."}, {"numero": 18, "texto": "And Jacob rose up early in the morning, and took the stone that he had put for his pillows, and set it up for a pillar, and poured oil upon the top of it."}, {"numero": 19, "texto": "And he called the name of that place Bethel: but the name of that city was called Luz at the first."}, {"numero": 20, "texto": "And Jacob vowed a vow, saying, If God will be with me, and will keep me in this way that I go, and will give me bread to eat, and raiment to put on,"}, {"numero": 21, "texto": "So that I come again to my father''s house in peace; then shall the Lord be my God:"}, {"numero": 22, "texto": "And this stone, which I have set for a pillar, shall be God''s house: and of all that thou shalt give me I will surely give the tenth unto thee."}]'::jsonb, 'King James Version'),
  ('Gn', 28, 'fr', '[{"numero": 1, "texto": "Isaac appela Jacob, le bénit, et lui donna cet ordre: Tu ne prendras pas une femme parmi les filles de Canaan."}, {"numero": 2, "texto": "Lève-toi, va à Paddan-Aram, à la maison de Bethuel, père de ta mère, et prends-y une femme d''''entre les filles de Laban, frère de ta mère."}, {"numero": 3, "texto": "Que le Dieu tout-puissant te bénisse, te rende fécond et te multiplie, afin que tu deviennes une multitude de peuples!"}, {"numero": 4, "texto": "Qu''''il te donne la bénédiction d''''Abraham, à toi et à ta postérité avec toi, afin que tu possèdes le pays où tu habites comme étranger, et qu''''il a donné à Abraham!"}, {"numero": 5, "texto": "Et Isaac fit partir Jacob, qui s''''en alla à Paddan-Aram, auprès de Laban, fils de Bethuel, l''''Araméen, frère de Rebecca, mère de Jacob et d''''Esaü."}, {"numero": 6, "texto": "Esaü vit qu''''Isaac avait béni Jacob, et qu''''il l''''avait envoyé à Paddan-Aram pour y prendre une femme, et qu''''en le bénissant il lui avait donné cet ordre: Tu ne prendras pas une femme parmi les filles de Canaan."}, {"numero": 7, "texto": "Il vit que Jacob avait obéi à son père et à sa mère, et qu''''il était parti pour Paddan-Aram."}, {"numero": 8, "texto": "Esaü comprit ainsi que les filles de Canaan déplaisaient à Isaac, son père."}, {"numero": 9, "texto": "Et Esaü s''''en alla vers Ismaël. Il prit pour femme, outre les femmes qu''''il avait, Mahalath, fille d''''Ismaël, fils d''''Abraham, et soeur de Nebajoth."}, {"numero": 10, "texto": "Jacob partit de Beer-Schéba, et s''''en alla à Charan."}, {"numero": 11, "texto": "Il arriva dans un lieu où il passa la nuit; car le soleil était couché. Il y prit une pierre, dont il fit son chevet, et il se coucha dans ce lieu-là."}, {"numero": 12, "texto": "Il eut un songe. Et voici, une échelle était appuyée sur la terre, et son sommet touchait au ciel. Et voici, les anges de Dieu montaient et descendaient par cette échelle."}, {"numero": 13, "texto": "Et voici, l''''Eternel se tenait au-dessus d''''elle; et il dit: Je suis l''''Eternel, le Dieu d''''Abraham, ton père, et le Dieu d''''Isaac. La terre sur laquelle tu es couché, je la donnerai à toi et à ta postérité."}, {"numero": 14, "texto": "Ta postérité sera comme la poussière de la terre; tu t''''étendras à l''''occident et à l''''orient, au septentrion et au midi; et toutes les familles de la terre seront bénies en toi et en ta postérité."}, {"numero": 15, "texto": "Voici, je suis avec toi, je te garderai partout où tu iras, et je te ramènerai dans ce pays; car je ne t''''abandonnerai point, que je n''''aie exécuté ce que je te dis."}, {"numero": 16, "texto": "Jacob s''''éveilla de son sommeil et il dit: Certainement, l''''Eternel est en ce lieu, et moi, je ne le savais pas!"}, {"numero": 17, "texto": "Il eut peur, et dit: Que ce lieu est redoutable! C''''est ici la maison de Dieu, c''''est ici la porte des cieux!"}, {"numero": 18, "texto": "Et Jacob se leva de bon matin; il prit la pierre dont il avait fait son chevet, il la dressa pour monument, et il versa de l''''huile sur son sommet."}, {"numero": 19, "texto": "Il donna à ce lieu le nom de Béthel; mais la ville s''''appelait auparavant Luz."}, {"numero": 20, "texto": "Jacob fit un voeu, en disant: Si Dieu est avec moi et me garde pendant ce voyage que je fais, s''''il me donne du pain à manger et des habits pour me vêtir,"}, {"numero": 21, "texto": "et si je retourne en paix à la maison de mon père, alors l''''Eternel sera mon Dieu;"}, {"numero": 22, "texto": "cette pierre, que j''''ai dressée pour monument, sera la maison de Dieu; et je te donnerai la dîme de tout ce que tu me donneras."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 28, 'es', '[{"numero": 1, "texto": "ENTONCES Isaac llamó á Jacob, y bendíjolo, y mandóle diciendo: No tomes mujer de las hijas de Canaán."}, {"numero": 2, "texto": "Levántate, ve á Padan-aram, á casa de Bethuel, padre de tu madre, y toma allí mujer de las hijas de Labán, hermano de tu madre."}, {"numero": 3, "texto": "Y el Dios omnipotente te bendiga, y te haga fructificar, y te multiplique, hasta venir á ser congregación de pueblos;"}, {"numero": 4, "texto": "Y te dé la bendición de Abraham, y á tu simiente contigo, para que heredes la tierra de tus peregrinaciones, que Dios dió á Abraham."}, {"numero": 5, "texto": "Así envió Isaac á Jacob, el cual fué á Padan-aram, á Labán, hijo de Bethuel Arameo, hermano de Rebeca, madre de Jacob y de Esaú."}, {"numero": 6, "texto": "Y vió Esaú cómo Isaac había bendecido á Jacob, y le había enviado á Padan-aram, para tomar para sí mujer de allí; y que cuando le bendijo, le había mandado, diciendo: No tomarás mujer de las hijas de Canaán;"}, {"numero": 7, "texto": "Y que Jacob había obedecido á su padre y á su madre, y se había ido á Padan-aram."}, {"numero": 8, "texto": "Vió asimismo Esaú que las hijas de Canaán parecían mal á Isaac su padre;"}, {"numero": 9, "texto": "Y fuése Esaú á Ismael, y tomó para sí por mujer á Mahaleth, hija de Ismael, hijo de Abraham, hermana de Nabaioth, además de sus otras mujeres."}, {"numero": 10, "texto": "Y salió Jacob de Beer-seba, y fué á Harán;"}, {"numero": 11, "texto": "Y encontró con un lugar, y durmió allí, porque ya el sol se había puesto: y tomó de las piedras de aquel paraje y puso á su cabecera, y acostóse en aquel lugar."}, {"numero": 12, "texto": "Y soñó, y he aquí una escala que estaba apoyada en tierra, y su cabeza tocaba en el cielo: y he aquí ángeles de Dios que subían y descendían por ella."}, {"numero": 13, "texto": "Y he aquí, Jehová estaba en lo alto de ella, el cual dijo: Yo soy Jehová, el Dios de Abraham tu padre, y el Dios de Isaac: la tierra en que estás acostado te la daré á ti y á tu simiente."}, {"numero": 14, "texto": "Y será tu simiente como el polvo de la tierra, y te extenderás al occidente, y al oriente, y al aquilón, y al mediodía; y todas las familias de la tierra serán benditas en ti y en tu simiente."}, {"numero": 15, "texto": "Y he aquí, yo soy contigo, y te guardaré por donde quiera que fueres, y te volveré á esta tierra; porque no te dejaré hasta tanto que haya hecho lo que te he dicho."}, {"numero": 16, "texto": "Y despertó Jacob de su sueño, y dijo: Ciertamente Jehová está en este lugar, y yo no lo sabía."}, {"numero": 17, "texto": "Y tuvo miedo, y dijo: ¡Cuán terrible es este lugar! No es otra cosa que casa de Dios, y puerta del cielo."}, {"numero": 18, "texto": "Y levantóse Jacob de mañana, y tomó la piedra que había puesto de cabecera, y alzóla por título, y derramó aceite encima de ella."}, {"numero": 19, "texto": "Y llamó el nombre de aquel lugar Beth-el, bien que Luz era el nombre de la ciudad primero."}, {"numero": 20, "texto": "E hizo Jacob voto, diciendo: Si fuere Dios conmigo, y me guardare en este viaje que voy, y me diere pan para comer y vestido para vestir,"}, {"numero": 21, "texto": "Y si tornare en paz á casa de mi padre, Jehová será mi Dios,"}, {"numero": 22, "texto": "Y esta piedra que he puesto por título, será casa de Dios: y de todo lo que me dieres, el diezmo lo he de apartar para ti."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 29, 'pt', '[{"numero": 1, "texto": "E Jacó seguiu o seu caminho, e foi à terra dos filhos do oriente."}, {"numero": 2, "texto": "E olhou, e viu um poço no campo: e eis três rebanhos de ovelhas que estavam deitados próximo dele; porque daquele poço davam de beber aos gados: e havia uma grande pedra sobre a boca do poço."}, {"numero": 3, "texto": "E juntavam-se ali todos os rebanhos; e revolviam a pedra de sobre a boca do poço, e davam de beber às ovelhas; e voltavam a pedra sobre a boca do poço a seu lugar."}, {"numero": 4, "texto": "E disse-lhes Jacó: Irmãos meus, de onde sois? E eles responderam: De Harã somos."}, {"numero": 5, "texto": "E ele lhes disse: Conheceis a Labão, filho de Naor? E eles disseram: Sim, nós o conhecemos."}, {"numero": 6, "texto": "E ele lhes disse: Ele está bem? E eles disseram: Está bem; e eis que Raquel sua filha vem com o gado."}, {"numero": 7, "texto": "E ele disse: Eis que ainda é cedo do dia; não é hora de recolher o gado; dai de beber às ovelhas, e ide apascentá-las."}, {"numero": 8, "texto": "E eles responderam: Não podemos, até que se juntem todos os gados, e removam a pedra de sobre a boca do poço, para que demos de beber às ovelhas."}, {"numero": 9, "texto": "Estando ainda ele falando com eles Raquel veio com o gado de seu pai, porque ela era a pastora."}, {"numero": 10, "texto": "E sucedeu que, quando Jacó viu Raquel, filha de Labão irmão de sua mãe, e as ovelhas de Labão, o irmão de sua mãe, chegou-se Jacó, e removeu a pedra de sobre a boca do poço, e deu de beber ao gado de Labão irmão de sua mãe."}, {"numero": 11, "texto": "E Jacó beijou a Raquel, e levantou sua voz, e chorou."}, {"numero": 12, "texto": "E Jacó disse a Raquel como ele era irmão de seu pai, e como era filho de Rebeca: e ela correu, e deu as novas a seu pai."}, {"numero": 13, "texto": "E assim que ouviu Labão as novas de Jacó, filho de sua irmã, correu a recebê-lo, e abraçou-o, e beijou-o, e trouxe-lhe à sua casa: e ele contou a Labão todas estas coisas."}, {"numero": 14, "texto": "E Labão lhe disse: Certamente és osso meu e carne minha. E esteve com ele durante um mês."}, {"numero": 15, "texto": "Então disse Labão a Jacó: Por ser tu meu irmão, me hás de servir de graça? Declara-me o que será teu salário."}, {"numero": 16, "texto": "E Labão tinha duas filhas: o nome da mais velha era Lia, e o nome da mais nova, Raquel."}, {"numero": 17, "texto": "E os olhos de Lia eram tenros, mas Raquel era de lindo semblante e de bela aparência."}, {"numero": 18, "texto": "E Jacó amou a Raquel, e disse: Eu te servirei sete anos por Raquel tua filha mais nova."}, {"numero": 19, "texto": "E Labão respondeu: Melhor é que a dê a ti, que não que a dê a outro homem: fica-te comigo."}, {"numero": 20, "texto": "Assim serviu Jacó por Raquel sete anos: e pareceram-lhe como poucos dias, porque a amava."}, {"numero": 21, "texto": "E disse Jacó a Labão: Dá-me minha mulher, porque meu tempo é cumprido para que me deite com ela."}, {"numero": 22, "texto": "Então Labão juntou a todos os homens daquele lugar, e fez banquete."}, {"numero": 23, "texto": "E sucedeu que à noite tomou sua filha Lia, e a trouxe; e ele se deitou com ela."}, {"numero": 24, "texto": "E deu Labão sua serva Zilpa à sua filha Lia por criada."}, {"numero": 25, "texto": "E vinda a manhã, eis que era Lia: e ele disse a Labão: Que é isto que me fizeste? Não te servi por Raquel? Por que, pois, me enganaste?"}, {"numero": 26, "texto": "E Labão respondeu: Não se faz assim em nosso lugar, que se dê a mais nova antes da mais velha."}, {"numero": 27, "texto": "Cumpre a semana desta, e se te dará também a outra, pelo serviço que fizeres comigo por outros sete anos."}, {"numero": 28, "texto": "E fez Jacó assim, e cumpriu a semana daquela; e ele lhe deu a sua filha Raquel por mulher."}, {"numero": 29, "texto": "E deu Labão a Raquel sua filha por criada a sua serva Bila."}, {"numero": 30, "texto": "E deitou-se também com Raquel: e amou-a também mais que a Lia: e serviu a ele ainda outros sete anos."}, {"numero": 31, "texto": "E viu o SENHOR que Lia era mal-amada, e abriu sua madre; mas Raquel era estéril."}, {"numero": 32, "texto": "E concebeu Lia, e deu à luz um filho, e chamou seu nome Rúben, porque disse: Já que olhou o SENHOR minha aflição; agora, portanto, meu marido me amará."}, {"numero": 33, "texto": "E concebeu outra vez, e deu à luz um filho, e disse: Porquanto ouviu o SENHOR que eu era mal-amada, me deu também este. E chamou seu nome Simeão."}, {"numero": 34, "texto": "E concebeu outra vez, e deu à luz um filho, e disse: Agora esta vez meu marido se apegará a mim, porque lhe dei três filhos; portanto, chamou seu nome Levi."}, {"numero": 35, "texto": "E concebeu outra vez, e deu à luz um filho, e disse: Esta vez louvarei ao SENHOR; por isto chamou seu nome Judá; e deixou de dar à luz."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 29, 'en', '[{"numero": 1, "texto": "Then Jacob went on his journey, and came into the land of the people of the east."}, {"numero": 2, "texto": "And he looked, and behold a well in the field, and, lo, there were three flocks of sheep lying by it; for out of that well they watered the flocks: and a great stone was upon the well''s mouth."}, {"numero": 3, "texto": "And thither were all the flocks gathered: and they rolled the stone from the well''s mouth, and watered the sheep, and put the stone again upon the well''s mouth in his place."}, {"numero": 4, "texto": "And Jacob said unto them, My brethren, whence be ye? And they said, Of Haran are we."}, {"numero": 5, "texto": "And he said unto them, Know ye Laban the son of Nahor? And they said, We know him."}, {"numero": 6, "texto": "And he said unto them, Is he well? And they said, He is well: and, behold, Rachel his daughter cometh with the sheep."}, {"numero": 7, "texto": "And he said, Lo, it is yet high day, neither is it time that the cattle should be gathered together: water ye the sheep, and go and feed them."}, {"numero": 8, "texto": "And they said, We cannot, until all the flocks be gathered together, and till they roll the stone from the well''s mouth; then we water the sheep."}, {"numero": 9, "texto": "And while he yet spake with them, Rachel came with her father''s sheep; for she kept them."}, {"numero": 10, "texto": "And it came to pass, when Jacob saw Rachel the daughter of Laban his mother''s brother, and the sheep of Laban his mother''s brother, that Jacob went near, and rolled the stone from the well''s mouth, and watered the flock of Laban his mother''s brother."}, {"numero": 11, "texto": "And Jacob kissed Rachel, and lifted up his voice, and wept."}, {"numero": 12, "texto": "And Jacob told Rachel that he was her father''s brother, and that he was Rebekah''s son: and she ran and told her father."}, {"numero": 13, "texto": "And it came to pass, when Laban heard the tidings of Jacob his sister''s son, that he ran to meet him, and embraced him, and kissed him, and brought him to his house. And he told Laban all these things."}, {"numero": 14, "texto": "And Laban said to him, Surely thou art my bone and my flesh. And he abode with him the space of a month."}, {"numero": 15, "texto": "And Laban said unto Jacob, Because thou art my brother, shouldest thou therefore serve me for nought? tell me, what shall thy wages be?"}, {"numero": 16, "texto": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}, {"numero": 17, "texto": "Leah was tender eyed; but Rachel was beautiful and well favoured."}, {"numero": 18, "texto": "And Jacob loved Rachel; and said, I will serve thee seven years for Rachel thy younger daughter."}, {"numero": 19, "texto": "And Laban said, It is better that I give her to thee, than that I should give her to another man: abide with me."}, {"numero": 20, "texto": "And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her."}, {"numero": 21, "texto": "And Jacob said unto Laban, Give me my wife, for my days are fulfilled, that I may go in unto her."}, {"numero": 22, "texto": "And Laban gathered together all the men of the place, and made a feast."}, {"numero": 23, "texto": "And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her."}, {"numero": 24, "texto": "And Laban gave unto his daughter Leah Zilpah his maid for an handmaid."}, {"numero": 25, "texto": "And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me?"}, {"numero": 26, "texto": "And Laban said, It must not be so done in our country, to give the younger before the firstborn."}, {"numero": 27, "texto": "Fulfil her week, and we will give thee this also for the service which thou shalt serve with me yet seven other years."}, {"numero": 28, "texto": "And Jacob did so, and fulfilled her week: and he gave him Rachel his daughter to wife also."}, {"numero": 29, "texto": "And Laban gave to Rachel his daughter Bilhah his handmaid to be her maid."}, {"numero": 30, "texto": "And he went in also unto Rachel, and he loved also Rachel more than Leah, and served with him yet seven other years."}, {"numero": 31, "texto": "And when the Lord saw that Leah was hated, he opened her womb: but Rachel was barren."}, {"numero": 32, "texto": "And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the Lord hath looked upon my affliction; now therefore my husband will love me."}, {"numero": 33, "texto": "And she conceived again, and bare a son; and said, Because the Lord hath heard I was hated, he hath therefore given me this son also: and she called his name Simeon."}, {"numero": 34, "texto": "And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi."}, {"numero": 35, "texto": "And she conceived again, and bare a son: and she said, Now will I praise the Lord: therefore she called his name Judah; and left bearing."}]'::jsonb, 'King James Version'),
  ('Gn', 29, 'fr', '[{"numero": 1, "texto": "Jacob se mit en marche, et s''''en alla au pays des fils de l''''Orient."}, {"numero": 2, "texto": "Il regarda. Et voici, il y avait un puits dans les champs; et voici, il y avait à côté trois troupeaux de brebis qui se reposaient, car c''''était à ce puits qu''''on abreuvait les troupeaux. Et la pierre sur l''''ouverture du puits était grande."}, {"numero": 3, "texto": "Tous les troupeaux se rassemblaient là; on roulait la pierre de dessus l''''ouverture du puits, on abreuvait les troupeaux, et l''''on remettait la pierre à sa place sur l''''ouverture du puits."}, {"numero": 4, "texto": "Jacob dit aux bergers: Mes frères, d''''où êtes-vous? Ils répondirent: Nous sommes de Charan."}, {"numero": 5, "texto": "Il leur dit: Connaissez-vous Laban, fils de Nachor? Ils répondirent: Nous le connaissons."}, {"numero": 6, "texto": "Il leur dit: Est-il en bonne santé? Ils répondirent: Il est en bonne santé; et voici Rachel, sa fille, qui vient avec le troupeau."}, {"numero": 7, "texto": "Il dit: Voici, il est encore grand jour, et il n''''est pas temps de rassembler les troupeaux; abreuvez les brebis, puis allez, et faites-les paître."}, {"numero": 8, "texto": "Ils répondirent: Nous ne le pouvons pas, jusqu''''à ce que tous les troupeaux soient rassemblés; c''''est alors qu''''on roule la pierre de dessus l''''ouverture du puits, et qu''''on abreuve les brebis."}, {"numero": 9, "texto": "Comme il leur parlait encore, survint Rachel avec le troupeau de son père; car elle était bergère."}, {"numero": 10, "texto": "Lorsque Jacob vit Rachel, fille de Laban, frère de sa mère, et le troupeau de Laban, frère de sa mère, il s''''approcha, roula la pierre de dessus l''''ouverture du puits, et abreuva le troupeau de Laban, frère de sa mère."}, {"numero": 11, "texto": "Et Jacob baisa Rachel, il éleva la voix et pleura."}, {"numero": 12, "texto": "Jacob apprit à Rachel qu''''il était parent de son père, qu''''il était fils de Rebecca. Et elle courut l''''annoncer à son père."}, {"numero": 13, "texto": "Dès que Laban eut entendu parler de Jacob, fils de sa soeur, il courut au-devant de lui, il l''''embrassa et le baisa, et il le fit venir dans sa maison. Jacob raconta à Laban toutes ces choses."}, {"numero": 14, "texto": "Et Laban lui dit: Certainement, tu es mon os et ma chair. Jacob demeura un mois chez Laban."}, {"numero": 15, "texto": "Puis Laban dit à Jacob: Parce que tu es mon parent, me serviras-tu pour rien? Dis-moi quel sera ton salaire."}, {"numero": 16, "texto": "Or, Laban avait deux filles: l''''aînée s''''appelait Léa, et la cadette Rachel."}, {"numero": 17, "texto": "Léa avait les yeux délicats; mais Rachel était belle de taille et belle de figure."}, {"numero": 18, "texto": "Jacob aimait Rachel, et il dit: Je te servirai sept ans pour Rachel, ta fille cadette."}, {"numero": 19, "texto": "Et Laban dit: J''''aime mieux te la donner que de la donner à un autre homme. Reste chez moi!"}, {"numero": 20, "texto": "Ainsi Jacob servit sept années pour Rachel: et elles furent à ses yeux comme quelques jours, parce qu''''il l''''aimait."}, {"numero": 21, "texto": "Ensuite Jacob dit à Laban: Donne-moi ma femme, car mon temps est accompli: et j''''irai vers elle."}, {"numero": 22, "texto": "Laban réunit tous les gens du lieu, et fit un festin."}, {"numero": 23, "texto": "Le soir, il prit Léa, sa fille, et l''''amena vers Jacob, qui s''''approcha d''''elle."}, {"numero": 24, "texto": "Et Laban donna pour servante à Léa, sa fille, Zilpa, sa servante."}, {"numero": 25, "texto": "Le lendemain matin, voilà que c''''était Léa. Alors Jacob dit à Laban: Qu''''est-ce que tu m''''as fait? N''''est-ce pas pour Rachel que j''''ai servi chez toi? Pourquoi m''''as-tu trompé?"}, {"numero": 26, "texto": "Laban dit: Ce n''''est point la coutume dans ce lieu de donner la cadette avant l''''aînée."}, {"numero": 27, "texto": "Achève la semaine avec celle-ci, et nous te donnerons aussi l''''autre pour le service que tu feras encore chez moi pendant sept nouvelles années."}, {"numero": 28, "texto": "Jacob fit ainsi, et il acheva la semaine avec Léa; puis Laban lui donna pour femme Rachel, sa fille."}, {"numero": 29, "texto": "Et Laban donna pour servante à Rachel, sa fille, Bilha, sa servante."}, {"numero": 30, "texto": "Jacob alla aussi vers Rachel, qu''''il aimait plus que Léa; et il servit encore chez Laban pendant sept nouvelles années."}, {"numero": 31, "texto": "L''''Eternel vit que Léa n''''était pas aimée; et il la rendit féconde, tandis que Rachel était stérile."}, {"numero": 32, "texto": "Léa devint enceinte, et enfanta un fils, à qui elle donna le nom de Ruben; car elle dit: L''''Eternel a vu mon humiliation, et maintenant mon mari m''''aimera."}, {"numero": 33, "texto": "Elle devint encore enceinte, et enfanta un fils, et elle dit: L''''Eternel a entendu que je n''''étais pas aimée, et il m''''a aussi accordé celui-ci. Et elle lui donna le nom de Siméon."}, {"numero": 34, "texto": "Elle devint encore enceinte, et enfanta un fils, et elle dit: Pour cette fois, mon mari s''''attachera à moi; car je lui ai enfanté trois fils. C''''est pourquoi on lui donna le nom de Lévi."}, {"numero": 35, "texto": "Elle devint encore enceinte, et enfanta un fils, et elle dit: Cette fois, je louerai l''''Eternel. C''''est pourquoi elle lui donna le nom de Juda. Et elle cessa d''''enfanter."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 29, 'es', '[{"numero": 1, "texto": "Y SIGUIÓ Jacob su camino, y fué á la tierra de los orientales."}, {"numero": 2, "texto": "Y miró, y vió un pozo en el campo: y he aquí tres rebaños de ovejas que yacían cerca de él; porque de aquel pozo abrevaban los ganados: y había una gran piedra sobre la boca del pozo."}, {"numero": 3, "texto": "Y juntábanse allí todos los rebaños; y revolvían la piedra de sobre la boca del pozo, y abrevaban las ovejas; y volvían la piedra sobre la boca del pozo á su lugar."}, {"numero": 4, "texto": "Y díjoles Jacob: Hermanos míos, ¿de dónde sois? Y ellos respondieron: De Harán somos."}, {"numero": 5, "texto": "Y él les dijo: ¿Conocéis á Labán, hijo de Nachôr? Y ellos dijeron: Sí, le conocemos."}, {"numero": 6, "texto": "Y él les dijo: ¿Tiene paz? Y ellos dijeron: Paz; y he aquí Rachêl su hija viene con el ganado."}, {"numero": 7, "texto": "Y él dijo: He aquí el día es aún grande; no es tiempo todavía de recoger el ganado; abrevad las ovejas, é id á apacentarlas."}, {"numero": 8, "texto": "Y ellos respondieron: No podemos, hasta que se junten todos los ganados, y remuevan la piedra de sobre la boca del pozo, para que abrevemos las ovejas."}, {"numero": 9, "texto": "Estando aún él hablando con ellos, Rachêl vino con el ganado de su padre, porque ella era la pastora."}, {"numero": 10, "texto": "Y sucedió que, como Jacob vió á Rachêl, hija de Labán hermano de su madre, y á las ovejas de Labán el hermano de su madre, llegóse Jacob, y removió la piedra de sobre la boca del pozo, y abrevó el ganado de Labán hermano de su madre."}, {"numero": 11, "texto": "Y Jacob besó á Rachêl, y alzó su voz, y lloró."}, {"numero": 12, "texto": "Y Jacob dijo á Rachêl como él era hermano de su padre, y como era hijo de Rebeca: y ella corrió, y dió las nuevas á su padre."}, {"numero": 13, "texto": "Y así que oyó Labán las nuevas de Jacob, hijo de su hermana, corrió á recibirlo, y abrazólo, y besólo, y trájole á su casa: y él contó á Labán todas estas cosas."}, {"numero": 14, "texto": "Y Labán le dijo: Ciertamente hueso mío y carne mía eres. Y estuvo con él el tiempo de un mes."}, {"numero": 15, "texto": "Entonces dijo Labán á Jacob: ¿Por ser tú mi hermano, me has de servir de balde? declárame qué será tu salario."}, {"numero": 16, "texto": "Y Labán tenía dos hijas: el nombre de la mayor era Lea, y el nombre de la menor, Rachêl."}, {"numero": 17, "texto": "Y los ojos de Lea eran tiernos, pero Rachêl era de lindo semblante y de hermoso parecer."}, {"numero": 18, "texto": "Y Jacob amó á Rachêl, y dijo: Yo te serviré siete años por Rachêl tu hija menor."}, {"numero": 19, "texto": "Y Labán respondió: Mejor es que te la dé á ti, que no que la dé á otro hombre: estáte conmigo."}, {"numero": 20, "texto": "Así sirvió Jacob por Rachêl siete años: y pareciéronle como pocos días, porque la amaba."}, {"numero": 21, "texto": "Y dijo Jacob á Labán: Dame mi mujer, porque mi tiempo es cumplido, para que cohabite con ella."}, {"numero": 22, "texto": "Entonces Labán juntó á todos los varones de aquel lugar, é hizo banquete."}, {"numero": 23, "texto": "Y sucedió que á la noche tomó á Lea su hija, y se la trajo: y él entró á ella."}, {"numero": 24, "texto": "Y dió Labán su sierva Zilpa á su hija Lea por criada."}, {"numero": 25, "texto": "Y venida la mañana, he aquí que era Lea: y él dijo á Labán: ¿Qué es esto que me has hecho? ¿no te he servido por Rachêl? ¿por qué, pues, me has engañado?"}, {"numero": 26, "texto": "Y Labán respondió: No se hace así en nuestro lugar, que se dé la menor antes de la mayor."}, {"numero": 27, "texto": "Cumple la semana de ésta, y se te dará también la otra, por el servicio que hicieres conmigo otros siete años."}, {"numero": 28, "texto": "E hizo Jacob así, y cumplió la semana de aquélla: y él le dió á Rachêl su hija por mujer."}, {"numero": 29, "texto": "Y dió Labán á Rachêl su hija por criada á su sierva Bilha."}, {"numero": 30, "texto": "Y entró también á Rachêl: y amóla también más que á Lea: y sirvió con él aún otros siete años."}, {"numero": 31, "texto": "Y vió Jehová que Lea era aborrecida, y abrió su matriz: pero Rachêl era estéril."}, {"numero": 32, "texto": "Y concibió Lea, y parió un hijo, y llamó su nombre Rubén, porque dijo: Ya que ha mirado Jehová mi aflicción; ahora por tanto me amará mi marido."}, {"numero": 33, "texto": "Y concibió otra vez, y parió un hijo, y dijo: Por cuanto oyó Jehová que yo era aborrecida, me ha dado también éste. Y llamó su nombre Simeón."}, {"numero": 34, "texto": "Y concibió otra vez, y parió un hijo, y dijo: Ahora esta vez se unirá mi marido conmigo, porque le he parido tres hijos: por tanto, llamó su nombre Leví."}, {"numero": 35, "texto": "Y concibió otra vez, y parió un hijo, y dijo: Esta vez alabaré á Jehová: por esto llamó su nombre Judá: y dejó de parir."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 31, 'pt', '[{"numero": 1, "texto": "E ouvia ele as palavras dos filhos de Labão que diziam: Jacó tomou tudo o que era de nosso pai; e do que era de nosso pai adquiriu toda esta grandeza."}, {"numero": 2, "texto": "Olhava também Jacó o semblante de Labão, e via que não era para com ele como antes."}, {"numero": 3, "texto": "Também o SENHOR disse a Jacó: Volta-te à terra de teus pais, e à tua parentela; que eu serei contigo."}, {"numero": 4, "texto": "E enviou Jacó, e chamou a Raquel e a Lia ao campo a suas ovelhas,"}, {"numero": 5, "texto": "E disse-lhes: Vejo que o semblante de vosso pai não é para comigo como antes: mas o Deus de meu pai tem sido comigo."}, {"numero": 6, "texto": "E vós sabeis que com todas minhas forças servi a vosso pai:"}, {"numero": 7, "texto": "E vosso pai me enganou, e me mudou o salário dez vezes: mas Deus não lhe permitiu que me fizesse mal."}, {"numero": 8, "texto": "Se ele dizia assim: Os pintados serão teu salário; então todas as ovelhas geravam pintados: e se dizia assim: Os listrados serão teu salário; então todas as ovelhas geravam listrados."}, {"numero": 9, "texto": "Assim tirou Deus o gado de vosso pai, e deu-o a mim."}, {"numero": 10, "texto": "E sucedeu que ao tempo que as ovelhas se aqueciam, levantei eu meus olhos e vi em sonhos, e eis que os machos que cobriam às fêmeas eram listrados, pintados e malhados."}, {"numero": 11, "texto": "E disse-me o anjo de Deus em sonhos: Jacó. E eu disse: Eis-me aqui."}, {"numero": 12, "texto": "E ele disse: Levanta agora teus olhos, e verás todos os machos que cobrem às ovelhas são listrados, pintados e malhados; porque eu vi tudo o que Labão te fez."}, {"numero": 13, "texto": "Eu sou o Deus de Betel, onde tu ungiste a coluna, e onde me fizeste um voto. Levanta-te agora, e sai desta terra, e volta-te à terra de teu nascimento."}, {"numero": 14, "texto": "E respondeu Raquel e Lia, e disseram-lhe: Temos ainda parte ou herança na casa de nosso pai?"}, {"numero": 15, "texto": "Não nos tem já como por estranhas, pois que nos vendeu, e ainda consumiu de todo nosso valor?"}, {"numero": 16, "texto": "Porque toda a riqueza que Deus tirou a nosso pai, nossa é e de nossos filhos: agora, pois, faze tudo o que Deus te disse."}, {"numero": 17, "texto": "Então se levantou Jacó, e subiu seus filhos e suas mulheres sobre os camelos."}, {"numero": 18, "texto": "E pôs em caminho todo seu gado, e todos os seus pertences que havia adquirido, o gado de seu ganho que havia obtido em Padã-Arã, para voltar-se a Isaque seu pai na terra de Canaã."}, {"numero": 19, "texto": "E Labão havia ido tosquiar suas ovelhas; e Raquel furtou os ídolos de seu pai."}, {"numero": 20, "texto": "E enganou Jacó o coração de Labão arameu, em não lhe fazer saber que se fugia."}, {"numero": 21, "texto": "Fugiu, pois, com tudo o que tinha; e levantou-se, e passou o rio, e pôs seu rosto ao monte de Gileade."}, {"numero": 22, "texto": "E foi dito a Labão ao terceiro dia como Jacó havia fugido."}, {"numero": 23, "texto": "Então tomou a seus irmãos consigo, e foi atrás dele caminho de sete dias, e alcançou-lhe no monte de Gileade."}, {"numero": 24, "texto": "E veio Deus a Labão arameu em sonhos aquela noite, e lhe disse: Guarda-te que não fales a Jacó descomedidamente."}, {"numero": 25, "texto": "Alcançou, pois, Labão a Jacó, e este havia fixado sua tenda no monte: e Labão pôs a sua com seus irmãos no monte de Gileade."}, {"numero": 26, "texto": "E disse Labão a Jacó: Que fizeste, que me furtaste o coração, e trouxeste a minhas filhas como prisioneiras de guerra?"}, {"numero": 27, "texto": "Por que te escondeste para fugir, e me furtaste, e não me deste notícia, para que eu te enviasse com alegria e com cantares, com tamborim e harpa?"}, {"numero": 28, "texto": "Que ainda não me deixaste beijar meus filhos e minhas filhas. Agora loucamente fizeste."}, {"numero": 29, "texto": "Poder há em minha mão para fazer-vos mal; mas o Deus de vosso pai me falou de noite dizendo: Guarda-te que não fales a Jacó descomedidamente."}, {"numero": 30, "texto": "E já que te ias, porque tinhas saudade da casa de teu pai, por que me furtaste meus deuses?"}, {"numero": 31, "texto": "E Jacó respondeu, e disse a Labão: Pois tive medo; porque disse, que talvez me tirasse à força tuas filhas."}, {"numero": 32, "texto": "Em quem achares teus deuses, não viva: diante de nossos irmãos reconhece o que eu tiver teu, e leva-o. Jacó não sabia que Raquel havia os furtado."}, {"numero": 33, "texto": "E entrou Labão na tenda de Jacó, e na tenda de Lia, e na tenda das duas servas, e não os achou, e saiu da tenda de Lia, e veio à tenda de Raquel."}, {"numero": 34, "texto": "E tomou Raquel os ídolos, e os pôs em uma albarda de um camelo, e sentou-se sobre eles: e provou Labão toda a tenda e não os achou."}, {"numero": 35, "texto": "E ela disse a seu pai: Não se ire meu senhor, porque não me posso levantar diante de ti; pois estou com o costume das mulheres. E ele buscou, mas não achou os ídolos."}, {"numero": 36, "texto": "Então Jacó se irou, e brigou com Labão; e respondeu Jacó e disse a Labão: Que transgressão é a minha? Qual é meu pecado, que com tanto ardor vieste a me perseguir?"}, {"numero": 37, "texto": "Depois que apalpaste todos os meus móveis, acaso achaste algum dos objetos de tua casa? Põe-o aqui diante de meus irmãos e teus, e julguem entre nós ambos."}, {"numero": 38, "texto": "Estes vinte anos estive contigo; tuas ovelhas e tuas cabras nunca abortaram, nem eu comi carneiro de tuas ovelhas."}, {"numero": 39, "texto": "Nunca te trouxe o arrebatado pelas feras; eu pagava o dano; o furtado tanto de dia como de noite, de minha mão o exigias."}, {"numero": 40, "texto": "De dia me consumia o calor, e de noite a geada, e o sono se fugia de meus olhos."}, {"numero": 41, "texto": "Assim estive vinte anos em tua casa: catorze anos te servi por tuas duas filhas, e seis anos por teu gado; e mudaste meu salário dez vezes."}, {"numero": 42, "texto": "Se o Deus de meu pai, o Deus de Abraão, e o temor de Isaque, não fossem comigo, certamente me enviarias agora vazio; Deus viu minha aflição e o trabalho de minhas mãos, e repreendeu-te de noite."}, {"numero": 43, "texto": "E respondeu Labão, e disse a Jacó: As filhas são filhas minhas, e os filhos, filhos meus são, e as ovelhas são minhas ovelhas, e tudo o que tu vês é meu; e que posso eu fazer hoje a estas minhas filhas, ou a seus filhos que elas geraram?"}, {"numero": 44, "texto": "Vem, pois, agora, façamos aliança eu e tu; e seja em testemunho entre mim e ti."}, {"numero": 45, "texto": "Então Jacó tomou uma pedra, e levantou-a por coluna."}, {"numero": 46, "texto": "E disse Jacó a seus irmãos: Recolhei pedras. E tomaram pedras e fizeram um amontoado; e comeram ali sobre aquele amontoado."}, {"numero": 47, "texto": "E Labão o chamou Jegar-Saaduta; e Jacó o chamou Galeede."}, {"numero": 48, "texto": "Porque Labão disse: Este amontoado é testemunha hoje entre mim e entre ti; por isso foi chamado seu nome Galeede."}, {"numero": 49, "texto": "E Mispá, porquanto disse: Vigie o SENHOR entre mim e entre ti, quando nos separarmos um do outro."}, {"numero": 50, "texto": "Se afligires minhas filhas, ou se tomares outras mulheres além de minhas filhas, ninguém está conosco; olha, Deus é testemunha entre mim e ti."}, {"numero": 51, "texto": "Disse mais Labão a Jacó: Eis que este amontoado, e eis que esta coluna, que erigi entre mim e ti."}, {"numero": 52, "texto": "Testemunha seja este amontoado, e testemunha seja esta coluna, que nem eu passarei contra ti este amontoado, nem tu passarás contra mim este amontoado nem esta coluna, para o mal."}, {"numero": 53, "texto": "O Deus de Abraão, e o Deus de Naor julgue entre nós, o Deus de seus pais. E Jacó jurou pelo temor de Isaque seu pai."}, {"numero": 54, "texto": "Então Jacó ofereceu sacrifícios no monte, e chamou seus parentes para comer pão; e comeram pão, e dormiram aquela noite no monte."}, {"numero": 55, "texto": "E levantou-se Labão de manhã, beijou seus filhos e suas filhas, e os abençoou; e retrocedeu e voltou a seu lugar."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 31, 'en', '[{"numero": 1, "texto": "And he heard the words of Laban''s sons, saying, Jacob hath taken away all that was our father''s; and of that which was our father''s hath he gotten all this glory."}, {"numero": 2, "texto": "And Jacob beheld the countenance of Laban, and, behold, it was not toward him as before."}, {"numero": 3, "texto": "And the Lord said unto Jacob, Return unto the land of thy fathers, and to thy kindred; and I will be with thee."}, {"numero": 4, "texto": "And Jacob sent and called Rachel and Leah to the field unto his flock,"}, {"numero": 5, "texto": "And said unto them, I see your father''s countenance, that it is not toward me as before; but the God of my father hath been with me."}, {"numero": 6, "texto": "And ye know that with all my power I have served your father."}, {"numero": 7, "texto": "And your father hath deceived me, and changed my wages ten times; but God suffered him not to hurt me."}, {"numero": 8, "texto": "If he said thus, The speckled shall be thy wages; then all the cattle bare speckled: and if he said thus, The ringstraked shall be thy hire; then bare all the cattle ringstraked."}, {"numero": 9, "texto": "Thus God hath taken away the cattle of your father, and given them to me."}, {"numero": 10, "texto": "And it came to pass at the time that the cattle conceived, that I lifted up mine eyes, and saw in a dream, and, behold, the rams which leaped upon the cattle were ringstraked, speckled, and grisled."}, {"numero": 11, "texto": "And the angel of God spake unto me in a dream, saying, Jacob: And I said, Here am I."}, {"numero": 12, "texto": "And he said, Lift up now thine eyes, and see, all the rams which leap upon the cattle are ringstraked, speckled, and grisled: for I have seen all that Laban doeth unto thee."}, {"numero": 13, "texto": "I am the God of Bethel, where thou anointedst the pillar, and where thou vowedst a vow unto me: now arise, get thee out from this land, and return unto the land of thy kindred."}, {"numero": 14, "texto": "And Rachel and Leah answered and said unto him, Is there yet any portion or inheritance for us in our father''s house?"}, {"numero": 15, "texto": "Are we not counted of him strangers? for he hath sold us, and hath quite devoured also our money."}, {"numero": 16, "texto": "For all the riches which God hath taken from our father, that is ours, and our children''s: now then, whatsoever God hath said unto thee, do."}, {"numero": 17, "texto": "Then Jacob rose up, and set his sons and his wives upon camels;"}, {"numero": 18, "texto": "And he carried away all his cattle, and all his goods which he had gotten, the cattle of his getting, which he had gotten in Padanaram, for to go to Isaac his father in the land of Canaan."}, {"numero": 19, "texto": "And Laban went to shear his sheep: and Rachel had stolen the images that were her father''s."}, {"numero": 20, "texto": "And Jacob stole away unawares to Laban the Syrian, in that he told him not that he fled."}, {"numero": 21, "texto": "So he fled with all that he had; and he rose up, and passed over the river, and set his face toward the mount Gilead."}, {"numero": 22, "texto": "And it was told Laban on the third day that Jacob was fled."}, {"numero": 23, "texto": "And he took his brethren with him, and pursued after him seven days'' journey; and they overtook him in the mount Gilead."}, {"numero": 24, "texto": "And God came to Laban the Syrian in a dream by night, and said unto him, Take heed that thou speak not to Jacob either good or bad."}, {"numero": 25, "texto": "Then Laban overtook Jacob. Now Jacob had pitched his tent in the mount: and Laban with his brethren pitched in the mount of Gilead."}, {"numero": 26, "texto": "And Laban said to Jacob, What hast thou done, that thou hast stolen away unawares to me, and carried away my daughters, as captives taken with the sword?"}, {"numero": 27, "texto": "Wherefore didst thou flee away secretly, and steal away from me; and didst not tell me, that I might have sent thee away with mirth, and with songs, with tabret, and with harp?"}, {"numero": 28, "texto": "And hast not suffered me to kiss my sons and my daughters? thou hast now done foolishly in so doing."}, {"numero": 29, "texto": "It is in the power of my hand to do you hurt: but the God of your father spake unto me yesternight, saying, Take thou heed that thou speak not to Jacob either good or bad."}, {"numero": 30, "texto": "And now, though thou wouldest needs be gone, because thou sore longedst after thy father''s house, yet wherefore hast thou stolen my gods?"}, {"numero": 31, "texto": "And Jacob answered and said to Laban, Because I was afraid: for I said, Peradventure thou wouldest take by force thy daughters from me."}, {"numero": 32, "texto": "With whomsoever thou findest thy gods, let him not live: before our brethren discern thou what is thine with me, and take it to thee. For Jacob knew not that Rachel had stolen them."}, {"numero": 33, "texto": "And Laban went into Jacob''s tent, and into Leah''s tent, and into the two maidservants'' tents; but he found them not. Then went he out of Leah''s tent, and entered into Rachel''s tent."}, {"numero": 34, "texto": "Now Rachel had taken the images, and put them in the camel''s furniture, and sat upon them. And Laban searched all the tent, but found them not."}, {"numero": 35, "texto": "And she said to her father, Let it not displease my lord that I cannot rise up before thee; for the custom of women is upon me. And he searched but found not the images."}, {"numero": 36, "texto": "And Jacob was wroth, and chode with Laban: and Jacob answered and said to Laban, What is my trespass? what is my sin, that thou hast so hotly pursued after me?"}, {"numero": 37, "texto": "Whereas thou hast searched all my stuff, what hast thou found of all thy household stuff? set it here before my brethren and thy brethren, that they may judge betwixt us both."}, {"numero": 38, "texto": "This twenty years have I been with thee; thy ewes and thy she goats have not cast their young, and the rams of thy flock have I not eaten."}, {"numero": 39, "texto": "That which was torn of beasts I brought not unto thee; I bare the loss of it; of my hand didst thou require it, whether stolen by day, or stolen by night."}, {"numero": 40, "texto": "Thus I was; in the day the drought consumed me, and the frost by night; and my sleep departed from mine eyes."}, {"numero": 41, "texto": "Thus have I been twenty years in thy house; I served thee fourteen years for thy two daughters, and six years for thy cattle: and thou hast changed my wages ten times."}, {"numero": 42, "texto": "Except the God of my father, the God of Abraham, and the fear of Isaac, had been with me, surely thou hadst sent me away now empty. God hath seen mine affliction and the labour of my hands, and rebuked thee yesternight."}, {"numero": 43, "texto": "And Laban answered and said unto Jacob, These daughters are my daughters, and these children are my children, and these cattle are my cattle, and all that thou seest is mine: and what can I do this day unto these my daughters, or unto their children which they have born?"}, {"numero": 44, "texto": "Now therefore come thou, let us make a covenant, I and thou; and let it be for a witness between me and thee."}, {"numero": 45, "texto": "And Jacob took a stone, and set it up for a pillar."}, {"numero": 46, "texto": "And Jacob said unto his brethren, Gather stones; and they took stones, and made an heap: and they did eat there upon the heap."}, {"numero": 47, "texto": "And Laban called it Jegarsahadutha: but Jacob called it Galeed."}, {"numero": 48, "texto": "And Laban said, This heap is a witness between me and thee this day. Therefore was the name of it called Galeed;"}, {"numero": 49, "texto": "And Mizpah; for he said, The Lord watch between me and thee, when we are absent one from another."}, {"numero": 50, "texto": "If thou shalt afflict my daughters, or if thou shalt take other wives beside my daughters, no man is with us; see, God is witness betwixt me and thee."}, {"numero": 51, "texto": "And Laban said to Jacob, Behold this heap, and behold this pillar, which I have cast betwixt me and thee:"}, {"numero": 52, "texto": "This heap be witness, and this pillar be witness, that I will not pass over this heap to thee, and that thou shalt not pass over this heap and this pillar unto me, for harm."}, {"numero": 53, "texto": "The God of Abraham, and the God of Nahor, the God of their father, judge betwixt us. And Jacob sware by the fear of his father Isaac."}, {"numero": 54, "texto": "Then Jacob offered sacrifice upon the mount, and called his brethren to eat bread: and they did eat bread, and tarried all night in the mount."}, {"numero": 55, "texto": "And early in the morning Laban rose up, and kissed his sons and his daughters, and blessed them: and Laban departed, and returned unto his place."}]'::jsonb, 'King James Version'),
  ('Gn', 31, 'fr', '[{"numero": 1, "texto": "Jacob entendit les propos des fils de Laban, qui disaient: Jacob a pris tout ce qui était à notre père, et c''''est avec le bien de notre père qu''''il s''''est acquis toute cette richesse."}, {"numero": 2, "texto": "Jacob remarqua aussi le visage de Laban; et voici, il n''''était plus envers lui comme auparavant."}, {"numero": 3, "texto": "Alors l''''Eternel dit à Jacob: Retourne au pays de tes pères et dans ton lieu de naissance, et je serai avec toi."}, {"numero": 4, "texto": "Jacob fit appeler Rachel et Léa, qui étaient aux champs vers son troupeau."}, {"numero": 5, "texto": "Il leur dit: Je vois, au visage de votre père, qu''''il n''''est plus envers moi comme auparavant; mais le Dieu de mon père a été avec moi."}, {"numero": 6, "texto": "Vous savez vous-mêmes que j''''ai servi votre père de tout mon pouvoir."}, {"numero": 7, "texto": "Et votre père s''''est joué de moi, et a changé dix fois mon salaire; mais Dieu ne lui a pas permis de me faire du mal."}, {"numero": 8, "texto": "Quand il disait: Les tachetées seront ton salaire, toutes les brebis faisaient des petits tachetés. Et quand il disait: Les rayées seront ton salaire, toutes les brebis faisaient des petits rayés."}, {"numero": 9, "texto": "Dieu a pris à votre père son troupeau, et me l''''a donné."}, {"numero": 10, "texto": "Au temps où les brebis entraient en chaleur, je levai les yeux, et je vis en songe que les boucs qui couvraient les brebis étaient rayés, tachetés et marquetés."}, {"numero": 11, "texto": "Et l''''ange de Dieu me dit en songe: Jacob! Je répondis: Me voici!"}, {"numero": 12, "texto": "Il dit: Lève les yeux, et regarde: tous les boucs qui couvrent les brebis sont rayés, tachetés et marquetés; car j''''ai vu tout ce que te fait Laban."}, {"numero": 13, "texto": "Je suis le Dieu de Béthel, où tu as oint un monument, où tu m''''as fait un voeu. Maintenant, lève-toi, sors de ce pays, et retourne au pays de ta naissance."}, {"numero": 14, "texto": "Rachel et Léa répondirent, et lui dirent: Avons-nous encore une part et un héritage dans la maison de notre père?"}, {"numero": 15, "texto": "Ne sommes-nous pas regardées par lui comme des étrangères, puisqu''''il nous a vendues, et qu''''il a mangé notre argent?"}, {"numero": 16, "texto": "Toute la richesse que Dieu a ôtée à notre père appartient à nous et à nos enfants. Fais maintenant tout ce que Dieu t''''a dit."}, {"numero": 17, "texto": "Jacob se leva, et il fit monter ses enfants et ses femmes sur les chameaux."}, {"numero": 18, "texto": "Il emmena tout son troupeau et tous les biens qu''''il possédait, le troupeau qui lui appartenait, qu''''il avait acquis à Paddan-Aram; et il s''''en alla vers Isaac, son père, au pays de Canaan."}, {"numero": 19, "texto": "Tandis que Laban était allé tondre ses brebis, Rachel déroba les théraphim de son père;"}, {"numero": 20, "texto": "et Jacob trompa Laban, l''''Araméen, en ne l''''avertissant pas de sa fuite."}, {"numero": 21, "texto": "Il s''''enfuit, avec tout ce qui lui appartenait; il se leva, traversa le fleuve, et se dirigea vers la montagne de Galaad."}, {"numero": 22, "texto": "Le troisième jour, on annonça à Laban que Jacob s''''était enfui."}, {"numero": 23, "texto": "Il prit avec lui ses frères, le poursuivit sept journées de marche, et l''''atteignit à la montagne de Galaad."}, {"numero": 24, "texto": "Mais Dieu apparut la nuit en songe à Laban, l''''Araméen, et lui dit: Garde-toi de parler à Jacob ni en bien ni en mal!"}, {"numero": 25, "texto": "Laban atteignit donc Jacob. Jacob avait dressé sa tente sur la montagne; Laban dressa aussi la sienne, avec ses frères, sur la montagne de Galaad."}, {"numero": 26, "texto": "Alors Laban dit à Jacob: Qu''''as-tu fait? Pourquoi m''''as-tu trompé, et emmènes-tu mes filles comme des captives par l''''épée?"}, {"numero": 27, "texto": "Pourquoi as-tu pris la fuite en cachette, m''''as-tu trompé, et ne m''''as-tu point averti? Je t''''aurais laissé partir au milieu des réjouissances et des chants, au son du tambourin et de la harpe."}, {"numero": 28, "texto": "Tu ne m''''as pas permis d''''embrasser mes fils et mes filles! C''''est en insensé que tu as agi."}, {"numero": 29, "texto": "Ma main est assez forte pour vous faire du mal; mais le Dieu de votre père m''''a dit hier: Garde-toi de parler à Jacob ni en bien ni en mal!"}, {"numero": 30, "texto": "Maintenant que tu es parti, parce que tu languissais après la maison de ton père, pourquoi as-tu dérobé mes dieux?"}, {"numero": 31, "texto": "Jacob répondit, et dit à Laban: J''''avais de la crainte à la pensée que tu m''''enlèverais peut-être tes filles."}, {"numero": 32, "texto": "Mais périsse celui auprès duquel tu trouveras tes dieux! En présence de nos frères, examine ce qui t''''appartient chez moi, et prends-le. Jacob ne savait pas que Rachel les eût dérobés."}, {"numero": 33, "texto": "Laban entra dans la tente de Jacob, dans la tente de Léa, dans la tente des deux servantes, et il ne trouva rien. Il sortit de la tente de Léa, et entra dans la tente de Rachel."}, {"numero": 34, "texto": "Rachel avait pris les théraphim, les avait mis sous le bât du chameau, et s''''était assise dessus. Laban fouilla toute la tente, et ne trouva rien."}, {"numero": 35, "texto": "Elle dit à son père: Que mon seigneur ne se fâche point, si je ne puis me lever devant toi, car j''''ai ce qui est ordinaire aux femmes. Il chercha, et ne trouva point les théraphim."}, {"numero": 36, "texto": "Jacob s''''irrita, et querella Laban. Il reprit la parole, et lui dit: Quel est mon crime, quel est mon péché, que tu me poursuives avec tant d''''ardeur?"}, {"numero": 37, "texto": "Quand tu as fouillé tous mes effets, qu''''as-tu trouvé des effets de ta maison? Produis-le ici devant mes frères et tes frères, et qu''''ils prononcent entre nous deux."}, {"numero": 38, "texto": "Voilà vingt ans que j''''ai passés chez toi; tes brebis et tes chèvres n''''ont point avorté, et je n''''ai point mangé les béliers de ton troupeau."}, {"numero": 39, "texto": "Je ne t''''ai point rapporté de bêtes déchirées, j''''en ai payé le dommage; tu me redemandais ce qu''''on me volait de jour et ce qu''''on me volait de nuit."}, {"numero": 40, "texto": "La chaleur me dévorait pendant le jour, et le froid pendant la nuit, et le sommeil fuyait de mes yeux."}, {"numero": 41, "texto": "Voilà vingt ans que j''''ai passés dans ta maison; je t''''ai servi quatorze ans pour tes deux filles, et six ans pour ton troupeau, et tu as changé dix fois mon salaire."}, {"numero": 42, "texto": "Si je n''''eusse pas eu pour moi le Dieu de mon père, le Dieu d''''Abraham, celui que craint Isaac, tu m''''aurais maintenant renvoyé à vide. Dieu a vu ma souffrance et le travail de mes mains, et hier il a prononcé son jugement."}, {"numero": 43, "texto": "Laban répondit, et dit à Jacob: Ces filles sont mes filles, ces enfants sont mes enfants, ce troupeau est mon troupeau, et tout ce que tu vois est à moi. Et que puis-je faire aujourd''''hui pour mes filles, ou pour leurs enfants qu''''elles ont mis au monde?"}, {"numero": 44, "texto": "Viens, faisons alliance, moi et toi, et que cela serve de témoignage entre moi et toi!"}, {"numero": 45, "texto": "Jacob prit une pierre, et il la dressa pour monument."}, {"numero": 46, "texto": "Jacob dit à ses frères: Ramassez des pierres. Ils prirent des pierres, et firent un monceau; et ils mangèrent là sur le monceau."}, {"numero": 47, "texto": "Laban l''''appela Jegar-Sahadutha, et Jacob l''''appela Galed."}, {"numero": 48, "texto": "Laban dit: Que ce monceau serve aujourd''''hui de témoignage entre moi et toi! C''''est pourquoi on lui a donné le nom de Galed."}, {"numero": 49, "texto": "On l''''appelle aussi Mitspa, parce que Laban dit: Que l''''Eternel veille sur toi et sur moi, quand nous nous serons l''''un et l''''autre perdus de vue."}, {"numero": 50, "texto": "Si tu maltraites mes filles, et si tu prends encore d''''autres femmes, ce n''''est pas un homme qui sera avec nous, prends-y garde, c''''est Dieu qui sera témoin entre moi et toi."}, {"numero": 51, "texto": "Laban dit à Jacob: Voici ce monceau, et voici ce monument que j''''ai élevé entre moi et toi."}, {"numero": 52, "texto": "Que ce monceau soit témoin et que ce monument soit témoin que je n''''irai point vers toi au delà de ce monceau, et que tu ne viendras point vers moi au delà de ce monceau et de ce monument, pour agir méchamment."}, {"numero": 53, "texto": "Que le Dieu d''''Abraham et de Nachor, que le Dieu de leur père soit juge entre nous. Jacob jura par celui que craignait Isaac."}, {"numero": 54, "texto": "Jacob offrit un sacrifice sur la montagne, et il invita ses frères à manger; ils mangèrent donc, et passèrent la nuit sur la montagne."}, {"numero": 55, "texto": "Laban se leva de bon matin, baisa ses fils et ses filles, et les bénit. Ensuite il partit pour retourner dans sa demeure."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 31, 'es', '[{"numero": 1, "texto": "Y OÍA él las palabras de los hijos de Labán, que decían: Jacob ha tomado todo lo que era de nuestro padre; y de lo que era de nuestro padre ha adquirido toda esta grandeza."}, {"numero": 2, "texto": "Miraba también Jacob el semblante de Labán, y veía que no era para con él como ayer y antes de ayer."}, {"numero": 3, "texto": "También Jehová dijo á Jacob: Vuélvete á la tierra de tus padres, y á tu parentela; que yo seré contigo."}, {"numero": 4, "texto": "Y envió Jacob, y llamó á Rachêl y á Lea al campo á sus ovejas,"}, {"numero": 5, "texto": "Y díjoles: Veo que el semblante de vuestro padre no es para conmigo como ayer y antes de ayer: mas el Dios de mi padre ha sido conmigo."}, {"numero": 6, "texto": "Y vosotras sabéis que con todas mis fuerzas he servido á vuestro padre:"}, {"numero": 7, "texto": "Y vuestro padre me ha engañado, y me ha mudado el salario diez veces: pero Dios no le ha permitido que me hiciese mal."}, {"numero": 8, "texto": "Si él decía así: Los pintados serán tu salario; entonces todas las ovejas parían pintados: y si decía así: Los listados serán tu salario; entonces todas las ovejas parían listados."}, {"numero": 9, "texto": "Así quitó Dios el ganado de vuestro padre, y diómelo á mí."}, {"numero": 10, "texto": "Y sucedió que al tiempo que las ovejas se recalentaban, alcé yo mis ojos y vi en sueños, y he aquí los machos que cubrían á las hembras eran listados, pintados y abigarrados."}, {"numero": 11, "texto": "Y díjome el ángel de Dios en sueños: Jacob. Y yo dije: Heme aquí."}, {"numero": 12, "texto": "Y él dijo: Alza ahora tus ojos, y verás todos los machos que cubren á las ovejas listados, pintados y abigarrados; porque yo he visto todo lo que Labán te ha hecho."}, {"numero": 13, "texto": "Yo soy el Dios de Beth-el, donde tú ungiste el título, y donde me hiciste un voto. Levántate ahora, y sal de esta tierra, y vuélvete á la tierra de tu naturaleza."}, {"numero": 14, "texto": "Y respondió Rachêl y Lea, y dijéronle: ¿Tenemos ya parte ni heredad en la casa de nuestro padre?"}, {"numero": 15, "texto": "¿No nos tiene ya como por extrañas, pues que nos vendió, y aun se ha comido del todo nuestro precio?"}, {"numero": 16, "texto": "Porque toda la riqueza que Dios ha quitado á nuestro padre, nuestra es y de nuestros hijos: ahora pues, haz todo lo que Dios te ha dicho."}, {"numero": 17, "texto": "Entonces se levantó Jacob, y subió sus hijos y sus mujeres sobre los camellos."}, {"numero": 18, "texto": "Y puso en camino todo su ganado, y toda su hacienda que había adquirido, el ganado de su ganancia que había obtenido en Padan-aram, para volverse á Isaac su padre en la tierra de Canaán."}, {"numero": 19, "texto": "Y Labán había ido á trasquilar sus ovejas: y Rachêl hurtó los ídolos de su padre."}, {"numero": 20, "texto": "Y recató Jacob el corazón de Labán Arameo, en no hacerle saber que se huía."}, {"numero": 21, "texto": "Huyó, pues, con todo lo que tenía; y levantóse, y pasó el río, y puso su rostro al monte de Galaad."}, {"numero": 22, "texto": "Y fué dicho á Labán al tercero día como Jacob se había huído."}, {"numero": 23, "texto": "Entonces tomó á sus hermanos consigo, y fué tras él camino de siete días, y alcanzóle en el monte de Galaad."}, {"numero": 24, "texto": "Y vino Dios á Labán Arameo en sueños aquella noche, y le dijo: Guárdate que no hables á Jacob descomedidamente."}, {"numero": 25, "texto": "Alcanzó pues Labán á Jacob, y éste había fijado su tienda en el monte: y Labán plantóla con sus hermanos en el monte de Galaad."}, {"numero": 26, "texto": "Y dijo Labán á Jacob: ¿Qué has hecho, que me hurtaste el corazón, y has traído á mis hijas como prisioneras de guerra?"}, {"numero": 27, "texto": "¿Por qué te escondiste para huir, y me hurtaste, y no me diste noticia, para que yo te enviara con alegría y con cantares, con tamborín y vihuela?"}, {"numero": 28, "texto": "Que aun no me dejaste besar mis hijos y mis hijas. Ahora locamente has hecho."}, {"numero": 29, "texto": "Poder hay en mi mano para haceros mal: mas el Dios de vuestro padre me habló anoche diciendo: Guárdate que no hables á Jacob descomedidamente."}, {"numero": 30, "texto": "Y ya que te ibas, porque tenías deseo de la casa de tu padre, ¿por qué me hurtaste mis dioses?"}, {"numero": 31, "texto": "Y Jacob respondió, y dijo á Labán: Porque tuve miedo; pues dije, que quizá me quitarías por fuerza tus hijas."}, {"numero": 32, "texto": "En quien hallares tus dioses, no viva: delante de nuestros hermanos reconoce lo que yo tuviere tuyo, y llévatelo. Jacob no sabía que Rachêl los había hurtado."}, {"numero": 33, "texto": "Y entró Labán en la tienda de Jacob, y en la tienda de Lea, y en la tienda de las dos siervas, y no los halló, y salió de la tienda de Lea, y vino á la tienda de Rachêl."}, {"numero": 34, "texto": "Y tomó Rachêl los ídolos, y púsolos en una albarda de un camello, y sentóse sobre ellos: y tentó Labán toda la tienda, y no los halló."}, {"numero": 35, "texto": "Y ella dijo á su padre: No se enoje mi señor, porque no me puedo levantar delante de ti; pues estoy con la costumbre de las mujeres. Y él buscó, pero no halló los ídolos."}, {"numero": 36, "texto": "Entonces Jacob se enojó, y regañó con Labán; y respondió Jacob y dijo á Labán: ¿Qué prevaricación es la mía? ¿cuál es mi pecado, que con tanto ardor has venido en seguimiento mío?"}, {"numero": 37, "texto": "Pues que has tentado todos mis muebles, ¿qué has hallado de todas las alhajas de tu casa? Ponlo aquí delante de mis hermanos y tuyos, y juzguen entre nosotros ambos."}, {"numero": 38, "texto": "Estos veinte años he estado contigo: tus ovejas y tus cabras nunca abortaron, ni yo comí carnero de tus ovejas."}, {"numero": 39, "texto": "Nunca te traje lo arrebatado por las fieras; yo pagaba el daño; lo hurtado así de día como de noche, de mi mano lo requerías."}, {"numero": 40, "texto": "De día me consumía el calor, y de noche la helada, y el sueño se huía de mis ojos."}, {"numero": 41, "texto": "Así he estado veinte años en tu casa: catorce años te serví por tus dos hijas, y seis años por tu ganado; y has mudado mi salario diez veces."}, {"numero": 42, "texto": "Si el Dios de mi padre, el Dios de Abraham, y el temor de Isaac, no fuera conmigo, de cierto me enviarías ahora vacío: vió Dios mi aflicción y el trabajo de mis manos, y reprendióte anoche."}, {"numero": 43, "texto": "Y respondió Labán, y dijo á Jacob: Las hijas son hijas mías, y los hijos, hijos míos son, y las ovejas son mis ovejas, y todo lo que tú ves es mío: ¿y qué puedo yo hacer hoy á estas mis hijas, ó á sus hijos que ellas han parido?"}, {"numero": 44, "texto": "Ven pues ahora, y hagamos alianza yo y tú; y sea en testimonio entre mí y entre ti."}, {"numero": 45, "texto": "Entonces Jacob tomó una piedra, y levantóla por título."}, {"numero": 46, "texto": "Y dijo Jacob á sus hermanos: Coged piedras. Y tomaron piedras é hicieron un majano; y comieron allí sobre aquel majano."}, {"numero": 47, "texto": "Y llamólo Labán Jegar Sahadutha: y lo llamó Jacob Galaad."}, {"numero": 48, "texto": "Porque Labán dijo: Este majano es testigo hoy entre mí y entre ti; por eso fué llamado su nombre Galaad;"}, {"numero": 49, "texto": "Y Mizpa, por cuanto dijo: Atalaye Jehová entre mí y entre ti, cuando nos apartáremos el uno del otro."}, {"numero": 50, "texto": "Si afligieres mis hijas, ó si tomares otras mujeres además de mis hijas, nadie está con nosotros; mira, Dios es testigo entre mí y entre ti."}, {"numero": 51, "texto": "Dijo más Labán á Jacob: He aquí este majano, y he aquí este título, que he erigido entre mí y ti."}, {"numero": 52, "texto": "Testigo sea este majano, y testigo sea este título, que ni yo pasaré contra ti este majano, ni tú pasarás contra mí este majano ni este título, para mal."}, {"numero": 53, "texto": "El Dios de Abraham, y el Dios de Nachôr juzgue entre nosotros, el Dios de sus padres. Y Jacob juró por el temor de Isaac su padre."}, {"numero": 54, "texto": "Entonces Jacob inmoló víctimas en el monte, y llamó á sus hermanos á comer pan: y comieron pan, y durmieron aquella noche en el monte."}, {"numero": 55, "texto": "Y levantóse Labán de mañana, y besó sus hijos y sus hijas, y los bendijo; y retrocedió y volvióse á su lugar."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 32, 'pt', '[{"numero": 1, "texto": "E Jacó se foi seu caminho, e saíram-lhe ao encontro anjos de Deus."}, {"numero": 2, "texto": "E disse Jacó quando os viu: Este é o acampamento de Deus; e chamou o nome daquele lugar Maanaim."}, {"numero": 3, "texto": "E enviou Jacó mensageiros diante de si a Esaú seu irmão, à terra de Seir, campo de Edom."}, {"numero": 4, "texto": "E mandou-lhes dizendo: Assim direis a mim senhor Esaú: Assim diz teu servo Jacó: Com Labão morei, e detive-me até agora;"}, {"numero": 5, "texto": "E tenho vacas, e asnos, e ovelhas, e servos, e servas; e envio a dizê-lo a meu senhor, para achar favor em teus olhos."}, {"numero": 6, "texto": "E os mensageiros voltaram a Jacó, dizendo: Viemos a teu irmão Esaú, e ele também veio a receber-te, e quatrocentos homens com ele."}, {"numero": 7, "texto": "Então Jacó teve grande temor, e angustiou-se; e partiu o povo que tinha consigo, e as ovelhas e as vacas e os camelos, em dois grupos;"}, {"numero": 8, "texto": "E disse: Se vier Esaú a um grupo e o ferir, o outro grupo escapará."}, {"numero": 9, "texto": "E disse Jacó: Deus de meu pai Abraão, e Deus de meu pai Isaque, o SENHOR, que me disseste: Volta-te à tua terra e à tua parentela, e eu te farei bem."}, {"numero": 10, "texto": "Menor sou que todas as misericórdias, e que toda a verdade que usaste para com teu servo; que com meu bordão passei este Jordão, e agora estou sobre dois grupos."}, {"numero": 11, "texto": "Livra-me agora da mão de meu irmão, da mão de Esaú, porque o temo; não venha talvez, e me fira a mãe com os filhos."}, {"numero": 12, "texto": "E tu disseste: Eu te farei bem, e tornarei tua descendência como a areia do mar, que não se pode contar de tão numerosa."}, {"numero": 13, "texto": "E dormiu ali aquela noite, e tomou do que lhe veio à mão um presente para seu irmão Esaú."}, {"numero": 14, "texto": "Duzentas cabras e vinte machos de bode, duzentas ovelhas e vinte carneiros,"}, {"numero": 15, "texto": "Trinta camelas de cria, com seus filhotes, quarenta vacas e dez novilhos, vinte asnas e dez jumentos."}, {"numero": 16, "texto": "E entregou-o em mão de seus servos, cada manada à parte; e disse a seus servos: Passai diante de mim, e ponde espaço entre manada e manada."}, {"numero": 17, "texto": "E mandou ao primeiro, dizendo: Se meu irmão Esaú te encontrar, e te perguntar, dizendo De quem és? E: Para onde vais? E: para quem é isto que levas diante de ti?"}, {"numero": 18, "texto": "Então dirás: Presente é de teu servo Jacó, que envia a meu senhor Esaú; e eis que também ele vem atrás de nós."}, {"numero": 19, "texto": "E mandou também ao segundo, e ao terceiro, e a todos os que iam atrás aquelas manadas, dizendo: Conforme isto falareis a Esaú, quando o achardes."}, {"numero": 20, "texto": "E direis também: Eis que teu servo Jacó vem atrás de nós. Porque disse: Apaziguarei sua ira com o presente que vai adiante de mim, e depois verei seu rosto; talvez lhe serei aceito."}, {"numero": 21, "texto": "E passou o presente adiante dele; e ele dormiu aquela noite no acampamento."}, {"numero": 22, "texto": "E levantou-se aquela noite, e tomou suas duas mulheres, e suas duas servas, e seus onze filhos, e passou o vau de Jaboque."}, {"numero": 23, "texto": "Tomou-os, pois, e passou-os o ribeiro, e fez passar o que tinha."}, {"numero": 24, "texto": "E ficou Jacó sozinho, e lutou com ele um homem até que raiava a alva."}, {"numero": 25, "texto": "E quando viu que não podia com ele, tocou no lugar da juntura de sua coxa, e desconjuntou-se a coxa de Jacó enquanto com ele lutava."}, {"numero": 26, "texto": "E disse: Deixa-me, que raia a alva. E ele disse: Não te deixarei, se não me abençoares."}, {"numero": 27, "texto": "E ele lhe disse: Qual é teu nome? E ele respondeu: Jacó."}, {"numero": 28, "texto": "E ele disse: Não se dirá mais teu nome Jacó, mas sim Israel: porque lutaste com Deus e com os homens, e venceste."}, {"numero": 29, "texto": "Então Jacó lhe perguntou, e disse: Declara-me agora teu nome. E ele respondeu: Por que perguntas por meu nome? E abençoou-o ali."}, {"numero": 30, "texto": "E chamou Jacó o nome daquele lugar Peniel: porque vi a Deus face a face, e foi livrada minha alma."}, {"numero": 31, "texto": "E saiu-lhe o sol quando passou a Peniel; e andava mancando de sua coxa."}, {"numero": 32, "texto": "Por isto até o dia de hoje os filhos de Israel não comem do tendão que se contrai, o qual está na juntura da coxa; porque o homem tocou a Jacó este lugar de sua coxa no tendão que se contrai."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 32, 'en', '[{"numero": 1, "texto": "And Jacob went on his way, and the angels of God met him."}, {"numero": 2, "texto": "And when Jacob saw them, he said, This is God''s host: and he called the name of that place Mahanaim."}, {"numero": 3, "texto": "And Jacob sent messengers before him to Esau his brother unto the land of Seir, the country of Edom."}, {"numero": 4, "texto": "And he commanded them, saying, Thus shall ye speak unto my lord Esau; Thy servant Jacob saith thus, I have sojourned with Laban, and stayed there until now:"}, {"numero": 5, "texto": "And I have oxen, and asses, flocks, and menservants, and womenservants: and I have sent to tell my lord, that I may find grace in thy sight."}, {"numero": 6, "texto": "And the messengers returned to Jacob, saying, We came to thy brother Esau, and also he cometh to meet thee, and four hundred men with him."}, {"numero": 7, "texto": "Then Jacob was greatly afraid and distressed: and he divided the people that was with him, and the flocks, and herds, and the camels, into two bands;"}, {"numero": 8, "texto": "And said, If Esau come to the one company, and smite it, then the other company which is left shall escape."}, {"numero": 9, "texto": "And Jacob said, O God of my father Abraham, and God of my father Isaac, the Lord which saidst unto me, Return unto thy country, and to thy kindred, and I will deal well with thee:"}, {"numero": 10, "texto": "I am not worthy of the least of all the mercies, and of all the truth, which thou hast shewed unto thy servant; for with my staff I passed over this Jordan; and now I am become two bands."}, {"numero": 11, "texto": "Deliver me, I pray thee, from the hand of my brother, from the hand of Esau: for I fear him, lest he will come and smite me, and the mother with the children."}, {"numero": 12, "texto": "And thou saidst, I will surely do thee good, and make thy seed as the sand of the sea, which cannot be numbered for multitude."}, {"numero": 13, "texto": "And he lodged there that same night; and took of that which came to his hand a present for Esau his brother;"}, {"numero": 14, "texto": "Two hundred she goats, and twenty he goats, two hundred ewes, and twenty rams,"}, {"numero": 15, "texto": "Thirty milch camels with their colts, forty kine, and ten bulls, twenty she asses, and ten foals."}, {"numero": 16, "texto": "And he delivered them into the hand of his servants, every drove by themselves; and said unto his servants, Pass over before me, and put a space betwixt drove and drove."}, {"numero": 17, "texto": "And he commanded the foremost, saying, When Esau my brother meeteth thee, and asketh thee, saying, Whose art thou? and whither goest thou? and whose are these before thee?"}, {"numero": 18, "texto": "Then thou shalt say, They be thy servant Jacob''s; it is a present sent unto my lord Esau: and, behold, also he is behind us."}, {"numero": 19, "texto": "And so commanded he the second, and the third, and all that followed the droves, saying, On this manner shall ye speak unto Esau, when ye find him."}, {"numero": 20, "texto": "And say ye moreover, Behold, thy servant Jacob is behind us. For he said, I will appease him with the present that goeth before me, and afterward I will see his face; peradventure he will accept of me."}, {"numero": 21, "texto": "So went the present over before him: and himself lodged that night in the company."}, {"numero": 22, "texto": "And he rose up that night, and took his two wives, and his two womenservants, and his eleven sons, and passed over the ford Jabbok."}, {"numero": 23, "texto": "And he took them, and sent them over the brook, and sent over that he had."}, {"numero": 24, "texto": "And Jacob was left alone; and there wrestled a man with him until the breaking of the day."}, {"numero": 25, "texto": "And when he saw that he prevailed not against him, he touched the hollow of his thigh; and the hollow of Jacob''s thigh was out of joint, as he wrestled with him."}, {"numero": 26, "texto": "And he said, Let me go, for the day breaketh. And he said, I will not let thee go, except thou bless me."}, {"numero": 27, "texto": "And he said unto him, What is thy name? And he said, Jacob."}, {"numero": 28, "texto": "And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed."}, {"numero": 29, "texto": "And Jacob asked him, and said, Tell me, I pray thee, thy name. And he said, Wherefore is it that thou dost ask after my name? And he blessed him there."}, {"numero": 30, "texto": "And Jacob called the name of the place Peniel: for I have seen God face to face, and my life is preserved."}, {"numero": 31, "texto": "And as he passed over Penuel the sun rose upon him, and he halted upon his thigh."}, {"numero": 32, "texto": "Therefore the children of Israel eat not of the sinew which shrank, which is upon the hollow of the thigh, unto this day: because he touched the hollow of Jacob''s thigh in the sinew that shrank."}]'::jsonb, 'King James Version'),
  ('Gn', 32, 'fr', '[{"numero": 1, "texto": "Jacob poursuivit son chemin; et des anges de Dieu le rencontrèrent."}, {"numero": 2, "texto": "En les voyant, Jacob dit: C''''est le camp de Dieu! Et il donna à ce lieu le nom de Mahanaïm."}, {"numero": 3, "texto": "Jacob envoya devant lui des messagers à Esaü, son frère, au pays de Séir, dans le territoire d''''Edom."}, {"numero": 4, "texto": "Il leur donna cet ordre: Voici ce que vous direz à mon seigneur Esaü: Ainsi parle ton serviteur Jacob: J''''ai séjourné chez Laban, et j''''y suis resté jusqu''''à présent;"}, {"numero": 5, "texto": "j''''ai des boeufs, des ânes, des brebis, des serviteurs et des servantes, et j''''envoie l''''annoncer à mon seigneur, pour trouver grâce à tes yeux."}, {"numero": 6, "texto": "Les messagers revinrent auprès de Jacob, en disant: Nous sommes allés vers ton frère Esaü; et il marche à ta rencontre, avec quatre cents hommes."}, {"numero": 7, "texto": "Jacob fut très effrayé, et saisi d''''angoisse. Il partagea en deux camps les gens qui étaient avec lui, les brebis, les boeufs et les chameaux;"}, {"numero": 8, "texto": "et il dit: Si Esaü vient contre l''''un des camps et le bat, le camp qui restera pourra se sauver."}, {"numero": 9, "texto": "Jacob dit: Dieu de mon père Abraham, Dieu de mon père Isaac, Eternel, qui m''''as dit: Retourne dans ton pays et dans ton lieu de naissance, et je te ferai du bien!"}, {"numero": 10, "texto": "Je suis trop petit pour toutes les grâces et pour toute la fidélité dont tu as usé envers ton serviteur; car j''''ai passé ce Jourdain avec mon bâton, et maintenant je forme deux camps."}, {"numero": 11, "texto": "Délivre-moi, je te prie, de la main de mon frère, de la main d''''Esaü! car je crains qu''''il ne vienne, et qu''''il ne me frappe, avec la mère et les enfants."}, {"numero": 12, "texto": "Et toi, tu as dit: Je te ferai du bien, et je rendrai ta postérité comme le sable de la mer, si abondant qu''''on ne saurait le compter."}, {"numero": 13, "texto": "C''''est dans ce lieu-là que Jacob passa la nuit. Il prit de ce qu''''il avait sous la main, pour faire un présent à Esaü, son frère:"}, {"numero": 14, "texto": "deux cents chèvres et vingt boucs, deux cents brebis et vingt béliers,"}, {"numero": 15, "texto": "trente femelles de chameaux avec leurs petits qu''''elles allaitaient, quarante vaches et dix taureaux, vingt ânesses et dix ânes."}, {"numero": 16, "texto": "Il les remit à ses serviteurs, troupeau par troupeau séparément, et il dit à ses serviteurs: Passez devant moi, et mettez un intervalle entre chaque troupeau."}, {"numero": 17, "texto": "Il donna cet ordre au premier: Quand Esaü, mon frère, te rencontrera, et te demandera: A qui es-tu? où vas-tu? et à qui appartient ce troupeau devant toi?"}, {"numero": 18, "texto": "tu répondras: A ton serviteur Jacob; c''''est un présent envoyé à mon seigneur Esaü; et voici, il vient lui-même derrière nous."}, {"numero": 19, "texto": "Il donna le même ordre au second, au troisième, et à tous ceux qui suivaient les troupeaux: C''''est ainsi que vous parlerez à mon seigneur Esaü, quand vous le rencontrerez."}, {"numero": 20, "texto": "Vous direz: Voici, ton serviteur Jacob vient aussi derrière nous. Car il se disait: Je l''''apaiserai par ce présent qui va devant moi; ensuite je le verrai en face, et peut-être m''''accueillera-t-il favorablement."}, {"numero": 21, "texto": "Le présent passa devant lui; et il resta cette nuit-là dans le camp."}, {"numero": 22, "texto": "Il se leva la même nuit, prit ses deux femmes, ses deux servantes, et ses onze enfants, et passa le gué de Jabbok."}, {"numero": 23, "texto": "Il les prit, leur fit passer le torrent, et le fit passer à tout ce qui lui appartenait."}, {"numero": 24, "texto": "Jacob demeura seul. Alors un homme lutta avec lui jusqu''''au lever de l''''aurore."}, {"numero": 25, "texto": "Voyant qu''''il ne pouvait le vaincre, cet homme le frappa à l''''emboîture de la hanche; et l''''emboîture de la hanche de Jacob se démit pendant qu''''il luttait avec lui."}, {"numero": 26, "texto": "Il dit: Laisse-moi aller, car l''''aurore se lève. Et Jacob répondit: Je ne te laisserai point aller, que tu ne m''''aies béni."}, {"numero": 27, "texto": "Il lui dit: Quel est ton nom? Et il répondit: Jacob."}, {"numero": 28, "texto": "Il dit encore: ton nom ne sera plus Jacob, mais tu seras appelé Israël; car tu as lutté avec Dieu et avec des hommes, et tu as été vainqueur."}, {"numero": 29, "texto": "Jacob l''''interrogea, en disant: Fais-moi je te prie, connaître ton nom. Il répondit: Pourquoi demandes-tu mon nom? Et il le bénit là."}, {"numero": 30, "texto": "Jacob appela ce lieu du nom de Peniel: car, dit-il, j''''ai vu Dieu face à face, et mon âme a été sauvée."}, {"numero": 31, "texto": "Le soleil se levait, lorsqu''''il passa Peniel. Jacob boitait de la hanche."}, {"numero": 32, "texto": "C''''est pourquoi jusqu''''à ce jour, les enfants d''''Israël ne mangent point le tendon qui est à l''''emboîture de la hanche; car Dieu frappa Jacob à l''''emboîture de la hanche, au tendon."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 32, 'es', '[{"numero": 1, "texto": "Y JACOB se fué su camino, y saliéronle al encuentro ángeles de Dios."}, {"numero": 2, "texto": "Y dijo Jacob cuando los vió: El campo de Dios es este: y llamó el nombre de aquel lugar Mahanaim."}, {"numero": 3, "texto": "Y envió Jacob mensajeros delante de sí á Esaú su hermano, á la tierra de Seir, campo de Edom."}, {"numero": 4, "texto": "Y mandóles diciendo: Así diréis á mi señor Esaú: Así dice tu siervo Jacob: Con Labán he morado, y detenídome hasta ahora;"}, {"numero": 5, "texto": "Y tengo vacas, y asnos, y ovejas, y siervos y siervas; y envío á decirlo á mi señor, por hallar gracia en tus ojos."}, {"numero": 6, "texto": "Y los mensajeros volvieron á Jacob, diciendo: Vinimos á tu hermano Esaú, y él también viene á recibirte, y cuatrocientos hombres con él."}, {"numero": 7, "texto": "Entonces Jacob tuvo gran temor, y angustióse; y partió el pueblo que tenía consigo, y las ovejas y las vacas y los camellos, en dos cuadrillas;"}, {"numero": 8, "texto": "Y dijo: Si viniere Esaú á la una cuadrilla y la hiriere, la otra cuadrilla escapará."}, {"numero": 9, "texto": "Y dijo Jacob: Dios de mi padre Abraham, y Dios de mi padre Isaac, Jehová, que me dijiste: Vuélvete á tu tierra y á tu parentela, y yo te haré bien;"}, {"numero": 10, "texto": "Menor soy que todas las misericordias, y que toda la verdad que has usado para con tu siervo; que con mi bordón pasé este Jordán, y ahora estoy sobre dos cuadrillas."}, {"numero": 11, "texto": "Líbrame ahora de la mano de mi hermano, de la mano de Esaú, porque le temo; no venga quizá, y me hiera la madre con los hijos."}, {"numero": 12, "texto": "Y tú has dicho: Yo te haré bien, y pondré tu simiente como la arena del mar, que no se puede contar por la multitud."}, {"numero": 13, "texto": "Y durmió allí aquella noche, y tomó de lo que le vino á la mano un presente para su hermano Esaú:"}, {"numero": 14, "texto": "Doscientas cabras y veinte machos de cabrío, doscientas ovejas y veinte carneros,"}, {"numero": 15, "texto": "Treinta camellas paridas, con sus hijos, cuarenta vacas y diez novillos, veinte asnas y diez borricos."}, {"numero": 16, "texto": "Y entrególo en mano de sus siervos, cada manada de por sí; y dijo á sus siervos: Pasad delante de mí, y poned espacio entre manada y manada."}, {"numero": 17, "texto": "Y mandó al primero, diciendo: Si Esaú mi hermano te encontrare, y te preguntare, diciendo: ¿De quién eres? ¿y adónde vas? ¿y para quién es esto que llevas delante de ti?"}, {"numero": 18, "texto": "Entonces dirás: Presente es de tu siervo Jacob, que envía á mi señor Esaú; y he aquí también él viene tras nosotros."}, {"numero": 19, "texto": "Y mandó también al segundo, y al tercero, y á todos los que iban tras aquellas manadas, diciendo: Conforme á esto hablaréis á Esaú, cuando le hallareis."}, {"numero": 20, "texto": "Y diréis también: He aquí tu siervo Jacob viene tras nosotros. Porque dijo: Apaciguaré su ira con el presente que va delante de mí, y después veré su rostro: quizá le seré acepto."}, {"numero": 21, "texto": "Y pasó el presente delante de él; y él durmió aquella noche en el campamento."}, {"numero": 22, "texto": "Y levantóse aquella noche, y tomó sus dos mujeres, y sus dos siervas, y sus once hijos, y pasó el vado de Jaboc."}, {"numero": 23, "texto": "Tomólos pues, y pasólos el arroyo, é hizo pasar lo que tenía."}, {"numero": 24, "texto": "Y quedóse Jacob solo, y luchó con él un varón hasta que rayaba el alba."}, {"numero": 25, "texto": "Y como vió que no podía con él, tocó en el sitio del encaje de su muslo, y descoyuntóse el muslo de Jacob mientras con él luchaba."}, {"numero": 26, "texto": "Y dijo: Déjame, que raya el alba. Y él dijo: No te dejaré, si no me bendices."}, {"numero": 27, "texto": "Y él le dijo: ¿Cuál es tu nombre? Y él respondió: Jacob."}, {"numero": 28, "texto": "Y él dijo: No se dirá más tu nombre Jacob, sino Israel: porque has peleado con Dios y con los hombres, y has vencido."}, {"numero": 29, "texto": "Entonces Jacob le preguntó, y dijo: Declárame ahora tu nombre. Y él respondió: ¿Por qué preguntas por mi nombre? Y bendíjolo allí."}, {"numero": 30, "texto": "Y llamó Jacob el nombre de aquel lugar, Peniel: porque vi á Dios cara á cara, y fué librada mi alma."}, {"numero": 31, "texto": "Y salióle el sol pasado que hubo á Peniel; y cojeaba de su anca."}, {"numero": 32, "texto": "Por esto no comen los hijos de Israel, hasta hoy día, del tendón que se contrajo, el cual está en el encaje del muslo: porque tocó á Jacob este sitio de su muslo en el tendón que se contrajo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 33, 'pt', '[{"numero": 1, "texto": "E levantando Jacó seus olhos, olhou, e eis que vinha Esaú, e os quatrocentos homens com ele: então repartiu ele os filhos entre Lia e Raquel e as duas servas."}, {"numero": 2, "texto": "E pôs as servas e seus filhos adiante; logo a Lia e a seus filhos; e a Raquel e a José os últimos."}, {"numero": 3, "texto": "E ele passou diante deles, e inclinou-se à terra sete vezes, até que chegou a seu irmão."}, {"numero": 4, "texto": "E Esaú correu a seu encontro, e abraçou-lhe, e lançou-se sobre seu pescoço, e o beijou; e choraram."}, {"numero": 5, "texto": "E levantou seus olhos, e viu as mulheres e os filhos, e disse: Quem são estes que estão contigo? E ele respondeu: São os filhos que Deus deu a teu servo."}, {"numero": 6, "texto": "E se chegaram as servas, elas e seus meninos, e inclinaram-se."}, {"numero": 7, "texto": "E chegou-se Lia com seus filhos, e inclinaram-se: e depois chegou José e Raquel, e também se inclinaram."}, {"numero": 8, "texto": "E ele disse: Qual é a tua intenção com todos estes grupos que encontrei? E ele respondeu: Achar favor aos olhos de meu senhor."}, {"numero": 9, "texto": "E disse Esaú: Tenho o bastante, meu irmão; seja para ti o que é teu."}, {"numero": 10, "texto": "E disse Jacó: Não, eu te rogo, se achei agora favor em teus olhos, toma meu presente de minha mão, pois vi teu rosto como se houvesse visto o rosto de Deus; e me aceitaste."}, {"numero": 11, "texto": "Toma, eu te rogo, minha dádiva que te é trazida; porque Deus me fez misericórdia, e tudo o que há aqui é meu. E insistiu com ele, e tomou-a."}, {"numero": 12, "texto": "E disse: Anda, e vamos; e eu irei adiante de ti."}, {"numero": 13, "texto": "E ele lhe disse: Meu senhor sabe que os meninos são tenros, e que tenho ovelhas e vacas de cria; e se as cansam, em um dia morrerão todas as ovelhas."}, {"numero": 14, "texto": "Passe agora meu senhor diante de seu servo, e eu me irei pouco a pouco ao passo do gado que vai adiante de mim, e à passagem dos meninos, até que chegue a meu senhor a Seir."}, {"numero": 15, "texto": "E Esaú disse: Deixarei agora contigo da gente que vem comigo. E ele disse: Para que isto? ache eu favor aos olhos de meu senhor."}, {"numero": 16, "texto": "Assim se voltou Esaú aquele dia por seu caminho a Seir."}, {"numero": 17, "texto": "E Jacó se partiu a Sucote, e edificou ali casa para si, e fez abrigos para seu gado; por isso chamou o nome daquele lugar Sucote."}, {"numero": 18, "texto": "E veio Jacó são à cidade de Siquém, que está na terra de Canaã, quando vinha de Padã-Arã; e acampou diante da cidade."}, {"numero": 19, "texto": "E comprou uma parte do campo, onde estendeu sua tenda, da mão dos filhos de Hamor, pai de Siquém, por cem peças de moeda."}, {"numero": 20, "texto": "E erigiu ali um altar, e chamou-lhe: Deus, o Deus de Israel."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 33, 'en', '[{"numero": 1, "texto": "And Jacob lifted up his eyes, and looked, and, behold, Esau came, and with him four hundred men. And he divided the children unto Leah, and unto Rachel, and unto the two handmaids."}, {"numero": 2, "texto": "And he put the handmaids and their children foremost, and Leah and her children after, and Rachel and Joseph hindermost."}, {"numero": 3, "texto": "And he passed over before them, and bowed himself to the ground seven times, until he came near to his brother."}, {"numero": 4, "texto": "And Esau ran to meet him, and embraced him, and fell on his neck, and kissed him: and they wept."}, {"numero": 5, "texto": "And he lifted up his eyes, and saw the women and the children; and said, Who are those with thee? And he said, The children which God hath graciously given thy servant."}, {"numero": 6, "texto": "Then the handmaidens came near, they and their children, and they bowed themselves."}, {"numero": 7, "texto": "And Leah also with her children came near, and bowed themselves: and after came Joseph near and Rachel, and they bowed themselves."}, {"numero": 8, "texto": "And he said, What meanest thou by all this drove which I met? And he said, These are to find grace in the sight of my lord."}, {"numero": 9, "texto": "And Esau said, I have enough, my brother; keep that thou hast unto thyself."}, {"numero": 10, "texto": "And Jacob said, Nay, I pray thee, if now I have found grace in thy sight, then receive my present at my hand: for therefore I have seen thy face, as though I had seen the face of God, and thou wast pleased with me."}, {"numero": 11, "texto": "Take, I pray thee, my blessing that is brought to thee; because God hath dealt graciously with me, and because I have enough. And he urged him, and he took it."}, {"numero": 12, "texto": "And he said, Let us take our journey, and let us go, and I will go before thee."}, {"numero": 13, "texto": "And he said unto him, My lord knoweth that the children are tender, and the flocks and herds with young are with me: and if men should overdrive them one day, all the flock will die."}, {"numero": 14, "texto": "Let my lord, I pray thee, pass over before his servant: and I will lead on softly, according as the cattle that goeth before me and the children be able to endure, until I come unto my lord unto Seir."}, {"numero": 15, "texto": "And Esau said, Let me now leave with thee some of the folk that are with me. And he said, What needeth it? let me find grace in the sight of my lord."}, {"numero": 16, "texto": "So Esau returned that day on his way unto Seir."}, {"numero": 17, "texto": "And Jacob journeyed to Succoth, and built him an house, and made booths for his cattle: therefore the name of the place is called Succoth."}, {"numero": 18, "texto": "And Jacob came to Shalem, a city of Shechem, which is in the land of Canaan, when he came from Padanaram; and pitched his tent before the city."}, {"numero": 19, "texto": "And he bought a parcel of a field, where he had spread his tent, at the hand of the children of Hamor, Shechem''s father, for an hundred pieces of money."}, {"numero": 20, "texto": "And he erected there an altar, and called it EleloheIsrael."}]'::jsonb, 'King James Version'),
  ('Gn', 33, 'fr', '[{"numero": 1, "texto": "Jacob leva les yeux, et regarda; et voici, Esaü arrivait, avec quatre cents hommes. Il répartit les enfants entre Léa, Rachel, et les deux servantes."}, {"numero": 2, "texto": "Il plaça en tête les servantes avec leurs enfants, puis Léa avec ses enfants, et enfin Rachel avec Joseph."}, {"numero": 3, "texto": "Lui-même passa devant eux; et il se prosterna en terre sept fois, jusqu''''à ce qu''''il fût près de son frère."}, {"numero": 4, "texto": "Esaü courut à sa rencontre; il l''''embrassa, se jeta à son cou, et le baisa. Et ils pleurèrent."}, {"numero": 5, "texto": "Esaü, levant les yeux, vit les femmes et les enfants, et il dit: Qui sont ceux que tu as là? Et Jacob répondit: Ce sont les enfants que Dieu a accordés à ton serviteur."}, {"numero": 6, "texto": "Les servantes s''''approchèrent, elles et leurs enfants, et se prosternèrent;"}, {"numero": 7, "texto": "Léa et ses enfants s''''approchèrent aussi, et se prosternèrent; ensuite Joseph et Rachel s''''approchèrent, et se prosternèrent."}, {"numero": 8, "texto": "Esaü dit: A quoi destines-tu tout ce camp que j''''ai rencontré? Et Jacob répondit: A trouver grâce aux yeux de mon seigneur."}, {"numero": 9, "texto": "Esaü dit: Je suis dans l''''abondance, mon frère; garde ce qui est à toi."}, {"numero": 10, "texto": "Et Jacob répondit: Non, je te prie, si j''''ai trouvé grâce à tes yeux, accepte de ma main mon présent; car c''''est pour cela que j''''ai regardé ta face comme on regarde la face de Dieu, et tu m''''as accueilli favorablement."}, {"numero": 11, "texto": "Accepte donc mon présent qui t''''a été offert, puisque Dieu m''''a comblé de grâces, et que je ne manque de rien. Il insista auprès de lui, et Esaü accepta."}, {"numero": 12, "texto": "Esaü dit: Partons, mettons-nous en route; j''''irai devant toi."}, {"numero": 13, "texto": "Jacob lui répondit: Mon seigneur sait que les enfants sont délicats, et que j''''ai des brebis et des vaches qui allaitent; si l''''on forçait leur marche un seul jour, tout le troupeau périrait."}, {"numero": 14, "texto": "Que mon seigneur prenne les devants sur son serviteur; et moi, je suivrai lentement, au pas du troupeau qui me précédera, et au pas des enfants, jusqu''''à ce que j''''arrive chez mon seigneur, à Séir."}, {"numero": 15, "texto": "Esaü dit: Je veux au moins laisser avec toi une partie de mes gens. Et Jacob répondit: Pourquoi cela? Que je trouve seulement grâce aux yeux de mon seigneur!"}, {"numero": 16, "texto": "Le même jour, Esaü reprit le chemin de Séir."}, {"numero": 17, "texto": "Jacob partit pour Succoth. Il bâtit une maison pour lui, et il fit des cabanes pour ses troupeaux. C''''est pourquoi l''''on a appelé ce lieu du nom de Succoth."}, {"numero": 18, "texto": "A son retour de Paddan-Aram, Jacob arriva heureusement à la ville de Sichem, dans le pays de Canaan, et il campa devant la ville."}, {"numero": 19, "texto": "Il acheta la portion du champ où il avait dressé sa tente, des fils d''''Hamor, père de Sichem, pour cent kesita."}, {"numero": 20, "texto": "Et là, il éleva un autel, qu''''il appela El-Elohé-Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 33, 'es', '[{"numero": 1, "texto": "Y ALZANDO Jacob sus ojos miró, y he aquí venía Esaú, y los cuatrocientos hombres con él: entonces repartió él los niños entre Lea y Rachêl y las dos siervas."}, {"numero": 2, "texto": "Y puso las siervas y sus niños delante; luego á Lea y á sus niños; y á Rachêl y á José los postreros."}, {"numero": 3, "texto": "Y él pasó delante de ellos, é inclinóse á tierra siete veces, hasta que llegó á su hermano."}, {"numero": 4, "texto": "Y Esaú corrió á su encuentro, y abrazóle, y echóse sobre su cuello, y le besó; y lloraron."}, {"numero": 5, "texto": "Y alzó sus ojos, y vió las mujeres y los niños, y dijo: ¿Qué te tocan éstos? Y él respondió: Son los niños que Dios ha dado á tu siervo."}, {"numero": 6, "texto": "Y se llegaron las siervas, ellas y sus niños, é inclináronse."}, {"numero": 7, "texto": "Y llegóse Lea con sus niños, é inclináronse: y después llegó José y Rachêl, y también se inclinaron."}, {"numero": 8, "texto": "Y él dijo: ¿Qué te propones con todas estas cuadrillas que he encontrado? Y él respondió: El hallar gracia en los ojos de mi señor."}, {"numero": 9, "texto": "Y dijo Esaú: Harto tengo yo, hermano mío: sea para ti lo que es tuyo."}, {"numero": 10, "texto": "Y dijo Jacob: No, yo te ruego, si he hallado ahora gracia en tus ojos, toma mi presente de mi mano, pues que así he visto tu rostro, como si hubiera visto el rostro de Dios; y hazme placer."}, {"numero": 11, "texto": "Toma, te ruego, mi dádiva que te es traída; porque Dios me ha hecho merced, y todo lo que hay aquí es mío. Y porfió con él, y tomóla."}, {"numero": 12, "texto": "Y dijo: Anda, y vamos; y yo iré delante de ti."}, {"numero": 13, "texto": "Y él le dijo: Mi señor sabe que los niños son tiernos, y que tengo ovejas y vacas paridas; y si las fatigan, en un día morirán todas las ovejas."}, {"numero": 14, "texto": "Pase ahora mi señor delante de su siervo, y yo me iré poco á poco al paso de la hacienda que va delante de mí, y al paso de los niños, hasta que llegue á mi señor á Seir."}, {"numero": 15, "texto": "Y Esaú dijo: Dejaré ahora contigo de la gente que viene conmigo. Y él dijo: ¿Para qué esto? halle yo gracia en los ojos de mi señor."}, {"numero": 16, "texto": "Así se volvió Esaú aquel día por su camino á Seir."}, {"numero": 17, "texto": "Y Jacob se partió á Succoth, y edificó allí casa para sí, é hizo cabañas para su ganado: por tanto llamó el nombre de aquel lugar Succoth."}, {"numero": 18, "texto": "Y vino Jacob sano á la ciudad de Sichêm, que está en la tierra de Canaán, cuando venía de Padan-aram; y acampó delante de la ciudad."}, {"numero": 19, "texto": "Y compró una parte del campo, donde tendió su tienda, de mano de los hijos de Hamor, padre de Sichêm, por cien piezas de moneda."}, {"numero": 20, "texto": "Y erigió allí un altar, y llamóle: El Dios de Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 35, 'pt', '[{"numero": 1, "texto": "E disse Deus a Jacó: Levanta-te, sobe a Betel, e fica ali; e faze ali um altar ao Deus que te apareceu quando fugias de teu irmão Esaú."}, {"numero": 2, "texto": "Então Jacó disse à sua família e a todos os que com ele estavam: Tirai os deuses alheios que há entre vós, e limpai-vos, e mudai vossas roupas."}, {"numero": 3, "texto": "E levantemo-nos, e subamos a Betel; e farei ali altar ao Deus que me respondeu no dia de minha angústia, e foi comigo no caminho que andei."}, {"numero": 4, "texto": "Assim deram a Jacó todos os deuses alheios que havia em poder deles, e os brincos que estavam em suas orelhas; e Jacó os escondeu debaixo de um carvalho, que estava junto a Siquém."}, {"numero": 5, "texto": "E partiram-se, e o terror de Deus foi sobre as cidades que havia em seus arredores, e não seguiram atrás dos filhos de Jacó."}, {"numero": 6, "texto": "E chegou Jacó a Luz, que está em terra de Canaã, (esta é Betel) ele e todo o povo que com ele estava;"}, {"numero": 7, "texto": "E edificou ali um altar, e chamou o lugar El-Betel, porque ali lhe havia aparecido Deus, quando fugia de seu irmão."}, {"numero": 8, "texto": "Então morreu Débora, ama de Rebeca, e foi sepultada às raízes de Betel, debaixo de um carvalho: e chamou-se seu nome Alom-Bacute."}, {"numero": 9, "texto": "E apareceu-se outra vez Deus a Jacó, quando se havia voltado de Padã-Arã, e abençoou-lhe."}, {"numero": 10, "texto": "E disse-lhe Deus: Teu nome é Jacó; não se chamará mais teu nome Jacó, mas sim Israel será teu nome: e chamou seu nome Israel."}, {"numero": 11, "texto": "E disse-lhe Deus: Eu sou o Deus Todo-Poderoso: cresce e multiplica-te; uma nação e conjunto de nações procederá de ti, e reis sairão de teus lombos:"}, {"numero": 12, "texto": "E a terra que eu dei a Abraão e a Isaque, a darei a ti: e à tua descendência depois de ti darei a terra."}, {"numero": 13, "texto": "E foi-se dele Deus, do lugar onde com ele havia falado."}, {"numero": 14, "texto": "E Jacó erigiu uma coluna no lugar onde havia falado com ele, uma coluna de pedra, e derramou sobre ela libação, e deitou sobre ela azeite."}, {"numero": 15, "texto": "E chamou Jacó o nome daquele lugar onde Deus havia falado com ele, Betel."}, {"numero": 16, "texto": "E partiram de Betel, e havia ainda como alguma distância para chegar a Efrata, quando deu à luz Raquel, e houve trabalho em seu parto."}, {"numero": 17, "texto": "E aconteceu, que quando havia trabalho em seu parto, disse-lhe a parteira: Não temas, que também terás este filho."}, {"numero": 18, "texto": "E aconteceu que ao sair dela a alma, (pois morreu) chamou seu nome Benoni; mas seu pai o chamou Benjamim."}, {"numero": 19, "texto": "Assim morreu Raquel, e foi sepultada no caminho de Efrata, a qual é Belém."}, {"numero": 20, "texto": "E pôs Jacó uma coluna sobre sua sepultura: esta é a coluna da sepultura de Raquel até hoje."}, {"numero": 21, "texto": "E partiu Israel, e estendeu sua tenda da outra parte de Migdal-Eder."}, {"numero": 22, "texto": "E aconteceu, morando Israel naquela terra, que foi Rúben e dormiu com Bila a concubina de seu pai; o qual chegou a entender Israel. Agora bem, os filhos de Israel foram doze:"}, {"numero": 23, "texto": "Os filhos de Lia: Rúben o primogênito de Jacó, e Simeão, e Levi, e Judá, e Issacar, e Zebulom."}, {"numero": 24, "texto": "Os filhos de Raquel: José, e Benjamim."}, {"numero": 25, "texto": "E os filhos de Bila, serva de Raquel: Dã, e Naftali."}, {"numero": 26, "texto": "E os filhos de Zilpa, serva de Lia: Gade, e Aser. Estes foram os filhos de Jacó, que lhe nasceram em Padã-Arã."}, {"numero": 27, "texto": "E veio Jacó a Isaque seu pai a Manre, à cidade de Arba, que é Hebrom, onde habitaram Abraão e Isaque."}, {"numero": 28, "texto": "E foram os dias de Isaque cento e oitenta anos."}, {"numero": 29, "texto": "E expirou Isaque, e morreu, e foi recolhido a seus povos, velho e farto de dias; e sepultaram-no Esaú e Jacó seus filhos."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 35, 'en', '[{"numero": 1, "texto": "And God said unto Jacob, Arise, go up to Bethel, and dwell there: and make there an altar unto God, that appeared unto thee when thou fleddest from the face of Esau thy brother."}, {"numero": 2, "texto": "Then Jacob said unto his household, and to all that were with him, Put away the strange gods that are among you, and be clean, and change your garments:"}, {"numero": 3, "texto": "And let us arise, and go up to Bethel; and I will make there an altar unto God, who answered me in the day of my distress, and was with me in the way which I went."}, {"numero": 4, "texto": "And they gave unto Jacob all the strange gods which were in their hand, and all their earrings which were in their ears; and Jacob hid them under the oak which was by Shechem."}, {"numero": 5, "texto": "And they journeyed: and the terror of God was upon the cities that were round about them, and they did not pursue after the sons of Jacob."}, {"numero": 6, "texto": "So Jacob came to Luz, which is in the land of Canaan, that is, Bethel, he and all the people that were with him."}, {"numero": 7, "texto": "And he built there an altar, and called the place Elbethel: because there God appeared unto him, when he fled from the face of his brother."}, {"numero": 8, "texto": "But Deborah, Rebekah''s nurse died, and she was buried beneath Bethel under an oak: and the name of it was called Allonbachuth."}, {"numero": 9, "texto": "And God appeared unto Jacob again, when he came out of Padanaram, and blessed him."}, {"numero": 10, "texto": "And God said unto him, Thy name is Jacob: thy name shall not be called any more Jacob, but Israel shall be thy name: and he called his name Israel."}, {"numero": 11, "texto": "And God said unto him, I am God Almighty: be fruitful and multiply; a nation and a company of nations shall be of thee, and kings shall come out of thy loins;"}, {"numero": 12, "texto": "And the land which I gave Abraham and Isaac, to thee I will give it, and to thy seed after thee will I give the land."}, {"numero": 13, "texto": "And God went up from him in the place where he talked with him."}, {"numero": 14, "texto": "And Jacob set up a pillar in the place where he talked with him, even a pillar of stone: and he poured a drink offering thereon, and he poured oil thereon."}, {"numero": 15, "texto": "And Jacob called the name of the place where God spake with him, Bethel."}, {"numero": 16, "texto": "And they journeyed from Bethel; and there was but a little way to come to Ephrath: and Rachel travailed, and she had hard labour."}, {"numero": 17, "texto": "And it came to pass, when she was in hard labour, that the midwife said unto her, Fear not; thou shalt have this son also."}, {"numero": 18, "texto": "And it came to pass, as her soul was in departing, (for she died) that she called his name Benoni: but his father called him Benjamin."}, {"numero": 19, "texto": "And Rachel died, and was buried in the way to Ephrath, which is Bethlehem."}, {"numero": 20, "texto": "And Jacob set a pillar upon her grave: that is the pillar of Rachel''s grave unto this day."}, {"numero": 21, "texto": "And Israel journeyed, and spread his tent beyond the tower of Edar."}, {"numero": 22, "texto": "And it came to pass, when Israel dwelt in that land, that Reuben went and lay with Bilhah his father''s concubine: and Israel heard it. Now the sons of Jacob were twelve:"}, {"numero": 23, "texto": "The sons of Leah; Reuben, Jacob''s firstborn, and Simeon, and Levi, and Judah, and Issachar, and Zebulun:"}, {"numero": 24, "texto": "The sons of Rachel; Joseph, and Benjamin:"}, {"numero": 25, "texto": "And the sons of Bilhah, Rachel''s handmaid; Dan, and Naphtali:"}, {"numero": 26, "texto": "And the sons of Zilpah, Leah''s handmaid: Gad, and Asher: these are the sons of Jacob, which were born to him in Padanaram."}, {"numero": 27, "texto": "And Jacob came unto Isaac his father unto Mamre, unto the city of Arbah, which is Hebron, where Abraham and Isaac sojourned."}, {"numero": 28, "texto": "And the days of Isaac were an hundred and fourscore years."}, {"numero": 29, "texto": "And Isaac gave up the ghost, and died, and was gathered unto his people, being old and full of days: and his sons Esau and Jacob buried him."}]'::jsonb, 'King James Version'),
  ('Gn', 35, 'fr', '[{"numero": 1, "texto": "Dieu dit à Jacob: Lève-toi, monte à Béthel, et demeures-y; là, tu dresseras un autel au Dieu qui t''''apparut, lorsque tu fuyais Esaü, ton frère."}, {"numero": 2, "texto": "Jacob dit à sa maison et à tous ceux qui étaient avec lui: Otez les dieux étrangers qui sont au milieu de vous, purifiez-vous, et changez de vêtements."}, {"numero": 3, "texto": "Nous nous lèverons, et nous monterons à Béthel; là, je dresserai un autel au Dieu qui m''''a exaucé dans le jour de ma détresse, et qui a été avec moi pendant le voyage que j''''ai fait."}, {"numero": 4, "texto": "Ils donnèrent à Jacob tous les dieux étrangers qui étaient entre leurs mains, et les anneaux qui étaient à leurs oreilles. Jacob les enfouit sous le térébinthe qui est près de Sichem."}, {"numero": 5, "texto": "Ensuite ils partirent. La terreur de Dieu se répandit sur les villes qui les entouraient, et l''''on ne poursuivit point les fils de Jacob."}, {"numero": 6, "texto": "Jacob arriva, lui et tous ceux qui étaient avec lui, à Luz, qui est Béthel, dans le pays de Canaan."}, {"numero": 7, "texto": "Il bâtit là un autel, et il appela ce lieu El-Béthel; car c''''est là que Dieu s''''était révélé à lui lorsqu''''il fuyait son frère."}, {"numero": 8, "texto": "Débora, nourrice de Rebecca, mourut; et elle fut enterrée au-dessous de Béthel, sous le chêne auquel on a donné le nom de chêne des pleurs."}, {"numero": 9, "texto": "Dieu apparut encore à Jacob, après son retour de Paddan-Aram, et il le bénit."}, {"numero": 10, "texto": "Dieu lui dit: Ton nom est Jacob; tu ne seras plus appelé Jacob, mais ton nom sera Israël. Et il lui donna le nom d''''Israël."}, {"numero": 11, "texto": "Dieu lui dit: Je suis le Dieu tout-puissant. Sois fécond, et multiplie: une nation et une multitude de nations naîtront de toi, et des rois sortiront de tes reins."}, {"numero": 12, "texto": "Je te donnerai le pays que j''''ai donné à Abraham et à Isaac, et je donnerai ce pays à ta postérité après toi."}, {"numero": 13, "texto": "Dieu s''''éleva au-dessus de lui, dans le lieu où il lui avait parlé."}, {"numero": 14, "texto": "Et Jacob dressa un monument dans le lieu où Dieu lui avait parlé, un monument de pierres, sur lequel il fit une libation et versa de l''''huile."}, {"numero": 15, "texto": "Jacob donna le nom de Béthel au lieu où Dieu lui avait parlé."}, {"numero": 16, "texto": "Ils partirent de Béthel; et il y avait encore une certaine distance jusqu''''à Ephrata, lorsque Rachel accoucha. Elle eut un accouchement pénible;"}, {"numero": 17, "texto": "et pendant les douleurs de l''''enfantement, la sage-femme lui dit: Ne crains point, car tu as encore un fils!"}, {"numero": 18, "texto": "Et comme elle allait rendre l''''âme, car elle était mourante, elle lui donna le nom de Ben-Oni; mais le père l''''appela Benjamin."}, {"numero": 19, "texto": "Rachel mourut, et elle fut enterrée sur le chemin d''''Ephrata, qui est Bethléhem."}, {"numero": 20, "texto": "Jacob éleva un monument sur son sépulcre; c''''est le monument du sépulcre de Rachel, qui existe encore aujourd''''hui."}, {"numero": 21, "texto": "Israël partit; et il dressa sa tente au delà de Migdal-Eder."}, {"numero": 22, "texto": "Pendant qu''''Israël habitait cette contrée, Ruben alla coucher avec Bilha, concubine de son père. Et Israël l''''apprit. Les fils de Jacob étaient au nombre de douze."}, {"numero": 23, "texto": "Fils de Léa: Ruben, premier-né de Jacob, Siméon, Lévi, Juda, Issacar et Zabulon."}, {"numero": 24, "texto": "Fils de Rachel: Joseph et Benjamin."}, {"numero": 25, "texto": "Fils de Bilha, servante de Rachel: Dan et Nephthali."}, {"numero": 26, "texto": "Fils de Zilpa, servante de Léa: Gad et Aser. Ce sont là les fils de Jacob, qui lui naquirent à Paddan-Aram."}, {"numero": 27, "texto": "Jacob arriva auprès d''''Isaac, son père, à Mamré, à Kirjath-Arba, qui est Hébron, où avaient séjourné Abraham et Isaac."}, {"numero": 28, "texto": "Les jours d''''Isaac furent de cent quatre-vingts ans."}, {"numero": 29, "texto": "Il expira et mourut, et il fut recueilli auprès de son peuple, âgé et rassasié de jours, et Esaü et Jacob, ses fils, l''''enterrèrent."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 35, 'es', '[{"numero": 1, "texto": "Y DIJO Dios á Jacob: Levántate, sube á Beth-el, y estáte allí; y haz allí un altar al Dios que te apareció cuando huías de tu hermano Esaú."}, {"numero": 2, "texto": "Entonces Jacob dijo á su familia y á todos los que con él estaban: Quitad los dioses ajenos que hay entre vosotros, y limpiaos, y mudad vuestros vestidos."}, {"numero": 3, "texto": "Y levantémonos, y subamos á Beth-el; y haré allí altar al Dios que me respondió en el día de mi angustia, y ha sido conmigo en el camino que he andado."}, {"numero": 4, "texto": "Así dieron á Jacob todos los dioses ajenos que había en poder de ellos, y los zarzillos que estaban en sus orejas; y Jacob los escondió debajo de una encina, que estaba junto á Sichêm."}, {"numero": 5, "texto": "Y partiéronse, y el terror de Dios fué sobre las ciudades que había en sus alrededores, y no siguieron tras los hijos de Jacob."}, {"numero": 6, "texto": "Y llegó Jacob á Luz, que está en tierra de Canaán, (esta es Beth-el) él y todo el pueblo que con él estaba;"}, {"numero": 7, "texto": "Y edificó allí un altar, y llamó al lugar El-Beth-el, porque allí le había aparecido Dios, cuando huía de su hermano."}, {"numero": 8, "texto": "Entonces murió Débora, ama de Rebeca, y fué sepultada á las raíces de Beth-el, debajo de una encina: y llamóse su nombre Allon-Bacuth."}, {"numero": 9, "texto": "Y aparecióse otra vez Dios á Jacob, cuando se había vuelto de Padan-aram, y bendíjole."}, {"numero": 10, "texto": "Y díjole Dios: Tu nombre es Jacob; no se llamará más tu nombre Jacob, sino Israel será tu nombre: y llamó su nombre Israel."}, {"numero": 11, "texto": "Y díjole Dios: Yo soy el Dios Omnipotente: crece y multiplícate; una nación y conjunto de naciones procederá de ti, y reyes saldrán de tus lomos:"}, {"numero": 12, "texto": "Y la tierra que yo he dado á Abraham y á Isaac, la daré á ti: y á tu simiente después de ti daré la tierra."}, {"numero": 13, "texto": "Y fuése de él Dios, del lugar donde con él había hablado."}, {"numero": 14, "texto": "Y Jacob erigió un título en el lugar donde había hablado con él, un título de piedra, y derramó sobre él libación, y echó sobre él aceite."}, {"numero": 15, "texto": "Y llamó Jacob el nombre de aquel lugar donde Dios había hablado con él, Beth-el."}, {"numero": 16, "texto": "Y partieron de Beth-el, y había aún como media legua de tierra para llegar á Ephrata, cuando parió Rachêl, y hubo trabajo en su parto."}, {"numero": 17, "texto": "Y aconteció, que como había trabajo en su parir, díjole la partera: No temas, que también tendrás este hijo."}, {"numero": 18, "texto": "Y acaeció que al salírsele el alma, (pues murió) llamó su nombre Benoni; mas su padre lo llamó Benjamín."}, {"numero": 19, "texto": "Así murió Rachêl, y fué sepultada en el camino de Ephrata, la cual es Beth-lehem."}, {"numero": 20, "texto": "Y puso Jacob un título sobre su sepultura: este es el título de la sepultura de Rachêl hasta hoy."}, {"numero": 21, "texto": "Y partió Israel, y tendió su tienda de la otra parte de Migdaleder."}, {"numero": 22, "texto": "Y acaeció, morando Israel en aquella tierra, que fué Rubén y durmió con Bilha la concubina de su padre; lo cual llegó á entender Israel. Ahora bien, los hijos de Israel fueron doce:"}, {"numero": 23, "texto": "Los hijos de Lea: Rubén el primogénito de Jacob, y Simeón, y Leví, y Judá, é Issachâr, y Zabulón."}, {"numero": 24, "texto": "Los hijos de Rachêl: José, y Benjamín."}, {"numero": 25, "texto": "Y los hijos de Bilha, sierva de Rachêl: Dan, y Nephtalí."}, {"numero": 26, "texto": "Y los hijos de Zilpa, sierva de Lea: Gad, y Aser. Estos fueron los hijos de Jacob, que le nacieron en Padan-aram."}, {"numero": 27, "texto": "Y vino Jacob á Isaac su padre á Mamre, á la ciudad de Arba, que es Hebrón, donde habitaron Abraham é Isaac."}, {"numero": 28, "texto": "Y fueron los días de Isaac ciento ochenta años."}, {"numero": 29, "texto": "Y exhaló Isaac el espíritu, y murió, y fué recogido á sus pueblos, viejo y harto de días; y sepultáronlo Esaú y Jacob sus hijos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 37, 'pt', '[{"numero": 1, "texto": "E habitou Jacó na terra onde peregrinou seu pai, na terra de Canaã."}, {"numero": 2, "texto": "Estas foram as gerações de Jacó. José, sendo de idade de dezessete anos apascentava as ovelhas com seus irmãos; e o jovem estava com os filhos de Bila, e com os filhos de Zilpa, mulheres de seu pai: e contava José a seu pai as más notícias acerca deles."}, {"numero": 3, "texto": "E amava Israel a José mais que a todos os seus filhos, porque lhe havia tido em sua velhice: e lhe fez uma roupa de diversas cores."}, {"numero": 4, "texto": "E vendo seus irmãos que seu pai o amava mais que a todos os seus irmãos, odiavam-lhe, e não lhe podiam falar pacificamente."}, {"numero": 5, "texto": "E sonhou José um sonho e contou-o a seus irmãos; e eles vieram a odiar-lhe mais ainda."}, {"numero": 6, "texto": "E ele lhes disse: Ouvi agora este sonho que sonhei:"}, {"numero": 7, "texto": "Eis que atávamos feixes no meio do campo, e eis que meu feixe se levantava, e estava em pé, e que vossos feixes estavam ao redor, e se inclinavam ao meu."}, {"numero": 8, "texto": "E responderam-lhe seus irmãos: Reinarás tu sobre nós, ou serás tu senhor sobre nós? E o odiaram ainda mais por causa de seus sonhos e de suas palavras."}, {"numero": 9, "texto": "E sonhou ainda outro sonho, e contou-o a seus irmãos, dizendo: Eis que sonhei outro sonho, e eis que o sol e a lua e onze estrelas se inclinavam a mim."}, {"numero": 10, "texto": "E contou-o a seu pai e a seus irmãos: e seu pai lhe repreendeu, e disse-lhe: Que sonho é este que sonhaste? Viremos eu e tua mãe, e teus irmãos, a nos inclinarmos a ti em terra?"}, {"numero": 11, "texto": "E seus irmãos lhe tinham inveja, mas seu pai guardava isso em mente."}, {"numero": 12, "texto": "E foram seus irmãos a apascentar as ovelhas de seu pai em Siquém."}, {"numero": 13, "texto": "E disse Israel a José: Teus irmãos apascentam as ovelhas em Siquém: vem, e te enviarei a eles. E ele respondeu: Eis-me aqui."}, {"numero": 14, "texto": "E ele lhe disse: Vai agora, olha como estão teus irmãos e como estão as ovelhas, e traze-me a resposta. E enviou-o do vale de Hebrom, e chegou a Siquém."}, {"numero": 15, "texto": "E achou-o um homem, andando ele perdido pelo campo, e perguntou-lhe aquele homem, dizendo: Que buscas?"}, {"numero": 16, "texto": "E ele respondeu: Busco a meus irmãos: rogo-te que me mostres onde apascentam."}, {"numero": 17, "texto": "E aquele homem respondeu: Já se foram daqui; eu lhes ouvi dizer: Vamos a Dotã. Então José foi atrás de seus irmãos, e achou-os em Dotã."}, {"numero": 18, "texto": "E quando eles o viram de longe, antes que perto deles chegasse, tramaram contra ele para matar-lhe."}, {"numero": 19, "texto": "E disseram um ao outro: Eis que vem o sonhador;"}, {"numero": 20, "texto": "Agora, pois, vinde, e o matemos e o lancemos em uma cisterna, e diremos: Alguma fera selvagem o devorou: e veremos que serão seus sonhos."}, {"numero": 21, "texto": "E quando Rúben ouviu isto, livrou-o de suas mãos e disse: Não o matemos."}, {"numero": 22, "texto": "E disse-lhes Rúben: Não derrameis sangue; lançai-o nesta cisterna que está no deserto, e não ponhais mão nele; para livrá-lo assim de suas mãos, para fazê-lo virar a seu pai."}, {"numero": 23, "texto": "E sucedeu que, quando chegou José a seus irmãos, eles fizeram desnudar a José sua roupa, a roupa de cores que tinha sobre si;"}, {"numero": 24, "texto": "E tomaram-no, e lançaram-lhe na cisterna; mas a cisterna estava vazia, não havia nela água."}, {"numero": 25, "texto": "E sentaram-se a comer pão: e levantando os olhos olharam, e eis uma companhia de ismaelitas que vinha de Gileade, e seus camelos traziam aromas e bálsamo e mirra, e iam a levá-lo ao Egito."}, {"numero": 26, "texto": "Então Judá disse a seus irmãos: Que proveito há em que matemos a nosso irmão e encubramos sua morte?"}, {"numero": 27, "texto": "Vinde, e o vendamos aos ismaelitas, e não seja nossa mão sobre ele; que nosso irmão é nossa carne. E seus irmãos concordaram com ele."}, {"numero": 28, "texto": "E quando passavam os midianitas mercadores, tiraram eles a José da cisterna, e trouxeram-lhe acima, e o venderam aos ismaelitas por vinte peças de prata. E levaram a José ao Egito."}, {"numero": 29, "texto": "E Rúben voltou à cisterna, e não achou a José dentro, e rasgou suas roupas."}, {"numero": 30, "texto": "E voltou a seus irmãos e disse: O jovem não aparece; e eu, aonde irei eu?"}, {"numero": 31, "texto": "Então eles tomaram a roupa de José, e degolaram um cabrito das cabras, e tingiram a roupa com o sangue;"}, {"numero": 32, "texto": "E enviaram a roupa de cores e trouxeram-na a seu pai, e disseram: Achamos isto, reconhece agora se é ou não a roupa de teu filho."}, {"numero": 33, "texto": "E ele a reconheceu, e disse: A roupa de meu filho é; alguma fera selvagem o devorou; José foi despedaçado."}, {"numero": 34, "texto": "Então Jacó rasgou suas roupas, e pôs saco sobre seus lombos, e fez luto por seu filho muitos dias."}, {"numero": 35, "texto": "E levantaram-se todos os seus filhos e todas as suas filhas para consolá-lo; mas ele não quis receber consolação, e disse: Porque eu tenho de descer ao meu filho com luto ao Xeol. E seu pai chorou por ele."}, {"numero": 36, "texto": "E os midianitas o venderam no Egito a Potifar, oficial de Faraó, capitão dos da guarda."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 37, 'en', '[{"numero": 1, "texto": "And Jacob dwelt in the land wherein his father was a stranger, in the land of Canaan."}, {"numero": 2, "texto": "These are the generations of Jacob. Joseph, being seventeen years old, was feeding the flock with his brethren; and the lad was with the sons of Bilhah, and with the sons of Zilpah, his father''s wives: and Joseph brought unto his father their evil report."}, {"numero": 3, "texto": "Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."}, {"numero": 4, "texto": "And when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him."}, {"numero": 5, "texto": "And Joseph dreamed a dream, and he told it his brethren: and they hated him yet the more."}, {"numero": 6, "texto": "And he said unto them, Hear, I pray you, this dream which I have dreamed:"}, {"numero": 7, "texto": "For, behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf."}, {"numero": 8, "texto": "And his brethren said to him, Shalt thou indeed reign over us? or shalt thou indeed have dominion over us? And they hated him yet the more for his dreams, and for his words."}, {"numero": 9, "texto": "And he dreamed yet another dream, and told it his brethren, and said, Behold, I have dreamed a dream more; and, behold, the sun and the moon and the eleven stars made obeisance to me."}, {"numero": 10, "texto": "And he told it to his father, and to his brethren: and his father rebuked him, and said unto him, What is this dream that thou hast dreamed? Shall I and thy mother and thy brethren indeed come to bow down ourselves to thee to the earth?"}, {"numero": 11, "texto": "And his brethren envied him; but his father observed the saying."}, {"numero": 12, "texto": "And his brethren went to feed their father''s flock in Shechem."}, {"numero": 13, "texto": "And Israel said unto Joseph, Do not thy brethren feed the flock in Shechem? come, and I will send thee unto them. And he said to him, Here am I."}, {"numero": 14, "texto": "And he said to him, Go, I pray thee, see whether it be well with thy brethren, and well with the flocks; and bring me word again. So he sent him out of the vale of Hebron, and he came to Shechem."}, {"numero": 15, "texto": "And a certain man found him, and, behold, he was wandering in the field: and the man asked him, saying, What seekest thou?"}, {"numero": 16, "texto": "And he said, I seek my brethren: tell me, I pray thee, where they feed their flocks."}, {"numero": 17, "texto": "And the man said, They are departed hence; for I heard them say, Let us go to Dothan. And Joseph went after his brethren, and found them in Dothan."}, {"numero": 18, "texto": "And when they saw him afar off, even before he came near unto them, they conspired against him to slay him."}, {"numero": 19, "texto": "And they said one to another, Behold, this dreamer cometh."}, {"numero": 20, "texto": "Come now therefore, and let us slay him, and cast him into some pit, and we will say, Some evil beast hath devoured him: and we shall see what will become of his dreams."}, {"numero": 21, "texto": "And Reuben heard it, and he delivered him out of their hands; and said, Let us not kill him."}, {"numero": 22, "texto": "And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again."}, {"numero": 23, "texto": "And it came to pass, when Joseph was come unto his brethren, that they stript Joseph out of his coat, his coat of many colours that was on him;"}, {"numero": 24, "texto": "And they took him, and cast him into a pit: and the pit was empty, there was no water in it."}, {"numero": 25, "texto": "And they sat down to eat bread: and they lifted up their eyes and looked, and, behold, a company of Ishmeelites came from Gilead with their camels bearing spicery and balm and myrrh, going to carry it down to Egypt."}, {"numero": 26, "texto": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood?"}, {"numero": 27, "texto": "Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content."}, {"numero": 28, "texto": "Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt."}, {"numero": 29, "texto": "And Reuben returned unto the pit; and, behold, Joseph was not in the pit; and he rent his clothes."}, {"numero": 30, "texto": "And he returned unto his brethren, and said, The child is not; and I, whither shall I go?"}, {"numero": 31, "texto": "And they took Joseph''s coat, and killed a kid of the goats, and dipped the coat in the blood;"}, {"numero": 32, "texto": "And they sent the coat of many colours, and they brought it to their father; and said, This have we found: know now whether it be thy son''s coat or no."}, {"numero": 33, "texto": "And he knew it, and said, It is my son''s coat; an evil beast hath devoured him; Joseph is without doubt rent in pieces."}, {"numero": 34, "texto": "And Jacob rent his clothes, and put sackcloth upon his loins, and mourned for his son many days."}, {"numero": 35, "texto": "And all his sons and all his daughters rose up to comfort him; but he refused to be comforted; and he said, For I will go down into the grave unto my son mourning. Thus his father wept for him."}, {"numero": 36, "texto": "And the Midianites sold him into Egypt unto Potiphar, an officer of Pharaoh''s, and captain of the guard."}]'::jsonb, 'King James Version'),
  ('Gn', 37, 'fr', '[{"numero": 1, "texto": "Jacob demeura dans le pays de Canaan, où avait séjourné son père."}, {"numero": 2, "texto": "Voici la postérité de Jacob. Joseph, âgé de dix-sept ans, faisait paître le troupeau avec ses frères; cet enfant était auprès des fils de Bilha et des fils de Zilpa, femmes de son père. Et Joseph rapportait à leur père leurs mauvais propos."}, {"numero": 3, "texto": "Israël aimait Joseph plus que tous ses autres fils, parce qu''''il l''''avait eu dans sa vieillesse; et il lui fit une tunique de plusieurs couleurs."}, {"numero": 4, "texto": "Ses frères virent que leur père l''''aimait plus qu''''eux tous, et ils le prirent en haine. Ils ne pouvaient lui parler avec amitié."}, {"numero": 5, "texto": "Joseph eut un songe, et il le raconta à ses frères, qui le haïrent encore davantage."}, {"numero": 6, "texto": "Il leur dit: Ecoutez donc ce songe que j''''ai eu!"}, {"numero": 7, "texto": "Nous étions à lier des gerbes au milieu des champs; et voici, ma gerbe se leva et se tint debout, et vos gerbes l''''entourèrent et se prosternèrent devant elle."}, {"numero": 8, "texto": "Ses frères lui dirent: Est-ce que tu règneras sur nous? est-ce que tu nous gouverneras? Et ils le haïrent encore davantage, à cause de ses songes et à cause de ses paroles."}, {"numero": 9, "texto": "Il eut encore un autre songe, et il le raconta à ses frères. Il dit: J''''ai eu encore un songe! Et voici, le soleil, la lune et onze étoiles se prosternaient devant moi."}, {"numero": 10, "texto": "Il le raconta à son père et à ses frères. Son père le réprimanda, et lui dit: Que signifie ce songe que tu as eu? Faut-il que nous venions, moi, ta mère et tes frères, nous prosterner en terre devant toi?"}, {"numero": 11, "texto": "Ses frères eurent de l''''envie contre lui, mais son père garda le souvenir de ces choses."}, {"numero": 12, "texto": "Les frères de Joseph étant allés à Sichem, pour faire paître le troupeau de leur père,"}, {"numero": 13, "texto": "Israël dit à Joseph: Tes frères ne font-ils pas paître le troupeau à Sichem? Viens, je veux t''''envoyer vers eux. Et il répondit: Me voici!"}, {"numero": 14, "texto": "Israël lui dit: Va, je te prie, et vois si tes frères sont en bonne santé et si le troupeau est en bon état; et tu m''''en rapporteras des nouvelles. Il l''''envoya ainsi de la vallée d''''Hébron; et Joseph alla à Sichem."}, {"numero": 15, "texto": "Un homme le rencontra, comme il errait dans les champs. Il le questionna, en disant: Que cherches-tu?"}, {"numero": 16, "texto": "Joseph répondit: Je cherche mes frères; dis-moi, je te prie, où ils font paître leur troupeau."}, {"numero": 17, "texto": "Et l''''homme dit: Ils sont partis d''''ici; car je les ai entendus dire: Allons à Dothan. Joseph alla après ses frères, et il les trouva à Dothan."}, {"numero": 18, "texto": "Ils le virent de loin; et, avant qu''''il fût près d''''eux, ils complotèrent de le faire mourir."}, {"numero": 19, "texto": "Ils se dirent l''''un à l''''autre: Voici le faiseur de songes qui arrive."}, {"numero": 20, "texto": "Venez maintenant, tuons-le, et jetons-le dans une des citernes; nous dirons qu''''une bête féroce l''''a dévoré, et nous verrons ce que deviendront ses songes."}, {"numero": 21, "texto": "Ruben entendit cela, et il le délivra de leurs mains. Il dit: Ne lui ôtons pas la vie."}, {"numero": 22, "texto": "Ruben leur dit: Ne répandez point de sang; jetez-le dans cette citerne qui est au désert, et ne mettez pas la main sur lui. Il avait dessein de le délivrer de leurs mains pour le faire retourner vers son père."}, {"numero": 23, "texto": "Lorsque Joseph fut arrivé auprès de ses frères, ils le dépouillèrent de sa tunique, de la tunique de plusieurs couleurs, qu''''il avait sur lui."}, {"numero": 24, "texto": "Ils le prirent, et le jetèrent dans la citerne. Cette citerne était vide; il n''''y avait point d''''eau."}, {"numero": 25, "texto": "Ils s''''assirent ensuite pour manger. Ayant levé les yeux, ils virent une caravane d''''Ismaélites venant de Galaad; leurs chameaux étaient chargés d''''aromates, de baume et de myrrhe, qu''''ils transportaient en Egypte."}, {"numero": 26, "texto": "Alors Juda dit à ses frères: Que gagnerons-nous à tuer notre frère et à cacher son sang?"}, {"numero": 27, "texto": "Venez, vendons-le aux Ismaélites, et ne mettons pas la main sur lui, car il est notre frère, notre chair. Et ses frères l''''écoutèrent."}, {"numero": 28, "texto": "Au passage des marchands madianites, ils tirèrent et firent remonter Joseph hors de la citerne; et ils le vendirent pour vingt sicles d''''argent aux Ismaélites, qui l''''emmenèrent en Egypte."}, {"numero": 29, "texto": "Ruben revint à la citerne; et voici, Joseph n''''était plus dans la citerne. Il déchira ses vêtements,"}, {"numero": 30, "texto": "retourna vers ses frères, et dit: L''''enfant n''''y est plus! Et moi, où irai-je?"}, {"numero": 31, "texto": "Ils prirent alors la tunique de Joseph; et, ayant tué un bouc, ils plongèrent la tunique dans le sang."}, {"numero": 32, "texto": "Ils envoyèrent à leur père la tunique de plusieurs couleurs, en lui faisant dire: Voici ce que nous avons trouvé! reconnais si c''''est la tunique de ton fils, ou non."}, {"numero": 33, "texto": "Jacob la reconnut, et dit: C''''est la tunique de mon fils! une bête féroce l''''a dévoré! Joseph a été mis en pièces!"}, {"numero": 34, "texto": "Et il déchira ses vêtements, il mit un sac sur ses reins, et il porta longtemps le deuil de son fils."}, {"numero": 35, "texto": "Tous ses fils et toutes ses filles vinrent pour le consoler; mais il ne voulut recevoir aucune consolation. Il disait: C''''est en pleurant que je descendrai vers mon fils au séjour des morts! Et il pleurait son fils."}, {"numero": 36, "texto": "Les Madianites le vendirent en Egypte à Potiphar, officier de Pharaon, chef des gardes."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 37, 'es', '[{"numero": 1, "texto": "Y HABITÓ Jacob en la tierra donde peregrinó su padre, en la tierra de Canaán."}, {"numero": 2, "texto": "Estas fueron las generaciones de Jacob. José, siendo de edad de diez y siete años apacentaba las ovejas con sus hermanos; y el joven estaba con los hijos de Bilha, y con los hijos de Zilpa, mujeres de su padre: y noticiaba José á su padre la mala fama de ellos."}, {"numero": 3, "texto": "Y amaba Israel á José más que á todos sus hijos, porque le había tenido en su vejez: y le hizo una ropa de diversos colores."}, {"numero": 4, "texto": "Y viendo sus hermanos que su padre lo amaba más que á todos sus hermanos, aborrecíanle, y no le podían hablar pacíficamente."}, {"numero": 5, "texto": "Y soñó José un sueño, y contólo á sus hermanos; y ellos vinieron á aborrecerle más todavía."}, {"numero": 6, "texto": "Y él les dijo: Oíd ahora este sueño que he soñado:"}, {"numero": 7, "texto": "He aquí que atábamos manojos en medio del campo, y he aquí que mi manojo se levantaba, y estaba derecho, y que vuestros manojos estaban alrededor, y se inclinaban al mío."}, {"numero": 8, "texto": "Y respondiéronle sus hermanos: ¿Has de reinar tú sobre nosotros, ó te has de enseñorear sobre nosotros? Y le aborrecieron aún más á causa de sus sueños y de sus palabras."}, {"numero": 9, "texto": "Y soñó aún otro sueño, y contólo á sus hermanos, diciendo: He aquí que he soñado otro sueño, y he aquí que el sol y la luna y once estrellas se inclinaban á mí."}, {"numero": 10, "texto": "Y contólo á su padre y á sus hermanos: y su padre le reprendió, y díjole: ¿Qué sueño es este que soñaste? ¿Hemos de venir yo y tu madre, y tus hermanos, á inclinarnos á ti á tierra?"}, {"numero": 11, "texto": "Y sus hermanos le tenían envidia, mas su padre paraba la consideración en ello."}, {"numero": 12, "texto": "Y fueron sus hermanos á apacentar las ovejas de su padre en Sichêm."}, {"numero": 13, "texto": "Y dijo Israel á José: Tus hermanos apacientan las ovejas en Sichêm: ven, y te enviaré á ellos. Y él respondió: Heme aquí."}, {"numero": 14, "texto": "Y él le dijo: Ve ahora, mira cómo están tus hermanos y cómo están las ovejas, y tráeme la respuesta. Y enviólo del valle de Hebrón, y llegó á Sichêm."}, {"numero": 15, "texto": "Y hallólo un hombre, andando él perdido por el campo, y preguntóle aquel hombre, diciendo: ¿Qué buscas?"}, {"numero": 16, "texto": "Y él respondió: Busco á mis hermanos: ruégote que me muestres dónde pastan."}, {"numero": 17, "texto": "Y aquel hombre respondió: Ya se han ido de aquí; y yo les oí decir: Vamos á Dothán. Entonces José fué tras de sus hermanos, y hallólos en Dothán."}, {"numero": 18, "texto": "Y como ellos lo vieron de lejos, antes que cerca de ellos llegara, proyectaron contra él para matarle."}, {"numero": 19, "texto": "Y dijeron el uno al otro: He aquí viene el soñador;"}, {"numero": 20, "texto": "Ahora pues, venid, y matémoslo y echémosle en una cisterna, y diremos: Alguna mala bestia le devoró: y veremos qué serán sus sueños."}, {"numero": 21, "texto": "Y como Rubén oyó esto, librólo de sus manos, y dijo: No lo matemos."}, {"numero": 22, "texto": "Y díjoles Rubén: No derraméis sangre; echadlo en esta cisterna que está en el desierto, y no pongáis mano en él; por librarlo así de sus manos, para hacerlo volver á su padre."}, {"numero": 23, "texto": "Y sucedió que, cuando llegó José á sus hermanos, ellos hicieron desnudar á José su ropa, la ropa de colores que tenía sobre sí;"}, {"numero": 24, "texto": "Y tomáronlo, y echáronle en la cisterna; mas la cisterna estaba vacía, no había en ella agua."}, {"numero": 25, "texto": "Y sentáronse á comer pan: y alzando los ojos miraron, y he aquí una compañía de Ismaelitas que venía de Galaad, y sus camellos traían aromas y bálsamo y mirra, é iban á llevarlo á Egipto."}, {"numero": 26, "texto": "Entonces Judá dijo á sus hermanos: ¿Qué provecho el que matemos á nuestro hermano y encubramos su muerte?"}, {"numero": 27, "texto": "Venid, y vendámosle á los Ismaelitas, y no sea nuestra mano sobre él; que nuestro hermano es nuestra carne. Y sus hermanos acordaron con él."}, {"numero": 28, "texto": "Y como pasaban los Midianitas mercaderes, sacaron ellos á José de la cisterna, y trajéronle arriba, y le vendieron á los Ismaelitas por veinte piezas de plata. Y llevaron á José á Egipto."}, {"numero": 29, "texto": "Y Rubén volvió á la cisterna, y no halló á José dentro, y rasgó sus vestidos."}, {"numero": 30, "texto": "Y tornó á sus hermanos, y dijo: El mozo no parece; y yo, ¿adónde iré yo?"}, {"numero": 31, "texto": "Entonces tomaron ellos la ropa de José, y degollaron un cabrito de las cabras, y tiñeron la ropa con la sangre;"}, {"numero": 32, "texto": "Y enviaron la ropa de colores y trajéronla á su padre, y dijeron: Esta hemos hallado, reconoce ahora si es ó no la ropa de tu hijo."}, {"numero": 33, "texto": "Y él la conoció, y dijo: La ropa de mi hijo es; alguna mala bestia le devoró; José ha sido despedazado."}, {"numero": 34, "texto": "Entonces Jacob rasgó sus vestidos, y puso saco sobre sus lomos, y enlutóse por su hijo muchos días."}, {"numero": 35, "texto": "Y levantáronse todos sus hijos y todas sus hijas para consolarlo; mas él no quiso tomar consolación, y dijo: Porque yo tengo de descender á mi hijo enlutado hasta la sepultura. Y llorólo su padre."}, {"numero": 36, "texto": "Y los Midianitas lo vendieron en Egipto á Potiphar, eunuco de Faraón, capitán de los de la guardia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 39, 'pt', '[{"numero": 1, "texto": "E levado José ao Egito, comprou-o Potifar, oficial de Faraó, capitão dos da guarda, homem egípcio, da mão dos ismaelitas que o haviam levado ali."}, {"numero": 2, "texto": "Mas o SENHOR foi com José, e foi homem próspero: e estava na casa de seu senhor o egípcio."}, {"numero": 3, "texto": "E viu seu senhor que o SENHOR era com ele, e que tudo o que ele fazia, o SENHOR o fazia prosperar em sua mão."}, {"numero": 4, "texto": "Assim achou José favor em seus olhos, e servia-lhe; e ele lhe fez mordomo de sua casa, e entregou em seu poder tudo o que tinha."}, {"numero": 5, "texto": "E aconteceu que, desde quando lhe deu o encargo de sua casa, e de tudo o que tinha, o SENHOR abençoou a casa do egípcio por causa de José; e a bênção do SENHOR foi sobre tudo o que tinha, tanto em casa como no campo."}, {"numero": 6, "texto": "E deixou tudo o que tinha em mão de José; nem com ele sabia de nada mais que do pão que comia. E era José de belo semblante e bela presença."}, {"numero": 7, "texto": "E aconteceu depois disto, que a mulher de seu senhor pôs seus olhos em José, e disse: Dorme comigo."}, {"numero": 8, "texto": "E ele não quis, e disse à mulher de seu senhor: Eis que meu senhor não sabe comigo o que há em casa, e pôs em minha mão tudo o que tem:"}, {"numero": 9, "texto": "Não há outro maior que eu nesta casa, e nenhuma coisa me há reservado a não ser a ti, porquanto tu és sua mulher; como, pois, faria eu este grande mal e pecaria contra Deus?"}, {"numero": 10, "texto": "E foi que falando ela a José cada dia, e não escutando-a ele para deitar-se ao lado dela, para estar com ela."}, {"numero": 11, "texto": "Aconteceu que entrou ele um dia em casa para fazer seu ofício, e não havia ninguém dos da casa ali em casa."}, {"numero": 12, "texto": "E pegou-o ela por sua roupa, dizendo: Dorme comigo. Então ele deixou sua roupa nas mãos dela, e fugiu, e saiu-se fora."}, {"numero": 13, "texto": "E aconteceu que quando viu ela que lhe havia deixado sua roupa em suas mãos, e havia fugido fora,"}, {"numero": 14, "texto": "Chamou aos de casa, e falou-lhes dizendo: Olhai que ele nos trouxe um hebreu, para que fizesse zombaria de nós: veio ele a mim para dormir comigo, e eu dei grandes vozes;"}, {"numero": 15, "texto": "E vendo que eu erguia a voz e gritava, deixou junto a mim sua roupa, e fugiu, e saiu-se fora."}, {"numero": 16, "texto": "E ela pôs junto a si a roupa dele, até que veio seu senhor à sua casa."}, {"numero": 17, "texto": "Então lhe falou ela semelhantes palavras, dizendo: O servo hebreu que nos trouxeste, veio a mim para desonrar-me;"}, {"numero": 18, "texto": "E quando eu levantei minha voz e gritei, ele deixou sua roupa junto a mim, e fugiu fora."}, {"numero": 19, "texto": "E sucedeu que quando ouviu seu senhor as palavras que sua mulher lhe falara, dizendo: Assim me tratou teu servo; acendeu-se seu furor."}, {"numero": 20, "texto": "E tomou seu senhor a José, e pôs-lhe na casa do cárcere, onde estavam os presos do rei, e esteve ali na casa do cárcere."}, {"numero": 21, "texto": "Mas o SENHOR foi com José, e estendeu a ele sua misericórdia, e deu-lhe favor aos olhos do chefe da casa do cárcere."}, {"numero": 22, "texto": "E o chefe da casa do cárcere entregou em mão de José todos os presos que havia naquela prisão; tudo o que faziam ali, ele o fazia."}, {"numero": 23, "texto": "Não via o chefe do cárcere coisa alguma que em sua mão estava; porque o SENHOR era com ele, e o que ele fazia, o SENHOR o fazia prosperar."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 39, 'en', '[{"numero": 1, "texto": "And Joseph was brought down to Egypt; and Potiphar, an officer of Pharaoh, captain of the guard, an Egyptian, bought him of the hands of the Ishmeelites, which had brought him down thither."}, {"numero": 2, "texto": "And the Lord was with Joseph, and he was a prosperous man; and he was in the house of his master the Egyptian."}, {"numero": 3, "texto": "And his master saw that the Lord was with him, and that the Lord made all that he did to prosper in his hand."}, {"numero": 4, "texto": "And Joseph found grace in his sight, and he served him: and he made him overseer over his house, and all that he had he put into his hand."}, {"numero": 5, "texto": "And it came to pass from the time that he had made him overseer in his house, and over all that he had, that the Lord blessed the Egyptian''s house for Joseph''s sake; and the blessing of the Lord was upon all that he had in the house, and in the field."}, {"numero": 6, "texto": "And he left all that he had in Joseph''s hand; and he knew not ought he had, save the bread which he did eat. And Joseph was a goodly person, and well favoured."}, {"numero": 7, "texto": "And it came to pass after these things, that his master''s wife cast her eyes upon Joseph; and she said, Lie with me."}, {"numero": 8, "texto": "But he refused, and said unto his master''s wife, Behold, my master wotteth not what is with me in the house, and he hath committed all that he hath to my hand;"}, {"numero": 9, "texto": "There is none greater in this house than I; neither hath he kept back any thing from me but thee, because thou art his wife: how then can I do this great wickedness, and sin against God?"}, {"numero": 10, "texto": "And it came to pass, as she spake to Joseph day by day, that he hearkened not unto her, to lie by her, or to be with her."}, {"numero": 11, "texto": "And it came to pass about this time, that Joseph went into the house to do his business; and there was none of the men of the house there within."}, {"numero": 12, "texto": "And she caught him by his garment, saying, Lie with me: and he left his garment in her hand, and fled, and got him out."}, {"numero": 13, "texto": "And it came to pass, when she saw that he had left his garment in her hand, and was fled forth,"}, {"numero": 14, "texto": "That she called unto the men of her house, and spake unto them, saying, See, he hath brought in an Hebrew unto us to mock us; he came in unto me to lie with me, and I cried with a loud voice:"}, {"numero": 15, "texto": "And it came to pass, when he heard that I lifted up my voice and cried, that he left his garment with me, and fled, and got him out."}, {"numero": 16, "texto": "And she laid up his garment by her, until his lord came home."}, {"numero": 17, "texto": "And she spake unto him according to these words, saying, The Hebrew servant, which thou hast brought unto us, came in unto me to mock me:"}, {"numero": 18, "texto": "And it came to pass, as I lifted up my voice and cried, that he left his garment with me, and fled out."}, {"numero": 19, "texto": "And it came to pass, when his master heard the words of his wife, which she spake unto him, saying, After this manner did thy servant to me; that his wrath was kindled."}, {"numero": 20, "texto": "And Joseph''s master took him, and put him into the prison, a place where the king''s prisoners were bound: and he was there in the prison."}, {"numero": 21, "texto": "But the Lord was with Joseph, and shewed him mercy, and gave him favour in the sight of the keeper of the prison."}, {"numero": 22, "texto": "And the keeper of the prison committed to Joseph''s hand all the prisoners that were in the prison; and whatsoever they did there, he was the doer of it."}, {"numero": 23, "texto": "The keeper of the prison looked not to any thing that was under his hand; because the Lord was with him, and that which he did, the Lord made it to prosper."}]'::jsonb, 'King James Version'),
  ('Gn', 39, 'fr', '[{"numero": 1, "texto": "On fit descendre Joseph en Egypte; et Potiphar, officier de Pharaon, chef des gardes, Egyptien, l''''acheta des Ismaélites qui l''''y avaient fait descendre."}, {"numero": 2, "texto": "L''''Eternel fut avec lui, et la prospérité l''''accompagna; il habitait dans la maison de son maître, l''''Egyptien."}, {"numero": 3, "texto": "Son maître vit que l''''Eternel était avec lui, et que l''''Eternel faisait prospérer entre ses mains tout ce qu''''il entreprenait."}, {"numero": 4, "texto": "Joseph trouva grâce aux yeux de son maître, qui l''''employa à son service, l''''établit sur sa maison, et lui confia tout ce qu''''il possédait."}, {"numero": 5, "texto": "Dès que Potiphar l''''eut établi sur sa maison et sur tout ce qu''''il possédait, l''''Eternel bénit la maison de l''''Egyptien, à cause de Joseph; et la bénédiction de l''''Eternel fut sur tout ce qui lui appartenait, soit à la maison, soit aux champs."}, {"numero": 6, "texto": "Il abandonna aux mains de Joseph tout ce qui lui appartenait, et il n''''avait avec lui d''''autre soin que celui de prendre sa nourriture. Or, Joseph était beau de taille et beau de figure."}, {"numero": 7, "texto": "Après ces choses, il arriva que la femme de son maître porta les yeux sur Joseph, et dit: Couche avec moi!"}, {"numero": 8, "texto": "Il refusa, et dit à la femme de son maître: Voici, mon maître ne prend avec moi connaissance de rien dans la maison, et il a remis entre mes mains tout ce qui lui appartient."}, {"numero": 9, "texto": "Il n''''est pas plus grand que moi dans cette maison, et il ne m''''a rien interdit, excepté toi, parce que tu es sa femme. Comment ferais-je un aussi grand mal et pécherais-je contre Dieu?"}, {"numero": 10, "texto": "Quoiqu''''elle parlât tous les jours à Joseph, il refusa de coucher auprès d''''elle, d''''être avec elle."}, {"numero": 11, "texto": "Un jour qu''''il était entré dans la maison pour faire son ouvrage, et qu''''il n''''y avait là aucun des gens de la maison,"}, {"numero": 12, "texto": "elle le saisit par son vêtement, en disant: Couche avec moi! Il lui laissa son vêtement dans la main, et s''''enfuit au dehors."}, {"numero": 13, "texto": "Lorsqu''''elle vit qu''''il lui avait laissé son vêtement dans la main, et qu''''il s''''était enfui dehors,"}, {"numero": 14, "texto": "elle appela les gens de sa maison, et leur dit: Voyez, il nous a amené un Hébreu pour se jouer de nous. Cet homme est venu vers moi pour coucher avec moi; mais j''''ai crié à haute voix."}, {"numero": 15, "texto": "Et quand il a entendu que j''''élevais la voix et que je criais, il a laissé son vêtement à côté de moi et s''''est enfui dehors."}, {"numero": 16, "texto": "Et elle posa le vêtement de Joseph à côté d''''elle, jusqu''''à ce que son maître rentrât à la maison."}, {"numero": 17, "texto": "Alors elle lui parla ainsi: L''''esclave hébreu que tu nous as amené est venu vers moi pour se jouer de moi."}, {"numero": 18, "texto": "Et comme j''''ai élevé la voix et que j''''ai crié, il a laissé son vêtement à côté de moi et s''''est enfui dehors."}, {"numero": 19, "texto": "Après avoir entendu les paroles de sa femme, qui lui disait: Voilà ce que m''''a fait ton esclave! le maître de Joseph fut enflammé de colère."}, {"numero": 20, "texto": "Il prit Joseph, et le mit dans la prison, dans le lieu où les prisonniers du roi étaient enfermés: il fut là, en prison."}, {"numero": 21, "texto": "L''''Eternel fut avec Joseph, et il étendit sur lui sa bonté. Il le mit en faveur aux yeux du chef de la prison."}, {"numero": 22, "texto": "Et le chef de la prison plaça sous sa surveillance tous les prisonniers qui étaient dans la prison; et rien ne s''''y faisait que par lui."}, {"numero": 23, "texto": "Le chef de la prison ne prenait aucune connaissance de ce que Joseph avait en main, parce que l''''Eternel était avec lui. Et l''''Eternel donnait de la réussite à ce qu''''il faisait."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 39, 'es', '[{"numero": 1, "texto": "Y LLEVADO José á Egipto, comprólo Potiphar, eunuco de Faraón, capitán de los de la guardia, varón Egipcio, de mano de los Ismaelitas que lo habían llevado allá."}, {"numero": 2, "texto": "Mas Jehová fué con José, y fué varón prosperado: y estaba en la casa de su señor el Egipcio."}, {"numero": 3, "texto": "Y vió su señor que Jehová era con él, y que todo lo que él hacía, Jehová lo hacía prosperar en su mano."}, {"numero": 4, "texto": "Así halló José gracia en sus ojos, y servíale; y él le hizo mayordomo de su casa, y entregó en su poder todo lo que tenía."}, {"numero": 5, "texto": "Y aconteció que, desde cuando le dió el encargo de su casa, y de todo lo que tenía, Jehová bendijo la casa del Egipcio á causa de José; y la bendición de Jehová fué sobre todo lo que tenía, así en casa como en el campo."}, {"numero": 6, "texto": "Y dejó todo lo que tenía en mano de José; ni con él sabía de nada más que del pan que comía. Y era José de hermoso semblante y bella presencia."}, {"numero": 7, "texto": "Y aconteció después de esto, que la mujer de su señor puso sus ojos en José, y dijo: Duerme conmigo."}, {"numero": 8, "texto": "Y él no quiso, y dijo á la mujer de su señor: He aquí que mi señor no sabe conmigo lo que hay en casa, y ha puesto en mi mano todo lo que tiene:"}, {"numero": 9, "texto": "No hay otro mayor que yo en esta casa, y ninguna cosa me ha reservado sino á ti, por cuanto tú eres su mujer; ¿cómo, pues, haría yo este grande mal, y pecaría contra Dios?"}, {"numero": 10, "texto": "Y fué que hablando ella á José cada día, y no escuchándola él para acostarse al lado de ella, para estar con ella,"}, {"numero": 11, "texto": "Aconteció que entró él un día en casa para hacer su oficio, y no había nadie de los de casa allí en casa:"}, {"numero": 12, "texto": "Y asiólo ella por su ropa, diciendo: Duerme conmigo. Entonces dejóla él su ropa en las manos, y huyó, y salióse fuera."}, {"numero": 13, "texto": "Y acaeció que cuando vió ella que le había dejado su ropa en sus manos, y había huído fuera,"}, {"numero": 14, "texto": "Llamó á los de casa, y hablóles diciendo: Mirad, nos ha traído un Hebreo, para que hiciese burla de nosotros: vino él á mí para dormir conmigo, y yo dí grandes voces;"}, {"numero": 15, "texto": "Y viendo que yo alzaba la voz y gritaba, dejó junto á mí su ropa, y huyó, y salióse fuera."}, {"numero": 16, "texto": "Y ella puso junto á sí la ropa de él, hasta que vino su señor á su casa."}, {"numero": 17, "texto": "Entonces le habló ella semejantes palabras, diciendo: El siervo Hebreo que nos trajiste, vino á mí para deshonrarme;"}, {"numero": 18, "texto": "Y como yo alcé mi voz y grité, él dejó su ropa junto á mí, y huyó fuera."}, {"numero": 19, "texto": "Y sucedió que como oyó su señor las palabras que su mujer le hablara, diciendo: Así me ha tratado tu siervo; encendióse su furor."}, {"numero": 20, "texto": "Y tomó su señor á José, y púsole en la casa de la cárcel, donde estaban los presos del rey, y estuvo allí en la casa de la cárcel."}, {"numero": 21, "texto": "Mas Jehová fué con José, y extendió á él su misericordia, y dióle gracia en ojos del principal de la casa de la cárcel."}, {"numero": 22, "texto": "Y el principal de la casa de la cárcel entregó en mano de José todos los presos que había en aquella prisión; todo lo que hacían allí, él lo hacía."}, {"numero": 23, "texto": "No veía el principal de la cárcel cosa alguna que en su mano estaba; porque Jehová era con él, y lo que él hacía, Jehová lo prosperaba."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 40, 'pt', '[{"numero": 1, "texto": "E aconteceu depois destas coisas, que o copeiro do rei do Egito e o padeiro transgrediram contra seu senhor o rei do Egito."}, {"numero": 2, "texto": "E irou-se Faraó contra seus dois eunucos, contra o principal dos copeiros, e contra o principal dos padeiros:"}, {"numero": 3, "texto": "E os pôs em prisão na casa do capitão dos da guarda, na casa do cárcere onde José estava preso."}, {"numero": 4, "texto": "E o capitão dos da guarda deu responsabilidade deles a José, e ele lhes servia: e estiveram dias na prisão."}, {"numero": 5, "texto": "E ambos, o copeiro e o padeiro do rei do Egito, que estavam detidos na prisão, viram um sonho, cada um seu sonho em uma mesma noite, cada um conforme a declaração de seu sonho."}, {"numero": 6, "texto": "E veio a eles José pela manhã, e olhou-os, e eis que estavam tristes."}, {"numero": 7, "texto": "E ele perguntou àqueles oficiais de Faraó, que estavam com ele na prisão da casa de seu senhor, dizendo: Por que parecem hoje mal vossos semblantes?"}, {"numero": 8, "texto": "E eles lhe disseram: Tivemos um sonho, e não há quem o declare. Então lhes disse José: Não são de Deus as interpretações? Contai-o a mim agora."}, {"numero": 9, "texto": "Então o chefe dos copeiros contou seu sonho a José, e disse-lhe: Eu sonhava que via uma vide diante de mim,"}, {"numero": 10, "texto": "E na vide três sarmentos; e ela como que brotava, e surgia sua flor, vindo a amadurecer seus cachos de uvas:"}, {"numero": 11, "texto": "E que o copo de Faraó estava em minha mão, e tomava eu as uvas, e as espremia no copo de Faraó, e dava eu o copo em mão de Faraó."}, {"numero": 12, "texto": "E disse-lhe José: Esta é sua declaração: Os três sarmentos são três dias:"}, {"numero": 13, "texto": "Ao fim de três dias Faraó te fará levantar a cabeça, e te restituirá a teu posto: e darás o copo a Faraó em sua mão, como costumavas quando eras seu copeiro."}, {"numero": 14, "texto": "Lembra-te, pois, de mim para contigo quando tiveres esse bem, e rogo-te que uses comigo de misericórdia, e faças menção de mim a Faraó, e me tires desta prisão:"}, {"numero": 15, "texto": "Porque furtado fui da terra dos hebreus; e tampouco fiz aqui para que me houvessem de pôr no cárcere."}, {"numero": 16, "texto": "E vendo o chefe dos padeiros que havia interpretado para o bem, disse a José: Também eu sonhava que via três cestos brancos sobre minha cabeça;"}, {"numero": 17, "texto": "E no cesto mais alto havia de todos os alimentos de Faraó, obra de padeiro; e que as aves as comiam do cesto de sobre minha cabeça."}, {"numero": 18, "texto": "Então respondeu José, e disse: Esta é sua declaração: Os três cestos três dias são;"}, {"numero": 19, "texto": "Ao fim de três dias tirará Faraó tua cabeça de sobre ti, e te fará enforcar na forca, e as aves comerão tua carne de sobre ti."}, {"numero": 20, "texto": "E foi o terceiro dia o dia do aniversário de Faraó, e fez banquete a todos os seus servos: e levantou a cabeça do chefe dos copeiros, e a cabeça do chefe dos padeiros, entre seus servos."}, {"numero": 21, "texto": "E fez voltar a seu ofício ao chefe dos copeiros; e deu ele o copo em mão de Faraó."}, {"numero": 22, "texto": "Mas fez enforcar ao principal dos padeiros, como lhe havia declarado José."}, {"numero": 23, "texto": "E o chefe dos copeiros não se lembrou de José, ao invés disso lhe esqueceu."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 40, 'en', '[{"numero": 1, "texto": "And it came to pass after these things, that the butler of the king of Egypt and his baker had offended their lord the king of Egypt."}, {"numero": 2, "texto": "And Pharaoh was wroth against two of his officers, against the chief of the butlers, and against the chief of the bakers."}, {"numero": 3, "texto": "And he put them in ward in the house of the captain of the guard, into the prison, the place where Joseph was bound."}, {"numero": 4, "texto": "And the captain of the guard charged Joseph with them, and he served them: and they continued a season in ward."}, {"numero": 5, "texto": "And they dreamed a dream both of them, each man his dream in one night, each man according to the interpretation of his dream, the butler and the baker of the king of Egypt, which were bound in the prison."}, {"numero": 6, "texto": "And Joseph came in unto them in the morning, and looked upon them, and, behold, they were sad."}, {"numero": 7, "texto": "And he asked Pharaoh''s officers that were with him in the ward of his lord''s house, saying, Wherefore look ye so sadly to day?"}, {"numero": 8, "texto": "And they said unto him, We have dreamed a dream, and there is no interpreter of it. And Joseph said unto them, Do not interpretations belong to God? tell me them, I pray you."}, {"numero": 9, "texto": "And the chief butler told his dream to Joseph, and said to him, In my dream, behold, a vine was before me;"}, {"numero": 10, "texto": "And in the vine were three branches: and it was as though it budded, and her blossoms shot forth; and the clusters thereof brought forth ripe grapes:"}, {"numero": 11, "texto": "And Pharaoh''s cup was in my hand: and I took the grapes, and pressed them into Pharaoh''s cup, and I gave the cup into Pharaoh''s hand."}, {"numero": 12, "texto": "And Joseph said unto him, This is the interpretation of it: The three branches are three days:"}, {"numero": 13, "texto": "Yet within three days shall Pharaoh lift up thine head, and restore thee unto thy place: and thou shalt deliver Pharaoh''s cup into his hand, after the former manner when thou wast his butler."}, {"numero": 14, "texto": "But think on me when it shall be well with thee, and shew kindness, I pray thee, unto me, and make mention of me unto Pharaoh, and bring me out of this house:"}, {"numero": 15, "texto": "For indeed I was stolen away out of the land of the Hebrews: and here also have I done nothing that they should put me into the dungeon."}, {"numero": 16, "texto": "When the chief baker saw that the interpretation was good, he said unto Joseph, I also was in my dream, and, behold, I had three white baskets on my head:"}, {"numero": 17, "texto": "And in the uppermost basket there was of all manner of bakemeats for Pharaoh; and the birds did eat them out of the basket upon my head."}, {"numero": 18, "texto": "And Joseph answered and said, This is the interpretation thereof: The three baskets are three days:"}, {"numero": 19, "texto": "Yet within three days shall Pharaoh lift up thy head from off thee, and shall hang thee on a tree; and the birds shall eat thy flesh from off thee."}, {"numero": 20, "texto": "And it came to pass the third day, which was Pharaoh''s birthday, that he made a feast unto all his servants: and he lifted up the head of the chief butler and of the chief baker among his servants."}, {"numero": 21, "texto": "And he restored the chief butler unto his butlership again; and he gave the cup into Pharaoh''s hand:"}, {"numero": 22, "texto": "But he hanged the chief baker: as Joseph had interpreted to them."}, {"numero": 23, "texto": "Yet did not the chief butler remember Joseph, but forgat him."}]'::jsonb, 'King James Version'),
  ('Gn', 40, 'fr', '[{"numero": 1, "texto": "Après ces choses, il arriva que l''''échanson et le panetier du roi d''''Egypte, offensèrent leur maître, le roi d''''Egypte."}, {"numero": 2, "texto": "Pharaon fut irrité contre ses deux officiers, le chef des échansons et le chef des panetiers."}, {"numero": 3, "texto": "Et il les fit mettre dans la maison du chef des gardes, dans la prison, dans le lieu où Joseph était enfermé."}, {"numero": 4, "texto": "Le chef des gardes les plaça sous la surveillance de Joseph, qui faisait le service auprès d''''eux; et ils passèrent un certain temps en prison."}, {"numero": 5, "texto": "Pendant une même nuit, l''''échanson et le panetier du roi d''''Egypte, qui étaient enfermés dans la prison, eurent tous les deux un songe, chacun le sien, pouvant recevoir une explication distincte."}, {"numero": 6, "texto": "Joseph, étant venu le matin vers eux, les regarda; et voici, ils étaient tristes."}, {"numero": 7, "texto": "Alors il questionna les officiers de Pharaon, qui étaient avec lui dans la prison de son maître, et il leur dit: Pourquoi avez-vous mauvais visage aujourd''''hui?"}, {"numero": 8, "texto": "Ils lui répondirent: Nous avons eu un songe, et il n''''y a personne pour l''''expliquer. Joseph leur dit: N''''est-ce pas à Dieu qu''''appartiennent les explications? Racontez-moi donc votre songe."}, {"numero": 9, "texto": "Le chef des échansons raconta son songe à Joseph, et lui dit: Dans mon songe, voici, il y avait un cep devant moi."}, {"numero": 10, "texto": "Ce cep avait trois sarments. Quand il eut poussé, sa fleur se développa et ses grappes donnèrent des raisins mûrs."}, {"numero": 11, "texto": "La coupe de Pharaon était dans ma main. Je pris les raisins, je les pressai dans la coupe de Pharaon, et je mis la coupe dans la main de Pharaon."}, {"numero": 12, "texto": "Joseph lui dit: En voici l''''explication. Les trois sarments sont trois jours."}, {"numero": 13, "texto": "Encore trois jours, et Pharaon relèvera ta tête et te rétablira dans ta charge; tu mettras la coupe dans la main de Pharaon, comme tu en avais l''''habitude lorsque tu étais son échanson."}, {"numero": 14, "texto": "Mais souviens-toi de moi, quand tu seras heureux, et montre, je te prie, de la bonté à mon égard; parle en ma faveur à Pharaon, et fais-moi sortir de cette maison."}, {"numero": 15, "texto": "Car j''''ai été enlevé du pays des Hébreux, et ici même je n''''ai rien fait pour être mis en prison."}, {"numero": 16, "texto": "Le chef des panetiers, voyant que Joseph avait donné une explication favorable, dit: Voici, il y avait aussi, dans mon songe, trois corbeilles de pain blanc sur ma tête."}, {"numero": 17, "texto": "Dans la corbeille la plus élevée il y avait pour Pharaon des mets de toute espèce, cuits au four; et les oiseaux les mangeaient dans la corbeille au-dessus de ma tête."}, {"numero": 18, "texto": "Joseph répondit, et dit: En voici l''''explication. Les trois corbeilles sont trois jours."}, {"numero": 19, "texto": "Encore trois jours, et Pharaon enlèvera ta tête de dessus toi, te fera pendre à un bois, et les oiseaux mangeront ta chair."}, {"numero": 20, "texto": "Le troisième jour, jour de la naissance de Pharaon, il fit un festin à tous ses serviteurs; et il éleva la tête du chef des échansons et la tête du chef des panetiers, au milieu de ses serviteurs:"}, {"numero": 21, "texto": "il rétablit le chef des échansons dans sa charge d''''échanson, pour qu''''il mît la coupe dans la main de Pharaon;"}, {"numero": 22, "texto": "mais il fit pendre le chef des panetiers, selon l''''explication que Joseph leur avait donnée."}, {"numero": 23, "texto": "Le chef des échansons ne pensa plus à Joseph. Il l''''oublia."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 40, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después de estas cosas, que el copero del rey de Egipto y el panadero delinquieron contra su señor el rey de Egipto."}, {"numero": 2, "texto": "Y enojóse Faraón contra sus dos eunucos, contra el principal de los coperos, y contra el principal de los panaderos:"}, {"numero": 3, "texto": "Y púsolos en prisión en la casa del capitán de los de la guardia, en la casa de la cárcel donde José estaba preso."}, {"numero": 4, "texto": "Y el capitán de los de la guardia dió cargo de ellos á José, y él les servía: y estuvieron días en la prisión."}, {"numero": 5, "texto": "Y ambos á dos, el copero y el panadero del rey de Egipto, que estaban arrestados en la prisión, vieron un sueño, cada uno su sueño en una misma noche, cada uno conforme á la declaración de su sueño."}, {"numero": 6, "texto": "Y vino á ellos José por la mañana, y mirólos, y he aquí que estaban tristes."}, {"numero": 7, "texto": "Y él preguntó á aquellos eunucos de Faraón, que estaban con él en la prisión de la casa de su señor, diciendo: ¿Por qué parecen hoy mal vuestros semblantes?"}, {"numero": 8, "texto": "Y ellos le dijeron: Hemos tenido un sueño, y no hay quien lo declare. Entonces les dijo José: ¿No son de Dios las declaraciones? Contádmelo ahora."}, {"numero": 9, "texto": "Entonces el principal de los coperos contó su sueño á José, y díjole: Yo soñaba que veía una vid delante de mí,"}, {"numero": 10, "texto": "Y en la vid tres sarmientos; y ella como que brotaba, y arrojaba su flor, viniendo á madurar sus racimos de uvas:"}, {"numero": 11, "texto": "Y que la copa de Faraón estaba en mi mano, y tomaba yo las uvas, y las exprimía en la copa de Faraón, y daba yo la copa en mano de Faraón."}, {"numero": 12, "texto": "Y díjole José: Esta es su declaración: Los tres sarmientos son tres días:"}, {"numero": 13, "texto": "Al cabo de tres días Faraón te hará levantar cabeza, y te restituirá á tu puesto: y darás la copa á Faraón en su mano, como solías cuando eras su copero."}, {"numero": 14, "texto": "Acuérdate, pues, de mí para contigo cuando tuvieres ese bien, y ruégote que uses conmigo de misericordia, y hagas mención de mí á Faraón, y me saques de esta casa:"}, {"numero": 15, "texto": "Porque hurtado he sido de la tierra de los Hebreos; y tampoco he hecho aquí porqué me hubiesen de poner en la cárcel."}, {"numero": 16, "texto": "Y viendo el principal de los panaderos que había declarado para bien, dijo á José: También yo soñaba que veía tres canastillos blancos sobre mi cabeza;"}, {"numero": 17, "texto": "Y en el canastillo más alto había de todas las viandas de Faraón, obra de panadero; y que las aves las comían del canastillo de sobre mi cabeza."}, {"numero": 18, "texto": "Entonces respondió José, y dijo: Esta es su declaración: Los tres canastillos tres días son;"}, {"numero": 19, "texto": "Al cabo de tres días quitará Faraón tu cabeza de sobre ti, y te hará colgar en la horca, y las aves comerán tu carne de sobre ti."}, {"numero": 20, "texto": "Y fué el tercero día el día del nacimiento de Faraón, é hizo banquete á todos sus sirvientes: y alzó la cabeza del principal de los coperos, y la cabeza del principal de los panaderos, entre sus servidores."}, {"numero": 21, "texto": "E hizo volver á su oficio al principal de los coperos; y dió él la copa en mano de Faraón."}, {"numero": 22, "texto": "Mas hizo ahorcar al principal de los panaderos, como le había declarado José."}, {"numero": 23, "texto": "Y el principal de los coperos no se acordó de José, sino que le olvidó."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 41, 'pt', '[{"numero": 1, "texto": "E aconteceu que passados dois anos teve Faraó um sonho: Parecia-lhe que estava junto ao rio;"}, {"numero": 2, "texto": "E que do rio subiam sete vacas, belas à vista, e muito gordas, e pastavam entre os juncos:"}, {"numero": 3, "texto": "E que outras sete vacas subiam depois delas do rio, de feia aparência, e magras de carne, e pararam perto das vacas belas à beira do rio;"}, {"numero": 4, "texto": "E que as vacas de feia aparência e magras de carne devoravam as sete vacas belas e muito gordas. E despertou Faraó."}, {"numero": 5, "texto": "Dormiu de novo, e sonhou a segunda vez: Que sete espigas cheias e belas subiam de uma só haste:"}, {"numero": 6, "texto": "E que outras sete espigas miúdas e abatidas do vento oriental, saíam depois delas:"}, {"numero": 7, "texto": "E as sete espigas miúdas devoravam as sete espigas espessas e cheias. E despertou Faraó, e eis que era sonho."}, {"numero": 8, "texto": "E aconteceu que à manhã estava movido seu espírito; e enviou e fez chamar a todos os magos do Egito, e a todos os seus sábios: e contou-lhes Faraó seus sonhos, mas não havia quem a Faraó os interpretasse."}, {"numero": 9, "texto": "Então o chefe dos copeiros falou a Faraó, dizendo: Lembro-me hoje de minhas faltas:"}, {"numero": 10, "texto": "Faraó se irou contra seus servos, e a mim me lançou à prisão da casa do capitão dos da guarda, a mim e ao chefe dos padeiros:"}, {"numero": 11, "texto": "E eu e ele vimos um sonho uma mesma noite: cada um sonhou conforme a interpretação de seu sonho."}, {"numero": 12, "texto": "E estava ali conosco um jovem hebreu, servente do capitão dos da guarda; e o contamos a ele, e ele nos interpretou nossos sonhos, e interpretou a cada um conforme seu sonho."}, {"numero": 13, "texto": "E aconteceu que como ele nos interpretou, assim foi: a mim me fez voltar a meu posto, e fez enforcar ao outro."}, {"numero": 14, "texto": "Então Faraó enviou e chamou a José; e fizeram-lhe sair correndo do cárcere; e ele rapou-se a barba, mudou-se de roupas, e veio a Faraó."}, {"numero": 15, "texto": "E disse Faraó a José: Eu tive um sonho, e não há quem o interprete; mas ouvi dizer de ti, que ouves sonhos para os interpretar."}, {"numero": 16, "texto": "E respondeu José a Faraó, dizendo: Não está em mim; Deus será o que responda paz a Faraó."}, {"numero": 17, "texto": "Então Faraó disse a José: Em meu sonho parecia-me que estava à beira do rio:"}, {"numero": 18, "texto": "E que do rio subiam sete vacas de gordas carnes e bela aparência, que pastavam entre os juncos:"}, {"numero": 19, "texto": "E que outras sete vacas subiam depois delas, magras e de muito feio aspecto; tão abatidas, que não vi outras semelhantes em toda a terra do Egito em feiura:"}, {"numero": 20, "texto": "E as vacas magras e feias devoravam as sete primeiras vacas gordas:"}, {"numero": 21, "texto": "E entravam em suas entranhas, mas não se conhecia que houvesse entrado nelas, porque sua aparência era ainda má, como de antes. E eu despertei."}, {"numero": 22, "texto": "Vi também sonhando, que sete espigas subiam em uma mesma haste, cheias e belas;"}, {"numero": 23, "texto": "E que outras sete espigas miúdas, definhadas, abatidas do vento oriental, subiam depois delas:"}, {"numero": 24, "texto": "E as espigas miúdas devoravam as sete espigas belas: e disse-o aos magos, mas não há quem o interprete a mim."}, {"numero": 25, "texto": "Então respondeu José a Faraó: O sonho de Faraó é um mesmo: Deus mostrou a Faraó o que vai fazer."}, {"numero": 26, "texto": "As sete vacas belas são sete anos, e as espigas belas são sete anos; o sonho é um mesmo."}, {"numero": 27, "texto": "Também as sete vacas magras e feias que subiam atrás elas, são sete anos; e as sete espigas miúdas e definhadas do vento oriental serão sete anos de fome."}, {"numero": 28, "texto": "Isto é o que respondo a Faraó. O que Deus vai fazer, mostrou-o a Faraó."}, {"numero": 29, "texto": "Eis que vêm sete anos de grande fartura toda a terra do Egito:"}, {"numero": 30, "texto": "E se levantarão depois eles sete anos de fome; e toda a fartura será esquecida na terra do Egito; e a fome consumirá a terra;"}, {"numero": 31, "texto": "E aquela abundância não mais será vista por causa da fome seguinte, a qual será gravíssima."}, {"numero": 32, "texto": "E o suceder o sonho a Faraó duas vezes, significa que a coisa é firme da parte de Deus, e que Deus se apressa a fazê-la."}, {"numero": 33, "texto": "Portanto, providencie Faraó agora um homem prudente e sábio, e ponha-o sobre a terra do Egito."}, {"numero": 34, "texto": "Faça isto Faraó, e ponha governadores sobre esta terra, e tome a quinta parte da terra do Egito nos sete anos da fartura;"}, {"numero": 35, "texto": "E juntem toda a provisão destes bons anos que vêm, e acumulem o trigo sob a mão de Faraó para mantimento das cidades; e guardem-no."}, {"numero": 36, "texto": "E esteja aquela provisão em depósito para esta terra, para os sete anos de fome que serão na terra do Egito; e esta terra não perecerá de fome."}, {"numero": 37, "texto": "E o negócio pareceu bem a Faraó, e a seus servos."}, {"numero": 38, "texto": "E disse Faraó a seus servos: Acharemos outro homem como este, em quem haja espírito de Deus?"}, {"numero": 39, "texto": "E disse Faraó a José: Pois que Deus te fez saber tudo isto, não há entendido nem sábio como tu:"}, {"numero": 40, "texto": "Tu serás sobre minha casa, e pelo que disseres se governará todo o meu povo; somente no trono serei eu maior que tu."}, {"numero": 41, "texto": "Disse mais Faraó a José: Eis que te pus sobre toda a terra do Egito."}, {"numero": 42, "texto": "Então Faraó tirou seu anel de sua mão, e o pôs na mão de José, e fez-lhe vestir de roupas de linho finíssimo, e pôs um colar de ouro em seu pescoço;"}, {"numero": 43, "texto": "E o fez subir em seu segundo carro, e proclamaram diante dele: Dobrai os joelhos; e pôs-lhe sobre toda a terra do Egito."}, {"numero": 44, "texto": "E disse Faraó a José: Eu sou Faraó; e sem ti ninguém levantará sua mão nem seu pé toda a terra do Egito."}, {"numero": 45, "texto": "E chamou Faraó o nome de José, Zefenate-Paneia; e deu-lhe por mulher a Azenate, filha de Potífera, sacerdote de Om. E saiu José por toda a terra do Egito."}, {"numero": 46, "texto": "E era José de idade de trinta anos quando foi apresentado diante de Faraó, rei do Egito: e saiu José de diante de Faraó, e transitou por toda a terra do Egito."}, {"numero": 47, "texto": "E fez a terra naqueles sete anos de fartura a amontoados."}, {"numero": 48, "texto": "E ele juntou todo o mantimento dos sete anos que foram na terra do Egito, e guardou mantimento nas cidades, pondo em cada cidade o mantimento do campo de seus arredores."}, {"numero": 49, "texto": "E ajuntou José trigo como areia do mar, muito em extremo, até não se poder contar, porque não tinha número."}, {"numero": 50, "texto": "E nasceram a José dois filhos antes que viesse o primeiro ano da fome, os quais lhe deu à luz Azenate, filha de Potífera, sacerdote de Om."}, {"numero": 51, "texto": "E chamou José o nome do primogênito Manassés; porque disse: Deus me fez esquecer todo o meu sofrimento, e toda a casa de meu pai."}, {"numero": 52, "texto": "E o nome do segundo chamou-o Efraim; porque disse: “Deus me fez frutífero na terra de minha aflição”."}, {"numero": 53, "texto": "E cumpriram-se os sete anos da fartura, que houve na terra do Egito."}, {"numero": 54, "texto": "E começaram a vir os sete anos de fome, como José havia dito; e houve fome em todos os países, mas em toda a terra do Egito havia pão."}, {"numero": 55, "texto": "E quando se sentiu a fome toda a terra do Egito, o povo clamou a Faraó por pão. E disse Faraó a todos os egípcios: Ide a José, e fazei o que ele vos disser."}, {"numero": 56, "texto": "E a fome estava por toda a extensão daquela terra. Então abriu José todo depósito de grãos onde havia, e vendia aos egípcios; porque havia crescido a fome na terra do Egito."}, {"numero": 57, "texto": "E toda a terra vinha ao Egito para comprar de José, porque por toda a terra havia aumentado a fome."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 41, 'en', '[{"numero": 1, "texto": "And it came to pass at the end of two full years, that Pharaoh dreamed: and, behold, he stood by the river."}, {"numero": 2, "texto": "And, behold, there came up out of the river seven well favoured kine and fatfleshed; and they fed in a meadow."}, {"numero": 3, "texto": "And, behold, seven other kine came up after them out of the river, ill favoured and leanfleshed; and stood by the other kine upon the brink of the river."}, {"numero": 4, "texto": "And the ill favoured and leanfleshed kine did eat up the seven well favoured and fat kine. So Pharaoh awoke."}, {"numero": 5, "texto": "And he slept and dreamed the second time: and, behold, seven ears of corn came up upon one stalk, rank and good."}, {"numero": 6, "texto": "And, behold, seven thin ears and blasted with the east wind sprung up after them."}, {"numero": 7, "texto": "And the seven thin ears devoured the seven rank and full ears. And Pharaoh awoke, and, behold, it was a dream."}, {"numero": 8, "texto": "And it came to pass in the morning that his spirit was troubled; and he sent and called for all the magicians of Egypt, and all the wise men thereof: and Pharaoh told them his dream; but there was none that could interpret them unto Pharaoh."}, {"numero": 9, "texto": "Then spake the chief butler unto Pharaoh, saying, I do remember my faults this day:"}, {"numero": 10, "texto": "Pharaoh was wroth with his servants, and put me in ward in the captain of the guard''s house, both me and the chief baker:"}, {"numero": 11, "texto": "And we dreamed a dream in one night, I and he; we dreamed each man according to the interpretation of his dream."}, {"numero": 12, "texto": "And there was there with us a young man, an Hebrew, servant to the captain of the guard; and we told him, and he interpreted to us our dreams; to each man according to his dream he did interpret."}, {"numero": 13, "texto": "And it came to pass, as he interpreted to us, so it was; me he restored unto mine office, and him he hanged."}, {"numero": 14, "texto": "Then Pharaoh sent and called Joseph, and they brought him hastily out of the dungeon: and he shaved himself, and changed his raiment, and came in unto Pharaoh."}, {"numero": 15, "texto": "And Pharaoh said unto Joseph, I have dreamed a dream, and there is none that can interpret it: and I have heard say of thee, that thou canst understand a dream to interpret it."}, {"numero": 16, "texto": "And Joseph answered Pharaoh, saying, It is not in me: God shall give Pharaoh an answer of peace."}, {"numero": 17, "texto": "And Pharaoh said unto Joseph, In my dream, behold, I stood upon the bank of the river:"}, {"numero": 18, "texto": "And, behold, there came up out of the river seven kine, fatfleshed and well favoured; and they fed in a meadow:"}, {"numero": 19, "texto": "And, behold, seven other kine came up after them, poor and very ill favoured and leanfleshed, such as I never saw in all the land of Egypt for badness:"}, {"numero": 20, "texto": "And the lean and the ill favoured kine did eat up the first seven fat kine:"}, {"numero": 21, "texto": "And when they had eaten them up, it could not be known that they had eaten them; but they were still ill favoured, as at the beginning. So I awoke."}, {"numero": 22, "texto": "And I saw in my dream, and, behold, seven ears came up in one stalk, full and good:"}, {"numero": 23, "texto": "And, behold, seven ears, withered, thin, and blasted with the east wind, sprung up after them:"}, {"numero": 24, "texto": "And the thin ears devoured the seven good ears: and I told this unto the magicians; but there was none that could declare it to me."}, {"numero": 25, "texto": "And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do."}, {"numero": 26, "texto": "The seven good kine are seven years; and the seven good ears are seven years: the dream is one."}, {"numero": 27, "texto": "And the seven thin and ill favoured kine that came up after them are seven years; and the seven empty ears blasted with the east wind shall be seven years of famine."}, {"numero": 28, "texto": "This is the thing which I have spoken unto Pharaoh: What God is about to do he sheweth unto Pharaoh."}, {"numero": 29, "texto": "Behold, there come seven years of great plenty throughout all the land of Egypt:"}, {"numero": 30, "texto": "And there shall arise after them seven years of famine; and all the plenty shall be forgotten in the land of Egypt; and the famine shall consume the land;"}, {"numero": 31, "texto": "And the plenty shall not be known in the land by reason of that famine following; for it shall be very grievous."}, {"numero": 32, "texto": "And for that the dream was doubled unto Pharaoh twice; it is because the thing is established by God, and God will shortly bring it to pass."}, {"numero": 33, "texto": "Now therefore let Pharaoh look out a man discreet and wise, and set him over the land of Egypt."}, {"numero": 34, "texto": "Let Pharaoh do this, and let him appoint officers over the land, and take up the fifth part of the land of Egypt in the seven plenteous years."}, {"numero": 35, "texto": "And let them gather all the food of those good years that come, and lay up corn under the hand of Pharaoh, and let them keep food in the cities."}, {"numero": 36, "texto": "And that food shall be for store to the land against the seven years of famine, which shall be in the land of Egypt; that the land perish not through the famine."}, {"numero": 37, "texto": "And the thing was good in the eyes of Pharaoh, and in the eyes of all his servants."}, {"numero": 38, "texto": "And Pharaoh said unto his servants, Can we find such a one as this is, a man in whom the Spirit of God is?"}, {"numero": 39, "texto": "And Pharaoh said unto Joseph, Forasmuch as God hath shewed thee all this, there is none so discreet and wise as thou art:"}, {"numero": 40, "texto": "Thou shalt be over my house, and according unto thy word shall all my people be ruled: only in the throne will I be greater than thou."}, {"numero": 41, "texto": "And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt."}, {"numero": 42, "texto": "And Pharaoh took off his ring from his hand, and put it upon Joseph''s hand, and arrayed him in vestures of fine linen, and put a gold chain about his neck;"}, {"numero": 43, "texto": "And he made him to ride in the second chariot which he had; and they cried before him, Bow the knee: and he made him ruler over all the land of Egypt."}, {"numero": 44, "texto": "And Pharaoh said unto Joseph, I am Pharaoh, and without thee shall no man lift up his hand or foot in all the land of Egypt."}, {"numero": 45, "texto": "And Pharaoh called Joseph''s name Zaphnathpaaneah; and he gave him to wife Asenath the daughter of Potipherah priest of On. And Joseph went out over all the land of Egypt."}, {"numero": 46, "texto": "And Joseph was thirty years old when he stood before Pharaoh king of Egypt. And Joseph went out from the presence of Pharaoh, and went throughout all the land of Egypt."}, {"numero": 47, "texto": "And in the seven plenteous years the earth brought forth by handfuls."}, {"numero": 48, "texto": "And he gathered up all the food of the seven years, which were in the land of Egypt, and laid up the food in the cities: the food of the field, which was round about every city, laid he up in the same."}, {"numero": 49, "texto": "And Joseph gathered corn as the sand of the sea, very much, until he left numbering; for it was without number."}, {"numero": 50, "texto": "And unto Joseph were born two sons before the years of famine came, which Asenath the daughter of Potipherah priest of On bare unto him."}, {"numero": 51, "texto": "And Joseph called the name of the firstborn Manasseh: For God, said he, hath made me forget all my toil, and all my father''s house."}, {"numero": 52, "texto": "And the name of the second called he Ephraim: For God hath caused me to be fruitful in the land of my affliction."}, {"numero": 53, "texto": "And the seven years of plenteousness, that was in the land of Egypt, were ended."}, {"numero": 54, "texto": "And the seven years of dearth began to come, according as Joseph had said: and the dearth was in all lands; but in all the land of Egypt there was bread."}, {"numero": 55, "texto": "And when all the land of Egypt was famished, the people cried to Pharaoh for bread: and Pharaoh said unto all the Egyptians, Go unto Joseph; what he saith to you, do."}, {"numero": 56, "texto": "And the famine was over all the face of the earth: and Joseph opened all the storehouses, and sold unto the Egyptians; and the famine waxed sore in the land of Egypt."}, {"numero": 57, "texto": "And all countries came into Egypt to Joseph for to buy corn; because that the famine was so sore in all lands."}]'::jsonb, 'King James Version'),
  ('Gn', 41, 'fr', '[{"numero": 1, "texto": "Au bout de deux ans, Pharaon eut un songe. Voici, il se tenait près du fleuve."}, {"numero": 2, "texto": "Et voici, sept vaches belles à voir et grasses de chair montèrent hors du fleuve, et se mirent à paître dans la prairie."}, {"numero": 3, "texto": "Sept autres vaches laides à voir et maigres de chair montèrent derrière elles hors du fleuve, et se tinrent à leurs côtés sur le bord du fleuve."}, {"numero": 4, "texto": "Les vaches laides à voir et maigres de chair mangèrent les sept vaches belles à voir et grasses de chair. Et Pharaon s''''éveilla."}, {"numero": 5, "texto": "Il se rendormit, et il eut un second songe. Voici, sept épis gras et beaux montèrent sur une même tige."}, {"numero": 6, "texto": "Et sept épis maigres et brûlés par le vent d''''orient poussèrent après eux."}, {"numero": 7, "texto": "Les épis maigres engloutirent les sept épis gras et pleins. Et Pharaon s''''éveilla. Voilà le songe."}, {"numero": 8, "texto": "Le matin, Pharaon eut l''''esprit agité, et il fit appeler tous les magiciens et tous les sages de l''''Egypte. Il leur raconta ses songes. Mais personne ne put les expliquer à Pharaon."}, {"numero": 9, "texto": "Alors le chef des échansons prit la parole, et dit à Pharaon: Je vais rappeler aujourd''''hui le souvenir de ma faute."}, {"numero": 10, "texto": "Pharaon s''''était irrité contre ses serviteurs; et il m''''avait fait mettre en prison dans la maison du chef des gardes, moi et le chef des panetiers."}, {"numero": 11, "texto": "Nous eûmes l''''un et l''''autre un songe dans une même nuit; et chacun de nous reçut une explication en rapport avec le songe qu''''il avait eu."}, {"numero": 12, "texto": "Il y avait là avec nous un jeune Hébreu, esclave du chef des gardes. Nous lui racontâmes nos songes, et il nous les expliqua."}, {"numero": 13, "texto": "Les choses sont arrivées selon l''''explication qu''''il nous avait donnée. Pharaon me rétablit dans ma charge, et il fit pendre le chef des panetiers."}, {"numero": 14, "texto": "Pharaon fit appeler Joseph. On le fit sortir en hâte de prison. Il se rasa, changea de vêtements, et se rendit vers Pharaon."}, {"numero": 15, "texto": "Pharaon dit à Joseph: J''''ai eu un songe. Personne ne peut l''''expliquer; et j''''ai appris que tu expliques un songe, après l''''avoir entendu."}, {"numero": 16, "texto": "Joseph répondit à Pharaon, en disant: Ce n''''est pas moi! c''''est Dieu qui donnera une réponse favorable à Pharaon."}, {"numero": 17, "texto": "Pharaon dit alors à Joseph: Dans mon songe, voici, je me tenais sur le bord du fleuve."}, {"numero": 18, "texto": "Et voici, sept vaches grasses de chair et belles d''''apparence montèrent hors du fleuve, et se mirent à paître dans la prairie."}, {"numero": 19, "texto": "Sept autres vaches montèrent derrière elles, maigres, fort laides d''''apparence, et décharnées: je n''''en ai point vu d''''aussi laides dans tout le pays d''''Egypte."}, {"numero": 20, "texto": "Les vaches décharnées et laides mangèrent les sept premières vaches qui étaient grasses."}, {"numero": 21, "texto": "Elles les engloutirent dans leur ventre, sans qu''''on s''''aperçût qu''''elles y fussent entrées; et leur apparence était laide comme auparavant. Et je m''''éveillai."}, {"numero": 22, "texto": "Je vis encore en songe sept épis pleins et beaux, qui montèrent sur une même tige."}, {"numero": 23, "texto": "Et sept épis vides, maigres, brûlés par le vent d''''orient, poussèrent après eux."}, {"numero": 24, "texto": "Les épis maigres engloutirent les sept beaux épis. Je l''''ai dit aux magiciens, mais personne ne m''''a donné l''''explication."}, {"numero": 25, "texto": "Joseph dit à Pharaon: Ce qu''''a songé Pharaon est une seule chose; Dieu a fait connaître à Pharaon ce qu''''il va faire."}, {"numero": 26, "texto": "Les sept vaches belles sont sept années: et les sept épis beaux sont sept années: c''''est un seul songe."}, {"numero": 27, "texto": "Les sept vaches décharnées et laides, qui montaient derrière les premières, sont sept années; et les sept épis vides, brûlés par le vent d''''orient, seront sept années de famine."}, {"numero": 28, "texto": "Ainsi, comme je viens de le dire à Pharaon, Dieu a fait connaître à Pharaon ce qu''''il va faire."}, {"numero": 29, "texto": "Voici, il y aura sept années de grande abondance dans tout le pays d''''Egypte."}, {"numero": 30, "texto": "Sept années de famine viendront après elles; et l''''on oubliera toute cette abondance au pays d''''Egypte, et la famine consumera le pays."}, {"numero": 31, "texto": "Cette famine qui suivra sera si forte qu''''on ne s''''apercevra plus de l''''abondance dans le pays."}, {"numero": 32, "texto": "Si Pharaon a vu le songe se répéter une seconde fois, c''''est que la chose est arrêtée de la part de Dieu, et que Dieu se hâtera de l''''exécuter."}, {"numero": 33, "texto": "Maintenant, que Pharaon choisisse un homme intelligent et sage, et qu''''il le mette à la tête du pays d''''Egypte."}, {"numero": 34, "texto": "Que Pharaon établisse des commissaires sur le pays, pour lever un cinquième des récoltes de l''''Egypte pendant les sept années d''''abondance."}, {"numero": 35, "texto": "Qu''''ils rassemblent tous les produits de ces bonnes années qui vont venir; qu''''ils fassent, sous l''''autorité de Pharaon, des amas de blé, des approvisionnements dans les villes, et qu''''ils en aient la garde."}, {"numero": 36, "texto": "Ces provisions seront en réserve pour le pays, pour les sept années de famine qui arriveront dans le pays d''''Egypte, afin que le pays ne soit pas consumé par la famine."}, {"numero": 37, "texto": "Ces paroles plurent à Pharaon et à tous ses serviteurs."}, {"numero": 38, "texto": "Et Pharaon dit à ses serviteurs: Trouverions-nous un homme comme celui-ci, ayant en lui l''''esprit de Dieu?"}, {"numero": 39, "texto": "Et Pharaon dit à Joseph: Puisque Dieu t''''a fait connaître toutes ces choses, il n''''y a personne qui soit aussi intelligent et aussi sage que toi."}, {"numero": 40, "texto": "Je t''''établis sur ma maison, et tout mon peuple obéira à tes ordres. Le trône seul m''''élèvera au-dessus de toi."}, {"numero": 41, "texto": "Pharaon dit à Joseph: Vois, je te donne le commandement de tout le pays d''''Egypte."}, {"numero": 42, "texto": "Pharaon ôta son anneau de la main, et le mit à la main de Joseph; il le revêtit d''''habits de fin lin, et lui mit un collier d''''or au cou."}, {"numero": 43, "texto": "Il le fit monter sur le char qui suivait le sien; et l''''on criait devant lui: A genoux! C''''est ainsi que Pharaon lui donna le commandement de tout le pays d''''Egypte."}, {"numero": 44, "texto": "Il dit encore à Joseph: Je suis Pharaon! Et sans toi personne ne lèvera la main ni le pied dans tout le pays d''''Egypte."}, {"numero": 45, "texto": "Pharaon appela Joseph du nom de Tsaphnath-Paenéach; et il lui donna pour femme Asnath, fille de Poti-Phéra, prêtre d''''On. Et Joseph partit pour visiter le pays d''''Egypte."}, {"numero": 46, "texto": "Joseph était âgé de trente ans lorsqu''''il se présenta devant Pharaon, roi d''''Egypte; et il quitta Pharaon, et parcourut tout le pays d''''Egypte."}, {"numero": 47, "texto": "Pendant les sept années de fertilité, la terre rapporta abondamment."}, {"numero": 48, "texto": "Joseph rassembla tous les produits de ces sept années dans le pays d''''Egypte; il fit des approvisionnements dans les villes, mettant dans l''''intérieur de chaque ville les productions des champs d''''alentour."}, {"numero": 49, "texto": "Joseph amassa du blé, comme le sable de la mer, en quantité si considérable que l''''on cessa de compter, parce qu''''il n''''y avait plus de nombre."}, {"numero": 50, "texto": "Avant les années de famine, il naquit à Joseph deux fils, que lui enfanta Asnath, fille de Poti-Phéra, prêtre d''''On."}, {"numero": 51, "texto": "Joseph donna au premier-né le nom de Manassé, car, dit-il, Dieu m''''a fait oublier toutes mes peines et toute la maison de mon père."}, {"numero": 52, "texto": "Et il donna au second le nom d''''Ephraïm, car, dit-il, Dieu m''''a rendu fécond dans le pays de mon affliction."}, {"numero": 53, "texto": "Les sept années d''''abondance qu''''il y eut au pays d''''Egypte s''''écoulèrent."}, {"numero": 54, "texto": "Et les sept années de famine commencèrent à venir, ainsi que Joseph l''''avait annoncé. Il y eut famine dans tous les pays; mais dans tout le pays d''''Egypte il y avait du pain."}, {"numero": 55, "texto": "Quand tout le pays d''''Egypte fut aussi affamé, le peuple cria à Pharaon pour avoir du pain. Pharaon dit à tous les Egyptiens: Allez vers Joseph, et faites ce qu''''il vous dira."}, {"numero": 56, "texto": "La famine régnait dans tout le pays. Joseph ouvrit tous les lieux d''''approvisionnements, et vendit du blé aux Egyptiens. La famine augmentait dans le pays d''''Egypte."}, {"numero": 57, "texto": "Et de tous les pays on arrivait en Egypte, pour acheter du blé auprès de Joseph; car la famine était forte dans tous les pays."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 41, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que pasados dos años tuvo Faraón un sueño: Parecíale que estaba junto al río;"}, {"numero": 2, "texto": "Y que del río subían siete vacas, hermosas á la vista, y muy gordas, y pacían en el prado:"}, {"numero": 3, "texto": "Y que otras siete vacas subían tras ellas del río, de fea vista, y enjutas de carne, y se pararon cerca de las vacas hermosas á la orilla del río:"}, {"numero": 4, "texto": "Y que las vacas de fea vista y enjutas de carne devoraban á las siete vacas hermosas y muy gordas. Y despertó Faraón."}, {"numero": 5, "texto": "Durmióse de nuevo, y soñó la segunda vez: Que siete espigas llenas y hermosas subían de una sola caña:"}, {"numero": 6, "texto": "Y que otras siete espigas menudas y abatidas del Solano, salían después de ellas:"}, {"numero": 7, "texto": "Y las siete espigas menudas devoraban á las siete espigas gruesas y llenas. Y despertó Faraón, y he aquí que era sueño."}, {"numero": 8, "texto": "Y acaeció que á la mañana estaba agitado su espíritu; y envió é hizo llamar á todos los magos de Egipto, y á todos sus sabios: y contóles Faraón sus sueños, mas no había quien á Faraón los declarase."}, {"numero": 9, "texto": "Entonces el principal de los coperos habló á Faraón, diciendo: Acuérdome hoy de mis faltas:"}, {"numero": 10, "texto": "Faraón se enojó contra sus siervos, y á mí me echó á la prisión de la casa del capitán de los de la guardia, á mí y al principal de los panaderos:"}, {"numero": 11, "texto": "Y yo y él vimos un sueño una misma noche: cada uno soñó conforme á la declaración de su sueño."}, {"numero": 12, "texto": "Y estaba allí con nosotros un mozo Hebreo, sirviente del capitán de los de la guardia; y se lo contamos, y él nos declaró nuestros sueños, y declaró á cada uno conforme á su sueño."}, {"numero": 13, "texto": "Y aconteció que como él nos declaró, así fué: á mí me hizo volver á mi puesto, é hizo colgar al otro."}, {"numero": 14, "texto": "Entonces Faraón envió y llamó á José; é hiciéronle salir corriendo de la cárcel, y le cortaron el pelo, y mudaron sus vestidos, y vino á Faraón."}, {"numero": 15, "texto": "Y dijo Faraón á José: Yo he tenido un sueño, y no hay quien lo declare; mas he oído decir de ti, que oyes sueños para declararlos."}, {"numero": 16, "texto": "Y respondió José á Faraón, diciendo: No está en mí; Dios será el que responda paz á Faraón."}, {"numero": 17, "texto": "Entonces Faraón dijo á José: En mi sueño parecíame que estaba á la orilla del río:"}, {"numero": 18, "texto": "Y que del río subían siete vacas de gruesas carnes y hermosa apariencia, que pacían en el prado:"}, {"numero": 19, "texto": "Y que otras siete vacas subían después de ellas, flacas y de muy fea traza; tan extenuadas, que no he visto otras semejantes en toda la tierra de Egipto en fealdad:"}, {"numero": 20, "texto": "Y las vacas flacas y feas devoraban á las siete primeras vacas gruesas:"}, {"numero": 21, "texto": "Y entraban en sus entrañas, mas no se conocía que hubiesen entrado en ellas, porque su parecer era aún malo, como de primero. Y yo desperté."}, {"numero": 22, "texto": "Vi también soñando, que siete espigas subían en una misma caña llenas y hermosas;"}, {"numero": 23, "texto": "Y que otras siete espigas menudas, marchitas, abatidas del Solano, subían después de ellas:"}, {"numero": 24, "texto": "Y las espigas menudas devoraban á las siete espigas hermosas: y helo dicho á los magos, mas no hay quien me lo declare."}, {"numero": 25, "texto": "Entonces respondió José á Faraón: El sueño de Faraón es uno mismo: Dios ha mostrado á Faraón lo que va á hacer."}, {"numero": 26, "texto": "Las siete vacas hermosas siete años son; y las espigas hermosas son siete años: el sueño es uno mismo."}, {"numero": 27, "texto": "También las siete vacas flacas y feas que subían tras ellas, son siete años; y las siete espigas menudas y marchitas del Solano, siete años serán de hambre."}, {"numero": 28, "texto": "Esto es lo que respondo á Faraón. Lo que Dios va á hacer, halo mostrado á Faraón."}, {"numero": 29, "texto": "He aquí vienen siete años de grande hartura en toda la tierra de Egipto:"}, {"numero": 30, "texto": "Y levantarse han tras ellos siete años de hambre; y toda la hartura será olvidada en la tierra de Egipto; y el hambre consumirá la tierra;"}, {"numero": 31, "texto": "Y aquella abundancia no se echará de ver á causa del hambre siguiente, la cual será gravísima."}, {"numero": 32, "texto": "Y el suceder el sueño á Faraón dos veces, significa que la cosa es firme de parte de Dios, y que Dios se apresura á hacerla."}, {"numero": 33, "texto": "Por tanto, provéase ahora Faraón de un varón prudente y sabio, y póngalo sobre la tierra de Egipto."}, {"numero": 34, "texto": "Haga esto Faraón, y ponga gobernadores sobre el país, y quinte la tierra de Egipto en los siete años de la hartura;"}, {"numero": 35, "texto": "Y junten toda la provisión de estos buenos años que vienen, y alleguen el trigo bajo la mano de Faraón para mantenimiento de las ciudades; y guárdenlo."}, {"numero": 36, "texto": "Y esté aquella provisión en depósito para el país, para los siete años del hambre que serán en la tierra de Egipto; y el país no perecerá de hambre."}, {"numero": 37, "texto": "Y el negocio pareció bien á Faraón, y á sus siervos."}, {"numero": 38, "texto": "Y dijo Faraón á sus siervos: ¿Hemos de hallar otro hombre como éste, en quien haya espíritu de Dios?"}, {"numero": 39, "texto": "Y dijo Faraón á José: Pues que Dios te ha hecho saber todo esto, no hay entendido ni sabio como tú:"}, {"numero": 40, "texto": "Tú serás sobre mi casa, y por tu dicho se gobernará todo mi pueblo: solamente en el trono seré yo mayor que tú."}, {"numero": 41, "texto": "Dijo más Faraón á José: He aquí yo te he puesto sobre toda la tierra de Egipto."}, {"numero": 42, "texto": "Entonces Faraón quitó su anillo de su mano, y púsolo en la mano de José, é hízole vestir de ropas de lino finísimo, y puso un collar de oro en su cuello;"}, {"numero": 43, "texto": "E hízolo subir en su segundo carro, y pregonaron delante de él: Doblad la rodilla: y púsole sobre toda la tierra de Egipto."}, {"numero": 44, "texto": "Y dijo Faraón á José: Yo Faraón; y sin ti ninguno alzará su mano ni su pie en toda la tierra de Egipto."}, {"numero": 45, "texto": "Y llamó Faraón el nombre de José, Zaphnath-paaneah; y dióle por mujer á Asenath, hija de Potipherah, sacerdote de On. Y salió José por toda la tierra de Egipto."}, {"numero": 46, "texto": "Y era José de edad de treinta años cuando fué presentado delante de Faraón, rey de Egipto: y salió José de delante de Faraón, y transitó por toda la tierra de Egipto."}, {"numero": 47, "texto": "E hizo la tierra en aquellos siete años de hartura á montones."}, {"numero": 48, "texto": "Y él juntó todo el mantenimiento de los siete años que fueron en la tierra de Egipto, y guardó mantenimiento en las ciudades, poniendo en cada ciudad el mantenimiento del campo de sus alrededores."}, {"numero": 49, "texto": "Y acopió José trigo como arena de la mar, mucho en extremo, hasta no poderse contar, porque no tenía número."}, {"numero": 50, "texto": "Y nacieron á José dos hijos antes que viniese el primer año del hambre, los cuales le parió Asenath, hija de Potipherah, sacerdote de On."}, {"numero": 51, "texto": "Y llamó José el nombre del primogénito Manasés; porque Dios (dijo) me hizo olvidar todo mi trabajo, y toda la casa de mi padre."}, {"numero": 52, "texto": "Y el nombre del segundo llamólo Ephraim; porque Dios (dijo) me hizo fértil en la tierra de mi aflicción."}, {"numero": 53, "texto": "Y cumpliéronse los siete años de la hartura, que hubo en la tierra de Egipto."}, {"numero": 54, "texto": "Y comenzaron á venir los siete años del hambre, como José había dicho: y hubo hambre en todos los países, mas en toda la tierra de Egipto había pan."}, {"numero": 55, "texto": "Y cuando se sintió el hambre en toda la tierra de Egipto, el pueblo clamó á Faraón por pan. Y dijo Faraón á todos los Egipcios: Id á José, y haced lo que él os dijere."}, {"numero": 56, "texto": "Y el hambre estaba por toda la extensión del país. Entonces abrió José todo granero donde había, y vendía á los Egipcios; porque había crecido el hambre en la tierra de Egipto."}, {"numero": 57, "texto": "Y toda la tierra venía á Egipto para comprar de José, porque por toda la tierra había crecido el hambre."}]'::jsonb, 'Reina-Valera 1909')
